(window.MUSEUM_MATCH_T = window.MUSEUM_MATCH_T || {})["ar"] = {"ui":{"lead":"مباريات عظيمة، نقلةً بعد نقلة. تابع على الرقعة مباريات مشهورة بينما يشرح Musowl كل نقلة.","all":"الكل","k_chess":"الشطرنج","k_shogi":"الشوغي","k_go":"الغو","k_xiangqi":"شيانغتشي","side_r":"الأحمر","res_r":"فوز الأحمر","back":"العودة إلى المباريات العظيمة","start":"البداية","prev":"نقلة إلى الوراء","next":"نقلة إلى الأمام","end":"النهاية","play":"تشغيل تلقائي","pause":"إيقاف","moves":"النقلات","move":"النقلة {n}","startpos":"وضع البداية","nextnote":"الشرح التالي (النقلة {n})","quiet":"لا يوجد شرح لهذه النقلة.","guide":"Musowl","keys":"← → للتنقل نقلةً نقلة","result":"النتيجة","r_event":"المباراة","r_date":"السنة","r_place":"المكان","side_w":"الأبيض","side_b":"الأسود","side_s":"سينتي","side_g":"غوتي","side_B":"الأسود","side_W":"الأبيض","res_w":"فوز الأبيض","res_b":"فوز الأسود","res_d":"تعادل","res_s":"فوز سينتي","res_g":"فوز غوتي","credit":"النقلات هي السجل المعروف لكل مباراة. الشروح من كتابة Musowl في المتحف.","caps":"المأسورة","hand":"في اليد","pnote":"الشرح السابق","nnote":"الشرح التالي","plies":"{n} نقلة","about":"عن هذه المباراة","ev":"التقييم","even":"متكافئ","evby":"قراءة محرك هذا الموقع (تقريبية): فرصة فوز من يبدأ","r_dp":"متى وأين","k_reversi":"ريفيرسي","pass":"تمرير","discs":"{n} قطعة","k_checkers":"الداما","taken":"المأسورة"},"opera":{"t":"مباراة الأوبرا","w":"بول مورفي","b":"دوق برونزفيك كارل الثاني والكونت إيزوار","ev":"لُعبت في مقصورة بدار أوبرا باريس (الحليفان يتشاوران معًا)","d":"1858","pl":"فرنسا (باريس)","lead":"البطل الأمريكي الشاب في مواجهة نبيلَين، أثناء عرض في الأوبرا: سبع عشرة نقلة. أخرِج القطع بسرعة، وضحِّ بها دون تردد، وأنهِ المباراة بقطع قليلة جدًا. لا توجد مباراة تظهر في كتب الشطرنج أكثر منها.","c":{"0":"باريس، 1858. كان الأمريكي بول مورفي، ابن الحادية والعشرين، يهزم أقوى لاعبي أوروبا واحدًا تلو الآخر. في تلك الليلة، في مقصورة بدار الأوبرا، أخذ دوق برونزويك والكونت إيزوار القطع السوداء معًا وتحدّياه، يتشاوران في كل نقلة. ويُقال إن مورفي أراد أن ينهي المباراة بسرعة ليشاهد العرض. هذه النقلات السبع عشرة مليئة بالأساسيات: أخرِج القطع بسرعة وضع الملك في أمان. وُلد مورفي في نيو أورلينز في جنوب الولايات المتحدة. كان أبوه محاميًا ثم صار قاضيًا في المحكمة العليا للولاية، ودرس مورفي القانون أيضًا في الجامعة. لكنه حين تخرّج كان لا يزال أصغر من أن يعمل محاميًا، فانطلق في هذه الأثناء في رحلة شطرنج إلى أوروبا.","1":"يتقدّم الأبيض ببيدق الملك مربعين. ينظر إلى d5 وe5 في الوسط ويفتح الطريق للفيل والوزير. كان المكان في تلك الليلة دار الأوبرا الإيطالية في باريس (قاعة فانتادور). ويُقال إن العرض كان «حلّاق إشبيلية» لروسيني، أو ربما «نورما» لبيليني؛ فالمصادر مختلفة، وما زال الأمر غير مؤكد حتى اليوم.","2":"يلعب الأسود e5 أيضًا. يتواجه البيدقان في الوسط، ولا يستطيع البيدق الأبيض التقدّم أكثر. في رحلة عام 1858 هذه، أحدث مورفي ضجة في مقهى «لا ريجانس» في باريس حين لعب معصوب العينين ضد ثمانية خصوم في وقت واحد وهزمهم. وفي ديسمبر من العام نفسه فاز أيضًا في مباراة على أندرسن، الذي كان يُعدّ الأقوى في أوروبا، بسبعة انتصارات وهزيمتين وتعادلين.","3":"يخرج الحصان إلى f3 ويهاجم بيدق e5. نقلة جيدة: تطوّر قطعة وتجعل الخصم يفكّر في الدفاع. وما زالت البداية 1.e4 e5 2.Nf3، بعد قرابة مئتي عام، من أكثر البدايات استعمالًا، من المبتدئين إلى أبطال العالم.","4":"يحمي الأسود e5 بـ d6. يُسمّى هذا دفاع فيليدور. إنه متين، لكنه يضيّق قليلًا طريق فيل f8. فيليدور، الذي سُمّي الدفاع باسمه، فرنسي من القرن الثامن عشر: كان أستاذًا في الشطرنج وموسيقيًا ألّف إحدى عشرة أوبرا. وقد نصح بهذه النقلة في كتاب نشره عام 1749. أليست مصادفة طريفة أن تبدأ «مباراة الأوبرا» بدفاع يحمل اسم مؤلف أوبرا؟ ويُعدّ اليوم دفاعًا متينًا لكنه ضيّق قليلًا.","5":"يلعب الأبيض d4: بيدق آخر إلى الوسط في مواجهة e5. على الأسود أن يختار بين الأخذ والحماية. وضد دفاع فيليدور، كان ضرب المركز فورًا بـ 3.d4 هكذا ولا يزال هو الخط الرئيسي.","6":"الفيل الأسود إلى g4. يضغط على حصان f3 الواقع على خط واحد مع الوزير الأبيض في d1. إذا تحرّك الحصان ضاع الوزير، فلا يستطيع الحصان الذهاب إلى e5. لكن هذه النقلة 3...Bg4 تُعدّ منذ زمن بعيد نقلة ضعيفة. وقد حكم عليها بطلا العالم اللاحقان شتاينتس وفيشر بالضعف. وفي نظرية الافتتاحيات اليوم يُلعب عادةً 3...exd4 بأخذ البيدق، أو 3...Nf6 بإخراج الحصان.","7":"يأخذ الأبيض في e5 بالبيدق. لو استردّ الأسود فورًا ببيدق d6 لبادل الأبيض الوزيرين ثم أخذ الحصان بيدق e5. لذلك يريد الأسود أولًا التخلّص من حصان f3.","8":"يأخذ الأسود الحصان بالفيل. صار بإمكانه الآن استرداد e5 بأمان. لكن مبادلة الفيل الذي خرج للتو بالحصان تجعل الأسود متأخرًا في التطوير. أحد لاعبَي الأسود، دوق برونزفيك، كان حاكم دوقية برونزفيك في ألمانيا سابقًا. طُرد من بلاده في اضطرابات عام 1830، ثم عاش غالبًا في باريس ولندن. وكانت أوروبا كلها تتحدث عن ترفه ومجموعته الضخمة من المجوهرات.","9":"يستردّ الأبيض بالوزير الذي يعمل بالفعل قرب الوسط، بينما لم يُخرج الأسود تقريبًا أي قطعة. كان الدوق مولعًا بالشطرنج. بل يروي خبر في صحيفة من العام السابق أنه أحدث ضجة كبيرة وهو يلعب الشطرنج في دار الأوبرا الإيطالية نفسها في أثناء العرض، حتى طُلب منه أن يهدأ.","10":"يستردّ الأسود ببيدق والعتاد متعادل. لكن الأبيض متقدّم في عدد القطع المطوَّرة. أما اللاعب الآخر، الكونت إيزوار، فكان نبيلًا فرنسيًا تملك أسرته قصرًا في فوفنارغ جنوب فرنسا. وحتى رجلان كبيران يفكّران معًا لم يقدرا على الشاب ذي الحادية والعشرين.","11":"الفيل إلى c4. مع وزير f3 يصوّب نحو f7. لا يحمي f7 إلا الملك، فهو مربع ضعيف: أخذه يعني كش مات.","12":"يضع الأسود الحصان في f6 ويسدّ العمود f. لولا ذلك لأخذ الوزير f7 بكش مات. الدفاع مع التطوير هو الردّ الصحيح.","13":"ينعطف الوزير إلى b3 ويهاجم f7 وb7 معًا. النقلة ذات التهديدين قوية لأن الخصم لا يستطيع صدّهما معًا.","14":"يضع الأسود الوزير في e7 ليحمي f7 ويترك b7. لكن الوزير الآن يسدّ طريق فيل f8. في الحقيقة لم يكن عند الأسود نقلة أفضل من Qe7. فمثلًا يبيّن التحليل أن الدفاع بـ Qd7 يسمح للأبيض بأخذ b7 والفوز بقلعة أيضًا.","15":"لا يأخذ مورفي بيدق b7، بل يُخرج حصانًا. لو أخذه لابتعد الوزير كثيرًا. تفضيل التطوير السريع على بيدق هو أسلوب مورفي تمامًا. ويُقال إن الأبيض لو أخذ b7 لاستطاع الأسود أن يكشّ بالوزير من b4 ويفرض تبادل الوزيرين، فيخمد هجوم الأبيض.","16":"يلعب الأسود c6: يسيطر على d5 وb5 ويفتح طريقًا للوزير نحو b6.","17":"الفيل إلى g5 يثبّت حصان f6. إذا تحرّك الحصان يمكن أخذ الوزير في e7 خلفه. صار تحريك قطع الأسود أصعب فأصعب.","18":"يلعب الأسود b5 ليطرد فيل c4. يكسب مساحة في جناح الوزير، لكنه يفتح ثغرة لدخول قطع الأبيض. ويُقال إن 9...b5 هي النقلة الخاسرة، لكن حتى التحليلات اللاحقة لم تجد هنا نقلة تنقذ الأسود بوضوح. فمتاعب الأسود بدأت قبل ذلك بكثير، مع 3...Bg4.","19":"يُضحّى بالحصان ليأخذ في b5! بدل سحب الفيل، يواصل مورفي الهجوم. والملك الأسود ما زال في الوسط، وهذا خطير جدًا على الأسود.","20":"يأخذ الأسود الحصان ويتقدّم بحصان. لكن ملكه ما زال في e8، وقطع الأبيض تواصل التجمّع.","21":"الفيل إلى b5، كش! الملك الأسود ما زال عالقًا في الوسط. للأبيض بيدقان مقابل الحصان، ويتّجه مباشرة نحو الملك.","22":"يسدّ الأسود بالحصان في d7. لكن هذا الحصان مثبّت: إذا تحرّك صار الملك الأسود في كش. الآن سيصوّب الأبيض نحو d7.","23":"يبيّت الأبيض في جهة الوزير. صار الملك آمنًا، وفي الوقت نفسه وصل الرخ إلى d1 ليصوّب نحو d7. نقلة واحدة تدافع وتهاجم: رائعة.","24":"يضع الأسود الرخ في d8 ليحمي d7. ما زال لا يستطيع التبييت، والرخ في h8 والفيل في f8 لا يفعلان شيئًا.","25":"يُضحّى بالرخ ليأخذ في d7! يعطي الأبيض رخًا ليزيل أحد مدافعي الأسود.","26":"يستردّ الأسود بالرخ. الآن هذا الرخ في d7 مثبّت أيضًا: إذا تحرّك أعطى فيل b5 كشًّا للملك الأسود.","27":"يصل الرخ الآخر إلى d1 ويهاجم d7 من جديد. صار عدد القطع البيضاء المهاجِمة لـ d7 أكثر من القطع السوداء المدافِعة.","28":"الوزير الأسود إلى e6، يعرض مبادلة الوزيرين ليُبعد وزير b3 ويريد مساعدة d7. لكن الأوان قد فات.","29":"يأخذ الفيل في d7 مع كش. يزيل الأبيض مدافعي الأسود واحدًا تلو الآخر.","30":"يستردّ الأسود بالحصان. بعد مغادرة الحصان f6 انفتح القطر من فيل g5 إلى d8. وسيكون لهذا القطر دور في النهاية.","31":"يُضحّى بالوزير في b8 مع كش! إنها أشهر نقلة في المباراة. لا بد أن يأخذ الأسود بالحصان، وعندما يغادر الحصان d7 ينفتح العمود d.","32":"يأخذ الأسود بالحصان. الآن لا توجد قطعة سوداء تحمي d8.","33":"الرخ إلى d8، كش مات! فيل g5 يدعم d8، والملك الأسود محاصر بقطعه نفسها فلا مهرب. أعطى الأبيض الوزير والرخ والفيل وأنهى برخ وفيل فقط. طوِّر بسرعة، أمِّن ملكك، وهاجم ما دام ملك الخصم في الوسط: تجمع هذه المباراة الشهيرة كل هذه الأفكار المهمة."}},"reti1910":{"t":"كش مات ريتي","w":"ريتشارد ريتي","b":"سافيلي تارتاكوفر","ev":"مباراة ودية (ليست في بطولة)","d":"1910","pl":"النمسا (فيينا)","lead":"لاعبان سيصبحان من كبار الأساتذة، في مباراة ودية في فيينا، إحدى عشرة نقلة. يضحّي الأبيض بالوزير وينهي المباراة بكش مزدوج: قطعتان تكشّان في الوقت نفسه. ويُسمّى هذا الشكل من الكش مات باسم الأبيض: كش مات ريتي.","c":{"0":"فيينا، 1910. الأبيض ريتشارد ريتي ابن العشرين، والأسود سافيلي تارتاكوفر. أصبح كلاهما من أفضل لاعبي العالم، ويُعرفان بإدخال أفكار جديدة إلى الشطرنج. لم تكن مباراة في بطولة، بل مباراة ودية على رهان صغير. إنها قصيرة، لكنها تُظهر بوضوح لماذا يجب تأمين الملك مبكرًا. وُلد ريتي في بلدة بيزينوك في سلوفاكيا اليوم، وكان أبوه طبيبًا في الجيش. وقد جاء إلى فيينا ليدرس الرياضيات في الجامعة. أما تارتاكوفر فوُلد في روستوف على الدون في روسيا، ودرس القانون في جامعتي جنيف وفيينا، وكان الناس يلقّبونه «الدكتور».","1":"يتقدّم الأبيض ببيدق الملك مربعين. السيطرة على الوسط تسهّل خروج القطع الخلفية. وانفتح الطريق للفيل والوزير. وبحسب زاوية الشطرنج في صحيفة من ذلك الوقت، كان الرهان عشر كرونات، ولُعبت المباراة بالساعة بمعدل خمس عشرة نقلة في الساعة.","2":"يلعب الأسود c6. بدل الذهاب إلى الوسط فورًا، يستعد لـ d5 لمهاجمة بيدق e4. يُسمّى هذا الافتتاح المتين دفاع كارو-كان. وسُمّي باسم لاعبَين من القرن التاسع عشر: هوراشيو كارو الذي نشط في برلين، وماركوس كان. وقد نشر كارو عام 1886 مقالًا يحلّل هذه النقلة في مجلة شطرنج.","3":"يضع الأبيض البيدق الآخر في d4 أيضًا. بيدقان متجاوران في الوسط: للأبيض مساحة كبيرة. سيحاول الأسود تفكيكهما. وفي ربيع هذا العام، 1910، اقترب مذنّب هالي من الأرض، وقيل إن الأرض ستمرّ عبر ذيله الطويل. وخاف بعض الناس من غاز سامّ في الذيل حتى تسابقوا إلى شراء «حبوب ضد المذنّب».","4":"كما خُطّط، d5. البيدق يتحدّى e4: \"أستطيع أخذك\". على الأبيض أن يقرّر: الحماية أو التقدّم أو المبادلة.","5":"يُخرج الأبيض حصانًا ليحمي e4. يطوّر قطعة ويدافع في الوقت نفسه دون إضاعة وقت. وفيما بعد صار ريتي من روّاد الفكرة الجديدة «الحداثة الفائقة» — أي التحكم في المركز من بعيد بالقطع بدل ملئه بالبيادق — وبقي اسمه في «افتتاح ريتي» الذي يبدأ بـ 1.Nf3. لكنه في هذه المباراة ما زال يلعب بالطريقة القديمة، فيصفّ البيادق على e4 وd4.","6":"يأخذ الأسود بيدق e4. بمبادلة بيادق الوسط يصغر وسط الأبيض.","7":"يستردّ الأبيض بالحصان، فيقف في وسط الرقعة. الحصان في الوسط يصل إلى مربعات كثيرة وهو قوي جدًا. وحتى هنا، هذا هو الخط الرئيسي لدفاع كارو-كان، وما زال الأكثر لعبًا اليوم.","8":"يُخرج الأسود حصانًا في مواجهة حصان e4. يُلعب هنا غالبًا الفيل إلى f5، لكن الأسود يدعو إلى مبادلة الحصانين. واشتهر تارتاكوفر لاحقًا أيضًا بأقواله الظريفة الكثيرة، مثل: «الفائز هو اللاعب الذي يرتكب الخطأ قبل الأخير».","9":"يخرج الوزير مبكرًا إلى d3 ليحمي حصان e4. عادةً لا يُخرَج الوزير بهذه السرعة، لكن للأبيض خطة. تذكّر أن هذا الوزير يقف على العمود d أمام الملك الأسود. عادةً يبادل الأبيض الحصانين هنا، ولذلك فإن 5.Qd3 نقلة غير مألوفة.","10":"يلعب الأسود e5 ويعرض بيدقًا ليفتح الطريق للفيل والوزير. نقلة نشطة تُشعل القتال في الوسط. لكن فتح المركز قبل التبييت جعلها نقلة خطرة على ملك الأسود أيضًا. وفي الحقيقة تُظهر السجلات أن تضحية بالوزير تشبه كثيرًا التضحية القادمة كانت قد لُعبت قبل هذه المباراة.","11":"يأخذ الأبيض بيدق e5. قبل الهدية، لكن الوزير الأسود صار أكثر حرية.","12":"كش! الوزير الأسود في a5 يصوّب قطريًا نحو الملك في e1. وفي الوقت نفسه يريد استرداد بيدق e5: مهمتان في نقلة واحدة. على الأبيض أن يسدّ.","13":"يسدّ الأبيض الكش بالفيل في d2. يمكن للوزير أخذ الفيل، لكن الوزير الأبيض يحميه جيدًا.","14":"استردّ الأسود البيدق وعاد التعادل في العتاد. وهذا الوزير ينظر على العمود e إلى حصان e4 والملك خلفه. إذا تحرّك الحصان صار الملك في كش، فالحصان مقيّد. يبدو أن الأسود سيربحه قريبًا.","15":"يبيّت الأبيض في جهة الوزير. يغادر الملك العمود e فيتحرّر الحصان. وفي الوقت نفسه يصل رخ إلى d1: الرخ في d1 والوزير في d3 والمربع d8 بجانب الملك الأسود صارت على خط واحد. هذا هو فخّ الأبيض.","16":"يأخذ الأسود حصان e4 ويبدو أنه ربح قطعة. لكن الملك الأسود ما زال في e8 ولم يبيّت. قطع الأبيض مصطفّة على العمود d، والملك الأسود بلا حماية. هذه النقلة الخاسرة هي نقطة التحوّل.","17":"الوزير إلى d8، كش! يقدّم الأبيض أقوى قطعه مجانًا. القطعة السوداء الوحيدة التي تستطيع أخذه هي الملك. بتركه يُؤخذ، يجرّ الأبيض الملك إلى المربع الخطِر d8.","18":"لا بد أن يأخذ الأسود بالملك؛ لا طريقة أخرى لصدّ الكش. صار الملك في d8، ورخ d1 ينتظر خلفه.","19":"يتحرّك الفيل من d2 إلى g5 بكش، وفي الوقت نفسه يفتح الطريق لرخ d1 الذي يكشّ أيضًا على العمود d. قطعتان تكشّان معًا: كش مزدوج. لا يمكن صدّه بأخذ قطعة ولا بالسدّ، فعلى الملك أن يهرب.","20":"يهرب الملك إلى c7. لو ذهب إلى e8 لجاء الرخ إلى d8 وأعطى كش مات. أينما ذهب الملك، فالضربة الأخيرة جاهزة لدى الأبيض.","21":"الفيل إلى d8: كش مات على القطر للملك في c7! الفيل يحميه رخ d1، فلا يستطيع الملك أخذه. مربعات مثل b8 وc8 وb7 وc6 مشغولة بقطع الأسود نفسه، والرخ يراقب d6 وd7. في إحدى عشرة نقلة فقط ضحّى الأبيض بالوزير وفاز بقطعتين صغيرتين. تعلّمنا هذه المباراة مدى خطورة السعي وراء العتاد قبل التبييت. وتقول بعض السجلات إن الأسود استسلم قبل ذلك بنقلة."}},"immortal":{"t":"المباراة الخالدة","w":"أدولف أندرسن","b":"ليونيل كيزيريتسكي","ev":"مباراة غير رسمية في استراحة بطولة لندن 1851","d":"1851","pl":"المملكة المتحدة (لندن)","lead":"لندن، أثناء أول بطولة شطرنج دولية: مباراة لُعبت في استراحة. يضحّي الأبيض بفيل ورخّين ثم بالوزير، ويعطي كش مات بالقطع الصغيرة الثلاث الباقية. ويُقال إن الأسود استسلم قبل النهاية، وإن النقلات الأخيرة هي الختام الذي عرضه الأبيض.","c":{"0":"لندن، يونيو 1851. في تلك السنة كانت أول بطولة دولية للشطرنج في العالم تُقام في لندن. يلعب بالأبيض أدولف أندرسن، معلّم الرياضيات الألماني، وبالأسود ليونيل كيزيريتسكي الذي كان يعلّم الشطرنج في مقهى «لا ريجانس» في باريس. لم تكن هذه مباراة من البطولة، بل مباراة ودية لُعبت في استراحة. نشر كيزيريتسكي النقلات في مجلته الخاصة فانتشرت، وصارت هذه المباراة تُسمّى لاحقًا «المباراة الخالدة». لنشاهد معركة تمثّل عصرها، مليئة بالقطع التي تُرمى في الهجوم. يرافقك Musowl. في مايو من ذلك العام ارتفع في حديقة هايد بارك بلندن مبنى ضخم من الحديد والزجاج هو «القصر البلوري»، وافتُتح المعرض الكبير الذي جمع الاختراعات والبضائع الجديدة من أنحاء العالم. ففكّر لاعبو الشطرنج: «لنقم حدثًا عالميًا للشطرنج أيضًا»، وأُقيمت هذه البطولة الدولية بدعوة من ستونتون.","1":"يدفع الأبيض البيدق الذي أمام الملك مربعين. صار يراقب مربعَي الوسط d5 وf5، وانفتحت الطرق للفيل والوزير. قديمًا وحديثًا، هذه هي النقلة الأولى الأكثر شيوعًا. وُلد أندرسن في مدينة فروتسواف في بولندا اليوم (وكانت تُسمّى بريسلاو الألمانية). علّمه أبوه الشطرنج وهو في التاسعة. وكان في حياته اليومية مدرّسًا للرياضيات في مدرسة، ومعروفًا أيضًا بتأليف مسائل الشطرنج. وفي هذه البطولة هزم كيزيريتسكي في الدور الأول ثم فاز بالبطولة كلها.","2":"يلعب الأسود أيضًا e5. تتواجه البيادق وجهًا لوجه ولا يتخلّى الأسود عن الوسط. وانفتحت كذلك طرق الفيل والوزير الأسودين. وُلد كيزيريتسكي في تارتو في إستونيا اليوم. وكان هو أيضًا مدرّسًا للرياضيات في الأصل، لكنه انتقل إلى باريس وصار يعيش من الشطرنج، فيعطي دروسًا أو يلعب مباريات مقابل خمسة فرنكات في الساعة. فهذه إذن مباراة بين مدرّسَي رياضيات!","3":"f4! يقدّم الأبيض بيدقًا مجانًا: هذا هو «جامبيت الملك». إذا أخذه الأسود يغادر بيدقه في e5 الوسط، ويسهل على الأبيض أن يدفع بيدقًا إلى d4 أيضًا. في ذلك العصر كانت هذه الخطط التي تبدأ الهجوم مبكرًا محبوبة جدًا. لكن نقطة ضعفها أن المساحة أمام الملك الأبيض تنفتح. كان «غامبيت الملك» من أشهر الافتتاحيات في القرن التاسع عشر. ويُعدّ اليوم خيارًا فيه شيء من المخاطرة، ونادرًا ما يُرى في المباريات الجادة بين كبار اللاعبين.","4":"يقبل الأسود البيدق. البيدق في f4 يسدّ طريق الفيل الأبيض في c1، ويراقب أيضًا المربعين e3 وg3. صار للأسود بيدق زائد. أما اسم «المباراة الخالدة» فقد أطلقه عليها عام 1855 اللاعب النمساوي إرنست فالكبير.","5":"يُخرج الأبيض الفيل إلى c4. المربع f7 بجوار الملك الأسود ضعيف لأن الملك وحده يحميه. يصوّب الأبيض نحوه ليستطيع الهجوم في أي لحظة. ولعب 3.Bc4 هنا بدل 3.Nf3 هو شكل من «غامبيت الملك» يُسمّى «غامبيت الفيل».","6":"كش! لأن الأبيض دفع بيدق العمود f، كان القطر من h4 إلى e1 مفتوحًا. إذا اعترض الأبيض بـ g3 فسيأكله بيدق f4 ببساطة. على الأبيض أن يحرّك الملك.","7":"يتنحّى الملك إلى f1. الآن لم يعد الأبيض قادرًا على التبييت ولا على إخفاء ملكه في مكان آمن. في المقابل، خرج الوزير الأسود مبكرًا جدًا، فيستطيع الأبيض مطاردته وهو يُخرج قطعه. ورغم أنه خسر، أرسل كيزيريتسكي النقلات إلى أصدقائه في باريس ونشرها في مجلة «لا ريجانس» التي كان يحرّرها. فقد كانت المباراة الرائعة عنده أهمّ من الفائز.","8":"يقدّم الأسود هو أيضًا بيدقًا مجانًا. بـ b5 يستدرج فيل c4 ويبعده عن القطر الذي يصوّب نحو f7. سُمّيت هذه النقلة لاحقًا «جامبيت برايان المضاد»، وكانت نقلة هجومية يحب كيزيريتسكي استعمالها. لكن معظم اللاعبين اليوم يرون أن 4...b5 ليست نقلة سليمة؛ ففيها حيوية، لكنها لا تعطي مقابلًا كافيًا للبيدق.","9":"يأخذ الأبيض البيدق. غادر الفيل c4 فلم يعد يصوّب نحو f7. لكن الأبيض استعاد بيدقًا وعاد العدد متساويًا.","10":"يذهب الحصان الأسود إلى f6. يهاجم بيدق e4 ويساعد أيضًا في حماية الملك: مربع جيد. بدأ سباق إخراج القطع.","11":"يخرج الحصان الأبيض أيضًا إلى f3. يُخرج قطعة ويهدّد الوزير في h4 في الوقت نفسه: نقلة ممتعة جدًا. على الوزير أن يهرب، فيكسب الأبيض نقلة.","12":"يتراجع الوزير إلى h6. من هنا يراقب العمود h ويرى الرخ في h1 خلف بيدق الأبيض في h2. ما زال مربعًا آمنًا.","13":"بـ d3 يحمي الأبيض بقوة بيدق e4 الذي كان مهدَّدًا. وفي الوقت نفسه ينفتح طريق فيل c1. نقلة هادئة لا تُضيّع شيئًا.","14":"يذهب الحصان الأسود إلى h5. يحمي بيدق f4 ويخطّط للقفز إلى g3. القفز إلى g3 سيعطي كشًّا ويهاجم رخ h1؛ وإذا أخذه الأبيض ببيدق h2 ينفتح العمود h ويستطيع وزير h6 أخذ رخ h1. خطة حادّة إلى حدّ ما.","15":"يذهب الحصان الأبيض إلى h4. هذا الحصان يسدّ العمود h، فحتى لو قفز الحصان الأسود إلى g3 لم يعد رخ h1 قابلًا للأخذ. كما أنه يستعدّ للقفز إلى f5 لتهديد الوزير في h6.","16":"يذهب الوزير الأسود إلى g5 ويهاجم الحصان في h4. على الأبيض أن يقرّر: هل يحميه أم ينقله إلى مكان آخر؟","17":"يقفز الحصان إلى f5. وهو محميّ ببيدق e4، فهذا موقع قويّ جدًا. من هنا يهاجم بيدق g7 ويراقب المربعين h6 وd6. قطع الأبيض تقترب من الملك الأسود.","18":"بـ c6 يحاول الأسود طرد الفيل من b5. إذا هرب الفيل يستطيع الأسود توسيع الوسط ببيادقه. نقلة عادية ومعقولة.","19":"لكن الأبيض لا ينقذ الفيل ويلعب g4! مهدّدًا الحصان في h5. الأبيض مستعدّ لخسارة فيل كي يطارد قطع الأسود ويكسب وقتًا للهجوم: فكرة جريئة. بيدق g4 يحميه وزير d1 قطريًا. وتعدّ التحليلات اللاحقة هذه النقلة 10.g4 مبالغًا فيها قليلًا. ومع ذلك فقد ضيّق اندفاعها على الأسود أكثر فأكثر في المباراة الفعلية.","20":"الحصان المهاجَم في h5 يعود إلى f6. يقرّر الأسود أن أخذ الفيل الأبيض يمكن أن ينتظر. بيدق c6 ما زال يهاجم الفيل في b5.","21":"يذهب الرخ إلى g1. يحمي بيدق g4 ويستعدّ للقتال على العمود g. ما زال فيل b5 متروكًا ليؤخذ. يرى الأبيض أن مطاردة الوزير الأسود أهمّ من فيل واحد. وما زالت النقلة 11.Rg1 تُمدح كثيرًا بوصفها تضحية مقصودة، تترك الفيل يُؤخذ عن عمد.","22":"يأخذ الأسود الفيل. في العتاد صار الأسود متقدّمًا بفيل كامل، وهي أفضلية كبيرة. لكن ما عدا الوزير وحصانًا واحدًا، ما زالت قطع الأسود في مربعات البداية. من هنا يبدأ هجوم الأبيض. وقد حلّل اللاعب الألماني القوي هوبنر أن أخذ الفيل هنا كان خطأ الأسود الكبير، وأن دفع البيدق إلى h5 كان أفضل.","23":"h4! يطارد الأبيض بالبيدق الوزير الأسود في g5. بمجرد دفع البيادق، يقلّص الأبيض باستمرار الأماكن التي يمكن للوزير الأسود الوقوف فيها.","24":"يهرب الوزير إلى g6. ما زالت لديه بعض المربعات، لكنه بدأ يُحاصَر ببيادق الأبيض وحصانه.","25":"بـ h5 يطارد الأبيض الوزير مرة أخرى. كلما تقدّم بيدق أبيض، لا يستطيع الوزير الأسود إلا التراجع.","26":"يعود الوزير إلى g5. حصان f5 يراقب h6 والمربعات الأخرى مسدودة، فلم يبقَ له تقريبًا مكان غير هذا. الوزير الأسود يُحشر في الزاوية شيئًا فشيئًا.","27":"يذهب الوزير الأبيض إلى f3. إذا أخذ فيل c1 الآن بيدق f4، سيصبح وزير g5 مهاجَمًا ولن يجد تقريبًا مربعًا للهرب. إنها نقلة تنصب فخًّا للإمساك بالوزير.","28":"يعيد الأسود الحصان إلى g8 ليُخلي للوزير مربع الهرب f6. عودة حصان خرج من قبل إلى مربع بدايته علامة على أن الأسود في ورطة. في سباق إخراج القطع، الأبيض متقدّم كثيرًا.","29":"يأخذ الفيل بيدق f4، فيستعيد بيدقًا وهو يطارد الوزير في g5. وأخيرًا ينضمّ الفيل الأبيض أيضًا إلى المعركة.","30":"يهرب الوزير إلى المربع الذي أعدّه، f6. من هنا يرى قطريًا حتى بيدق b2، ويمكنه أيضًا التصويب نحو رخ a1 خلفه.","31":"يذهب الحصان الأبيض إلى c3. حصان c3 يسدّ أيضًا القطر من وزير f6 إلى b2. وبعد ذلك يخطّط للقفز إلى d5 لتهديد الوزير في f6.","32":"يُخرج الأسود الفيل إلى c5 ويهاجم رخ g1. أخيرًا يُخرج الأسود فيلًا وينضمّ إلى الهجوم. هل يذهب لجمع القطع أم يدافع عن الملك؟ كانت لحظة مهمة للأسود.","33":"الحصان إلى d5! يهدّد وزير f6، وهناك أيضًا قفزة إلى c7 تهاجم الملك والرخ معًا. لكن لأن الحصان غادر c3، انفتح من جديد طريق الوزير الأسود إلى b2. لا يحاول الأبيض حماية رخ g1 ولا بيدق b2. إنه مستعدّ لترك قطعه تؤخذ كي يهاجم الملك الأسود.","34":"يأخذ الوزير الأسود بيدق b2 ويصوّب الآن نحو رخ a1. الفكرة هي جمع قطع كثيرة والفوز بالعدد. لكن الوزير يبتعد أكثر فأكثر عن ملكه.","35":"الفيل إلى d6! الآن يترك الأبيض الرخّين كليهما ليؤخذا. في المقابل يسيطر الفيل على f8 وe7 ويسدّ طرق هرب الملك الأسود. لم يختر الأبيض عدّ القطع، بل نسج شبكة للإمساك بالملك الأسود. هذه هي نقطة التحوّل في المباراة.","36":"يأخذ الأسود رخ g1. صار للأسود فيل ورخ زائدان. لكن دراسات لاحقة تقول إن نقلة أخرى كانت أفضل هنا، وإن الأسود كان يملك دفاعًا أقوى.","37":"e5! نقلة بيدق هادئة، لكنها من الضربات الحاسمة. هذا البيدق يسدّ قطر الوزير من b2 إلى g7 ويسيطر أيضًا على f6. لم يعد الوزير الأسود قادرًا على العودة لمساعدة ملكه، ولا يستطيع حصان g8 الخروج إلى f6. يهدّد الأبيض الآن بأخذ g7 بالحصان مع كش، ثم الكش مات بالفيل في c7.","38":"يأخذ الأسود الرخ الآخر أيضًا مع كش. كان الصف الأول كله من a1 إلى f1 مفتوحًا. أخذ الأسود الرخّين ويتقدّم كثيرًا في العتاد.","39":"يتنحّى الملك إلى e2. لم يبقَ للأبيض من القطع الكبيرة إلا الوزير، ومعه حصانان وفيل. ومع ذلك، حول الملك الأسود للأبيض قطع أكثر بكثير من الأسود.","40":"يُخرج الأسود الحصان إلى a6 ليحمي c7. الغرض منع الكش مات الذي يأخذ فيه الحصان g7 مع كش، ويهرب الملك إلى d8، ثم يُنهي الفيل في c7. ويقال إن كيزيريتسكي استسلم تقريبًا هنا، وإن بقية النقلات عرضها الأبيض.","41":"الحصان يأخذ بيدق g7 مع كش! حصان g7 يهاجم الملك في e8. فيل d6 يسيطر على e7 وf8، لذلك لا يجد الملك أماكن كثيرة يذهب إليها.","42":"على الملك أن يهرب إلى d8. لا يستطيع البقاء في e8 ولا الذهاب إلى e7 أو f8؛ كان d8 المربع الوحيد الباقي.","43":"يضحّي الأبيض بالوزير في f6 مع كش! حتى آخر قطعة كبيرة تُعطى مجانًا. يعطي الوزير كشًّا قطريًا من f6 مرورًا بـ e7 إلى d8، ولا خيار للأسود إلا أخذه.","44":"يأخذ الأسود الوزير بحصان g8. لا مكان للملك ليهرب إليه، فلا توجد نقلة أخرى. لكن ابتعاد هذا الحصان بالذات هو ما يُكمل شبكة الكش مات.","45":"يذهب الفيل إلى e7. كش مات! حصان d5 يسيطر على e7 وc7، وحصان g7 يسيطر على e8، وقطع الأسود نفسها تسدّ c8 وd7. أعطى الأبيض فيلًا ورخّين وحتى الوزير، وفاز بثلاث قطع صغيرة فقط. ما زال لدى الأسود وزير ورخّان، لكن لا شيء منها يصل في الوقت المناسب. تعلّمنا هذه المباراة أن مدى عمل قطعك أهمّ من عددها، وهي من أشهر المباريات في تاريخ الشطرنج. ويقال إن اسمها أطلقه بعد بضع سنوات الأستاذ النمساوي فالكبير."}},"mimiaka":{"t":"مباراة الأذنين المحمرّتين","w":"هونينبو شوساكو","b":"إينوي غينان إنسيكي","ev":"مباراة في أوساكا (على ثلاثة أيام)","d":"1846","pl":"اليابان (أوساكا)","lead":"واجه شوساكو، وهو في السابعة عشرة (4 دان)، غينان (8 دان)، أحد أقوى لاعبي عصره. يُروى أن أذني غينان احمرّتا عند النقلة 127، ومن هنا جاء الاسم. لم يكن هناك كومي آنذاك: فاز الأسود بنقطتين.","c":{"0":"أوساكا، 1846. الأسود: شوساكو، 17 عامًا، 4 دان. الأبيض: إينوي غينان إنسيكي، 8 دان، نحو 48 عامًا، من أقوى لاعبي عصره، وقد نافس هونينبو جووا على منصب ميجين غودوكورو. في اليوم السابق بدأ شوساكو بحجرين مسبقين كما يقتضي فارق الدرجة، لكن غينان أدرك قوته سريعًا فأوقف تلك المباراة، ولعب شوساكو هذه بالأسود مباشرة. لم يكن هناك كومي، فلا يُحسب إلا ما على اللوحة من أرض. لنتابع هذه المباراة ذات الأيام الثلاثة نقلةً نقلة. في عصر إيدو كان الغو يقوم على أربعة «بيوت»: هونينبو وإينوي وياسوي وهاياشي. وكانت حكومة الشوغون تدفع لها أجرًا لتلعب الغو وتعلّمه. كان شوساكو من بيت هونينبو، وغينان من بيت إينوي، فكانت هذه المباراة تحمل أيضًا شرف بيتين. وفي العام نفسه 1846 دخل القائد الأمريكي بيدل خليج أوراغا بسفينتين حربيتين يطلب التجارة، فرفضت حكومة الشوغون، وذلك قبل مجيء بيري بسبع سنوات. وفي أوروبا اكتُشف كوكب نبتون بعد هذه المباراة بنحو أسبوعين.","1":"الأسود 1 على نقطة 3-4 في الأعلى يمينًا (R16). توازن بين أرض الزاوية وإمكان الامتداد على الجانبين. كان شوساكو يحب نقاط 3-4 حين يلعب بالأسود. وُلد شوساكو عام 1829 في جزيرة إنّوشيما في بحر سيتو الداخلي (وهي اليوم جزء من مدينة أونوميتشي في هيروشيما). وكان أبوه يخدم أسرة أسانو، سادة قلعة ميهارا. كان قويًا جدًا في الغو منذ طفولته، وفي عام 1837، وهو في نحو الثامنة، ذهب إلى إيدو ليصبح تلميذًا لهونينبو جووا.","2":"الأبيض 2 على نقطة 3-4 في الأعلى يسارًا (D17). في الافتتاح تأتي الزوايا أولًا لأن الأرض تُصنع فيها بأسهل طريقة. يتقاسم الطرفان الزوايا الفارغة.","3":"الأسود 3 على نقطة 3-4 في الأسفل يمينًا (Q3). يتناسق مع R16 بحيث يصبح الجانب الأيمن بين الزاويتين لاحقًا منطقة سوداء كبيرة.","4":"الأبيض 4 (P17) يقترب من زاوية الأسود العليا اليمنى. لو لعب الأسود هناك مرة أخرى لصارت الزاوية متينة جدًا، لذا يتحرك الأبيض أولًا. يستطيع الأسود أن يرد أو أن يأخذ نقطة كبيرة أخرى.","5":"الأسود 5 لا يرد بل يأخذ نقطة 3-4 في الأسفل يسارًا (C4). ثلاث نقاط 3-4 في النقلات 1 و3 و5 نمط يتكرر كثيرًا في مباريات شوساكو بالأسود. التعامل مع P17 يمكن أن ينتظر. صار هذا الترتيب لحركات الأسود 1 و3 و5 يُسمّى لاحقًا «افتتاح شوساكو». لم يخترعه شوساكو، لكنه فاز به في مباريات كثيرة حتى حمل اسمه. وهو أشهر افتتاح للأسود في زمن ما قبل الكومي.","6":"الأبيض 6 (C14) على الجانب الأيسر. المعتاد الاقتراب من الزاوية السفلى اليسرى، لكن غينان يبني على الجانب مع D17. نقلة غير مألوفة قليلًا تمنع مسبقًا C4 من التمدد صعودًا. وُلد غينان عام 1798. كان يتمنى بشدة أن يصبح «ميجين غودوكورو»، أعلى منصب في الغو، ونازع هونينبو جووا عليه سنوات طويلة. وحين اعتزل جووا عام 1839 حاول مرة أخرى، لكنه خسر المباراة الأولى من مباراة تحدٍّ أمام شووا من بيت هونينبو فتخلى عن حلمه. فهذه أيضًا مباراة يختبر فيها لاعب عظيم لم يصبح ميجين أبدًا الأملَ الشاب لبيت هونينبو.","7":"الأسود 7 (E4) يغلق الزاوية السفلى اليسرى بحجر ثانٍ، فتصبح شبه مضمونة للأسود. وبالدفاع قبل اقتراب الأبيض يحدّ أيضًا من فعالية الأبيض 6 على اليسار.","8":"الأبيض 8 (R5) يقترب من Q3. مع نقطتي 3-4 سوداوين في طرفي الجانب الأيمن، يحتاج الأبيض موطئ قدم هناك. تبدأ معركة طويلة في الأسفل يمينًا.","9":"الأسود 9 (Q15) يدافع في الأعلى يمينًا. وُضع تحت P17 فيقوّي الزاوية ويدفع P17 نحو الحافة العليا الضيقة. يريد الأسود أن يبقى الجانب الأيمن من نصيبه. الحركة 9 للأسود هي الحركة الشهيرة التي سُمّيت لاحقًا «كوسومي شوساكو» (خطوة قطرية). فبدل أن يرد الأسود على P17 مباشرة، يتقدم خطوة قطرية ليحمي الزاوية والجانب الأيمن. ويُروى أن شوساكو قال إنه ما دام حجم اللوح لا يتغير فلن تصبح هذه الكوسومي حركة سيئة أبدًا. وفي زمن الكومي وُصفت أحيانًا بأنها بطيئة، لكن الذكاء الاصطناعي للغو قيّمها جيدًا في السنوات الأخيرة فعاد الاهتمام بها.","10":"الأبيض 10 (O4) هو «التايشا»: يغطي أحجار الأسود قطريًا من مسافة قصيرة. تفرعاته كثيرة حتى إن مثلًا قديمًا يتحدث عن «وجوه التايشا المئة»، وكان اختصاص غينان. كيف سيواجه شوساكو ابن السابعة عشرة سلاح خصمه المفضل؟ بدأت دراسة التايشا نحو عشرينيات القرن التاسع عشر وازدهرت في عهد تينبو (الثلاثينيات والأربعينيات). ويُروى أن بيت إينوي كان يحتفظ بأبحاث سرية عنها: فقبل أحد عشر عامًا، في «مباراة الدم»، لعب أكابوشي إنتيتسو تلميذ غينان داخل التايشا حركة جديدة من أسرار بيت إينوي. والتفرع الجديد الذي يلعبه غينان في هذه المباراة يُعدّ نتيجة متكافئة، وما زال جوسيكي حتى اليوم.","11":"بالنقلة 11 (Q5) يلتصق الأسود بـR5 ويقبل القتال. كان الدفاع الهادئ ممكنًا، لكن شوساكو يختار المسار الكثير التفرعات. تبدأ مبارزة في الحساب.","12":"الأبيض 12 (Q4) يقتحم بين أحجار الأسود ليفصل Q3 عن Q5 ويُضعف أحدهما.","15":"بالنقلتين 13 (P4) و15 (P3) يصل الأسود أحجاره السفلية بإحكام. دخل الأبيض 14 (R4) الزاوية فصارت متنازعًا عليها. يفضّل الأسود البقاء متصلًا وقويًا ولو تنازل عن شيء من الزاوية. ما زلنا هنا على طريق جوسيكي التايشا الذي درسه لاعبو ذلك الزمن بعمق. كلاهما يعرف الأشكال جيدًا، فتمضي حتى هذه السلسلة الصعبة بلا تردد.","17":"مع الأبيض 16 (P5) والأسود 17 (Q6) تنمو الأحجار صعودًا. يُطل الأسود برأسه نحو الجانب الأيمن، ويضغط الأبيض من الأعلى ليحبسه.","19":"الأبيض 18 (R3) يضيف حجرًا في الزاوية ليعيش، والأسود 19 (O3) يكبح الأبيض في الجانب السفلي. خطة الأسود: ترك الزاوية مقابل القوة في الخارج أسفلًا ويمينًا.","20":"الأبيض 20 (P6) يغطي Q6 من الأعلى محاولًا حبس الأسود منخفضًا على اليمين. إن لم يخرج الأسود صعودًا فستعيش أحجاره اليمنى بالكاد دون مكسب يُذكر. بعد هذه المباراة بثلاث سنوات، ابتداءً من 1849، شارك شوساكو في «مباريات القلعة» (أوشيروغو)، وهي المباريات الرسمية في قلعة إيدو، وترك سجلًا من 19 فوزًا في 19 مباراة. لكن في عام 1862، حين انتشرت الكوليرا في إيدو، تولّى رعاية المرضى في بيت هونينبو فأُصيب بها هو أيضًا وتوفي في الرابعة والثلاثين.","21":"بالنقلتين 21 (Q7) و23 (Q8) يزحف الأسود صعودًا على الجانب الأيمن بحثًا عن مخرج، بينما يضغط الأبيض 22 (P7) بجانبه. السلسلة السوداء الطويلة على الخط الثالث منخفضة وأرضها قليلة، لكنها حية بوضوح.","24":"الأبيض 24 (N4) يغلق من الخارج حجري الأسود O3–P3 في الأسفل. صارت أحجار الأسود تتجه اتجاهين، يمينًا وأسفل، وحماية الاثنين معًا تزداد صعوبة.","25":"الأسود 25 (N3) يمتد خطوة في الأسفل. تقول الدراسات اللاحقة إن نقلة أخرى تعتمد على «السلّم» كانت أفضل، لذا تُعدّ هذه هفوة الأسود الصغيرة في المباراة. تبقى أحجار الأسود السفلية منخفضة وسهلة التطويق، فتمنح الأبيض فرصة للهجوم المضاد. حتى شوساكو قد يضلّ داخل الشكل المفضل لخصمه. بهذه الحركة خرج الأسود قليلًا عن الطريق المدروس جيدًا لجوسيكي التايشا.","26":"الأبيض 26 (P8) يغطي أحجار الأسود اليمنى من الأعلى. لا يستطيع الأسود الخروج صعودًا، وهو مهدد بالحبس في الأسفل أيضًا.","28":"الأبيض 28 (M3) يلتصق مباشرة بـN3: نقلة قاسية. توقف تمدد الأسود في الأسفل وتسلبه مساحة الحياة، وتجبره على إضافة أحجار. عاقب غينان هفوة النقلة 25 فورًا.","30":"بعد الأسود 29 (M2) يلتف الأبيض 30 (L2) من الأسفل أيضًا. لا تستطيع أحجار الأسود السفلية الخروج لا نحو الخارج ولا جانبًا. لتعيش عليها الاتصال بالزاوية السفلى اليمنى، فيبدأ سباق أسر حول الزاوية.","31":"الأسود 31 (M4) نقلة مهمة. بدل الاندفاع إلى معركة الزاوية يصنع أولًا نقطة يجب على الأبيض الرد عليها. إنها تحضير للكو الآتي حتمًا.","33":"بالنقلة 33 (R2) يبدأ سباق الأسر في الزاوية السفلى اليمنى. أمّن الأبيض 32 (L3) أحجاره السفلية، فلا بد للأسود من مهاجمة أحجار الأبيض في الزاوية. إن أسرها عاشت أحجاره السفلية، وإلا فهي في خطر.","35":"الأبيض 34 (S2) والأسود 35 (S1): نقلات دقيقة على الخطين الأول والثاني في الزاوية. يقلّص كل طرف حريات الآخر (النقاط الفارغة حول المجموعة) ليأسر أولًا.","36":"الأبيض 36 (N2). قبل بدء الكو يلعب الأبيض أولًا قرب أحجار الأسود السفلية. حتى لو ربح الأسود الكو سيكسب أقل قليلًا: توقيت جيد.","40":"الأبيض 40 (R1) يأسر حجرًا فيتكوّن الكو أخيرًا. في الكو لا يجوز لمن أُسر حجره للتو أن يستردّه فورًا. على الأسود أولًا أن يلعب تهديدًا في مكان آخر يجب على الأبيض الرد عليه، ثم يستردّ. يفوز من يملك تهديدات أكثر.","41":"الأسود 41 (O5) أول تهديد كو. تجاهله يضع أحجار الأبيض في الأسفل يمينًا في ورطة، فيرد الأبيض بـ42 (N5)، ويستردّ الأسود بـ43 (R2). يكلّف قليلًا لكنه ضروري.","44":"الأبيض 44 (S7) تهديد الكو الأبيض. لُعب بجوار أحجار الأسود اليمنى فأجبر الأسود على الرد بـ45 (S8)، ثم استرد الأبيض بـ46 (R1). كل تهديد يحسم جزءًا آخر من اللوحة.","47":"الأسود 47 (M5)، الأبيض 48 (N6)، الأسود 49 (R2): تهديد آخر واسترداد آخر. حول أحجار الأبيض السفلية يضيف الأسود أحجارًا في الخارج شيئًا فشيئًا.","50":"الأبيض 50 (R7) يقطع أحجار الأسود اليمنى: تهديد كبير. عادة كان الأسود سيرد، لكنه يقدّم الكو. تحدث مقايضة كبيرة: يكسب الأبيض على الجانب الأيمن، ويأخذ الأسود الزاوية السفلى اليمنى.","51":"الأسود 51 (P2) يأسر حجرًا ويربح الكو. تصبح الزاوية السفلى اليمنى أرضًا حية للأسود، وتنجو أحجاره السفلية. في المقابل يتابع الأبيض بـ52 (R8) ليشطر أحجار الأسود اليمنى نصفين.","53":"الأسود 53 (R10) فكرة بارعة قلّما يجدها أحد. يأتي لنجدة الجزء العلوي من أحجار الأسود اليمنى المنقسمة من الجهة الأخرى لأحجار الأبيض. لو رد الأسود ردًا بسيطًا لأخذ الأبيض جزءًا كبيرًا من الجانب الأيمن.","56":"الأبيض 54 (S10) والأسود 55 (S11) والأبيض 56 (S9): يعيش الأبيض على الحافة اليمنى، ويكبحه الأسود من الأعلى محتفظًا بالنصف العلوي من الجانب.","59":"بعد الأسود 57 (M6) والأبيض 58 (N7) يصل الأسود 59 (R11) أحجاره اليمنى بإحكام. صار جانب الأسود الأيمن آمنًا من أعلاه إلى أسفله. تبدو المقايضة الكبيرة متكافئة تقريبًا.","60":"الأبيض 60 (S3) نقلة كبيرة. تقلّص أرض الأسود في الزاوية وتقوّي أحجار الأبيض، وتتيح لاحقًا لعب 62 (M1) كنقلة يجب على الأسود الرد عليها.","63":"الأبيض 62 (M1) يأسر حجرًا والأسود 63 (O1) يصل: انتهت المعركة الطويلة في الأسفل يمينًا مؤقتًا. للأبيض أرض في الأسفل، وللأسود جدار سميك على اليمين. وبسبب النقلة 25 جزئيًا يُعتقد أن الأبيض لعب أفضل حتى الآن. لكن جدار شوساكو سيعمل كثيرًا لاحقًا في الوسط.","65":"الأبيض 64 (G3) يمتد نحو يسار الجانب السفلي ليكبّر منطقته أكثر. والأسود 65 (G5) يغطيه من الأعلى كي لا تكبر صعودًا. يتضح النمط: الأبيض يأخذ الأرض، والأسود القوة الخارجية.","66":"الأبيض 66 (C9) على الجانب الأيسر. مع الأبيض 6 (C14) يبني هناك أيضًا إطارًا أبيض. يجمع الأبيض الأرض في الأسفل واليسار.","67":"الأسود 67 (L17) على الجانب العلوي. مستندًا إلى جداره السميك يسعى إلى إطار كبير — منطقة واسعة قد تصير أرضًا — من الأعلى نحو الوسط. وفي الوقت نفسه يضع P17 في كماشة.","69":"الأبيض 68 (J17) يدخل يسار L17 ليشطر إطار الأسود العلوي. والأسود 69 (Q17) يلتصق بـP17 فيهاجمه ويقوّي الزاوية.","70":"الأبيض 70 (O10) يتوسط جدار الأسود الأيمن وإطاره العلوي. يمنع الإطار من الالتحام عبر الوسط ويحاول الاتصال بأحجار الأبيض اليمنى.","72":"الأبيض 72 (P13) نقلة رائعة. وُضع فوق جدار الأسود مباشرة فأنشأ مأوى أبيض في قلب إطار الأسود. حتى لو طارده الأسود يستطيع الأبيض الإفلات بخفة. تقلصت آمال الأسود في الأعلى بهذه النقلة.","73":"الأسود 73 (P12) يسدّ أسفل P13 كي لا يتصل بأحجار الأبيض اليمنى. ثم يدخل الأبيض 74 (Q18) الزاوية العليا اليمنى ليقتطع من أرضها أيضًا.","77":"بعد الأسود 75 (R18) الذي يحمي الزاوية، يأتي الأبيض 76 (O13) والأسود 77 (N11). يغطي الأسود أحجار الأبيض في الوسط ليكسب الأرض بالهجوم. من هنا حتى النقلة 100 تقريبًا لا يتهاون غينان أبدًا ويتفادى كل الهجمات.","79":"الأبيض 78 (N10) يصل أحجاره في الوسط، والأسود 79 (O16) يقوّي الأعلى. لم يكسب الأسود كثيرًا من الهجوم، لكنه يحتفظ بأرض الأعلى بأمان.","80":"بالنقلتين 80 (Q12) و82 (Q13) يصل الأبيض أحجارًا بجوار جدار الأسود مباشرة. ومع شكل متين داخل إطار الأسود ستكون أرض الأسود في الأعلى يمينًا أصغر من المأمول.","83":"الأسود 83 (H3) يدخل أرض الأبيض السفلية التي كبرت كثيرًا. ثم الأبيض 84 (H2) والأسود 85 (J2): معركة دقيقة حول ما إذا كان الأسود سيعيش في الداخل أو يهرب إلى الخارج.","87":"الأبيض 86 (J3) والأسود 87 (H4) والأبيض 88 (K2): يصل الأسود أحجاره المتسللة بـG5 ويُخرجها. تتقلص أرض الأبيض السفلية ويزيد الأسود سُمكه في الوسط.","89":"الأسود 89 (F17) يقترب من D17 ويضع حجرًا أسود يسار الجانب العلوي، فيكبح تمدد الأبيض. ويحاول الأبيض 90 (M17) و92 (N17) إحياء أحجاره بين أحجار الأسود في الأعلى.","93":"بالنقلتين 93 (M18) و95 (N16) يضغط الأسود أحجار الأبيض العليا من فوق ومن تحت. لا يستطيع الأبيض أن يعيش إلا منخفضًا على الخطين الأول والثاني، وبأرض قليلة جدًا.","96":"منذ الأبيض 96 (R14) تبدأ معركة دقيقة بجوار زاوية الأسود العليا اليمنى. يفصل الأبيض جدار الأسود عن الزاوية ليُضعف أحجاره. يرد الأسود بـ97 (Q14)، ويتقدم الأبيض على الحافة اليمنى بـ98 (R12) و100 (S12).","101":"بالنقلتين 101 (T12) و103 (T13) ينزل الأسود إلى الخط الأول على الحافة اليمنى فيضيّق مساحة حياة الأبيض. تبدو نقلات الحافة صغيرة، لكنها هنا تحسم الحياة والموت.","104":"الأبيض 104 (Q10) يضرب نقطة ضعف في جدار الأسود الأيمن. بعد الأسود 105 (Q11) والأبيض 106 (P11) يذهب الأسود للأسر بالنقلة 107.","107":"الأسود 107 (P10) يأسر حجرًا أبيض. صار جدار الأسود الأيمن متصلًا بإحكام وآمنًا. ويخرج الأبيض 108 (O11) و110 (P9) نحو الوسط لحماية أحجاره القريبة من الجدار.","112":"منذ الأبيض 112 (L18) تسارع أحجار الأبيض العليا إلى الحياة. ويطوّقها الأسود بـ113 (K18) و115 (K17) و117 (K19) كي لا تخرج.","118":"الأبيض 118 (M19) يأسر حجرًا فتعيش مجموعته العليا. العيش داخل إطار الأسود يقلّص أرضه كثيرًا. لعب غينان حتى الآن ممتاز.","120":"الأسود 119 (D18) يجسّ زاوية الأبيض العليا اليسرى، ويرد الأبيض بـ120 (C17). لا يريد الأسود الزاوية، بل تقوية يسار الجانب العلوي لكسب أرض.","122":"الأسود 121 (F15) يرتّب شكله من الأعلى نحو الوسط. والأبيض 122 (C6) يلعب بجوار زاوية الأسود السفلى اليسرى ليقتطع من أرضها شيئًا فشيئًا.","124":"الأسود 123 (G2) والأبيض 124 (J1) والأسود 125 (F3): تُحسم الحدود يسار الأسفل. يأسر الأبيض هناك حجرًا ويحافظ على أرضه.","126":"الأبيض 126 (J5). الأبيض سميك في الأسفل ومستعد للتقدم نحو الوسط. بأرضه في الأسفل واليسار ومجموعته الحية في الأعلى يمينًا يتقدم الأبيض. يُقال إن معظم المحترفين الحاضرين رأوا الأبيض متقدمًا. لن يلحق الأسود بنقلات عادية.","127":"هذه هي نقلة «الأذنين المحمرّتين» الشهيرة، الأسود 127 (K11). يُقال إن هذا الحجر في وسط اللوحة يعمل في أربعة اتجاهات معًا: صعودًا يوسّع إطار الأسود، ونزولًا يوقف سُمك الأبيض، ويمينًا يسند جدار الأسود، ويسارًا يصد تمدد الأبيض. نقلة واحدة بأربع مهام. ومن هنا تبدأ المباراة، التي بدت في صالح الأبيض، بالميل تدريجيًا نحو الأسود.","128":"عندما لُعبت النقلة 127 لاحظ طبيب يراقب قريبًا أن أذني غينان احمرّتا. لم يكن يعرف الكثير عن الغو، لكنه يُروى أنه رأى في ذلك علامة اضطراب وتوقّع فوز الأسود. وبينما ظن المحترفون أن الأبيض أفضل، التقطت عين الطبيب وحدها نقطة التحول. الأبيض 128 (E18) يدافع عن الزاوية العليا اليسرى.","131":"بعد أن يقوّي الأسود يسار الأعلى بـ129 (F18)، يدخل الأسود 131 (D10) إطار الأبيض على الجانب الأيسر. ولأن الحجر 127 يسند الوسط يستطيع الأسود الاقتحام بأمان.","136":"بالنقلتين 133 (E10) و135 (D12) تتسلل أحجار الأسود اليسرى بين أحجار الأبيض وتتخذ شكلًا. ويأتي الأبيض 136 (J10) إلى الوسط ليُضعف أثر الحجر 127، فلا يمكنه ترك الوسط للأسود.","140":"الأسود 137 (H7) يغطي أحجار الأبيض السفلية، ويحاول الأبيض 138 (G10) و140 (F8) وصل أحجاره يسار الوسط. في الوسط تتشابك الأحجار ولكلا الطرفين نقاط ضعف.","143":"الأبيض 142 (E2) يتسلل إلى زاوية الأسود السفلى اليسرى. ويصل الأسود 143 (D7) و145 (D6) أحجاره وعينه على أحجار الأبيض اليسرى وعلى المتسلل في الزاوية معًا.","147":"الأسود 147 (K10) يمتد مباشرة إلى الأسفل من الحجر 127 فيشطر أحجار الأبيض في الوسط يمينًا ويسارًا. هنا يبدأ الحجر 127 في إظهار قوته الحقيقية.","150":"الأبيض 148 (K9) والأسود 149 (L9) والأبيض 150 (J11): يحاول الأبيض وصل أحجار الوسط، ويقطعها الأسود عن الأسفل. ويحط الأبيض 150 بجوار الحجر 127 مباشرة ليدخل وسط الأسود أيضًا.","155":"من الأسود 151 (J9) إلى الأسود 155 (K12) يضغط الأسود أحجار الأبيض في الوسط من الجهتين. الأسود 155 يتصل فوق الحجر 127 فيوحّد وسط الأسود مع الأعلى. المبادرة في الوسط للأسود.","160":"بعد الأبيض 156 (C5) والأسود 157 (D5) يلعب الأبيض 158 (J12) و160 (H8). يحمي أحجاره في الوسط ويستهدف ضعفًا لدى الأسود في الأسفل يسارًا. ما زالت المباراة متقاربة ولا يمكن لأحد التهاون.","162":"الأسود 161 (B8) يدخل تحت أحجار الأبيض اليسرى. والأبيض 162 (D13) يغطي أحجار الأسود اليسرى من الأعلى ليضيّق عليها.","167":"بعد تقوية الوسط بـ163 (G12) و165 (J13) يأتي الأسود 167 (C2) نقلة دقيقة تحمي الزاوية السفلى اليسرى. لو أُهملت لاستطاع حجر الأبيض 142 (E2) تهديد الزاوية. يزيل الأسود الخطر أولًا ويبني موقفًا يصعب خسارته.","169":"الأبيض 166 (E17) و168 (F16) يحاولان قطع أحجار الأسود في الأعلى يسارًا. يرد الأسود بـ169 (G16) و171 (G17) واصلًا أحجاره العليا بإحكام.","175":"الأسود 175 (G4) يأسر حجرًا أبيض. تنجو أحجار سوداء داخل منطقة الأبيض السفلية، فأرضها أصغر مما بدت. يضيق الفارق تدريجيًا.","180":"الأبيض 176 (M11) والأسود 177 (L13) والأبيض 178 (J6) والأسود 179 (M10) والأبيض 180 (M13): يمين الوسط أيضًا يضع الأبيض أحجارًا في إطار الأسود ليقلّصه. يرد الأسود محوّلًا الوسط كله إلى أرضه.","187":"من الأسود 183 (K13) إلى 187 (M14) يضغط الأسود من الأعلى على أحجار الأبيض في الوسط ويبعدها عن الأعلى. يكافح الأبيض ليعيش، لكن جدار الأسود سميك والمعركة شاقة عليه.","195":"من الأبيض 190 (G14) إلى 194 (M9) يوسّع الأبيض منافذ أحجاره في الوسط. ويقتحم الأسود 195 (L10) بينها ليكسر شكلها.","199":"مع الأسود 199 (K7) تهدأ معركة الوسط. تنجو أحجار الأبيض في الوسط بالكاد، لكن الأسود كسب أرضًا في الطريق وصارت المباراة تميل إليه. تأتي الآن النهاية: تثبيت الحدود، حيث تحسم نقطة أو نقطتان كل شيء.","208":"الأسود 203 (E19) و205 (F2) والأبيض 208 (R19): تُلعب نقلات النهاية على الحواف من الأكبر إلى الأصغر. في النهاية من المهم لعب النقلات التي يجب على الخصم الرد عليها أولًا.","212":"بالنقلتين 212 (D19) و216 (F19) يأسر الأبيض أحجارًا سوداء على الحافة العليا، ويعوّض الأسود في مكان آخر بـ213 (G11) و217 (G19). لا يتراجع أحد.","225":"الأسود 225 (L6) يأسر حجرًا أبيض ويواصل اقتطاع أرض الأبيض في منتصف الأسفل. تقترب المعركة الكبيرة الأخيرة: كو في الوسط.","228":"الأبيض 228 (N12) يأسر حجرًا فيصنع كو في الوسط. لأكثر من 80 نقلة سيتبادل الطرفان الأسر في M13 وN13. كل تهديد يُحدث مقايضة صغيرة في مكان ما. يبدأ الكو الطويل جدًا الذي سيحسم المباراة.","236":"الأبيض 236 (T8) يأسر حجرًا في منتصف الكو. يرى بعض المحللين أن إغلاق الكو هنا كان سيقلص الفارق. في الكو الطويل تحدد المقايضات المختارة النقطة أو النقطتين الأخيرتين.","262":"بالنقلتين 262 (T1) و266 (S4) يأسر الأبيض أحجارًا سوداء في الزاوية السفلى اليمنى. في الأثناء استرد الأسود في مكان آخر، ويستمر الكو مع مكاسب وخسائر لدى الطرفين.","275":"الأسود 275 (T14) يأسر حجرين أبيضين، وهذه المقايضة على الحافة العليا اليمنى لصالحه. وبجمع مقايضات الكو يحافظ الأسود على تقدمه الطفيف.","299":"الأسود 299 (J16) يأسر أربعة أحجار بيضاء دفعة واحدة. زال تهديد الأبيض في الأعلى وصار أعلى الأسود آمنًا. تجاوز الأسود آخر أزمة كبيرة في الكو.","311":"الأسود 311 (M13) يغلق الكو أخيرًا. انتهى كو الوسط الذي دام أكثر من 80 نقلة. وعبر كل المقايضات حافظ الأسود على تقدمه. لم تبق إلا نقلات نهاية صغيرة.","321":"من الأسود 317 (N1) إلى 321 (M2) تُثبَّت آخر الحدود في الأسفل. يواصل الطرفان اللعب بدقة حتى النهاية لكسب ولو نقطة واحدة.","325":"تنتهي المباراة بعد 325 نقلة، ويُظهر العدّ تقدّم الأسود بنقطتين. تعثّر الأسود قليلًا في التايشا المفضّلة لدى غينان في البداية، وكان الأبيض يُعدّ أفضل حتى منتصف اللعب. قلب شوساكو المجرى بحجر النقلة 127، وصمد في الكو الطويل، وحافظ على تقدم ضئيل. يُروى أن غينان قال لاحقًا إن قوة شوساكو لم تكن دون مستوى 7 دان. صنعت هذه المباراة اسم شوساكو، وصار لاحقًا وريث بيت هونينبو. التايشا في الافتتاح، ونقلة الأذنين المحمرّتين 127، والكو الطويل في النهاية: هذه أبرز محطات هذه المباراة العظيمة."}},"evergreen":{"t":"المباراة دائمة الخضرة","w":"أدولف أندرسن","b":"جان دوفرين","ev":"مباراة ودية (ليست في بطولة)","d":"1852","pl":"ألمانيا (على الأرجح برلين)","lead":"أندرسن، صاحب المباراة الخالدة، لعب هذه التحفة الأخرى بعد عام. في اللحظة التي يهدّد فيها الأسود بالكش مات، يحرّك الأبيض رخًا بهدوء، ثم يضحّي بالوزير وينهي بكش مزدوج. تُسمّى \"دائمة الخضرة\" لأنها لا تذبل أبدًا.","c":{"0":"ألمانيا، 1852. يلعب بالأبيض أدولف أندرسن، الذي فاز ببطولة لندن في السنة السابقة وكان يُعدّ أقوى لاعب في العالم. ويلعب بالأسود صديقه جان دوفرين، الذي كتب لاحقًا كتابًا لتعليم الشطرنج قرأه كثير من الناس. كانت مباراة ودية لا مباراة بطولة؛ ويُعتقد أنها لُعبت في برلين، لكن لا يوجد سجل مؤكد. إنها مباراة عظيمة أخرى وُلدت بعد «المباراة الخالدة» بسنة. ويقال إن اسمها جاء من البطل اللاحق شتاينتس، الذي امتدحها بوصفها «الورقة دائمة الخضرة في إكليل غار أندرسن». لنشاهدها مع Musowl. وكتب شتاينتس هذه الكلمات عام 1879، العام الذي توفي فيه أندرسن، في مقال صحفي يستذكره.","1":"يدفع الأبيض البيدق الذي أمام الملك مربعين. صار يراقب d5 وf5 في الوسط، وانفتحت طرق الفيل والوزير.","2":"يلعب الأسود أيضًا e5. يواجه بيدق الأبيض في الوسط ولا يتراجع. وفي العام نفسه، 1852، نشر أندرسن أيضًا كتابه الثاني في مسائل الشطرنج. وبعد فوزه بالبطولة في العام السابق صار أكثر لاعب تتجه إليه الأنظار في أوروبا.","3":"يذهب الحصان الأبيض إلى f3. يُخرج قطعة ويهاجم بيدق الأسود في e5. على الأسود أن يحمي هذا البيدق.","4":"يُخرج الأسود الحصان إلى c6 ليحمي بيدق e5. يدافع وهو يُخرج قطعة: نقلة لا تُضيّع شيئًا.","5":"يذهب الفيل الأبيض إلى c4. يصوّب نحو f7 بجوار الملك الأسود. f7 مربع ضعيف لا يحميه إلا الملك.","6":"ويُخرج الأسود بالمثل الفيل إلى c5 ويصوّب نحو f2 الأبيض. للطرفين الشكل نفسه؛ حتى الآن البداية هادئة جدًا. وحتى هنا هذه هي «اللعبة الإيطالية» (جوكو بيانو، أي «اللعب الهادئ»)، وهي بداية مسجّلة منذ زمن بعيد جدًا.","7":"b4! يقدّم الأبيض بيدقًا مجانًا: هذا هو «جامبيت إيفانز». يقال إن مبتكره قبطان سفينة بريطاني اسمه إيفانز، وكان رائجًا جدًا في ذلك العصر. إذا أخذه الأسود بالفيل، يدفع الأبيض بيادقه إلى c3 وd4، فيكسب الوقت ويستولي على الوسط. وُلد ويليام ديفيس إيفانز في ويلز. التحق في شبابه بالبحرية، ثم صار قبطان سفينة تنقل البريد. ويُقال إنه ابتكر هذا الغامبيت في منتصف عشرينيات القرن التاسع عشر، وجعله مشهورًا حين هزم في لندن اللاعب القوي ماكدونيل. وكان مخترعًا أيضًا: إذ ابتكر نظام أضواء بثلاثة ألوان حتى لا تتصادم السفن ليلًا.","8":"يأخذ الأسود البيدق بالفيل. إنها نقلة تقبل الهدية، لكن لأن الفيل تحرّك، يستطيع الأبيض الآن مطاردته وأخذ زمام المبادرة.","9":"بـ c3 يهدّد الأبيض الفيل في b4. وفي الوقت نفسه يمهّد للنقلة التالية d4.","10":"يتراجع الفيل إلى a5. من a5 يرى قطريًا حتى e1، ويصوّب نحو بيدق c3 من الجانب.","11":"d4! يدفع الأبيض بيدقًا إلى الوسط. يصطدم ببيدق الأسود في e5 ويحاول أن يجعل وسط الرقعة للأبيض. الآن تستطيع قطع الأبيض الخروج واحدة تلو الأخرى. التخلّي عن بيدق مقابل كسب الوقت والمركز: تلك هي فكرة غامبيت إيفانز كلها.","12":"يأخذ الأسود بيدق d4. صار للأسود بيدقان زائدان. لكنه لم يبيّت بعد، ولم يُخرج إلا قليلًا من القطع.","13":"يبيّت الأبيض. صار الملك آمنًا في الزاوية، والرخ سيستطيع قريبًا دخول المعركة. حتى مع نقص بيدقين، الأبيض متقدّم كثيرًا في سرعة إخراج القطع.","14":"يلعب الأسود d3. يتقدّم البيدق مربعًا ويدقّ إسفينًا في معسكر الأبيض. يصبح هذا البيدق شوكة صغيرة تعيق قطع الأبيض. في هذه الوضعية دُرست نقلات أخرى كثيرًا، لكن الأسود اختار نقلة غير مألوفة قليلًا. كانت النقلة 7...d3 من النقلات المفضلة لدى دوفرين؛ فهي تمنع حصان الأبيض من الخروج إلى c3، وتجعل الأبيض يصرف نقلة لاسترداد البيدق. لكنها تُعدّ اليوم أضعف، وعادةً تُلعب 7...Nge7 أو نقلات أخرى.","15":"يذهب الوزير الأبيض إلى b3. ومع الفيل في c4 يصوّب نحو f7: تشكيل مخيف. لأن الملك وحده يحمي f7، يصبح تهديد أخذ f7 بالفيل مع كش تهديدًا جديًا.","16":"يُخرج الأسود الوزير إلى f6 ليحمي f7. وبينما يحمي f7 يراقب الوزير أيضًا جناح الملك الأبيض: مربع نشيط جدًا.","17":"e5! يطرد الأبيض الوزير الأسود ببيدق. وهذا البيدق يسدّ أيضًا طريق الحصان الأسود إلى f6، ويضيّق على قطع الأسود.","18":"يهرب الوزير إلى g6. من هنا يصوّب عبر العمود g نحو g2 أمام الملك الأبيض، ويراقب أيضًا e4. يبدو أن بيدق e5 يمكن أخذه، لكن التحليل يبيّن أن الأسود إن أخذه جاءت قلعة إلى e1 بتثبيت، فيخسر قطعة.","19":"يذهب الرخ إلى e1 ويحمي بيدق e5 بقوة. ودخل الرخ الأبيض هو أيضًا المعركة. لكن التحليلات الحديثة بالحاسوب تشير إلى أن Rd1 ربما كانت أفضل هنا.","20":"يُخرج الأسود الحصان إلى e7. بعد ذلك يريد الأسود أن يبيّت ويؤمّن ملكه. ذهب الحصان إلى e7 بدل f6 لأن بيدق e5 يسيطر على f6.","21":"الفيل إلى a3! يمتدّ قطر مستقيم من a3 نحو f8. يصوّب هذا الفيل نحو الحصان في e7 وينظر أيضًا إلى f8 خلفه. إذا تحرّك الحصان انفتح الطريق إلى f8، لذلك صار صعبًا على الأسود أن يبيّت في جهة الملك. نقلة مهمة جدًا تُبقي الملك الأسود محبوسًا في الوسط. وتقترح الحواسيب هنا أيضًا Qd1 أو Re3، لكن Ba3 نقلة واضحة وقوية يسهل على الإنسان فهمها.","22":"بـ b5 يعطي الأسود بيدقًا ويهدّد الفيل في c4. إنه هجوم مضاد لإبعاد الوزير الأبيض عن f7 وزعزعة الوضع.","23":"يأخذ الأبيض البيدق بالوزير. يحمي الوزير فيل c4 ويواصل التصويب نحو ما حول الملك الأسود.","24":"يخرج الرخ الأسود إلى b8 ويهدّد الوزير في b5. بدأ الرخ يعمل على العمود b المفتوح.","25":"يذهب الوزير إلى a4. يهاجم الفيل في a5، وعلى القطر من a4 إلى e8 يثبّت حصان c6 على ملكه. إذا تحرّك هذا الحصان صار الملك في كش، لذلك لا يستطيع الحركة.","26":"يهرب الفيل من a5 إلى b6. عاد إلى قطره القديم، مصوّبًا نحو f2.","27":"يُخرج الأبيض الحصان إلى d2. تخرج آخر قطعة بقيت في البيت، وبعدها تخطّط للقفز إلى e4 والاقتراب من الملك الأسود.","28":"يُخرج الأسود الفيل إلى b7 ليحمي حصان c6 المثبَّت. القطر الطويل من b7 مسدود الآن بحصان c6، لكن إذا تحرّك الحصان سيستطيع الفيل التصويب نحو f3 وg2.","29":"الحصان إلى e4! من وسط الرقعة يهدّد بالقفز إلى f6 أو d6 مع كش. الملك الأسود ما زال في الوسط وفي خطر.","30":"يذهب الوزير الأسود إلى f5. يصوّب في آن واحد نحو حصان e4 وحصان f3. الفكرة إجبار الحصانين على التنحّي ثم مهاجمة الملك الأبيض.","31":"يأخذ الفيل بيدق d3. اختفى البيدق الذي كان شوكة الأسود. وفوق ذلك ينظر هذا الفيل إلى وزير f5 من خلف حصان e4: إذا تحرّك الحصان أخذ الفيل الوزير.","32":"يهرب الوزير إلى h5. من هنا يصوّب عبر g4 نحو حصان f3. الخطة أخذ f3 بالوزير، واستعمال العمود g أيضًا لإماتة الملك الأبيض.","33":"يقفز الحصان إلى f6 مع كش! ويهاجم أيضًا الوزير في h5: شوكة. حتى لا يخسر الوزير، يقرّر الأسود أخذ هذا الحصان.","34":"يأخذ الأسود الحصان ببيدق g7. انفتح العمود g، فصار الأسود يستطيع التصويب نحو الملك الأبيض برخ g8.","35":"يستردّ الأبيض في f6 ببيدق e5. هذا البيدق يهدّد حصان e7، ولأن العمود e انفتح، ينظر رخ e1 عبر حصان e7 إلى الملك الأسود. ويسيطر بيدق f6 أيضًا على المربعين g7 وe7.","36":"يذهب الرخ الأسود إلى g8. على العمود g المفتوح يصوّب نحو g2 أمام الملك الأبيض. إذا أخذ الوزير f3 في النقلة التالية، سيُهاجَم g2 بالوزير والرخ معًا، ويبدو أن الأسود على وشك الكش مات.","37":"الرخ إلى d1! للأسود تهديد بالكش مات، ومع ذلك يحرّك الأبيض رخًّا بهدوء. بين d1 وd7 لا يوجد إلا فيل d3. إذا تحرّك الفيل سينظر الرخ مباشرة إلى المربع المجاور للملك الأسود. إنها نقلة محسوبة بعمق لإنهاء المباراة أولًا بسلسلة من الكشّات، وهي أشهر نقلة في هذه المباراة. لكن دراسات لاحقة تقول إن لدى الأبيض والأسود كليهما نقلات أخرى، وما زالت المباراة تُحلَّل حتى اليوم.","38":"يأخذ الوزير الأسود حصان f3. إذا أخذ g2 في النقلة التالية فهو كش مات بمساعدة الرخ. على الأبيض الآن أن يفوز بالكش تلو الكش.","39":"الرخ يأخذ حصان e7 مع كش! حتى مع التضحية بقطعة، يواصل الأبيض مطاردة الملك الأسود.","40":"يستردّ الأسود بحصان c6. لكن لأن الحصان غادر c6، انفتح القطر من وزير a4 حتى d7. ويقال إنه حتى لو حرّك الأسود الملك بدل الاسترداد بالحصان، لاستمرّ هجوم الأبيض.","41":"يضحّي الأبيض بالوزير في d7 مع كش! عبر القطر الذي انفتح للتوّ، يقفز الوزير أمام الملك الأسود مباشرة. هذه هي الضربة الحاسمة في المباراة دائمة الخضرة.","42":"يأخذ الأسود الوزير بالملك. لو هرب إلى f8 لأخذ الوزير حصان e7 بكش مات، لذلك كان الأخذ هو الخيار الوحيد.","43":"يذهب الفيل إلى f5: كش مزدوج! يعطي الفيل كشًّا للملك في d7 من f5، والرخ في d1 الذي كشفه الفيل يعطي أيضًا كشًّا عبر العمود d. عندما تعطي قطعتان الكش معًا لا يمكن الدفاع بالاعتراض أو بالأخذ: على الملك أن يهرب.","44":"يهرب الملك إلى e8. لو هرب إلى c6 بدلًا من ذلك لجاء الفيل إلى d7 وكان كش مات.","45":"يصل الفيل إلى d7 مع كش. هذه المرة هو بجانب الملك في e8 مباشرة. هذا الفيل يحميه رخ d1، لذلك لا يستطيع الملك أخذه.","46":"يذهب الملك إلى f8. الهرب إلى d8 يخسر أيضًا: سيأخذ فيل a3 حصان e7 بكش مات.","47":"فيل a3 يأخذ حصان e7: كش مات! فيل d7 يسيطر على e8، وبيدق f6 يسيطر على e7 وg7، وقطع الأسود نفسها تسدّ f7 وg8. بيدق f6، والفيل الذي لم يتحرّك منذ وصوله إلى a3، ورخ d1: في النهاية عملت كل القطع على أكمل وجه. كان الأسود يصوّب نحو g2 بالوزير والرخ، لكنه تأخّر نقلة واحدة. قراءة تهديد الخصم ثم الإنهاء أولًا بسلسلة من الكشّات: هذه المباراة نموذج لكيفية الهجوم."}},"lasker1912":{"t":"صيد الملك","w":"إدوارد لاسكر","b":"جورج آلان توماس","ev":"مباراة سريعة ودية في نادي مدينة لندن للشطرنج","d":"1912","pl":"المملكة المتحدة (لندن)","lead":"مباراة سريعة وودية في نادٍ بلندن. يضحّي الأبيض بالوزير ويطارد الملك الأسود عبر الرقعة كلها، من g8 إلى g1. تختلف ترتيبات نقلات الافتتاح قليلًا بين السجلات، لكن الوضع بعد النقلة العاشرة هو نفسه.","c":{"0":"أكتوبر 1912، نادي مدينة لندن للشطرنج. الأبيض إدوارد لاسكر، مهندس شاب وصل لتوّه من ألمانيا، والأسود جورج آلان توماس الذي صار لاحقًا بطل بريطانيا. كانت مباراة سريعة وودية. وهي مشهورة باسم \"صيد الملك\": يُطارَد الملك الأسود من g8 حتى g1 في الطرف الآخر من الرقعة. انتقل لاسكر لاحقًا إلى أمريكا واشتهر بكتبه في الشطرنج. وبحسب السجلات كان التاريخ 29 أكتوبر. وتوصف المباراة بأنها «مباراة الخمس دقائق»، لكنها ليست كالشطرنج الخاطف اليوم: فقد كانت القاعدة ألّا يستعمل أيّ لاعب أكثر من خمس دقائق زيادةً على خصمه.","1":"يبدأ الأبيض بـ d4، بيدق الوزير. يسيطر على e5 وc5 ويفتح الطريق لفيل c1. وُلد لاسكر في كيمبنو في بولندا اليوم (وكانت ألمانية آنذاك). درس الهندسة الميكانيكية والكهربائية في الجامعة التقنية في برلين، ووصل إلى لندن في ذلك العام، وانضم إلى هذا النادي في أكتوبر. وكان قريبًا بعيدًا لبطل العالم إيمانويل لاسكر، وكثيرًا ما يُخلط بينهما.","2":"يلعب الأسود e6: وضع متين أولًا، مع التحضير لـ f5 أو d5. وُلد توماس في إسطنبول. لم يكن لاعب شطرنج فحسب، بل كان أيضًا لاعب ريشة طائرة عظيمًا فاز بإحدى وعشرين بطولة في أكبر بطولات بريطانيا (أول إنغلاند). و«كأس توماس»، بطولة العالم للفرق في الريشة الطائرة، تحمل اسمه. كما تألق في التنس في ويمبلدون: رياضي مدهش حقًا!","3":"الحصان إلى f3. يسيطر على e5 ويساعد في حماية جناح الملك: أكثر المربعات طبيعية. وفي أبريل من هذا العام، 1912، اصطدمت السفينة العملاقة «تايتانيك» بجبل جليدي وغرقت في رحلتها الأولى من بريطانيا إلى أمريكا.","4":"يلعب الأسود f5 ويسيطر على e4، كما في الدفاع الهولندي. لكن تحريك بيدق أمام الملك يُضعفه قليلًا. وبالترتيب 1.d4 e6 2.Nf3 f5 دخلت المباراة في «الدفاع الهولندي». وتورد الكتب ترتيب نقلات هذه المباراة باختلاف بسيط، لكن يُعتقد أن هذا هو الترتيب في ورقة لاسكر نفسه.","5":"الحصان الآخر إلى c3، استعدادًا لـ e4 لضرب بيدق f5.","6":"يُخرج الأسود حصانًا إلى f6: يزيد سيطرته على e4 ويستعد للتبييت.","7":"الفيل إلى g5 يصوّب نحو حصان f6. هذا الحصان مدافع مهم عن الملك الأسود، لذا يريد الأبيض إزالته مبكرًا.","8":"يضع الأسود الفيل في e7 ليحمي الحصان ويقترب من التبييت.","9":"يبادل الأبيض الفيل بالحصان. اختفى الحصان الذي كان يحمي الملك الأسود.","10":"يستردّ الأسود بالفيل. الآن يتولّى فيل f6 حماية جناح الملك.","11":"e4! يضرب الأبيض بيدق f5 ويكسب مساحة في الوسط. تنفتح الخطوط وتتحرّك قطع الأبيض بحرية أكبر.","12":"يأخذ الأسود بيدق e4. وإلا لعب الأبيض e5 ودفع قطع الأسود إلى الخلف.","13":"يستردّ الحصان ويستقر في الوسط، ينظر إلى فيل f6 والمربعين g5 وd6. وبعد عامين، في 1914، انتقل لاسكر إلى أمريكا وعمل مهندسًا. وفي عشرينيات القرن العشرين اخترع مضخة لحليب الأم، ساعدت على إنقاذ حياة الأطفال المولودين قبل أوانهم.","14":"يلعب الأسود b6 ليضع الفيل في b7 ويصوّب على القطر الطويل نحو حصان e4.","15":"الحصان إلى e5، مربع قوي في الوسط يرى أيضًا g4 وf7. صار الحصانان الأبيضان قريبين من جناح ملك الأسود. وكان لاسكر يحب لعبة «غو» أيضًا، ويُعرف بأنه من الذين نشروها في أمريكا. وفي 1934 ألّف كتابًا عن «غو» و«غوموكو»، ثم نال لاحقًا جائزة من اليابان لنشره لعبة «غو».","16":"يبيّت الأسود. الملك في g8. لكن بغياب بيدق f توجد ثغرات كثيرة حول الملك. وبعد هذه المباراة صار توماس بطل بريطانيا في الشطرنج عامي 1923 و1934.","17":"الفيل إلى d3. حصانه في e4 يعترضه الآن، لكن خلفه بيدق h7. ما إن يتحرّك حصان e4 حتى يصوّب هذا الفيل مباشرة نحو h7.","18":"الفيل الأسود إلى b7 يصوّب على القطر الطويل نحو حصان e4 ويقيّد قطع الأبيض.","19":"الوزير إلى h5 يصوّب نحو بيدق h7 الذي لا يحميه إلا الملك الأسود. وزير الأبيض وفيله وحصاناه كلها موجّهة نحو الملك الأسود.","20":"يضع الأسود الوزير في e7. يحمي فيل f6 ويستعد للذهاب إلى c5، لكنه لا يرى فكرة الأبيض. كان لا بد من h6 أو أخذ حصان e5. هذه نقطة التحوّل.","21":"يُضحّى بالوزير في h7 مع كش! يقدّم الأبيض أقوى قطعه مجانًا. كان لاسكر يرى الطريق كله لمطاردة الملك حتى الكش مات.","22":"لا بد أن يأخذ الأسود بالملك، فيصير الملك في h7.","23":"يأخذ الحصان فيل f6 مع كش. وفي الوقت نفسه يخلو e4، فيكشّ فيل d3 أيضًا الملك في h7: كش مزدوج. لا يمكن سدّه، فعلى الملك أن يهرب.","24":"الملك إلى h6. لو ذهب إلى h8 لقفز الحصان الآخر إلى g6 بكش مات. يُدفع الملك إلى الأمام أكثر فأكثر.","25":"يقفز الحصان الآخر من e5 إلى g4 بكش، يهاجم الملك في h6 ويدفعه أبعد.","26":"الملك إلى g5: يترك معسكره ويمشي نحو جهة الأبيض.","27":"كش ببيدق h! حتى البيادق تشارك في الصيد. على الملك أن يواصل التقدّم.","28":"الملك إلى f4. عبر منتصف الرقعة ويدخل معسكر الأبيض.","29":"كش مرة أخرى ببيدق g. بيدقان يسدّان طريق العودة على الملك.","30":"الملك إلى f3، في وسط قطع الأبيض تمامًا.","31":"يتراجع الفيل من d3 إلى e2 بكش. يُدفع الملك إلى عمق أكبر.","32":"الملك إلى g2. لم يعد الملك الأبيض في e1 بعيدًا.","33":"الرخ إلى h2، كش. أخيرًا يدخل الرخ اللعب.","34":"يصل الملك أخيرًا إلى g1. انطلق من g8 وبلغ الصف الأول في الطرف الآخر من الرقعة.","35":"يتحرّك الملك الأبيض من e1 إلى d2. ينفتح بذلك طريق رخ a1 الذي يكشّ الملك في g1 على الصف الأول: كش مات! كان التبييت الطويل سيعطي كش مات أيضًا، لكن لاسكر حرّك الملك. في مباراة سريعة، وبعد التضحية بالوزير، طارد الأبيض الملك أربع عشرة نقلة حتى أعمق زاوية في معسكره. مباراة نادرة جدًا."}},"toketsu":{"t":"مباراة الدم","w":"أكابوشي إنتيتسو","b":"هونينبو جووا","ev":"لُعبت في دار السيد ماتسودايرا حاكم سوو (على أربعة أيام)","d":"1835","pl":"اليابان (إيدو)","lead":"مباراة وُلدت من الصراع على منصب «ميجين غودوكورو»، أعلى منصب في الغو الياباني. أرسل إينوي غينان إنسيكي تلميذه أكابوشي إنتيتسو لمواجهة الميجين جووا. بعد أربعة أيام من القتال خسر إنتيتسو، ويُروى أنه سعل دمًا أمام اللوحة.","c":{"0":"إيدو، 1835. لُعبت هذه المباراة في لقاء للغو بدار السيد ماتسودايرا حاكم سوو، أحد كبار الوزراء. الأسود: أكابوشي إنتيتسو (7 دان) من مدرسة إينوي. الأبيض: هونينبو جووا، صاحب منصب ميجين غودوكورو، أعلى منصب في الغو، الذي ناله بعد صراع مع إينوي غينان إنسيكي. لم يرضَ غينان، فأرسل أفضل تلاميذه ليقول إن ميجين يخسر أمام 7 دان لا يستحق اللقب. دامت المباراة أربعة أيام وتركت واحدة من أشهر قصص الغو وأكثرها حزنًا. في عام 1835 هذا كان مذنّب هالي، الذي يعود كل 76 عامًا تقريبًا، يمرّ قرب الأرض، وفي خريف ذلك العام وُلد الكاتب مارك توين في أمريكا. وفي عالم الغو كان ذلك زمنًا تتنازع فيه البيوت الأربعة — هونينبو وإينوي وياسوي وهاياشي — على منصب واحد فقط هو «ميجين غودوكورو».","1":"الأسود 1 على نقطة 3-4 في الأسفل يسارًا (C4). يبدأ إنتيتسو بهدوء، مُظهرًا أنه سيلعب أسلوبه حتى أمام الميجين. وُلد إنتيتسو عام 1810 في كيكوتشي بإقليم هيغو (كوماموتو اليوم). ذهب إلى إيدو في الثانية عشرة ودخل بيت إينوي، ومنذ نحو الخامسة عشرة صار يتعلم على يد غينان. وفي عام 1833 ألّف كتابًا لمسائل الحياة والموت اسمه «غينران»، وفي 1834 بلغ الدان السابع، فكان الأمل الشاب الكبير لبيت إينوي.","2":"الأبيض 2 (Q3) والأسود 3 (R16) والأبيض 4 (E16): حجر في كل زاوية. الأبيض 4 على النقطة العالية 4-5، التي تفضّل الامتداد على الأرض. وُلد جووا عام 1787، وكان هونينبو الثاني عشر، وصار «ميجين غودوكورو» عام 1831. كان أسلوبه قويًا جدًا، ويُلقَّب «القديس المتأخر» إلى جانب المعلم العظيم دوساكو «القديس المتقدم». وقيل زمنًا طويلًا إنه بلغ منصب الميجين بالتحايل على غينان، لكن وثائق عُثر عليها في السنوات الأخيرة جعلت بعضهم يرى أن هذه القصة تحتاج إلى مراجعة.","5":"الأسود 5 (P17) يغلق الزاوية العليا اليمنى بحجر ثانٍ ويجعلها متينة للمعارك القادمة.","6":"الأبيض 6 (E3) يقترب مبكرًا من زاوية الأسود السفلى اليسرى. جووا هجومي منذ البداية ولا يترك للأسود وقتًا ليستقر بهدوء. E3 هي «مقاربة الحصان الصغير» لنقطة 3-4، وهي من أكثر المقاربات شيوعًا منذ عصر إيدو حتى اليوم.","8":"الأسود 7 (R5) يقترب من Q3، والأبيض 8 (R9) يضعه في كماشة من الأعلى. يريد الأبيض إضعاف هذا الحجر الأسود على اليمين وجعله هدفًا. بين R5 وR9 ثلاث نقاط فارغة، فحركة الأبيض 8 «كمّاشة بثلاث مسافات».","9":"الأسود 9 (R11) يرد الكماشة على الأبيض 8 من الأعلى. ولأن زاوية الأسود العليا اليمنى متينة يستطيع قلب الأدوار ومهاجمة الأبيض على اليمين.","10":"الأبيض 10 (P4) يدافع عن الزاوية السفلى اليمنى، فيؤجل معركة الجانب الأيمن ويقوّي زاويته أولًا.","11":"الأسود 11 (J3) يأخذ منتصف الجانب السفلي بين E3 وP4 كي لا ينال الأبيض منطقة كبيرة هناك. وبين E3 وJ3 أيضًا ثلاث نقاط فارغة، فحركة الأسود 11 هي كذلك «كمّاشة بثلاث مسافات» على E3: يرد الأسود على مقاربة زاويته بالإطباق عليها.","12":"الأبيض 12 (D6) يضغط من الأعلى على زاوية الأسود السفلى اليسرى، ومع E3 يحاول تطويق C4. هنا تبدأ أكبر معارك المباراة. تقع D6 على بُعد قفزة حصان كبير من حجر الأبيض E3. هذه هي «التايشا»، وهي حركة تُلعب حين تتعرض مقاربة الحصان الصغير لكمّاشة بثلاث مسافات، وتُعرف هذه المباراة مثالًا على تايشا نشأت من كمّاشة بثلاث مسافات. كانت التايشا شكلًا يدرسه بيت إينوي سرًّا، فدخل جووا بنفسه إلى تخصص خصومه. وبعد أحد عشر عامًا، في «مباراة الأذنين المحمرّتين»، سيلعب غينان التايشا أيضًا.","13":"الأسود 13 (E4) يلتصق بين أحجار الأبيض تمامًا ويفصلها قبل أن يُطوَّق. يقبل الأسود القتال وجهًا لوجه.","16":"الأبيض 14 (D4) والأسود 15 (D5) والأبيض 16 (D3): يحفر الأبيض تحت زاوية الأسود بينما يكبر الأسود صعودًا. الأحجار مقطوعة من الجانبين ولكل طرف مجموعات ضعيفة: معركة صعبة. نحن هنا داخل جوسيكي التايشا الذي يقال إن له «مئة تفرّع». والطريق الذي يختاره كل طرف هنا يغيّر القتال اللاحق كله.","19":"الأسود 17 (C5) والأبيض 18 (E5) والأسود 19 (F4): يكبح الأسود E5 من الأسفل ويُبقي أحجار الأبيض منفصلة. على أحجار الأبيض في الأسفل يسارًا أن تعيش في الزاوية أو تهرب.","20":"الأبيض 20 (C3) يتسلل تحت زاوية الأسود فيأكل أرضها ويحاول العيش فيها. ويواصل الأسود 21 (B3) والأبيض 22 (B2) التبادل الدقيق داخل الزاوية.","22":"الأبيض 22 (B2) ينزل إلى الخط الثاني في الزاوية ليتخذ شكلًا حيًا هناك. تصغر زاوية الأسود، لكن أحجاره الخارجية تقوى.","23":"الأسود 23 (C7) يصعد على الجانب الأيسر ويكبح أحجار الأبيض العليا (مثل D6) من الأسفل. والأبيض 24 (G2) يمتد في الأسفل ليمنح أحجار الزاوية طريقًا للاتصال والعيش.","26":"الأسود 25 (H4) يغطي أحجار الأبيض السفلية، والأبيض 26 (E6) يقوّي العليا. المجموعة البيضاء السفلى تريد أرضًا والعليا مخرجًا إلى الوسط، والأسود يراقب الاثنتين.","27":"الأسود 27 (B4) يسد ما فوق أحجار الأبيض في الزاوية ويضيّق مساحة حياتها تمهيدًا لهجمات لاحقة.","28":"الأبيض 28 (C9) يمتد بعيدًا على الجانب الأيسر ليمنح أحجاره العليا قاعدة للعيش. كثيرًا ما يُعدّ مبالغًا فيه: نقلة عنيفة على طريقة جووا. يسعى الأسود الآن إلى معاقبتها.","31":"الأسود 29 (D8) والأبيض 30 (D9) والأسود 31 (E8): يقتحم الأسود بين C9 وأحجار الأبيض العليا فيشطر الأبيض نصفين. انفصلت C9–D9 على اليسار عن D6–E6 في الوسط.","33":"الأسود 33 (C2). يُروى أنها تفرّعة جديدة درستها مدرسة إينوي سرًّا. تضغط أحجار الأبيض في الزاوية وتهاجم في الوقت نفسه أحجاره العائمة في الوسط: هدفان معًا. إنها «نقلة سرية» أُعدّت لهزيمة الميجين، ومن هنا يتضح تفوق الأسود.","36":"الأبيض 34 (D2) والأسود 35 (B1) والأبيض 36 (F3): يسارع الأبيض إلى وصل أحجاره السفلية والعيش. في الأثناء تبقى أحجار الأبيض في الوسط بلا عون فتصير هدفًا للأسود.","38":"الأبيض 38 (A2) نقلة على الخط الأول تؤمّن عيونًا لأحجار الزاوية. حين تستقر المجموعة السفلى يستطيع الأبيض التركيز على معركة الأعلى.","40":"من الأسود 37 (G5) إلى الأبيض 40 (G7) تهرب أحجار الأبيض في الوسط صعودًا، ويطاردها الأسود عن قرب مقوّيًا نفسه في الطريق.","42":"الأسود 41 (H7) والأبيض 42 (G8): يهرب الأبيض صعودًا في الوسط ويتبعه الأسود من الخارج. كلما صعد الأبيض أكثر ازداد أسفل الأسود ويساره متانة.","43":"الأسود 43 (E9). صارت C9–D9 على اليسار محاصرة وفي ورطة، وأحجار الأبيض في الوسط لم تعش بعد. لعب إنتيتسو حتى الآن ببراعة ويُعتقد أنه تقدّم بوضوح. أمام الميجين بدت خطة إينوي ناجحة.","45":"الأبيض 44 (H8) يقود أحجار الوسط صعودًا، والأسود 45 (D11) يصعد على الجانب الأيسر ساددًا ما فوق C9–D9. تفقد أحجار الأبيض اليسرى مخارجها صعودًا ونحو الوسط.","48":"الأسود 47 (H5) والأبيض 48 (F5): يحاول الأبيض وصل أحجاره في الوسط والأسفل، ويحاول الأسود فصلها. لكل اتصال قيمته عند الأبيض.","50":"الأسود 49 (C12) يقوّي الجانب الأيسر أكثر، والأبيض 50 (C16) يتجه إلى الزاوية العليا اليسرى. يترك الأبيض مؤقتًا معركة الأسفل يسارًا الصعبة ليكسب في مكان آخر.","53":"الأسود 51 (M3) يقوّي الأسفل، والأبيض 52 (Q6) يضغط على R5 يمينًا. ويدخل الأسود 53 (G17) الجانب العلوي ليوقف نمو الأبيض في الأعلى يسارًا.","57":"بعد أن يقوّي الأبيض 54 (R6) اليمين، يأتي الأسود 55 (D17) والأبيض 56 (C17) والأسود 57 (E17): يلعب الأسود فوق زاوية الأبيض مباشرة فيقتطع منها ويمتد في الأعلى.","58":"الأبيض 58 (C14) يمتد من الزاوية العليا اليسرى نحو أحجار الأسود على الجانب. تلتقي زاوية الأبيض وجانب الأسود وجهًا لوجه.","60":"عندما يغطي الأسود 59 (J8) أحجار الأبيض في الوسط، يأسر الأبيض 60 (G4) حجرين أسودين. تتنفس أحجار الأبيض في الأسفل يسارًا أخيرًا: أبيض محاصر يأخذ ما يستطيع.","63":"الأسود 61 (O3) يضع حجرًا يمين الأسفل، والأبيض 62 (J17) يذهب إلى الأعلى، والأسود 63 (F16) يكبح زاوية الأبيض العليا اليسرى من الخارج. تنتشر شرارات القتال في أنحاء اللوحة.","66":"الأبيض 64 (M17) والأسود 65 (B13) والأبيض 66 (B14): يتسلل الأسود تحت أحجار الأبيض على الحافة اليسرى، ويحاول الأبيض تثبيت مجموعته العليا اليسرى. ما زالت C9–D9 محاصرة.","68":"الأبيض 68 (B11). اشتهرت نقلات الأبيض التالية، مع النقلة 80، بأنها نقلات جووا العبقرية، مدهشة لدرجة أن الناس قالوا إن الأشباح أرتها له. تبحث B11 عن طريق يصل C9–D9 المحاصرتين بالمجموعة العليا اليسرى. من هنا يبدأ الأبيض المحاصر هجومه المضاد.","70":"الأسود 69 (D10) يحاول منع الاتصال، لكن الأبيض 70 (E12) لا يرد في اليسار ويأخذ أولًا نقطة مفتاحية في الوسط. تبقى له موارد خفية في اليسار فلا داعي للرد فورًا. استعادة المبادرة مع ترك الهجوم ينزلق: نقلة ميجين.","72":"بعد الأسود 71 (F10) الذي يضغط وسط الأبيض، يتجه الأبيض 72 (R13) إلى الجانب الأيمن. يوقف الأبيض معركة الوسط مؤقتًا ليكبح إطار الأسود في الأعلى يمينًا.","76":"الأسود 73 (P11) والأبيض 74 (R15) والأسود 75 (Q16) والأبيض 76 (O14): يتسلل الأبيض بجوار زاوية الأسود ويضع أحجارًا تصل الجانب الأيمن بالوسط، تمهيدًا لشطر الأسود.","78":"الأسود 77 (P9) والأبيض 78 (Q9): يعيق الأبيض اتصال أحجار الأسود اليمنى (R5 وP9) بالأحجار العليا. هل سيتصل الأسود أم يُقطع؟ لحظة متوترة.","80":"الأبيض 80 (Q10) يصنع «مثلثًا فارغًا»، كتلة من ثلاثة أحجار تُعدّ عادة شكلًا سيئًا. لكنها صارت قاعدة لشطر أحجار الأسود اليمنى نصفين ومهاجمتها. تقدّم الوظيفة على المظهر، فهي المثال الكلاسيكي على نقلة قبيحة لكنها ممتازة، وآخر النقلات الثلاث الشهيرة. من هنا يبدأ هجوم الأبيض الفاصل بجدية، وتبدأ المباراة بالميل تدريجيًا نحو الأبيض.","83":"بعد الأسود 81 (S6) والأبيض 82 (S7) يدخل الأسود 83 (R3) زاوية الأبيض السفلى اليمنى. تحت الضغط على اليمين، يطلب الأسود الحياة والأرض معًا باقتحام الزاوية.","86":"الأسود 85 (S2) والأبيض 86 (R4): يقلّص الأسود حريات الأبيض من الخط الأول، ويكبح الأبيض الأسود من داخل الزاوية. يعدّ الطرفان كم نقلة بقيت قبل الأسر.","88":"من الأبيض 84 (R2) إلى الأبيض 88 (Q2) يستمر سباق أسر متقارب على الخطين الأول والثاني في الزاوية. من سيأسر أولًا؟ قد تحسمه نقلة واحدة.","91":"الأسود 91 (Q4) يأسر حجرًا أبيض فيتقدم خطوة في الزاوية. لكن الأبيض يستعد لتطويق الأسود من الخارج.","95":"الأبيض 92 (N4) والأسود 93 (R7) والأبيض 94 (Q7) والأسود 95 (O4): يلتف الأبيض حول الأسود من الخارج انطلاقًا من الأسفل، ويحاول الأسود الاتصال يمينًا وأسفل. كلما كبرت المجموعة السوداء صعب إنقاذها.","98":"الأبيض 98 (M4) يطوّق أحجار الأسود السفلية من الخارج. لا يملك الأسود شكلًا آمنًا سريعًا لا في الزاوية ولا نحو الوسط.","101":"من الأبيض 96 (N3) إلى الأسود 101 (O5) تنمو أحجار سوداء وبيضاء جنبًا إلى جنب من الأسفل نحو الوسط: تدافع يكبح فيه كل طرف الآخر من جهة.","104":"بعد الأسود 103 (P2) يأسر الأبيض 104 (R4) حجرًا أسود. في سباق الزاوية يستعيد الأبيض خطوة.","106":"الأسود 105 (N2) ثم يأسر الأبيض 106 (S5) حجرًا أسود. يحتفظ الأبيض بالزاوية السفلى اليمنى، ولا تستطيع أحجار الأسود العيش فيها فعليها الهرب إلى الخارج.","107":"الأسود 107 (Q11) يحمي مجموعته العليا على اليمين: ما دامت السفلى في ورطة فليؤمّن العليا على الأقل. ويواصل الأبيض 108 (M2) والأسود 109 (O1) معركة أسر صغيرة على الحافة السفلى.","113":"بعد الأبيض 110 (J4) والأسود 111 (K2) والأبيض 112 (H3) يأتي الأسود 113 (K6): تطل أحجار الأسود السفلية نحو الوسط بحثًا عن الحياة. عليها تأمين مخرج قبل أن يُحكم الأبيض الشبكة.","116":"الأبيض 114 (L5) والأسود 115 (L3) والأبيض 116 (L6): يضع الأبيض غطاءً فوق أحجار الأسود ويضيّق مخرجها نحو الوسط. ويقطع الأسود أحجار الأبيض السفلية محاولًا الخروج.","120":"الأسود 117 (K7) والأبيض 118 (L7) والأسود 119 (J9) والأبيض 120 (N9): يقفز الأسود إلى الوسط ويسبقه الأبيض ليسد طريقه من اليمين. صار السؤال: أيّ الأحجار تضعف أولًا؟","125":"مع الأبيض 122 (J2) والأسود 123 (K3) تتمكن أحجار الأسود السفلية بالكاد من الاتصال. ويحاول الأسود 125 (N11) وصل المجموعة العليا اليمنى بأحجار الوسط.","128":"الأبيض 126 (O7) والأسود 127 (N8) والأبيض 128 (L11): يلتف الأبيض فوق أحجار الأسود في الوسط أيضًا ويضغطها من فوق ومن تحت. خطة الشطر المعدّة منذ النقلة 80 تتشكل.","132":"من الأسود 129 (M10) إلى الأبيض 132 (K10) يقطع الطرفان بعضهما في الوسط. يحاول الأسود كسر طوق الأبيض، ويغلق الأبيض مخارجه واحدًا تلو الآخر.","137":"من الأسود 133 (L8) إلى الأبيض 136 (P10) يزداد الوسط تشابكًا. ويقفز الأسود 137 (N13) بعيدًا صعودًا ليصل الوسط بالجانب العلوي.","138":"الأبيض 138 (K8) يأسر حجرًا فيبدأ كو في الوسط. لنحو 30 نقلة يتبادل الطرفان الأسر في K8 وL8. سيحدد هذا الكو مصير أحجار الأسود في الوسط.","143":"من الأسود 139 (K9) إلى الأسود 143 (J6) تتوالى التهديدات والاستردادات. يأسر الأسود 143 حجرًا أبيض ويخفف الضغط عن أحجاره السفلية.","148":"من الأبيض 144 (K5) إلى الأبيض 148 (K8) تستمر التهديدات والاستردادات في الأسفل والوسط. ومع كل تهديد يكسب الأبيض قليلًا حول أحجار الأسود السفلية.","152":"الأبيض 152 (E11) تهديد كو يضرب نقطة ضعف في أحجار الأسود اليسرى. طوال الكو يجد الأبيض في كل مكان نقلات يجب على الأسود الرد عليها.","158":"من الأسود 155 (H2) إلى الأبيض 158 (C6) تُحدث تهديدات الكو في الأسفل والأسفل يسارًا مقايضات صغيرة. يهدد الأبيض 158 زاوية الأسود السفلى اليسرى، فيدافع الأسود بـ159 (B6).","162":"الأسود 161 (G1) والأبيض 162 (F1): يحدث الأسر على الحافة السفلى أيضًا. أثناء الكو تنتشر معارك صغيرة في كل أرجاء اللوحة.","167":"بعد أن يستردّ الأبيض 166 (K8) مجددًا، لا يواصل الأسود 167 (M1) الكو ويلعب في مكان آخر في الأسفل. وهكذا يربح الأبيض كو الوسط ويستطيع وصل أحجاره هناك. يكسب الأسود شيئًا في الأسفل بالمقابل، لكن أحجاره في الوسط تقع في ورطة.","170":"بعد الأبيض 168 (K11) والأسود 169 (H10) يتجه الأبيض 170 (P15) إلى الأعلى يمينًا. يهدّئ الوسط مؤقتًا ويستهدف المجموعة السوداء الكبيرة هناك التي لم تعش تمامًا بعد.","175":"من الأسود 171 (L13) إلى الأسود 175 (K14) يمتد الأسود صعودًا ليصل المجموعة العليا اليمنى بالوسط. ويضيّق الأبيض 174 (O17) مساحة حياة الأسود قرب الزاوية.","178":"الأبيض 178 (J14) يقفز إلى وسط الأعلى ليفصل أحجار الأسود يمينًا ويسارًا. يبدأ الآن بجدية الهجوم الفاصل المعدّ منذ النقلة 80. على الأسود الدفاع عن الجانبين معًا: موقف صعب جدًا.","182":"من الأسود 179 (K15) إلى الأبيض 182 (G14) يضغط الأبيض من الخارج على يسار الأعلى أيضًا. وعلى أحجار الأسود في الأعلى يسارًا أن تبحث عن مكان للعيش.","190":"من الأسود 183 (F14) إلى الأبيض 190 (J13) يتقاطع الطرفان بعنف على يسار الأعلى. يضع الأبيض حجرًا بعد حجر بين أحجار الأسود فيكسر شكلها.","193":"الأسود 193 (J11) يأسر حجرًا أبيض ويكافح ليتصل ويعيش. لكن أحجار الأسود على يمين الأعلى ما زالت قلقة.","199":"من الأبيض 194 (S14) إلى الأسود 199 (A16) يكبح الأبيض زاوية الأسود العليا اليمنى من الخارج، ويعمل الأسود أيضًا عند الحافة العليا اليسرى. أي مجموعة كبيرة ستضعف أولًا؟ لحظة حاسمة قبل النهاية.","201":"الأسود 201 (R14) يأسر حجرًا فيبدأ كو جديد على الجانب الأيمن في R14 وR15. حياة مجموعة الأسود العليا اليمنى تتوقف على هذا الكو.","206":"من الأبيض 202 (E14) إلى الأبيض 206 (M13) يلعب الأبيض تهديدات كو بينما يشدّ تدريجيًا الخناق على أحجار الأسود في الوسط. حتى أثناء الكو تكاد شبكة الأبيض تنغلق.","213":"من الأسود 207 (L17) إلى الأسود 213 (K18) يكافح الأسود ليتصل في الأعلى. ويمد الأبيض يده إلى الخطين الأول والثاني ليسلب الأسود «العيون»، وهي النقاط الفارغة التي تحتاجها المجموعة لتعيش.","222":"الأبيض 222 (L14) يأسر حجرًا. تبقى أحجار الأسود العليا منقسمة، وإنقاذ القسمين صار صعبًا جدًا. يؤتي هجوم الميجين الفاصل ثماره أخيرًا.","225":"الأسود 225 (R15) يغلق كو اليمين فتنجو مجموعته العليا اليمنى بالكاد. لكن الأبيض أخذ في الأثناء منتصف الأعلى، وما زال متقدمًا إجمالًا.","232":"الأسود 229 (P14) والأبيض 232 (Q14) يبدآن كو صغيرًا آخر في الأعلى يمينًا. يبحث الأسود عن فرص حتى النهاية، لكن الأبيض يرد بعناية.","239":"بالنقلتين 237 (F12) و239 (E13) يسترد الأسود أحجارًا في الأعلى يسارًا. ومع ذلك لا يعوّض ما خسره في منتصف الأعلى، ولا يتقلص الفارق الكلي.","244":"الأسود 241 (P18) والأبيض 242 (P19) والأسود 243 (P14) والأبيض 244 (N12): تستمر النقلات الصغيرة حتى النهاية، لكن الأبيض يأخذ نقاط الوسط المهمة واحدة تلو الأخرى. المباراة شبه محسومة.","246":"بعد الأبيض 246 (L8) استسلم إنتيتسو. في البداية حقق تقدمًا كبيرًا بفضل التفرّعة السرية لمدرسة إينوي، لكن جووا رد بنقلاته العبقرية بدءًا من 68 وبالنقلة 80 القبيحة لكنها ممتازة، وواصل شطر أحجار الأسود ومهاجمتها حتى قلب المباراة. يُروى أن إنتيتسو سعل دمًا على اللوحة أثناء جمع الأحجار. ربما كان مريضًا منذ مدة، وتوفي بعد ذلك بقليل. وبالنسبة لجووا الذي حافظ على لقب الميجين تُعدّ أعظم انتصار في حياته، وفشلت خطة غينان. وما زالت تُروى حتى اليوم بوصفها المباراة التي لعبها الشاب إنتيتسو بحياته."}},"deepblue1997":{"t":"انتصار ديب بلو","w":"ديب بلو (حاسوب IBM)","b":"غاري كاسباروف","ev":"المباراة السادسة من مواجهة الثأر مع ديب بلو من IBM (لقاء من ست مباريات)","d":"1997","pl":"الولايات المتحدة (نيويورك)","lead":"بطل العالم كاسباروف في مواجهة ديب بلو، حاسوب شطرنج صنعته IBM، في لقاء من ست مباريات. كانت النتيجة متعادلة بعد خمس مباريات، وانتهت الأخيرة في 19 نقلة فقط. كانت أول مرة يهزم فيها حاسوب بطل العالم في لقاء كامل من عدة مباريات.","c":{"0":"نيويورك، 11 مايو 1997. بطل العالم غاري كاسباروف في مواجهة ديب بلو، حاسوب شطرنج صنعته IBM، في لقاء من ست مباريات. كان كاسباروف قد فاز في العام السابق، لكن في مواجهة الثأر هذه مع ديب بلو الأقوى كانت النتيجة 2½–2½ بعد خمس مباريات. في المباراة الأخيرة لعب ديب بلو بالأبيض. كان العالم كله يتابع: من الأقوى، الإنسان أم الآلة؟ وُلد كاسباروف عام 1963 في باكو في أذربيجان اليوم. وفي 1985، وهو في الثانية والعشرين، هزم كاربوف وصار أصغر بطل للعالم حتى ذلك الوقت. وكانت جائزة هذه المباراة 700 ألف دولار للفائز و400 ألف دولار للخاسر.","1":"يتقدّم الأبيض ببيدق الملك مربعين، فيحتل الوسط ويفتح الطريق للقطع. نشأ «ديب بلو» من آلة شطرنج بدأ الباحث المولود في تايوان فينغ-شيونغ شو ورفاقه بناءها حين كانوا طلابًا في جامعة كارنيغي ميلون بالولايات المتحدة. ثم طوّرتها IBM كثيرًا، ويُقال إنها كانت تفحص مئات الملايين من الأوضاع في الثانية.","2":"يلعب كاسباروف c6 تحضيرًا لـ d5 ضد e4: دفاع كارو-كان. إنه متين، وكان يُختار كثيرًا ضد الحواسيب. في الحقيقة كان نادرًا أن يختار كاسباروف دفاع كارو-كان بـ c6؛ فقد كان يفضّل عادةً افتتاحيات تقود إلى معارك أحدّ.","3":"يضع الأبيض البيدق الآخر في الوسط أيضًا. بيدقان متجاوران. وفي يوليو من هذا العام، 1997، أُعيدت هونغ كونغ التي كانت تحكمها بريطانيا إلى الصين. كان عامًا شهد تغيّرات كبيرة في العالم.","4":"يلعب الأسود d5 ضد e4. يبدأ الصراع على بيادق الوسط.","5":"الحصان إلى c3 يحمي e4. نقلة طبيعية: تطوير ودفاع.","6":"يأخذ الأسود بيدق e4 ويبادل بيادق الوسط ليُصغّر وسط الأبيض.","7":"يستردّ الحصان. صار الحصان الأبيض في وسط الرقعة.","8":"يضع الأسود حصانًا في d7. فإذا خرج الحصان الآخر إلى f6 وبادل الأبيض الحصانين، يستطيع الأسود الاسترداد بهذا الحصان. ويُسمّى هذا الخط 4...Nd7 «تفريعة شتاينتس»، ولأن كاربوف، منافس كاسباروف القديم، كان يحبّه كثيرًا يُعرف أيضًا بـ«تفريعة كاربوف».","9":"يقفز الحصان إلى g5: خطة حادّة تصوّب نحو f7 وe6. يهاجم الأبيض مبكرًا قبل أن يستقر جناح ملك الأسود. كانت النقلة 5.Ng5 فكرة جديدة نسبيًا في ذلك الوقت. فهي تكسر عمدًا القاعدة الأساسية «لا تحرّك القطعة نفسها مرتين في الافتتاح» لتستهدف المربع الضعيف f7. وكان كاسباروف نفسه قد لعبها عدة مرات بالأبيض.","10":"يُخرج الأسود الحصان إلى f6. ازدادت القطع التي تحمي الملك.","11":"الفيل إلى d3. يصوّب قطريًا نحو h7، باتجاه جناح ملك الأسود.","12":"يلعب الأسود e6 ليقوّي الدفاع ويفتح طريق فيل f8. لكن بيدق e6 يصبح أيضًا هدفًا للحصان الأبيض.","13":"الحصان الآخر من g1 إلى f3. الأبيض جاهز للتبييت.","14":"يلعب الأسود h6 لطرد حصان g5. لكن في هذا الوضع كانت التضحية بالحصان في e6 معروفة من قبل. استغرب كثيرون أن يختار أستاذ مثل كاسباروف هذه النقلة، ويظن بعضهم أنه بدّل ترتيب النقلات سهوًا. هذه نقطة التحوّل. الخط المعتاد في الكتب هو 7...Bd6، ولا يُلعب h6 إلا بعد 8.Qe2. وإلى جانب الرأي القائل إن كاسباروف لعب h6 قبل وقتها بنقلة، كتب صانع «ديب بلو» شو أنه ربما اختارها عمدًا ليربك الحاسوب.","15":"يُضحّى بالحصان في e6! في المقابل يحطّم الأبيض البيادق حول الملك الأسود ويمنعه من التبييت. يُقال إن ديب بلو لعب هذه النقلة من نقلات الافتتاح المخزّنة لديه مسبقًا. وكانت هذه التضحية بالحصان قد ظهرت في عدة مباريات بين لاعبين أقوياء، وحقق فيها الأبيض نتائج جيدة. ومحركات الشطرنج القوية اليوم تعدّها أفضل نقلة حتى من دون إعداد مسبق للافتتاح.","16":"لا يأخذ الأسود فورًا، بل يضع الوزير في e7. على العمود e يصوّب نحو حصان e6 والملك الأبيض خلفه. إذا تحرّك الحصان صار الملك في كش، فلا يستطيع الحصان الهرب. ورأى كثير من المعلّقين أن هذا التثبيت كان خطأ، ويقترح بعضهم أن أخذ الحصان فورًا كان أفضل.","17":"يبيّت الأبيض ويُبعد الملك. لم يعد حصان e6 مثبّتًا. ولا يبالي الأبيض إن أُخذ الحصان.","18":"يأخذ الأسود الحصان ويتقدّم في العتاد. لكن البيادق حول الملك الأسود تحطّمت، والملك ضعيف الحماية.","19":"الفيل إلى g6، كش. بغياب بيدق f7 يصل القطر إلى الملك في e8.","20":"الملك إلى d8. لم يعد الأسود قادرًا على التبييت، وبقي الملك قرب الوسط. قطع الأسود يعترض بعضها بعضًا حول الملك.","21":"الفيل الآخر إلى f4، يصوّب نحو c7 وb8 ويضيّق مساحة الملك الأسود أكثر.","22":"يلعب الأسود b5 ليفسح مكانًا في جناح الوزير، ويُخرج الفيل إلى b7، ويعطي الملك مخرجًا. وكانت 11...b5 أول نقلة جديدة في المباراة، لم تظهر في مباريات سابقة. وهنا انتهت نظرية الافتتاح المعروفة.","23":"a4 يضرب بيدق b5. يريد الأبيض فتح الخطوط في جناح الوزير كي ينضمّ رخ a1 إلى الهجوم.","24":"يُخرج الأسود الفيل إلى b7 ويصوّب على القطر الطويل نحو g2. أخيرًا بدأت قطع الأسود تتحرّك.","25":"الرخ إلى e1. على العمود e ينظر إلى بيدق e6 وخلفه الوزير في e7. انضمّت كل قطع الأبيض إلى الهجوم.","26":"الحصان الأسود إلى d5، مربع قوي في الوسط: يهاجم فيل f4 ويحمي e6.","27":"يتراجع الفيل إلى g3. يواصل التصويب نحو c7 وb8 ويحافظ على الضغط على الملك الأسود.","28":"الملك الأسود إلى c8، أكثر أمانًا قليلًا، ويتيح لرخ d8 الحركة.","29":"يأخذ الأبيض بيدق b5. ينفتح العمود a، وينظر رخ a1 إلى بيدق a7.","30":"يستردّ الأسود ببيدق. لكن البيادق حول الملك الأسود تقلّ شيئًا فشيئًا.","31":"الوزير إلى d3: ينظر إلى بيدق b5 والمربع f5. قطع الأبيض تطوّق الملك الأسود شيئًا فشيئًا.","32":"يُرجع الأسود الفيل إلى c6 ليحمي بيدق b5.","33":"الفيل إلى f5! يمكن أخذه مجانًا. لكن إذا أخذه بيدق، يختفي بيدق العمود e، ويصل رخ e1 مباشرة إلى الوزير في e7.","34":"يأخذ الأسود ببيدق. الآن لا شيء على العمود e بين e1 وe7.","35":"يأخذ الرخ الوزير في e7. أعطى الأبيض حصانًا وفيلًا ورخًا، لكنه كسب أقوى قطعة: الوزير.","36":"يستردّ الأسود الرخ بالفيل. العتاد متقارب، لكن الملك الأسود بلا ملجأ تقريبًا.","37":"c4! يضرب البيدق b5 وd5 معًا، فيبدأ مدافعو الأسود بالانهيار. والوزير الأبيض جاهز للانضمام إلى الهجوم في أي لحظة. استسلم كاسباروف هنا، ربما لأنه رأى ملكه مكشوفًا أكثر من أن يوقف الهجوم. 19 نقلة فقط. كانت أول مرة يهزم فيها حاسوب بطل العالم في لقاء كامل من عدة مباريات: لحظة تاريخية. ومنذ ذلك الحين صار التعلّم والتدريب بالحاسوب أمرًا عاديًا في الشطرنج."}},"seigen1933":{"t":"مباراة 3-3 ونقطة النجم والتنغن","w":"غو سيغن","b":"هونينبو شوساي","ev":"مباراة تذكارية مع الميجين (أكثر من ثلاثة أشهر)","d":"1933–1934","pl":"اليابان (طوكيو)","lead":"لعب غو سيغن، وهو في التاسعة عشرة (5 دان)، ضد الميجين هونينبو شوساي. بالأسود افتتح على نقطة 3-3، ثم على نقطة نجم، ثم في المركز تمامًا (تنغن)، محطّمًا أعراف زمانه ومُدهشًا عالم الغو. مع توقفات كثيرة استمرت المباراة أكثر من ثلاثة أشهر، وفاز الأبيض بنقطتين.","c":{"0":"طوكيو، خريف 1933. الأسود: غو سيغن، 19 عامًا (5 دان). الأبيض: الميجين هونينبو شوساي، 59 عامًا. وُلد غو سيغن في فوجيان بالصين وجاء إلى اليابان في الرابعة عشرة طفلًا معجزة. في تلك السنة كان ينشر مع صديقه كيتاني مينورو طريقة لعب جديدة اسمها «شين فوسيكي» (الافتتاح الجديد)، تقدّر القوة في الوسط أكثر من أرض الزوايا، وصارت حديث عالم الغو. أما شوساي فكان آخر ميجين يحمل اسم هونينبو بالوراثة، ويقف في قمة الغو. أراد الجميع أن يروا كيف يتحدى الجيل الجديد المعلّم القديم. أُجّلت المباراة مرات كثيرة (تتوقف ثم تُستأنف في يوم آخر) ودامت أكثر من ثلاثة أشهر. لم يكن هناك كومي آنذاك، فلا يحسم النتيجة إلا الأرض على اللوح. بدأت المباراة في 16 أكتوبر 1933 في نُزل كاجيباشي بحيّ كيوباشي في طوكيو. كان غو سيغن قد فاز ببطولة اليابان للغو التي نظّمتها صحيفة يوميوري، وكانت هذه المباراة أمام الميجين جائزته. في عصر إيدو كانت حكومة الشوغون ترعى بيوت الغو، أما الآن فصارت الصحف هي التي تنظّم المباريات الكبرى وتنقل أخبارها يوميًا على صفحاتها. وفي العالم، صار هتلر مستشارًا لألمانيا في يناير من ذلك العام، وفي 17 أكتوبر، بعد بدء المباراة بيوم، وصل أينشتاين إلى أمريكا. وأثناء المباراة، في 23 ديسمبر، وُلد وليّ عهد اليابان (الإمبراطور أكيهيتو فيما بعد).","1":"الأسود 1 هو نقطة 3-3 في الأعلى يمينًا (R17)، حيث يتقاطع الخط الثالث من الحافتين. حجر واحد هناك يكاد يضمن أرض الزاوية. لكن قوته نحو الخارج ضعيفة، وكان يُظن آنذاك أنها «ليست نقلة للبداية». أمام الميجين بدأ غو سيغن بنقطة 3-3 مباشرة. لقد تغيّر الزمن: فاليوم صارت نقطة 3-3 حركة عادية حتى في بداية المباراة.","2":"الأبيض 2 هو الكوموكو (3-4) في الأعلى يسارًا (C16)، حيث يتقاطع الخطان الثالث والرابع. إنها أبسط نقلة افتتاحية، تُلعب منذ عصر إيدو. لم يُظهر الميجين أي دهشة واختار نقلته المعتادة. وُلد شوساي عام 1874 باسم تامورا ياسوهيسا، وكان هونينبو الحادي والعشرين، وصار ميجين عام 1914. وكان آخر هونينبو يرث اللقب عن طريق البيت. وفي عام 1936 سلّم اسم «هونينبو» إلى منظمة نيهون كي-إن، ومن هنا نشأت بطولة هونينبو التي يُنال فيها الاسم بالقوة. وكانت مباراة اعتزاله عام 1938 أمام كيتاني مينورو صديق غو سيغن، وقد رواها الكاتب كاواباتا ياسوناري في روايته «معلم الغو».","3":"الأسود 3 هو نقطة النجمة (هوشي) في الأسفل يسارًا (D4)، حيث يتقاطع الخطان الرابعان. على عكس 3-3، تقدّر الانتشار نحو الخارج أكثر من الأرض. في الزاوية المقابلة لنقطة 3-3 وضع الأسود حجرًا ذا طبع مختلف تمامًا. وُلد غو سيغن عام 1914 في مدينة فوتشو بإقليم فوجيان في الصين. وفي عام 1928، وهو في الرابعة عشرة، جاء إلى اليابان بدعوة من اللاعب المحترف سيغوي كينساكو، وساعد في ذلك رجل الأعمال أوكورا كيشيتشيرو وإينوكاي تسويوشي الذي صار لاحقًا رئيسًا للوزراء.","4":"الأبيض 4 يأخذ الزاوية السفلى اليمنى بكوموكو آخر (Q3). ينوي الأبيض أخذ الزوايا واحدة تلو الأخرى والتقدم في الأرض. مهما جرّب الأسود من جديد، لا تتزعزع خطة الميجين.","5":"الأسود 5 يذهب إلى منتصف اللوح تمامًا: التنغن (K10). التنغن قريب من كل الجهات بالقدر نفسه، فيمكنه دعم القتال في أي اتجاه. لكنه نادرًا ما يصير أرضًا، ولذلك لم يكد أحد يلعبه في الافتتاح. 3-3، النجمة، التنغن: بثلاثة أحجار عرض الأسود ثلاث أفكار جنبًا إلى جنب — أرض الزاوية، والانتشار نحو الخارج، وقوة الوسط. أحدث هذا الافتتاح الجريء ضجة كبيرة، ويُروى أن بعضهم عدّه قلة احترام للميجين. تشكّل «الشين-فوسيكي»، أي «الافتتاح الجديد»، في صيف 1933 هذا، حين درسه غو سيغن وكيتاني مينورو معًا في ينابيع جيغوكوداني الحارة في ناغانو. وفي مباريات الترقية الخريفية لعبه الاثنان فحلّا أولًا وثانيًا، وفي 1934 صدر كتاب «ثورة في الغو: الافتتاح الجديد» وبيعت منه 100 ألف نسخة. والحقيقة أن تينغن في الحركة الأولى جُرّب من قبل: يُروى أن شيبوكاوا هارومي (ياسوي سانتيتسو)، وكان عالم فلك أيضًا، افتتح بتينغن أمام هونينبو دوساكو في مباراة بقلعة إيدو عام 1670 وخسر بفارق 9 نقاط. هدأت موجة الشين-فوسيكي خلال سنوات قليلة، لكن فكرة تقدير الوسط انتقلت إلى اللاعبين من بعدهم.","6":"الأبيض 6 (Q16) «ضربة كتف» تتكئ قطريًا على حجر 3-3 الأسود في الأعلى يمينًا. يريد الأبيض حبس الأسود منخفضًا في الزاوية وبناء جدار سميك في الخارج. هذا هو الرد المعتاد على 3-3، وقد اتجه الميجين مباشرة إلى نقطة انطلاق الافتتاح الجديد للأسود.","8":"الأسود 7 (R16) يزحف والأبيض 8 (Q15) يمتد. يوسّع الأسود مكان حياته في الزاوية، ويمدّ الأبيض جداره نحو الجانب الأيمن. لا يدفع الأسود نحو الخارج هنا لأنه حدّد بوضوح أن دور حجر 3-3 هو «أرض الزاوية».","9":"الأسود 9 (P18) يقفز على الخط الثاني من الجانب العلوي، فيوسّع أرض الزاوية ويصنع شكلًا حيًّا متينًا. صار تقسيم الأدوار في الأعلى يمينًا واضحًا: الزاوية أرض للأسود، والخارج سُمك للأبيض.","10":"الأبيض 10 (R6) يقع حيث يعمل مع الجدار في الأعلى يمينًا (Q16 وQ15) ومع الحجر في الأسفل يمينًا (Q3) معًا. نقلة كبيرة هادئة تهدف إلى جعل الجانب الأيمن كله مجالًا للأبيض.","11":"الأسود 11 (K4) في منتصف الجانب السفلي، على الخط الرابع تحت التنغن مباشرة. مصطفًّا عموديًا مع K10، يستهدف إطارًا كبيرًا من الأسفل حتى الوسط. كل أحجار الأسود عالية؛ واضح أن الأسود يقدّم النفوذ على الأرض.","12":"الأبيض 12 (M3) يقترب من جهة الزاوية السفلى اليمنى ويحطّ على الخط الثالث يمين K4 مباشرة. إنها نقلة لاتخاذ موطئ قدم مبكر حتى لا يطوّق الأسود الجانب السفلي. لو تُرك لربما لعب الأسود هنا وحوّل الأسفل إلى أرض كبيرة.","13":"الأسود 13 (D10) يأخذ منتصف الجانب الأيسر. مع D4 وD10 على اليسار وK4 وK10 في الوسط، انتشرت الأحجار السوداء كالشبكة فوق النصف السفلي الأيسر. وعدم الرد فورًا على الأبيض 12 وأخذ نقطة كبيرة أولًا هو روح الشين فوسيكي.","14":"الأبيض 14 (E16) يضع حجرًا ثانيًا في الزاوية العليا اليسرى ويغلقها (شيماري). لا ينشغل الميجين بالأسلوب الجديد ويواصل ضمان الزوايا لنفسه. انقسمت الخطط الآن بوضوح: للأبيض زاويتان والجانب الأيمن، وللأسود زاويتان والوسط. كان الغو التقليدي يقدّر ترتيب «الزوايا أولًا، ثم الجوانب، والوسط في الآخر». ويلعب شوساي تمامًا كما تقول هذه الفكرة، أما الأسود فينظر إلى الوسط أولًا على طريقة الافتتاح الجديد. إنها أفكار عصرين تتصادم على لوح واحد.","15":"الأسود 15 (M5) يغطي حجر الأبيض M3 من الأعلى. يريد الأسود دفع الأبيض إلى الأسفل وبناء جدار في الخارج. الفكرة: حتى لو أخذ الأبيض بعض الأرض في الأسفل، يحوّل الأسود ذلك إلى قوة في الوسط.","18":"الأبيض 16 (O3) يوسّع قاعدته نحو حجر الأبيض في Q3، ثم مع الأسود 17 (L3) والأبيض 18 (M4) تتصادم الأحجار في الجانب السفلي. يعيش الأبيض على الخط الثالث مؤمّنًا الأرض، ويضغط الأسود من الأعلى. كلٌّ يمضي في خطته.","20":"الأبيض 20 (C12) ينزلق من الزاوية المغلقة في الأعلى يسارًا نزولًا على الخط الثالث. يقترب من D10 ويمنع الجانب الأيسر كله من أن يصير أسود. كانت طريقة الميجين أخذ الأرض شيئًا فشيئًا من الحواف قبل أن يكبر إطار الأسود. في هذه المباراة كان يحق لشوساي أن يؤجّل اللعب حين يأتي دوره، فبلغ عدد التأجيلات 13 مرة. وانتقد بعضهم ذلك قائلين إنه كان يستطيع التشاور مع تلاميذه في فترات التوقف، فبدأ منذ مباراة اعتزال شوساي عام 1938 استعمال «الحركة المختومة»: عند التوقف تُكتب الحركة التالية على ورقة وتُختم في ظرف.","21":"الأسود 21 (G10) يقع تمامًا بين D10 على الجانب الأيسر وK10 في التنغن. صارت الأحجار السوداء صفًّا على ارتفاع الخط الرابع: جدار كبير من اليسار حتى الوسط. لا يبالي الأسود بأرض الأبيض ويواصل توسيع نفوذه في الوسط.","22":"الأبيض 22 (F3) يقترب من نجمة الأسود D4 في الأسفل يسارًا من جهة الجانب السفلي (كاكاري). للأبيض أحجار في الأسفل يمينًا وعلى الجانب السفلي، فإن صنع هنا أرضًا أيضًا صار الحد السفلي كله أبيض. إنها تقشط الحافة الدنيا من إطار الأسود الكبير.","25":"الأسود 23 (F5) يغطي F3، وحين يمتد الأبيض 24 (J3) يمينًا في الأسفل يضغط الأسود 25 (G4) من الأعلى مجددًا. الأبيض على الخط الثالث، والأسود على الرابع والخامس: نمط هذه المباراة — الأبيض يأخذ الأرض والأسود الجدران — يتكرر هنا.","26":"الأبيض 26 (C3) هو نقطة 3-3 داخل نجمة الأسود D4 في الأسفل يسارًا. ينسلّ تحت حجر النجمة مباشرة ليأخذ أرض الزاوية. للنجمة قوة كبيرة نحو الخارج، لكن ضعفها أنها لا تحفظ الزاوية إذا غُزيت نقطة 3-3. وما زال هذا الاقتحام في 3-3 تحت نقطة النجمة حتى اليوم بداية شائعة لجوسيكي نقطة النجمة في الافتتاح.","28":"الأسود 27 (C4) يسدّ من الخارج، والأبيض 28 (D3) يصنع شكلًا حيًّا في الزاوية. يتنازل الأسود عن الزاوية للأبيض ويكسب مقابلها جدارًا سميكًا يواجه الوسط: C4 وD4 وF5 وG4. بالنظر إلى الافتتاح، للأبيض أرض في الزوايا العليا اليسرى والسفلى اليمنى والسفلى اليسرى وفي الجانب السفلي، وللأسود الزاوية العليا اليمنى ونفوذ في الوسط. كم من هذا النفوذ سيصير أرضًا هو ما سيحسم المباراة من الآن.","29":"الأسود 29 (O16) يُلعب على الجانب العلوي، يسار جدار الأبيض في الأعلى يمينًا (Q16 وQ15). يمنع الجدار من العمل على طول الأعلى ويوسّع زاوية الأسود نحو الحافة العليا. يقف على مسافة معقولة من سُمك الأبيض.","30":"الأبيض 30 (Q12) يمتد نزولًا على الجانب الأيمن من الجدار العلوي ويصنع قاعدة (موطئًا للحياة). صار أسهل الآن أن تتصل أحجار الأبيض في الأعلى بـ R6، وبدأ الجانب الأيمن يبدو أرضًا بيضاء.","31":"الأسود 31 (Q10) يحطّ على نجمة الجانب الأيمن، تمامًا بين Q12 وR6. يمنع الأبيض من جعل الجانب الأيمن كله أرضًا، ويتجاوب أيضًا مع نفوذ الأسود في الوسط. من هنا يصير الجانب الأيمن ساحة قتال تختلط فيها أحجار اللونين.","33":"الأبيض 32 (O15) يلتصق تحت O16 ويزعزع جذر حجر الأسود في الأعلى. الأسود 33 (N15) يسدّ من اليسار ويغلق على الأبيض الطريق نحو اليسار والوسط. بعدم السماح للأحجار البيضاء بالخروج، يريد الأسود أن يكون الجانب العلوي منطقة نفوذه.","35":"حين يمتد الأبيض 34 (N14) إلى الأسفل، يقطع الأسود 35 (O14) بين O15 وN14. بعد القطع تنقسم أحجار الأبيض إلى مجموعتين ضعيفتين. يجعل الأسود الأبيضَ يقاتل داخل منطقة نفوذه ويريد الربح وهو يهاجم.","37":"بعد الأبيض 36 (O13)، يأسر الأسود 37 (P15) حجر الأبيض في O15: أول أسير في المباراة. يرد الأسود على الأبيض 38 (P14) بـ 39 (O15) واصلًا، فتتصل أحجار الأسود في الأعلى يمينًا بالجانب العلوي بإحكام. خسر الأبيض حجرًا لكنه أطلّ على الوسط بـ O13 وN13 وN14.","40":"الأبيض 40 (O10) يقفز بعيدًا نحو الوسط من O13 ويحطّ بين Q10 على الجانب الأيمن والتنغن. صار للأبيض موطئ قدم داخل إطار الأسود في الوسط. وللأسود أيضًا فرصة لمهاجمة هذه الأحجار داخل منطقته.","41":"الأسود 41 (P7) يُلعب في أسفل الجانب الأيمن: يضغط R6 من الأعلى ويتعاون مع Q10. صارت أحجار الأبيض على الجانب الأيمن، Q12 فوقًا وR6 تحتًا، محصورة بين الأسود ويصعب اتصالها. يريد الأسود تقليص أرض الأبيض على اليمين أيضًا.","43":"بعد أن يصل الأبيض 42 (N13) أحجاره في الوسط ويطمئن عليها، يمتد الأسود 43 (L15) يسارًا على الجانب العلوي. يطول جدار الأسود في الأعلى، وتصير المنطقة من الأعلى إلى الوسط نفوذًا للأسود. لا يستعجل الأسود القتال، بل يكبّر مجاله أولًا.","44":"الأبيض 44 (H17) يمتد من الزاوية المغلقة في الأعلى يسارًا على طول الجانب العلوي، فيوقف نفوذ الأسود قبل أن يكبر. هنا أيضًا يضع الميجين حجرًا على الجانب، حيث تسهل صناعة الأرض، قبل أن يتسع إطار الأسود. حافة أخرى من إطار الأسود الكبير صارت للأبيض.","45":"الأسود 45 (R7) يلتصق فوق R6 مباشرة على الجانب الأيمن. هنا يبدأ أول قتال كبير في المباراة. يريد الأسود قطع R6 عن أحجار الأبيض في الأعلى (Q12) وشطر الجانب الأيمن للأبيض إلى نصفين. والأبيض لا يتراجع، فيستمر بعد ذلك من الجانب الأيمن إلى الزاوية السفلى اليمنى شكل صعب بأحجار مقطوعة من الطرفين.","48":"الأبيض 46 (S7)، الأسود 47 (S6)، الأبيض 48 (S8). يضع الأبيض أحجارًا على الخط الثاني تحت R7 وفوقه ليكتسب قوة حوله. ويلتفّ الأسود S6 إلى أسفل يمين R6 فيسلبه المكان ليعيش بسهولة على الحافة. كل طرف يضرب نقاط ضعف الآخر.","52":"الأسود 49 (S5)، الأبيض 50 (Q7)، الأسود 51 (R8)، الأبيض 52 (R9). يدخل Q7 بين R7 وP7، ومع R8 وR9 تصير الأحجار مقطوعة بعضها عن بعض. على الجانب الأيمن تبقى أحجار الطرفين مقطوعة: قتال صعب يعاني فيه من يترك أولًا مجموعة ضعيفة.","55":"الأسود 53 (Q8)، الأبيض 54 (Q6)، الأسود 55 (Q9). يمتد الأسود إلى Q8 وQ9 فيصل R7 وR8 بـ Q10 في الأعلى. وبـ Q6 يجمع الأبيض حجريه السفليين R6 وQ7 في مجموعة واحدة. صارت أحجار الأسود على اليمين سلسلة واحدة، لكنها محاطة بالأبيض وحرياتها قليلة.","58":"الأبيض 56 (R10)، الأسود 57 (O8)، الأبيض 58 (Q11). بـ R10 وQ11 يصل الأبيض حجره العلوي على الجانب الأيمن (Q12) بـ R9 وS8 على الحافة. ويقوّي الأسود جهة الوسط بـ O8 ويغلق على الأبيض الطريق إليه. اتصلت أحجار الأبيض على اليمين أعلى وأسفل، والأسود بالوسط، فهدأ القتال إلى حين.","59":"الأسود 59 (R4) يغزو الآن الزاوية السفلى اليمنى، داخلًا أرض Q3. ويستهدف أيضًا الاتصال بـ S5 وS6 في الأعلى، ويهدد أساس أحجار الأبيض R6 وQ6 وQ7. صار على الأبيض اختيار صعب: حماية أرض الزاوية أم الأحجار في الخارج.","63":"الأبيض 60 (P6)، الأسود 61 (O6)، الأبيض 62 (O5)، الأسود 63 (N5). بـ P6 وO5 يذهب الأبيض لوصل أحجار الجانب الأيمن بأحجاره في الأسفل، ويضغط الأسود من الأعلى ومن اليسار بـ O6 وN5. عبر O6 يقرّب الأسود جداره السفلي (M5) من حجريه P7 وO8. اختار الأبيض حماية الأحجار في الخارج، وبقي الأسود داخل الزاوية السفلى اليمنى.","66":"بالأبيض 64 (P4) يصل الأبيض الأحجار التي نزلت على الجانب الأيمن بـ Q3 في الأسفل بإحكام. ويستمر التجاذب داخل الزاوية مع الأسود 65 (R2) والأبيض 66 (R3). يحاول الأسود أن يصنع مكانًا للحياة في الزاوية على الخطين المنخفضين الأول والثاني.","69":"الأسود 67 (S3)، الأبيض 68 (Q2)، الأسود 69 (S2). يصل الأسود أحجاره على حافة الزاوية السفلى اليمنى ويصنع شكلًا حيًّا. صارت زاوية الأبيض أصغر بكثير مما كان متوقعًا، لكن أحجار الأبيض في المقابل متصلة بسُمك في الخارج (P4 وP6 وQ6). الأسود قضم الأرض والأبيض قوّى الخارج: نتيجة يقبلها الطرفان.","70":"الأبيض 70 (N6) يدخل بين O6 وN5، عند ملتقى أحجار الأسود في الجانب السفلي والجانب الأيمن. الهدف فصل أحجار الأسود وإضعاف جزء منها. يصل الأسود 71 (O7) فورًا ويبقي أحجاره على اليمين معًا.","74":"بعد الأبيض 72 (M7) والأسود 73 (M8)، يدفع الأبيض 74 (L4) بين K4 وL5 في الجانب السفلي محاولًا عزل حجر الأسود L3 بين أحجار الأبيض في الأسفل. ثم الأسود 75 (N4) والأبيض 76 (N3)، فتتصل أحجار الأبيض السفلى بأحجار اليمين على الخط الثالث.","78":"الأسود 77 (J4) يصل جداره السفلي نحو اليسار، والأبيض 78 (K3) يسدّ مخرج حجر الأسود L3. لم يبقَ لـ L3 إلا حرية واحدة (L2). يتخلى الأسود عنه ويقدّم الجدار الطويل المواجه للوسط: J4 وK4 وL5 وM5 وN5 وN4. بدل التمسك بحجر صغير، يحمي الأسود خطته الكبيرة.","79":"الأسود 79 (L9) يُلعب أسفل يمين التنغن (K10) فيزيد أحجار الأسود في الوسط سُمكًا. الجدار السفلي، وأحجار اليمين من O6 إلى Q10، والتنغن، وأحجار اليسار من D10 إلى G10 تحيط الآن بإطار هائل في الوسط. يكسب الأبيض أرضًا في الزوايا والجوانب، والسؤال: كم من الوسط يستطيع الأسود تحويله إلى أرض؟ يبدو الوضع قريبًا من التعادل، وتدخل المباراة قتال وسط اللعب.","80":"الأبيض 80 (C6) يصعد من زاوية الأبيض السفلى اليسرى على الجانب الأيسر ويضع حجرًا على الخط الثالث بجانب جدار الأسود. يضيّق الجانب الأيسر للأسود وسيكون لاحقًا موطئًا لغزو هناك. ويرمّم الأسود 81 (E4) الثغرة بين D4 وF5/G4 فيصير الجدار قطعة واحدة.","82":"الأبيض 82 (C10) يغزو ملتصقًا يسار D10 من جهة الحافة. لو صار الجانب الأيسر كله أرضًا للأسود لكان إطار الأسود في الوسط ضخمًا جدًا. لا يسمح الأبيض بذلك ويحاول العيش في أقصى يسار تشكيل الأسود.","85":"الأسود 83 (C9)، الأبيض 84 (D9)، الأسود 85 (C8)، الأبيض 86 (D8). يسدّ الأسود تحت C10 من جهة الحافة، ويمتد الأبيض بـ D9 وD8 على الجانب الداخلي من جدار الأسود. كل طرف يدفع الآخر نحو الحافة. لا يمكن بعدُ اعتبار أي من المجموعتين حية.","88":"الأسود 87 (C11) نقلة قاسية تقطع بين C10 وC12. ينزل الأبيض 88 (B10) نحو الحافة ويوسّع مكان حياة C10. هدف الأسود فصل أحجار الأبيض الغازية ثم مهاجمتها.","91":"الأسود 89 (B11)، الأبيض 90 (D11)، الأسود 91 (E10). يمدّ الأسود الحجر القاطع بـ B11، لكن الأبيض يضغط بـ D11 على رأس D10 من الأعلى. يصل E10 الحجر D10 بجهة التنغن ويحمي جدار الأسود الأيسر. الحجران القاطعان B11 وC11 محصوران بين أحجار بيضاء وحرياتهما تتناقص.","96":"بالأبيض 92 (B12) لم يبقَ للحجرين الأسودين B11 وC11 إلا حرية واحدة. لا ينقذهما الأسود، بل يسدّ بـ 93 (D7) أسفل D9 وD8. ثم الأبيض 94 (E11) والأسود 95 (F10) والأبيض 96 (C7)، وصار كل طرف على الجانب الأيسر يحاول أسر أحجار الآخر. اختار الأسود بجرأة الأسر بدل الإنقاذ.","98":"بعد الأسود 97 (A9)، يأسر الأبيض 98 (A11) الحجرين الأسودين B11 وC11. يصنع الأبيض شكلًا حيًّا على حافة الجانب الأيسر، وصارت أرض الأسود هناك أصغر من المتوقع. وفي المقابل، بعد الأسود 99 (E8) لم يبقَ لـ D9 وD8 إلا حرية واحدة (E9)، ويستطيع الأسود أسرهما متى شاء. حجران ضاعا وحجران كُسبا: انتهى الجانب الأيسر بالتعادل تقريبًا.","100":"الأبيض 100 (B4) يوسّع زاوية الأبيض السفلى اليسرى وهو يضغط أسفل C4. بـ B4 ثم C5 قريبًا تتصل حجرا الزاوية C3 وD3 بـ C6 وC7 على الجانب الأيسر. صارت أحجار الأبيض من الأسفل يسارًا إلى الجانب الأيسر مجموعة واحدة قوية.","101":"الأسود 101 (S14) ينزلق من زاويته في الأعلى يمينًا نزولًا على الجانب الأيمن، فيقلّص الجزء الأعلى من أرض الأبيض على اليمين (Q12 وQ11). وبينما يثبّت الأبيض 102 (C5) الأسفل يسارًا، يتقدم الأسود خطوة أخرى بـ 103 (R13)، ويحمي الأبيض 104 (S12) أرضه اليمنى بالكاد. تتحدد الحدود بين الأراضي شيئًا فشيئًا.","105":"الأسود 105 (K17) يُلعب في منتصف الجانب العلوي، يمين H17. يمنع أرض الأبيض في الأعلى من الامتداد يمينًا أكثر، ويتعاون مع حجري الأسود L15 وN15. يبدو أن الجانب العلوي مقبل على قتال على الحدود: الأبيض يسارًا والأسود يمينًا.","106":"الأبيض 106 (G3) يلتصق الآن على الجانب السفلي تحت G4 مباشرة. يريد الأبيض سدّ الفجوة بين F3 وJ3 بحجره وتثبيت أرضه السفلى. ويدخل الأسود 107 (E3) بين D3 وF3 ليقطع. قد يبدو صغيرًا، لكن هذا التبادل يحدد أين تمر حدود الأرض.","108":"الأبيض 108 (E6) يُلعب فوق جدار الأسود في الأسفل يسارًا، أعلى D4 وE4 بقليل. بالتعاون مع C5 وC6 على الجانب الأيسر، ينخز ظهر جدار الأسود. يضغط الأسود 109 (F6) فورًا من الأعلى ويمنع الأبيض من الخروج إلى الوسط.","113":"الأبيض 110 (E2) والأسود 111 (F2) والأبيض 112 (D2) يواصلون التجاذب على الأحجار في الحافة السفلى، ويدخل الأسود 113 (H3) بين G3 وJ3. يحاول تفريق أحجار الأبيض السفلى وتقليص أرضها. يريد الأسود إنقاص أرض الأبيض تحت جداره ولو قليلًا.","116":"يصل الأسود 115 (H4) الحجر H3 بالجدار، ويصل الأبيض 116 (G2) حجري F3 وG3 من الأسفل. لم يبقَ لحجر الأسود F2 إلا حرية واحدة (F1)، فهو مأسور تقريبًا. ورغم نخز ثغراته، بقي الجانب السفلي للأبيض متماسكًا.","117":"الأسود 117 (F17) يغزو على الخط الثالث من الجانب العلوي، بين زاوية الأبيض المغلقة (C16 وE16) وH17. يقضم أرض الأبيض في الأعلى، ويهدف إن أمكن إلى فصل أحجار الأبيض ومهاجمتها. يبدأ قتال جديد في النصف الأيسر من الأعلى.","120":"يقوّي الأبيض 118 (J17) أحجاره في الأعلى، ويدخل الأسود 119 (D17) أعمق في الزاوية العليا اليسرى. الأبيض 120 (C17) يحمي الزاوية. يحاول الأسود أخذ أعلى جزء من زاوية الأبيض، حول الخط الثاني. يحرس الأبيض الزاوية وهو يستعد لتضييق الخناق على الأسود من الخارج.","124":"الأسود 121 (G16)، الأبيض 122 (H15)، الأسود 123 (G15)، الأبيض 124 (K15). بـ G16 وG15 يمتد الأسود نحو الوسط ليفصل أحجار الأبيض في الأعلى يسارًا عن H17. وبـ H15 وK15 يصل الأبيض أحجاره العليا نحو جهة الوسط ويهدد حجر الأسود K17 في الأعلى. في هذا القتال العلوي تُطلّ أحجار الأسود والأبيض برؤوسها بالتناوب.","127":"الأسود 125 (H16)، الأبيض 126 (J16)، الأسود 127 (H14). يضغط الأسود على حجر الأبيض H15 من الأعلى بـ H16 ومن الأسفل بـ H14. صار H15 محاصرًا ولم تبقَ له إلا حرية واحدة (J15). يأخذ الأسود أعلى الوسط لنفسه وهو يُضعف أحجار الأبيض واحدًا تلو الآخر.","130":"الأبيض 128 (L16)، الأسود 129 (M15)، الأبيض 130 (L17). بـ L16 وL17 يحبس الأبيض حجر الأسود K17 على الجانب العلوي ويعطي أحجاره العليا شكلًا حيًّا. لم يعد K17 يكاد يتحرك. النتيجة: كسب الأسود أعلى الوسط، واحتفظ الأبيض بأرض الجانب العلوي.","133":"الأسود 131 (P13)، الأبيض 132 (P12)، الأسود 133 (Q13). يضغط الأسود على قاعدة أحجار الأبيض في الجانب الأيمن ويقطع أحجار الأبيض في الأعلى يمينًا Q16 وQ15 وP14 عن Q12. هذه الأحجار البيضاء محاصرة بالأسود وفي شكل سيئ. صارت الزاوية العليا اليمنى أرضًا سوداء مضمونة إلى حد كبير.","135":"يتقدم الأبيض 134 (E7) خطوة من الأسفل يسارًا إلى داخل جدار الأسود، ويأسر الأسود 135 (E9) حجري الأبيض D9 وD8. كان الأسود قد خسر حجرين على الجانب الأيسر من قبل، فاسترد الآن العدد نفسه. صارت أحجار الأسود على اليسار آمنة، وتتضح أرض الأسود من الجانب الأيسر إلى الوسط.","137":"الأبيض 136 (F7)، الأسود 137 (G7). يصفّ الأبيض E6 وE7 وF7 فوق جدار الأسود في الأسفل يسارًا محاولًا الخروج إلى الوسط، ويوقفه الأسود بـ G7. إطار الأسود في الوسط يُقشط شيئًا فشيئًا من الأسفل أيضًا. لا يندفع الأبيض عميقًا؛ خطته تصغير الحواف واحدة تلو الأخرى.","138":"الأبيض 138 (N18) يدخل على الخط الثاني في الجزء الأيمن من الجانب العلوي، يسار P18 وO16. يقلّص أرض الأسود في الأعلى يمينًا من جهة الحافة العليا. ولاحقًا يتقدم الأبيض 148 (O18) أكثر نحو اليمين، فتُقشط أرض الأسود العليا شيئًا فشيئًا.","139":"الأسود 139 (C18) يغزو الآن على الخط الثاني فوق زاوية الأبيض العليا اليسرى. فوق زاوية الأبيض (C16 وC17 وE16) ما زال هناك مكان ليعيش الأسود. إن عاش هنا تقلّصت أرض الأبيض في الأعلى يسارًا كثيرًا. نقلة جريئة: محاولة العيش بجوار أحجار الأبيض السميكة مباشرة.","145":"الأبيض 140 (E17)، الأسود 141 (E18)، الأبيض 142 (D16)، الأسود 143 (D18)، الأبيض 144 (G18)، الأسود 145 (B17). يصفّ الأسود C18 وD18 وE18 على الخط الثاني ويتوغل في الزاوية بـ B17. يقوّي الأبيض الخارج بـ E17 وD16 ويمنع الأسود من الامتداد يمينًا بـ G18. فوق زاوية الأبيض تتواصل سلسلة دقيقة: الأسود يحاول العيش في مكان ضيق.","150":"الأبيض 146 (B16)، الأسود 147 (B18)، الأبيض 148 (O18)، الأسود 149 (P19)، الأبيض 150 (F18). يجمع الأسود أحجاره فوق الزاوية العليا اليسرى، ويضيّق الأبيض من الخارج بنقلات مثل F18. لم يبقَ من زاوية الأبيض في الأعلى يسارًا إلا الجزء تحت الخط من B16 إلى E16. أبقى الأسود أحجاره حية داخل منطقة الأبيض وقلّص أرضه هناك كثيرًا. وفي الأثناء قشط الأبيض أيضًا أرض الأسود في الأعلى يمينًا بـ O18، وتستمر التبادلات الدقيقة.","152":"الأبيض 152 (G12): أخيرًا يدخل الأبيض إطار الأسود في الوسط. يقع G12 بين أحجار الأبيض على الجانب الأيسر (E11 وD11) وأحجاره في الأعلى، في ثغرة من سُمك الأسود. إن عاش الأبيض هنا أو اتصل بالأحجار البيضاء حوله، فلن يصير وسط الأسود أرضًا. من هنا تبدأ أكبر ذروة في المباراة.","153":"الأسود 153 (K14) يُلعب تحت حجر الأبيض K15 في الأعلى مباشرة، ويغلق الطريق الذي قد يصل به الأبيض G12 بأحجاره العليا. وهو في الوقت نفسه طريق عريض يصل أحجار الأسود في الوسط من الأعلى والأسفل. يريد الأسود شطر الأبيض إلى جزء علوي وجزء أوسط ومهاجمة أحدهما.","156":"ينقذ الأبيض 154 (J15) حجر الأبيض H15 في الأعلى، وبعد الأسود 155 (F14) يأتي الأبيض 156 (H11). يضع الأبيض حجرًا آخر في الوسط ويوسّع مع G12 موطئه داخل وسط الأسود. يتسرب الأبيض شيئًا فشيئًا إلى وسط الأسود من الأعلى ومن اليسار.","159":"الأبيض 158 (E5) ينخز داخل جدار الأسود في الأسفل يسارًا. لو لعب الأبيض بعده F4 لانقطع جدار الأسود بين E4 وF5. لذلك يصل الأسود 159 (F4) بإحكام. قبل قتال الوسط، يصلح الأسود نقاط ضعف جداره واحدة تلو الأخرى.","160":"الأبيض 160 (H8): أشهر نقلة في المباراة. في المساحة الواسعة أسفل إطار الأسود في الوسط، المحاطة بأحجار سوداء مثل G7 وG10 وK10 وL9، يضع الأبيض حجرًا واحدًا فقط. يقال إن هذا الحجر يستهدف عدة ثغرات في الروابط بين أحجار الأسود، ولا يستطيع الأسود حمايتها كلها دفعة واحدة. انطلاقًا من هذه النقلة يبدأ الأبيض بالتوغل في أرض الأسود في الوسط نقطة بعد نقطة. انتشرت شائعة بأن من وجد النقلة تلميذ لا شوساي نفسه، لكن لا شيء مؤكد في ذلك.","161":"الأسود 161 (J8) يُلعب يمين H8 ويمنع الأبيض من الانتشار تحت التنغن، بينه وبين جدار الأسود السفلي. إنه رد عادي يحمي ما يبدو الأكبر. لكن هدف الأبيض التالي كان في مكان آخر.","162":"الأبيض 162 (K12) يحطّ الآن فوق التنغن (K10). بالتعاون مع G12 وH11 يحاول شطر وسط الأسود إلى جزء أعلى وجزء أسفل. هزّة في الأسفل بـ H8 ثم الالتفاف فورًا إلى الأعلى: كلما حمى الأسود نقطة، لمس الأبيض نقطة ضعف أخرى. سلسلة بارعة.","165":"الأسود 163 (F12) يُلعب يسار G12 ليفصل هذا الحجر الأبيض عن أحجار الأبيض على الجانب الأيسر. يطلب الأبيض 164 (F11) الاتصال، ويسدّ الأسود 165 (H10) أسفل H11 حتى لا تخرج أحجار الأبيض في الوسط نحو الأسفل. في الوسط تتشابك أحجار الأسود والأبيض، وكل طرف يحاول قطع الآخر.","168":"الأبيض 166 (J14)، الأسود 167 (J12)، الأبيض 168 (J11). بـ J14 يمدّ الأبيض أحجاره العليا إلى الأسفل، وبـ J11 يتصل بحجره الأوسط H11. حجر الأسود J12 يقطع بين جزأي الأبيض الأعلى والأسفل. صار الوسط قتالًا دقيقًا جدًا تنقطع فيه أحجار كثيرة وتتصل.","172":"الأسود 169 (J13)، الأبيض 170 (K13)، الأسود 171 (K11)، الأبيض 172 (F13). بـ F13 يمدّ الأبيض يده نحو أحجاره على اليسار محاولًا وصل أحجار الوسط بأحجار الجانب الأيسر والزاوية العليا اليسرى. ما كان سُمك الأسود في الوسط يتحول الآن إلى طريق تعبره أحجار الأبيض.","175":"ينقذ الأسود 173 (L14) حجره في K14، ثم الأبيض 174 (J10) والأسود 175 (J9). بـ J10 يدخل الأبيض يسار التنغن مباشرة، ويسدّ الأسود من الأسفل بـ J9. وصلت أحجار الأبيض إلى النقطة المجاورة للتنغن (K10)، وتواصل أرض الأسود في الوسط التقلص.","178":"يصل الأبيض 176 (H12) أحجاره في الوسط، وبعد الأسود 177 (G14) يأتي الأبيض 178 (N9). هذه المرة يدخل الجزء الأيمن من الوسط، بين L9 وO8. غُزي وسط الأسود من اليسار ومن اليمين، ولم يعد يبدو أنه سيصير أرضًا كبيرة. ولا يفوّت الأبيض نقاط ضعف الأسود في الجهة الأخرى من اللوح أيضًا.","180":"بعد أن يحمي الأسود 179 (D14) أحجاره في الأعلى يسارًا، يمتد الأبيض 180 (N8) أكثر نحو الأسفل. بـ N9 وN8 يحاول الأبيض فصل أحجار الأسود على الجانب الأيمن من O6 إلى O8 عن حجري الوسط L9 وM8. أحجار الأسود على اليمين محاطة بالأبيض وحرياتها قليلة، فصارت نقطة ضعف جديدة.","186":"بعد تبادل على الحافة اليمنى بين الأسود 181 (T7) والأبيض 182 (T9)، يسدّ الأسود 183 (N7) أسفل N8، وبعد الأبيض 184 (D13) والأسود 185 (M11) يأتي الأبيض 186 (P8). نقلة حادة تقطع بين P7 وQ8. لم يبقَ لأحجار الأسود الخمسة على الجانب الأيمن O6 وO7 وO8 وP7 وN7 إلا حرية واحدة (O9)، ولأحجاره الخمسة من R7 إلى Q10 حريتان فقط. بنقلة واحدة استهدف الأبيض مجموعتين للأسود معًا.","189":"يأسر الأسود 187 (M6) حجر الأبيض N6، وبعد الأبيض 188 (O9) يأسر الأسود 189 (L7) حجر الأبيض M7. هكذا تزيد حريات أحجار الأسود الخمسة من O6 إلى P7 وتنجو باتصالها بأحجار الأسود السفلى. أسر الأسود حجرين أبيضين، لكن الأبيض في الأثناء امتد بـ O9 إلى مجموعة الأسود الأخرى على الجانب الأيمن.","192":"بعد الأبيض 190 (F8) والأسود 191 (G8) يأتي الأبيض 192 (P10). لم يبقَ لأحجار الأسود الخمسة على الجانب الأيمن R7 وR8 وQ8 وQ9 وQ10 إلا حرية واحدة: P9. حتى لو لعب الأسود P9 وأسر حجر الأبيض P8، يستطيع الأبيض أن يعود فورًا إلى P8 ويأسرها جميعًا معًا («الضربة المرتدة»)، فلم يعد إنقاذ هذه الأحجار الخمسة ممكنًا. انطلاقًا من قطع الأبيض 186، حقق الأبيض مكسبًا كبيرًا على الجانب الأيمن. جزء من نفوذ الأسود نحو الوسط لم يصر أرضًا، بل صار فريسة للأبيض.","197":"بعد الأسود 193 (R12) والأبيض 194 (S11) والأسود 195 (C14) والأبيض 196 (E14) يأتي الأسود 197 (G11). لم يبقَ لأحجار الأبيض الخمسة في الوسط G12 وH12 وH11 وJ11 وJ10 إلا حرية واحدة: G13. يريد الأسود أسر الأبيض في الوسط واسترداد خسارته على الجانب الأيمن. نجاة أحجار الأبيض في الوسط أو عدمها هو ما سيحسم المباراة.","198":"يأسر الأبيض 198 (E12) حجر الأسود F12. صارت لأحجار الأبيض الخمسة في الوسط حرية في F12 أيضًا، ويمكنها الاتصال بأحجار الأبيض على اليسار عبر F12 أو G13. إن سدّ الأسود إحداهما وصل الأبيض عبر الأخرى، فلم يعد أسر أحجار الأبيض في الوسط ممكنًا. نجت الأحجار البيضاء التي شقّت سُمك الأسود: هذا هو المشهد الذي حسم المباراة.","203":"بالأسود 199 (E15) والأبيض 200 (E13) والأسود 201 (D15) والأبيض 202 (B14) حُسم أعلى الجانب الأيسر أيضًا، ومن الأسود 203 (B3) تدخل المباراة مرحلة اليوسي (المرحلة الأخيرة التي تُحدَّد فيها حدود الأرض). يدخل B3 زاوية الأبيض السفلى اليسرى من الخطين الأول والثاني ليقشط من أرض الأبيض ولو قليلًا. من هنا تتوالى نقلات دقيقة على نقطة أو نقطتين.","206":"الأسود 205 (Q1)، الأبيض 206 (P1)، الأسود 207 (R1)، الأبيض 208 (P3). على الخط الأول من الزاوية السفلى اليمنى يقشط الأسود قليلًا من أرض الأبيض، ويحمي الأبيض زاويته بإحكام. في النهاية، نقلة واحدة على الخط الأول تصنع فرق نقطة أو نقطتين. ورغم انتهاء المعارك الكبيرة، لا يتراخى الميجين ولا غو سيغن.","214":"بالأسود 209 (B5) والأبيض 210 (A3) يأسر الأبيض حجر الأسود B3، وبالأسود 211 (A6) والأبيض 212 (B6) والأسود 213 (A7) والأبيض 214 (A5) يأسر B5 أيضًا. على الحافة السفلى اليسرى يأخذ الأبيض حجرين ويحمي أرضه تمامًا. ويقضم الأسود أيضًا من أرض الأبيض أعلى الحافة اليسرى (A6 وA7)، فيكسب كل طرف قليلًا.","220":"الأسود 215 (S13)، الأبيض 216 (N11)، الأسود 217 (R11)، الأبيض 218 (M12)، الأسود 219 (L12)، الأبيض 220 (M10). في الجزء الأيمن من الوسط أيضًا يتقدم الأبيض بـ N11 وM12 وM10 فيزيد تقليص ما بقي للأسود من أرض في الوسط. الأرض السوداء التي كان يُفترض أن تمتد حول التنغن صارت شريطًا رفيعًا.","224":"بالأسود 221 (S10) والأبيض 222 (S9) والأسود 223 (T12) والأبيض 224 (T10) يأسر الأبيض حجر الأسود S10 على الحافة اليمنى. أُغلقت أرض الأبيض على اليمين دون التنازل عن نقطة واحدة. وحتى حين يحاول الأسود استرداد شيء، يجيب الأبيض بعناية ولا يترك أي ثغرة.","232":"بعد الأسود 225 (B13) والأبيض 226 (A15) والأسود 227 (C13) والأبيض 228 (A13) والأسود 229 (F15) والأبيض 230 (G17) والأسود 231 (F16) يأتي الأبيض 232 (C15). بهذا C15 لم يبقَ لمجموعة الأسود الكبيرة ذات الأحجار الثمانية عشر، الممتدة من يسار الجانب العلوي إلى الوسط، إلا حرية واحدة: G13. وهو يلعب نقلات النهاية على الجانب الأيسر، صنع الأبيض خطرًا غير متوقع على مجموعة الأسود الكبيرة. على الأسود أن يتحرك فورًا.","233":"يأسر الأسود 233 (L13) حجري الأبيض K12 وK13. بذلك تكسب مجموعة الأسود الكبيرة حريات في K12 وK13، وتتصل بأحجار الأسود في الوسط وتصير آمنة. كان الأمر على الحافة، لكن الأسود حمى مجموعته الكبيرة بأسر هذين الحجرين. لو أسرها الميجين لفاز دفعة واحدة، لكن غو سيغن لم يغفل عن الخطر.","246":"الأبيض 234 (N17)، الأسود 235 (L11)، الأبيض 236 (F9) … الأبيض 244 (G13)، الأسود 245 (F19)، الأبيض 246 (G19). بـ G13 يصل الأبيض أحجاره في الوسط بـ F13، وبـ F19 وG19 تتحدد أيضًا الحدود عند الحافة العليا. لم يبقَ إلا نقلات نهاية صغيرة بنقطة أو نقطتين. وعند عدّ الأرض على اللوح يكون الفرق ضئيلًا جدًا.","249":"بعد الأبيض 248 (A16)، يضع الأسود 249 (M13) حجر الأبيض M12 في أتاري (على بُعد نقلة من الأسر)، ويصل الأبيض 250 (N12). تتحدد أيضًا آخر حدود في الوسط. يرتّب الأسود 251 (R5) شكله في الأسفل يمينًا، ولم يبقَ إلا القليل من النقلات.","252":"بالأبيض 252 (M9) تنتهي المباراة. فاز الأبيض بنقطتين. بالافتتاح الجديد 3-3 والنجمة والتنغن بنى الأسود، غو سيغن، نفوذًا كبيرًا في الوسط. لكن الميجين شوساي أخذ أرضًا متينة في الزوايا والجوانب، وفي أواخر وسط اللعب، بدءًا من النقلة 152، دخل وسط الأسود. كان حاسمًا أنه هزّ الوسط بدءًا من النقلة 160 في H8، ثم حوّل قطع النقلة 186 في P8 إلى أسر خمسة أحجار سوداء على الجانب الأيمن؛ فلم يصر نفوذ الأسود في الوسط أرضًا بقدر ما كان مأمولًا. في زمن بلا كومي كان يُعتقد أن الأسود الذي يبدأ أولًا يتمتع بأفضلية، لذا فإن الفوز بالأبيض يُظهر قوة الميجين الحقيقية. ومن جهة أخرى، لأن غو سيغن ذا التسعة عشر عامًا خسر أمام الميجين بنقطتين فقط، ترك الشين فوسيكي أثرًا عميقًا في عالم الغو. لاحقًا هزم غو سيغن في مباريات من عشر أدوار أفضل لاعبي عصره واحدًا تلو الآخر، وصار اللاعب الأبرز في عصر شووا."}},"century1956":{"t":"مباراة القرن","w":"دونالد بيرن","b":"بوبي فيشر","ev":"بطولة كأس روزنوالد الثالثة (بطولة روزنوالد التذكارية)","d":"1956","pl":"الولايات المتحدة (نيويورك)","lead":"بوبي فيشر، ابن الثالثة عشرة، يهزم دونالد بيرن، أحد أقوى أساتذة أمريكا. في النقلة 17 يترك فيشر وزيره يُؤخذ مجانًا، ثم يستعيد القطع واحدة تلو الأخرى، وفي النهاية تطارد قطعه الصغيرة الملك الأبيض. وأصبح فيشر لاحقًا بطلًا للعالم.","c":{"0":"17 أكتوبر 1956: مباراة من بطولة كأس روزنوالد (بطولة روزنوالد التذكارية) التي أُقيمت في نادي مارشال للشطرنج في نيويورك. كانت بطولة قوية يُدعى إليها أفضل لاعبي الولايات المتحدة، وكان بوبي فيشر، الذي يلعب بالأسود، في الثالثة عشرة فقط: أصغر المشاركين سنًّا. يلعب بالأبيض دونالد بيرن، 26 عامًا، بطل بطولة الولايات المتحدة المفتوحة عام 1953 وأحد كبار الأساتذة الأمريكيين في ذلك الوقت. لم تكن نتيجة فيشر في البطولة كلها جيدة، لكن هذه المباراة وحدها جعلت اسمه معروفًا في العالم كله. في مجلة «تشِس ريفيو» سمّاها هانز كموخ «مباراة القرن»، وما زال هذا الاسم مستعملًا حتى اليوم. لنتابعها نقلةً نقلة مع Musowl ونرى كيف هزم فتى في الثالثة عشرة أستاذًا كبيرًا.","1":"يلعب الأبيض الحصان إلى f3. يسيطر على مربعي الوسط e5 وd4 ويساعد في حماية جناح الملك: بداية هادئة جدًا. لم يحدّد الأبيض أي بيدق بعد، فما زالت تشكيلات كثيرة ممكنة. ولاحقًا مثّل بيرن الولايات المتحدة في ثلاث أولمبيادات للشطرنج، ونال لقب أستاذ دولي عام 1962.","2":"يلعب فيشر أيضًا الحصان إلى f6. يسيطر على e4 وd5. ومثل الأبيض يترك خططه مفتوحة وينتظر ليرى ما يفعله خصمه. وُلد فيشر في شيكاغو في 9 مارس 1943. انتقلت أسرته إلى بروكلين في نيويورك، وفي السادسة تعلّم القواعد مع أخته جوان، التي تكبره بخمس سنوات، من التعليمات المرفقة بطقم شطرنج أُهدي إليهما.","3":"يلعب الأبيض c4. هذا البيدق من جناح الوزير يهاجم المربع d5 من الجانب. الفكرة أن يصعب على الأسود وضع بيدق في d5 وأن يكسب الأبيض مساحة في الوسط. وفي نوفمبر من هذا العام، 1956، أُقيمت في ملبورن بأستراليا أول ألعاب أولمبية في نصف الكرة الجنوبي.","4":"يلعب الأسود g6. بعدها سيذهب الفيل إلى g7 لينظر إلى الوسط عبر القطر الطويل. أحبّ فيشر هذه التشكيلة منذ صغره: ينتظر أولًا ثم يردّ بهجوم مضاد قوي. وفي السابعة، بعد أن خسر أمام أستاذ في عرض لعب متزامن، انضم فيشر إلى نادي بروكلين للشطرنج، وكان نادرًا ما يغيب عن أمسياته يوم الجمعة. وفي الثانية عشرة انضم أيضًا إلى نادي مانهاتن للشطرنج، وصار يقوى بسرعة كبيرة.","5":"يُخرج الأبيض الحصان الآخر إلى c3. يسيطر أكثر على d5 وe4، ولاحقًا يستطيع الأبيض أن يضع بيادق في الوسط بـ d4 وe4.","6":"يذهب الفيل إلى g7. هو الآن خلف حصان f6، لكن ما إن يتحرك الحصان حتى ينفتح دفعةً واحدة القطر الطويل من h8 إلى a1. والأسود مستعدّ أيضًا للتبييت.","7":"يلعب الأبيض d4. ببيدقين في c4 وd4 يأخذ الوسط. إذا ردّ الأسود بـ d5 نصل إلى افتتاح اسمه «دفاع غرونفيلد».","8":"يبيّت الأسود. يذهب الملك إلى مكان آمن في g8، ويقترب رخ f8 من الوسط. فيشر الصغير يؤمّن ملكه أولًا قبل أن تبدأ المعركة. وبعد ذلك تقدّم فيشر بسرعة هائلة: ففاز ببطولة الولايات المتحدة التي بدأت في العام التالي، وفي 1958، وهو في الخامسة عشرة، صار أصغر أستاذ كبير في التاريخ حتى ذلك الوقت.","9":"يلعب الأبيض الفيل إلى f4. ينظر عبر القطر إلى c7 وb8 ويسيطر أيضًا على e5. لكن الملك الأبيض ما زال في الوسط في e1، والأبيض ليس مستعدًا للتبييت بعد.","10":"يلعب الأسود d5 ويصطدم ببيدق c4 في الوسط. صار الآن دفاع غرونفيلد. خطة الأسود أن يترك الوسط للأبيض فترةً ثم يهاجمه لاحقًا. ورغم أن المباراة بدأت بـ 1.Nf3 وبترتيب نقلات مختلف، فقد وصلت الآن إلى «دفاع غرونفيلد» مع 5.Bf4 (الخط المصنّف D92). والاسم مأخوذ من إرنست غرونفيلد، الأستاذ النمساوي الذي نشر هذا الدفاع في عشرينيات القرن العشرين.","11":"يخرج الوزير الأبيض مبكرًا إلى b3. يزيد الضغط على d5 ويستهدف أيضًا بيدق b7 عبر العمود b. نقلة قوية، لكن الوزير الذي يخرج مبكرًا يمكن أن تطارده قطع الخصم بسهولة.","12":"يأخذ الأسود بيدق c4. البيدق الذي أخذ يهاجم الآن الوزير في b3 قطريًا، فلا بد أن يستردّ الأبيض. هكذا يزيل الأسود أحد بيادق الوسط البيضاء.","13":"يستردّ الوزير الأبيض في c4. صار الوزير قريبًا من وسط الرقعة وينظر إلى d5 وf7. لكن هذا الوزير ستطارده القطع السوداء مرةً بعد مرة.","14":"يلعب الأسود c6. يسيطر على d5 وb5 حتى لا يدخلهما الوزير والحصان الأبيضان. ويُعدّ أيضًا لـ b5 لمطاردة الوزير لاحقًا.","15":"يلعب الأبيض e4. بيدقان في d4 وe4 يقفان الآن جنبًا إلى جنب في الوسط. من المظهر وحده، لدى الأبيض مساحة كبيرة ويبدو أنه يلعب براحة.","16":"يلعب الأسود الحصان إلى d7. من هنا يريد أن يقفز إلى b6 ليطارد الوزير. ويساعد هذا أيضًا في الإعداد لتقدّم e5 لضرب وسط الأبيض. ويرى المحلّلون أن 8...Nbd7 بطيئة قليلًا؛ وفي المباريات اللاحقة فضّل اللاعبون خطوطًا مثل 8...b5 ثم إخراج الوزير إلى a5.","17":"يلعب الأبيض الرخ إلى d1. يدعم بيدق d4 من الخلف ويقوّي العمود d. لكن لأن الرخ تحرّك قبل التبييت، بقي الملك عالقًا في الوسط في e1.","18":"يقفز الحصان إلى b6 ويهاجم الوزير في c4. على الوزير الأبيض أن يتحرك مرة أخرى. الأسود يطوّر قطعه ويجعل الأبيض يضيّع النقلات.","19":"يهرب الوزير إلى c5. من c5 ينظر إلى بيدق e7 ويحاول أن يكبح جناح الوزير الأسود. لكن الوزير صار متقدّمًا جدًا، في مكان تستطيع القطع السوداء أن تهاجمه فيه بسهولة. ويقول المحلّلون إن Qd3 كانت أفضل من Qc5 هذه. ففي c5 يتعرّض الوزير بسهولة لحصان الأسود الذي يقفز إلى a4 أو e4.","20":"يذهب الفيل إلى g4 ويهاجم حصان f3. خلف الحصان يقف رخ d1: إذا تحرّك الحصان أُخذ الرخ. هذا يُسمّى «التثبيت». حصان f3 يحمي مربعات مهمة مثل d4 وe5، فصار الأبيض بالكاد يستطيع تحريكه.","21":"يلعب الأبيض الفيل إلى g5. يهاجم حصان f6 ويحاول منع الأسود من تحريك هذا الحصان ولعب e5. لكن لدى الأبيض قطع لم تخرج بعد ولم يبيّت. يقول كثيرون إن لعب الفيل إلى e2 والاستعداد للتبييت كان أفضل. وفي مباراة لاحقة عام 1991، لعب الأبيض هنا 11.Be2 وحصل على وضع أكثر راحة قليلًا.","22":"الحصان إلى a4! هذه أول مفاجأة كبيرة في المباراة. حصان a4 يهاجم في آنٍ واحد الوزير في c5 والحصان في c3. إذا أخذه الأبيض بحصان c3، يأخذ الأسود بيدق e4 بحصان f6 ويهاجم معًا الوزير في c5 والفيل في g5. وسيبقى الملك الأبيض في الوسط تحت الهجوم، لذلك لا يستطيع الأبيض أخذ الحصان. ويُروى أن الناس تجمّعوا حول الرقعة ليشاهدوا بعد هذه النقلة.","23":"لا يأخذ الأبيض الحصان وينقل الوزير إلى a3. من هناك ما زال ينظر قطريًا إلى بيدق e7. اختار الأبيض الدفاع الأقل ضررًا.","24":"يأخذ الحصان حصان c3. كان ذلك الحصان هو القطعة التي تحمي بيدق e4. هكذا أزال الأسود حامي e4.","25":"يستردّ الأبيض ببيدق. المادة متساوية، لكن بيدقي الأبيض في c3 وd4 صارا مفكّكين قليلًا. ولم يعد شيء يحمي بيدق e4.","26":"يأخذ الحصان بيدق e4! من e4 يهاجم بيدق c3 والفيل في g5. تفكّكت بيادق الأبيض الجميلة في الوسط، والعمود e ينفتح، والمساحة أمام الملك الأبيض الباقي في الوسط صارت مكشوفة تمامًا.","27":"يأخذ الأبيض بيدق e7 بالفيل. من e7 يهاجم في الوقت نفسه الوزير الأسود في d8 والرخ في f8: هجوم مزدوج. يستردّ الأبيض البيدق ويهاجم القطع الكبيرة السوداء. هجوم مضاد قوي.","28":"ينقل الأسود الوزير إلى b6. نقلة جريئة تقول: خذ رخ f8 إن شئت. إذا أخذ الأبيض الرخ، يستردّ الأسود بالفيل، ثم يطارد ذلك الفيل الوزير في a3. يرى الأسود أن بقاء الملك الأبيض في الوسط أهم من رخ. ووزير b6 ينظر أيضًا إلى بيدق d4.","29":"لا يأخذ الأبيض الرخ ويُخرج الفيل إلى c4. هذا يُخلي f1 ليبيّت في النقلة التالية ويضع الملك في أمان. والأبيض أيضًا يعرف أن أمان الملك هو المشكلة الكبرى.","30":"يأخذ الحصان بيدق c3! من هنا يهاجم رخ d1. إذا أخذ الأبيض هذا الحصان بالوزير، يستطيع الأسود أن يضع رخًا في e8 ويهاجم في خط مستقيم فيل e7 والملك خلفه. القطع السوداء تتجمّع واحدةً بعد أخرى حول الملك الأبيض.","31":"يلعب الأبيض الفيل إلى c5 ويهاجم الوزير الأسود في b6. إذا أبعد الأسود الوزير فقط، يستطيع الأبيض أن يبيّت في النقلة التالية. لكن لأن الفيل ترك e7، صار العمود e مفتوحًا للرخ الأسود.","32":"يذهب الرخ إلى e8: كش على العمود e! ذهب فيل e7 إلى c5، فكان العمود e مفتوحًا من e8 حتى e1. قبل أن ينقذ الأسود وزيره، يلاحق الملك الأبيض أولًا.","33":"يذهب الملك إلى f1. الآن لن يستطيع الأبيض التبييت أبدًا. ورخ h1 أيضًا يعوقه الملك ويصعب عليه الخروج. كسب الأسود لحظة، لكن وزير b6 ما زال مهدَّدًا من فيل c5.","34":"الفيل إلى e6! هذه أشهر نقلة في المباراة: يترك الأسود وزيره يُؤخذ مجانًا. فيل e6 يهاجم الفيل الأبيض في c4، وأخذه سيكون كشًّا. إذا أخذ الأبيض في e6 بفيل c4، يكشّ الأسود بالوزير من b5، ويواصل الكشّ بالحصان، وفي النهاية يُحاط الملك بقطعه نفسها فلا يستطيع الحركة: «مات خانق». كتب فيشر أن نقل الحصان إلى b5 بدلًا من ذلك كان سيخسر، لأن الأبيض كان سيأخذ بيدق f7. فتى في الثالثة عشرة رأى بعيدًا جدًا، أبعد بكثير من التضحية بوزيره.","35":"يأخذ الأبيض الوزير الأسود. إذا عددنا القطع فقط، فالأبيض متقدّم كثيرًا. لكن القطع السوداء ستطارد الآن الملك الأبيض وتستعيد قطعةً بعد قطعة.","36":"يأخذ الفيل الفيل الأبيض في c4، كش! من c4 يصوّب عبر d3 وe2 نحو الملك في f1. هنا يبدأ الهجوم المضاد الأسود.","37":"يهرب الملك إلى g1. الرخ الأسود يسيطر على العمود e، فلا يكاد يوجد مكان آخر. في g1 يُحبس الملك بين رخ h1 وبيدق g2 ولا يكاد يتحرك.","38":"يقفز الحصان إلى e2 مع كش. على الملك أن يعود إلى f1. يقيّد الأسود يدي الأبيض بالكشّ وفي الوقت نفسه يستعدّ للأخذ التالي.","39":"يعود الملك إلى f1. الآن يقف حصان e2 أمام فيل c4. إذا تحرك هذا الحصان، سيكشّ الفيل الذي خلفه الملك في f1: هذا «كش مكشوف».","40":"يأخذ الحصان بيدق d4: كش مكشوف! لأن الحصان تحرّك، صار فيل c4 يكشّ الملك في f1. حين تكون في كش، عليك أن تهتم بالملك أولًا مهما كان ما يفعله الحصان.","41":"يذهب الملك إلى g1. ما زال الأبيض يتلقّى الكشّ، وليس لديه وقت لفعل أي شيء آخر.","42":"يقفز الحصان مرة أخرى إلى e2 مع كش. على الملك أن يعود إلى f1. يستطيع الأسود أن يكشّ مرةً بعد مرة، وفي كل مرة يبحث عن فرصة ليكسب شيئًا.","43":"يذهب الملك مرة أخرى إلى f1. لا يستطيع الأبيض إلا أن يكرّر النقلات نفسها. هذا الأسلوب، أن تكشّ وتأخذ قطعة ثم تعود، يُسمّى «الطاحونة» لأنه يدور ويدور.","44":"يذهب الحصان إلى c3: كش مكشوف آخر! فيل c4 يكشّ الملك في f1، وفي الوقت نفسه يهاجم حصان c3 رخ d1. الأبيض في كش، فلا يمكن إنقاذ الرخ. الطاحونة مستعدة لأخذ قطعة أخرى.","45":"يذهب الملك إلى g1. كان الأسود يستطيع مواصلة الكشّ، لكنه يتوقف هنا لحظة ليستعيد الفيل الأبيض في b6.","46":"يأخذ البيدق فيل b6. الآن اختفى أيضًا الفيل الذي أخذ الوزير الأسود. ولأن بيدق a7 تحرّك، انفتح العمود a، ورخ a8 يهاجم الوزير الأبيض في a3. لنعدّ القطع: للأسود رخان وفيلان وحصان، وللأبيض وزير ورخان وحصان. ويستطيع الأسود بعد ذلك أن يأخذ رخ d1 أيضًا، فهو يستعيد أكثر من قيمة الوزير.","47":"يهرب الوزير الأبيض إلى b4. من هنا يهاجم في آنٍ واحد فيل c4 وحصان c3 وبيدق b6: هروب لاذع. يحاول الأبيض بكل قوته أن يستعيد شيئًا.","48":"الرخ إلى a4! يطارد الوزير مرة أخرى. رخ a4 يحميه حصان c3، وعندما يبتعد الوزير سيحمي أيضًا فيل c4. لا يستطيع الوزير الأبيض أخذ أي قطعة سوداء، وعليه أن يهرب.","49":"يأخذ الوزير الأبيض بيدق b6. على الأقل يستعيد الأبيض بيدقًا واحدًا. لكن في هذه الأثناء يأتي دور حصان c3 ليأخذ رخ d1.","50":"يأخذ الحصان رخ d1. للأسود رخان وفيلان وحصان مقابل وزير الأبيض ورخه وحصانه، وهو متقدّم بوضوح. وما زال رخ h1 الأبيض محبوسًا.","51":"يلعب الأبيض h3. هذا يصنع للملك مربع هروب في h2. وعندما يذهب الملك إلى h2، يستطيع رخ h1 أخيرًا أن يخرج. ويمنع هذا أيضًا تهديد الأسود الدائم للصف الأول الأبيض.","52":"يأخذ الرخ بيدق a2. لم يبقَ للأبيض بيادق في جناح الوزير، ولم يعد شيء يستطيع إيقاف البيادق السوداء هناك. دخل الرخ الصف الثاني للأبيض، ومن هناك يستطيع أيضًا أن يستهدف f2 بجانب الملك الأبيض.","53":"يذهب الملك إلى h2. الآن يستطيع رخ h1 أخيرًا أن يتحرك بحرية على الصف الأول. يحاول الأبيض بأي طريقة إدخال قطعه الباقية إلى اللعب.","54":"يأخذ الحصان بيدق f2. من f2 يهاجم رخ h1 وبيدق h3. ذهب بيدق آخر قرب الملك الأبيض.","55":"ينقل الأبيض الرخ إلى e1 لينجو به ويعرض مبادلته بالرخ الأسود على العمود e. الفكرة إزالة إحدى قطع الهجوم السوداء.","56":"يبادل الأسود الرخين. حين يكون لديك قطع أكثر، فالمبادلات تفيدك عادةً. قبل أن يستردّ الأبيض في e1 بالحصان، يكشّ أولًا بالوزير.","57":"يذهب الوزير إلى d8 مع كش. بعد ذهاب رخ e8 كان الصف الثامن مفتوحًا حتى الملك الأسود في g8. يُدخل الأبيض هذا الكشّ أولًا وينوي استرداد الرخ بعده.","58":"يصدّ الأسود الكشّ بالفيل في f8. يقف الفيل بجانب الملك، ويصبح الدفاع متينًا.","59":"يستردّ الحصان الرخ في e1. للأبيض وزير وحصان، وللأسود رخ وفيلان وحصان. إذا جمعنا قوة القطع، فالأسود أفضل بوضوح.","60":"يذهب الفيل إلى d5. ينظر إلى المربع f3 وبيدق g2، ومن خلفه على القطر يحمي أيضًا رخ a2. يجمع الأسود قطعه واحدةً واحدة في مربعات جيدة يسند بعضها بعضًا.","61":"يعود الحصان إلى f3. يحميه بيدق g2، وهو القطعة الوحيدة التي تدافع عن الملك الأبيض. بالوزير والحصان يحاول الأبيض الصمود أمام هجوم الأسود.","62":"يذهب الحصان إلى e4. يدخل الوسط ويقترب من الملك الأبيض. بعد ذلك يريد الأسود أن يلعب فيل f8 إلى d6 ويكشّ الملك في h2.","63":"يذهب الوزير الأبيض إلى b8. يهاجم بيدق b7 ويثبّت على الصف الثامن فيل f8 أمام الملك في g8. إذا تحرّك الفيل صار الملك في كش، فهذا يوقف خطة الأسود للكشّ بالفيل.","64":"يلعب الأسود b5. يتقدّم البيدق مربعين ويهرب من هجوم الوزير. في b5 يحميه بيدق c6. ويومًا ما قد يدفعه الأسود إلى الأمام أيضًا.","65":"يلعب الأبيض h4. يتقدّم بيدق h على أمل أن يكسر، إن أمكن، البيادق حول الملك الأسود بـ h5. لم يبقَ للأبيض الكثير ليفعله.","66":"يلعب الأسود أيضًا h5. هذا يوقف البيدق الأبيض ويحافظ على متانة الشكل حول الملك الأسود. الأسود لا يستعجل ويلعب بأمان.","67":"يذهب الحصان إلى e5. من الوسط يهاجم f7. وأيضًا لو قفز الحصان إلى d7 لصار الفيل المثبَّت في f8 مهاجَمًا من قطعتين، الوزير والحصان. هذا آخر أمل للأبيض في هجوم مضاد.","68":"يذهب الملك إلى g7. يحرّر فيل f8 من التثبيت ويحميه أيضًا. الآن يستطيع الفيل التحرك بحرية. الأسود مستعدّ للهجوم الأخير.","69":"يذهب الملك إلى g1. في h2 كان يمكن أن يكشّه الفيل المحرَّر من d6، فيبدو أن الأبيض ابتعد مسبقًا. لكن لا تكاد توجد قطع دفاع قرب الملك الأبيض.","70":"يذهب الفيل إلى c5: كش! من c5 يصوّب عبر d4 وe3 وf2 نحو الملك في g1. الآن تبدأ القطع السوداء الصغيرة في صيد الملك الأبيض.","71":"يذهب الملك إلى f1. يبحث الملك الأبيض عن مخرج نحو الجانب الأيسر من الرقعة. لكن الرخ والفيلين الأسود ينتظرونه هناك، ويُدفع الملك شيئًا فشيئًا إلى الجهة الأخرى من الرقعة.","72":"يقفز الحصان إلى g3 مع كش. يُدفع الملك إلى e1. ويسدّ الحصان أيضًا طريق عودة الملك إلى الجانب الأيمن من الرقعة.","73":"يذهب الملك إلى e1. لا يستطيع العودة إلى f2 أو g1، فلا يمكنه إلا الهرب إلى اليسار. شبكة الأسود تضيق شيئًا فشيئًا.","74":"يخرج الفيل الآخر إلى b4 مع كش. من b4 يصوّب عبر c3 وd2 نحو e1. يُدفع الملك أكثر إلى اليسار، إلى d1.","75":"يذهب الملك إلى d1. الوزير والحصان الأبيضان في الجهة البعيدة من الرقعة ولا يستطيعان المجيء لمساعدة الملك.","76":"ينتقل الفيل من d5 إلى b3 مع كش. من b3 يصوّب عبر c2 نحو d1. لاحقًا سيكون لهذا الفيل دور مهم: حماية مربع نقلة الرخ الأخيرة.","77":"يذهب الملك إلى c1. لا تكاد تبقى مربعات للهرب. واحدةً بعد أخرى تغلق القطع السوداء المربعات حول الملك الأبيض.","78":"يقفز الحصان إلى e2 مع كش. من e2 يهاجم c1. لا يستطيع الملك الهرب إلا إلى b1.","79":"يذهب الملك إلى b1. لقد طورد حتى كاد يصل إلى زاوية الرقعة.","80":"يقفز الحصان إلى c3 مع كش. من c3 يهاجم b1 ويسيطر أيضًا على d1. على الملك أن يعود إلى c1.","81":"يذهب الملك إلى c1. سيكون هذا مربعه الأخير. حصان c3 يغطي b1 وd1، والرخ الذي سيصل بعد قليل سيغطي b2 وd2.","82":"يذهب الرخ إلى c2: كش مات! رخ c2 يحميه فيل b3، فلا يستطيع الملك أخذه؛ وحصان c3 يغطي b1 وd1، والرخ يغطي b2 وd2. ثلاث قطع، رخ وفيل وحصان، نسجت شبكة المات، وساعد الفيل الآخر في مطاردة الملك حتى هنا. طورد الملك الأبيض من g1 حتى c1 في الجهة الأخرى من الرقعة، ولم يستطع الوزير الأبيض أن يفعل شيئًا حتى النهاية. كان بيرن يستطيع الاستسلام قبل ذلك، لكن يُقال إنه واصل اللعب حتى المات احترامًا للعب الفتى الرائع. قفزة الحصان في النقلة 11، وقرار التخلّي عن الوزير في النقلة 17، و«الطاحونة» التي استعادت القطع، وشبكة مات نسجتها قطع صغيرة: بعد هذه المباراة صار فيشر بطل الولايات المتحدة في الرابعة عشرة، وبطل العالم عام 1972."}},"oshiro1849":{"t":"أول مباراة قلعة لشوساكو","w":"هونينبو شوساكو","b":"ياسوي سانتشي التاسع","ev":"مباراة القلعة (المباراة السنوية في قلعة إيدو)","d":"1849","pl":"اليابان (إيدو)","lead":"كانت مباريات القلعة المناسبة السنوية الكبرى التي يلعب فيها لاعبو بيوت الغو الرسمية في قلعة الشوغون. شارك شوساكو، وهو في العشرين، لأول مرة في ذلك العام وفاز بالأسود بفارق 11 نقطة، فبدأ سجلًا مثاليًا من 19 فوزًا في 19 مباراة قلعة.","c":{"0":"إيدو، عام 1849. الأسود هو هونينبو شوساكو ابن العشرين، والأبيض هو ياسوي سانتشي، الرئيس التاسع لبيت ياسوي. كانت مباريات القلعة مباريات رسمية يلعبها لاعبو بيوت الغو (العائلات الأربع: هونينبو وإينوئيه وياسوي وهاياشي) من أجل الشوغون، مرة كل عام في قلعة إيدو. كانت أعظم منصة للاعب البيت، وقد تلطّخ الهزيمة اسم عائلته. ويُقال إن المباراة كانت تُلعب غالبًا مسبقًا في دار أخرى، ثم يُعاد رصّها فقط في القلعة. وُلد شوساكو في جزيرة إينوشيما في إقليم بينغو (أونوميتشي في هيروشيما اليوم). وفي العام السابق اختير وريثًا لبيت هونينبو، وكانت هذه أول مباراة قلعة له. من هنا سيلعب 19 مباراة قلعة ويفوز بها كلها، دون أن يخسر مرة واحدة. لم يكن هناك كومي في ذلك الزمن، فالنتيجة تحددها المنطقة على اللوح وحدها.","1":"الأسود 1 (R16) هو الكوموكو في أعلى اليمين. الكوموكو نقطة يتقاطع فيها الخطان الثالث والرابع من الزاوية، وهي نقلة تسهّل أخذ الزاوية منطقةً. كان شوساكو كثيرًا ما يبدأ بالأسود من الكوموكو، والافتتاح الذي سُمّي لاحقًا «أسلوب شوساكو» يقوم أيضًا على الكوموكو. ومن دون كومي يكفي الأسود، الذي يلعب أولًا، أن يحافظ على تقدم صغير بأمان حتى النهاية. كان شوساكو يعرف ذلك جيدًا، ويلعب غو هادئًا لا يُكره شيئًا. في أسلوب شوساكو تشتهر النقلة السابعة للأسود، وهي خطوة قطرية من الكوموكو تُسمّى «كوسومي شوساكو»، وقد أعاد ذكاء الغو الاصطناعي اليوم تقييمها نقلةً جيدة. وفي هذه المباراة أيضًا يلعب الأسود في النقلة 45 كوسومي من كوموكو أعلى اليمين.","3":"الأبيض 2 (R4) هو الكوموكو في أسفل اليمين، والأسود 3 (D17) الكوموكو في أعلى اليسار. صار للأسود الآن الزاويتان العلويتان. والجانب العلوي بينهما سيسهل على الأسود جعله منطقة لاحقًا. لا يأخذ الأبيض الزاوية الباقية فورًا، بل يقترب في النقلة التالية من زاوية سوداء. لعب كوموكو متتاليين هو الفكرة نفسها التي يبدأ بها أسلوب شوساكو لاحقًا. وبالمناسبة، في ربيع هذا العام نفسه 1849 تُوفي في إيدو رسام الأوكييو-إي كاتسوشيكا هوكوساي، المشهور بـ«ستٍّ وثلاثين منظرًا لجبل فوجي».","4":"الأبيض 4 (C15) يقترب من الحجر الأسود D17 في أعلى اليسار (كاكاري). إنه «اقتراب الحصان الصغير» من مسافة قفزة حصان، ويمنع الأسود من إحاطة الزاوية على نطاق واسع. قبل أن يأخذ الزاوية الفارغة في أسفل اليسار، يذهب الأبيض لإفساد خطة الأسود في الأعلى. يستطيع الأسود أن يردّ بهدوء أو أن يطبق كمّاشة. كان بيت ياسوي الذي يلعب له الأبيض أحد بيوت الغو الأربعة. ورئيسه الثاني ياسوي سانتيتسو اتخذ لاحقًا اسم شيبوكاوا شونكاي، ويُعرف أيضًا بأنه الفلكي الذي وضع أول تقويم صُنع في اليابان (تقويم جوكيو).","5":"الأسود 5 (C11) يطبق كمّاشة على الحجر الأبيض المقترب C15 من الأسفل. بينهما ثلاث نقاط فارغة وهي على الخط الثالث، فهي «كمّاشة منخفضة بثلاث مسافات». تمنع الأبيض من الامتداد على الجانب الأيسر وبناء قاعدة (موطئ قدم للحياة). اختيار الكمّاشة بدل الرد الهادئ قرار فاعل لا يترك الأبيض مرتاحًا. في أسلوب شوساكو كانت النقلة 5 ستكون أيضًا كوموكو في زاوية أخرى، لكن الأسود هنا يردّ فورًا على الاقتراب بكمّاشة، وعندها يخرج عن نمط أسلوب شوساكو. وبالمناسبة، اسم «هونينبو» مأخوذ من المعبد الصغير في جاكّو-جي بكيوتو حيث عاش الرئيس الأول هونينبو سانسا.","6":"الأبيض 6 (F16) يقترب من D17 من جهة الأعلى أيضًا. بالحجر C15 يسارًا وF16 يمينًا يحاصر الأبيض حجر الزاوية الأسود من الجانبين (اقتراب مزدوج). بدل الرد على الكمّاشة، يردّ الأبيض الضغط على زاوية الأسود. سيكون على الأسود فصل أحد الحجرين الأبيضين. الاقتراب المزدوج شكل يرد في كتب الجوسيكي، وما يليه يتوقف على الحجر الأبيض الذي يتجه إليه الأسود. ويُروى أن موهبة شوساكو في صغره لفتت نظر عائلة أسانو، سادة قلعة ميهارا (ميهارا في هيروشيما اليوم)، فتعلّم الغو بدعمهم.","7":"الأسود 7 (D15) يطلّ بين الحجرين الأبيضين. يُلعب مباشرة يمين C15 فيمنع C15 وF16 من أن يتشابكا. لو لم يلعب الأسود هنا لاستطاع الأبيض اللعب قرب D15 وحبس زاوية الأسود في مساحة ضيقة. من هنا تبدأ الأحجار بالتصادم في أعلى اليسار.","9":"الأبيض 8 (D14) يسدّ رأس D15، والأسود 9 (E15) يمتد جانبيًا فيصطف حجران أسودان. لـD15 وE15 حريات كثيرة، فلا خطر من أسر سريع. وهذا الصف جدار أيضًا يُبقي F16 منفصلًا عن الأحجار البيضاء في الزاوية. في عام 1837، وهو في الثامنة، ذهب شوساكو إلى إيدو وصار تلميذًا في بيت هونينبو عند هونينبو جووا. ويُروى أن جووا أثنى عليه بأنه «أعظم موهبة في الغو منذ 150 عامًا».","12":"الأبيض 10 (C16)، الأسود 11 (E17)، الأبيض 12 (C17). يصفّ الأبيض أحجارًا على الحافة ويأخذ الزاوية العلوية اليسرى والجانب الأيسر. ومقابل التخلي عن الزاوية صار للأسود D17 وE17 وD15 وE15 متجهة نحو الأعلى. أما الحجر الأبيض F16 في الأعلى فيكاد يُحاط بالأسود وقد بقي وحيدًا. نتيجة يقبلها الطرفان. هذه النتيجة تشبه كثيرًا جوسيكي يذهب فيه الركن للأبيض والخارج للأسود بعد الاقتراب المزدوج. وفيما وراء البحار، في عام 1849 هذا، تدفّق الناس على كاليفورنيا بحثًا عن الذهب (حمّى الذهب)، وتُوفي في أوروبا الموسيقار شوبان.","13":"الأسود 13 (J17) امتداد واسع على الجانب العلوي. الفكرة استغلال الأحجار الخارجية من الزاوية وجعل الأعلى منطقة سوداء. كما يغلق يمين F16، فيصعب على هذا الحجر الحركة أكثر. سيبقى F16 على اللوح حتى النهاية، لكن حجرًا ميتًا داخل منطقة الأسود. وفي العام نفسه 1849 دخلت السفينة الحربية البريطانية «مارينر» خليج إيدو، وأجرت مسوحات ثم غادرت. كان زمنًا تقترب فيه السفن الأجنبية من اليابان أكثر فأكثر، وبعد أربع سنوات وصلت «السفن السوداء» بقيادة بيري.","14":"الأبيض 14 (P17) يقترب من الحجر الأسود R16 في أعلى اليمين من جهة الأعلى (كاكاري). يوقف من اليمين خطة الأسود لجعل الأعلى كله منطقة كبيرة بالحجرين J17 وR16. كان الأسود يودّ الرد هنا، لكن شوساكو يختار مكانًا آخر. كان شوساكو قد صار وريثًا في العام السابق، 1848، ويُروى أنه تزوّج حينها ابنة من بيت معلّمه.","15":"الأسود 15 (C5) يذهب إلى آخر زاوية فارغة، أسفل اليسار (موكوهازوشي). لا يردّ الأسود فورًا على P17 ويأخذ أولًا الزاوية الخالية. الزاوية تصير منطقة بأحجار قليلة، فهي في الافتتاح مكان كبير جدًا. قدّر الأسود أن R16 لن يقع في ورطة حتى لو انتظر أعلى اليمين قليلًا. والآن امتلأت الزوايا الأربع كلها. يقف الموكوهازوشي مائلًا قليلًا نحو خارج الزاوية، وكان كثير الاستعمال في غو عصر إيدو. وكان لاعبو بيوت الغو يتقاضون رواتب من الشوغونية، وكانت مباراة القلعة أهم مكان لإظهار براعتهم.","16":"الأبيض 16 (E4) اقتراب مباشر من C5. يمنع الأسود من إحاطة زاوية أسفل اليسار بسهولة، وهنا أيضًا يبدأ التصادم. سيصفّ الأبيض أحجارًا خارج الزاوية ويبني شكلًا يتجه نحو الجانب السفلي. في هذه الفترة كانت الشوغونية تأمر بتقوية الدفاعات الساحلية تحسّبًا للسفن الأجنبية التي تقترب من اليابان.","19":"الأسود 17 (D3)، الأبيض 18 (E3)، الأسود 19 (D2). يضع الأسود أحجارًا منخفضة في الزاوية وينزل حتى الخط الثاني، فيؤمّن منطقة الزاوية بإحكام. ويصفّ الأبيض E4 وE3 في الخارج فيكسب قوة نحو الجانب السفلي. الأسود يأخذ المنطقة والأبيض القوة الخارجية. أن يصنع أولًا شكلًا صغيرًا لكنه حيّ بلا شك، ذلك أسلوب شوساكو المتين.","20":"الأبيض 20 (C7) يضغط على زاوية الأسود من الأعلى. يمنع الأسود من الصعود على الجانب الأيسر ويريد جعله منطقة بيضاء. زاوية الأسود ليست حيّة تمامًا بعد، فعليه أن يُخرج رأسه نحو الأعلى.","23":"الأسود 21 (C6)، الأبيض 22 (D7)، الأسود 23 (E5). بعد أن يمتد الأسود إلى الأعلى، يلعب فوق E4 مباشرة فيسدّ رأس الأبيض. يصعب الآن على E4 وE3 الخروج إلى الأعلى، بينما تجد أحجار الأسود في الزاوية طريقًا للانتشار إلى الخارج. تتشابك الأحجار ويتحدد الشكل في أسفل اليسار شيئًا فشيئًا.","24":"الأبيض 24 (C13) يمدّ الأحجار البيضاء على اليسار من C15 إلى الأسفل. يقوّي أحجار الزاوية البيضاء ويضغط في الوقت نفسه من الأعلى على الحجر الأسود C11 من النقلة الخامسة. صار C11 بين أحجار بيضاء فوقه وتحته، وعلى الأسود أن يقرر: هل يعامله بخفة أم ينقذه؟","26":"الأسود 25 (E6) يمتد إلى الأعلى ليقوّي أحجار الزاوية، والأبيض 26 (E7) يسدّ رأسه. يستقر أسفل اليسار على شكل: للأسود منطقة الزاوية، وللأبيض جدار خارجي من C7 وD7 وE7. يراقب الجدار الأبيض الجانبين الأيسر والسفلي معًا.","27":"الأسود 27 (F15) يُلعب تحت الحجر الأبيض الوحيد F16 مباشرة. يُغلق طريق F16 نحو الأسفل ولا تبقى له إلا ثلاث حريات (نقاط فارغة مجاورة). وتتحد أحجار الأسود في الأعلى في مجموعة متينة، وتتضح منطقة الأعلى. نقلة هادئة لكنها مهمة للمنطقة التي سيصنعها الأسود في الأعلى.","28":"الأبيض 28 (G7) يقفز نقطتين إلى اليمين من E7 ويطيل الجدار الخارجي. يوسّع الأبيض نفوذه (قوة لم تصبح منطقة بعد) خارج الزاوية متجهًا إلى الجانب السفلي والوسط. والحجر الأسود C11 على اليسار قريب من هذه القوة ويبدأ يشعر ببعض الوحدة.","29":"الأسود 29 (F11) يقفز نقطتين إلى اليمين من C11 ويمنح الحجر الأسود على اليسار رفيقًا. يمنع مهاجمة C11 وحيدًا، ويصير موطئ قدم للخروج إلى الوسط. وفي الوقت نفسه يكبح القوة البيضاء القادمة من الأسفل كي لا تتسع كثيرًا في الوسط.","30":"الأبيض 30 (H4) ينفتح نقطتين إلى اليمين على الجانب السفلي من E4 وE3. يبدأ الأبيض ببناء منطقة في الأسفل ويقوّي خارج زاوية الأسود. صار النصف الأيسر من اللوح مقسومًا: للأسود الزوايا والأعلى، وللأبيض الجانبان الأيسر والسفلي. والآن يتجه الأسود إلى زاوية الأبيض في أسفل اليمين.","32":"الأسود 31 (O3) يقترب من الحجر الأبيض R4 في أسفل اليمين من مسافة أبعد قليلًا (اقتراب الحصان الكبير). ويطبق الأبيض 32 (L3) فورًا كمّاشة عليه من اليسار. ويتطلع L3 أيضًا إلى الاتصال بـH4 في الأسفل، فالأبيض يريد الجانب السفلي كله منطقةً له. صار O3 بين زاوية الأبيض وL3، وعلى الأسود أن يقرر كيف يلعب هنا.","33":"الأسود 33 (R3) يلتصق مباشرة تحت كوموكو الأبيض R4، في نقطة 3-3 (الخط الثالث من الحافتين). بدل الهرب بالحجر O3 المحاصر، يدخل الأسود زاوية الأبيض ليكسر شكله. وإن سدّ الأبيض، فسيصفّ الأسود أحجارًا في الخارج. إنها بداية خطة شوساكو: أن يترك منطقة الزاوية للأبيض ويكسب مقابلها سُمكًا خارجيًا (جدارًا قويًا).","36":"الأبيض 34 (S3) يسدّ R3 من جهة الزاوية، والأسود 35 (Q3) يمتد يسارًا نحو O3. والأبيض 36 (S2) يحمي أسفل الزاوية. صار R3 وQ3 متصلين بخارج زاوية الأبيض، بينما يختار الأبيض أن يعيش داخلها. ومن هنا سيتقدم الأسود إلى الأعلى على طول خارج الأحجار البيضاء.","37":"الأسود 37 (Q5) يقفز نقطة إلى الأعلى من Q3. يضغط على خارج R4 (جهته اليسرى) ليمنع الأبيض من الانتشار صعودًا على الجانب الأيمن. وإذا استمر الأمر، فلن يستطيع الأبيض إلا الزحف صعودًا على خط قريب من الحافة اليمنى. الأسود يستعد لبناء جدار.","42":"الأبيض 38 (R5)، الأسود 39 (Q6)، الأبيض 40 (R6)، الأسود 41 (Q7)، الأبيض 42 (R7). يزحف الأبيض خطوة خطوة صعودًا على الخط الثالث من الحافة اليمنى، ويصفّ الأسود أحجارًا خارجه مباشرة على الخط الرابع. الزحف على الخط الثالث يعطي الأبيض بعض المنطقة، لكنها ضيقة وصغيرة. أما أحجار الأسود على الخط الرابع فتصير جدارًا قويًا يتجه إلى الوسط والجانب السفلي.","43":"مع الأسود 43 (Q8) ارتفع جدار أسود سميك على اليمين من Q3 إلى Q8. للأبيض زاوية أسفل اليمين وشريط ضيق من المنطقة على الحافة، وللأسود قوة كبيرة متجهة إلى الخارج. سيصير هذا الجدار لاحقًا أساس منطقة سوداء كبيرة على اليمين، كما يراقب الحجر الأبيض L3 في الأسفل. هنا يظهر بوضوح الأسلوب الذي أحبه شوساكو: التخلي عن المنطقة لكسب السُّمك. وحتى الآن يُعدّ لعب الأسود أريح قليلًا.","44":"الأبيض 44 (L17) يدخل في الأعلى بين الحجر الأسود J17 والحجر الأبيض P17. الفكرة أن يمنع مسبقًا الأسود من صنع منطقة كبيرة في الأعلى إضافةً إلى الجدار على اليمين. أحجار الأبيض على اليمين لم تُغطَّ من الأعلى بعد، لكن الأبيض رأى اتساع الأعلى أهم. وبدل مهاجمة هذا الحجر فورًا، يرتّب الأسود أولًا الزاوية العلوية اليمنى.","45":"الأسود 45 (Q15) ينزل نقطة قطريًا من R16 (كوسومي). هنا يردّ الأسود أخيرًا على اقتراب P17. يقوّي حجر الزاوية ويلتفت في الوقت نفسه إلى الجانب الأيمن ليتعاون مع جدار Q8 في الأسفل. نقلة مدروسة تحمي زاوية أعلى اليمين وتُبقي الجانب الأيمن كله في النظر.","48":"الأبيض 46 (P15)، الأسود 47 (P14)، الأبيض 48 (O15). يصطدم الأبيض بـQ15 ويصنع شكلًا في الأعلى، ويمتد الأسود إلى الأسفل نحو الجانب الأيمن. تضرب أحجار الأبيض في أعلى اليمين (P17 وP15 وO15) جذورها في الأعلى، ويحصل الأسود على أحجار تتجه نحو اليمين. تقدّم كل طرف في الاتجاه الذي أراده.","49":"الأسود 49 (R8) يسدّ رأس الأحجار البيضاء التي زحفت على الخط الثالث (هانيه). لم يعد بإمكان R4–R7 الصعود على الجانب الأيمن. وعلى أحجار الأبيض في أسفل اليمين أن تعيش في مساحة صغيرة. صار الجدار الأسود يمتد من Q3 إلى R8 وازداد قوة، وارتفع احتمال أن يصير أعلى الجانب الأيمن منطقة سوداء. ويمكن القول إن شوساكو ترك غزو النقلة 44 فترة من أجل هذه النقلة بالذات.","50":"الأبيض 50 (R18) ينزلق تحت زاوية الأسود في أعلى اليمين على الخط الثاني. ومتصلًا بـP17، يقتطع قليلًا من منطقة زاوية الأسود. صارت زاوية R16 وQ15 أصغر، لكنهما تنظران مقابل ذلك إلى الأسفل، إلى الجانب الأيمن. وأوضح الأبيض شكله الحيّ في الأعلى.","51":"الأسود 51 (P13) يمتد إلى الأسفل من P14 ويقيم منطقة كبيرة على الجانب الأيمن. بـP13 وP14 في الأعلى وجدار Q8–R8 في الأسفل، يبدو الشكل كأنه يحيط مساحة واسعة على اليمين. إن لم يدخلها الأبيض صارت منطقة سوداء كبيرة. على الأبيض أن يدخل الجانب الأيمن في مكان ما. ومن هنا يصبح متى وأين يدخل الأبيض منطقة الأسود محورَ المباراة.","52":"الأبيض 52 (D10) يدخل تحت C11 وF11 السوداوين على اليسار. ومستندًا إلى الجدار الأبيض في أسفل اليسار، يذهب لمهاجمة أحجار الأسود الضعيفة بعدُ على الجانب الأيسر. بين C11 وF11 نقطتان فقط ولم يتصلا بعد. يريد الأبيض فصلهما ومهاجمتهما وتوسيع منطقته على اليسار.","56":"الأسود 53 (D11)، الأبيض 54 (E11)، الأسود 55 (E12)، الأبيض 56 (E10). يتصل الأسود بـC11 عبر D11، ويقطع الأبيض بـE11 بين C11–D11 وF11. يضع الأسود 55 الحجر E11 في أتاري (على بعد نقلة من الأسر)، لكن الأبيض يتصل بـE10 وينجو. صار الأسود مقسومًا إلى ثلاثة: C11–D11 يسارًا وF11 يمينًا وE12 فوقهما. ولفترة يصبح الجانب الأيسر مكانًا صعبًا تتشابك فيه أحجار ضعيفة للطرفين.","57":"الأسود 57 (B14) ينزلق على الخط الثاني تحت أحجار الأبيض في أعلى اليسار (C13–C17). يذهب ليسلبها المساحة التي تحتاجها للحياة (مكان صنع العيون). ويهدف أيضًا إلى توسيع المكان الذي يمكن فيه لـC11 وD11 العيش على الحافة اليسرى. صارت أحجار الأبيض أضعف هي أيضًا، فعليه أن يقاتل وهو يدافع.","60":"الأبيض 58 (D12)، الأسود 59 (C12)، الأبيض 60 (D13). يتسلل الأبيض بين أحجار الأسود بـD12، لكن الأسود يضعه في أتاري بـC12، فيتصل الأبيض بـD13 بالأحجار البيضاء في الأعلى. صارت C11 وC12 وD11 السوداء مجموعة واحدة، واجتمعت أحجار الأبيض في أعلى اليسار عبر D12–D14. وصل الطرفان أحجارهما ورتّبا شكليهما مؤقتًا.","63":"الأسود 61 (B13)، الأبيض 62 (C14)، الأسود 63 (B10). يصفّ الأسود B13 وB14 على الحافة اليسرى، ويتصل الأبيض بـC14 فيجعل أحجاره في أعلى اليسار كتلة واحدة متينة. ويضع الأسود 63 حجرًا على الحافة اليسرى تحت C11 ليمنع الأبيض من الدخول من الأسفل. صار لأحجار الأسود على اليسار مكان للحياة على طول الحافة. ثم يوجّه الأسود نظره إلى الجانب السفلي الأبعد قليلًا.","64":"الأبيض 64 (F12) يضع الحجر الأسود E12 في أتاري. لم يبقَ لـE12 إلا حرية واحدة في E13، ونقصت حريات F11 إلى اثنتين. لا ينقذ الأسود E12؛ سيبقى داخل منطقة الأبيض حتى النهاية حجرًا مُضحّى به. قرار شوساكو حاسم: اللعب في مكان أكبر أجدى من إنقاذ حجر واحد.","65":"الأسود 65 (G3) يدخل بين E3 وH4 البيضاوين على الجانب السفلي. يدخل المنطقة التي يحاول الأبيض بناءها هناك ويهدف إلى شطر الأحجار البيضاء نصفين. E4 وE3 خارج زاوية الأسود، وH4 في منتصف الجانب السفلي؛ فإن انفصلت ضعف الطرفان قليلًا. وبعد الدفاع على اليسار، يشنّ الأسود فورًا هجومًا مضادًا داخل منطقة الأبيض.","70":"الأبيض 66 (H3)، الأسود 67 (G4)، الأبيض 68 (G2)، الأسود 69 (F2)، الأبيض 70 (H2). يلتفّ الأبيض تحت الأحجار السوداء بـH3 وG2، ويقف الأسود صعودًا ثم ينقص حريات G2 بـF2. يتصل الأبيض بـH2 ويجمع أحجاره في يمين الجانب السفلي (H4 وH3 وH2 وG2) في مجموعة واحدة. دخل G3 وG4 الأسودان بين الأحجار البيضاء، لكن لا قاعدة لهما بعدُ وليسا قويين.","71":"الأسود 71 (G5) يمتد نقطة أخرى إلى الأعلى من G4. صارت الأحجار السوداء الثلاثة G3–G5 قائمة عموديًا بين E4–E3 البيضاوين يسارًا وH4–H2 البيضاء يمينًا. صار اتصال مجموعتي الأبيض صعبًا، لكن هذه الأحجار السوداء الثلاثة محاطة بالأبيض أيضًا وليست آمنة بعد. لاحقًا ستصير بذرة معركة كبيرة.","72":"الأبيض 72 (F13) يضيف حجرًا فوق F12 ليرتّب شكله. كان F12 حجرًا ضعيفًا بحريتين فقط، فقوّاه الأبيض قبل أن يستهدفه الأسود. صارت أحجار الأبيض الممتدة من أعلى اليسار على الجانب الأيسر أقدر على الخروج نحو الوسط. ثم يلتفت الأسود إلى الحجر الأبيض L17 في الأعلى.","75":"الأسود 73 (K17) يلتصق بالحجر الأبيض L17، والأبيض 74 (L16) يقف نحو الأسفل صانعًا شكلًا للهرب إلى الوسط. ثم الأسود 75 (H14): يوسّع الأسود منطقته العلوية بقوة نحو الوسط. وهذا الحجر يعيق أيضًا اتصال أحجار الأبيض على اليسار (F12 وF13) بأحجاره في الأعلى (L16 وL17). يصيب عصفورين بحجر: يوسّع الأعلى ويُبقي أحجار الخصم منفصلة.","76":"الأبيض 76 (P11) يقفز أخيرًا إلى داخل منطقة الأسود على اليمين. يقع بين P13–P14 في الأعلى وجدار Q8 في الأسفل، وهو المكان الذي يريده الأسود منطقةً أكثر من أي مكان. حياة هذا الحجر الأبيض أو أسره سيغيّر حساب المنطقة كثيرًا. بفضل الجدار القوي على اليمين يكون الأسود هو المهاجم، لكن محاولة الأسر بالقوة قد تفتح ضعفًا في مكان آخر. العشرات القليلة القادمة من النقلات منعطف كبير في هذه المباراة.","77":"الأسود 77 (Q11) يلتصق مباشرة يمين P11. بالرد من جهة جداره، يمنع الأسود الأبيض من بناء قاعدة (مكان للحياة) على طول الحافة اليمنى. فلا يبقى للأبيض إلا الخروج نحو الوسط، حيث أحجار الأسود القوية قليلة. اختار الأسود هجومًا معقولًا: طرد الأبيض مع حماية المنطقة. ولو هاجم الأسود من جهة الوسط لأمكن الأبيض أن يعيش على الحافة، ولتقلّصت منطقة الأسود كثيرًا.","80":"الأبيض 78 (Q10) يلعب هانيه تحت Q11، والأسود 79 (Q12) يمتد إلى الأعلى بشكل يتصل نحو P13. والأبيض 80 (N10) يقفز من P11 إلى الوسط بشكل قفزة الحصان. يتخلى الأبيض عن العيش على الحافة اليمنى ويهرب إلى الوسط ليفلت من شبكة الأسود. صارت منطقة الأسود على اليمين محمية، لكن هل يستطيع الأسود أسر الأحجار البيضاء؟ لم يتضح بعد.","81":"الأسود 81 (R10) يلتفّ تحت Q10 نحو الحافة اليمنى. لا يبقى لـQ10 إلا حريتان (P10 وQ9)، ولم يعد يستطيع أن يضرب جذوره على الحافة. يحيط الأسود منطقته اليمنى بإحكام حتى الحافة، ويجعل Q10 حجرًا ضعيفًا يستطيع أسره متى شاء. وبالفعل يأسره لاحقًا في النقلة 233.","84":"الأبيض 82 (J14) يصطدم بيمين H14، والأسود 83 (H15) يمتد إلى الأعلى فاتحًا طريق هرب نحو الأحجار السوداء في الأعلى. والأبيض 84 (H13) يضغط على أسفل H14. بـJ14 يتطلع الأبيض إلى الاتصال بـL16 في الأعلى، وبـH13 إلى الاتصال بـF13 على اليسار. صار H14 وH15 محصورين بين أحجار بيضاء، لكنهما قريبان من الأحجار السوداء في الأعلى ولا خطر عاجلًا عليهما.","85":"الأسود 85 (N12) يُلعب فوق N10 وP11 الهاربين إلى الوسط. يذهب ليمنع هذه الأحجار من الصعود والاتصال بـO15 وP15 في الأعلى. وفي الوقت نفسه يوسّع أكثر منطقة الأسود من أعلى اليمين نزولًا على الجانب الأيمن. طريقة بارعة لكسب المنطقة أثناء الهجوم. والآن يبحث الأبيض عن طريق هرب نحو اليسار عبر الوسط.","87":"الأبيض 86 (B9) يُلعب تحت B10 على الحافة اليسرى. يحاول تضييق المساحة التي يمكن لأحجار الأسود على اليسار أن تعيش فيها على الحافة. والأسود 87 (B15) يمتد في الاتجاه المعاكس، إلى الأعلى، فيوسّع تلك المساحة. صار للأسود الآن طول كافٍ صعودًا ونزولًا على الحافة اليسرى. أما أحجار الأبيض في أعلى اليسار فلم يبقَ لها إلا الخروج إلى الخارج.","90":"الأبيض 88 (M12) يصطدم بيسار N12، والأسود 89 (M13) يضغط من الأعلى تاركًا لـM12 حريتين. والأبيض 90 (L12) يمتد يسارًا وينجو. يتقدم الأبيض نحو اليسار عبر الوسط باحثًا عن اتصال بـJ14 وL16 في الأعلى. ويضغط الأسود من الأعلى وهو يرسّخ منطقته في الأعلى وأعلى اليمين.","91":"الأسود 91 (J7) يقفز إلى المساحة بين الجانب السفلي والوسط. يظهر الأسود بجرأة بين جدار الأبيض في G7 وحجري الأبيض H4 وL3 في الأسفل. يعيق الأبيض عن بناء منطقة كبيرة من الأسفل حتى الوسط، ويسعى إلى مدّ اليد إلى الجدار الأسود على اليمين. إنه دخول إلى منطقة الأبيض، لكن مع وجود أحجار سوداء صديقة حوله فليس غزوًا متهورًا.","94":"الأبيض 92 (J15) يضيّق على H14 وH15 من اليمين فينقص حرياتهما إلى ثلاث. والأسود 93 (H16) يمتد إلى الأعلى ويؤمّن طريق هرب قرب الأحجار السوداء في الأعلى. والأبيض 94 (N11) يتصل بـN10 في الوسط ليرتّب شكله، وينقص في الوقت نفسه حريات N12 إلى اثنتين. صار الوسط عقدة معقدة تضغط فيها الأحجار البيضاء والسوداء بعضها على بعض.","99":"الأسود 95 (M8)، الأبيض 96 (L9)، الأسود 97 (H7)، الأبيض 98 (J9). في الأسفل يضع الأسود M8 وH7 ويوسّع مجموعة الأحجار السوداء حول J7. ويضع الأبيض L9 وJ9 في الوسط ملتفًّا فوق الأحجار السوداء ومعيقًا اتصالها. ثم الأسود 99 (S8): يمدّ الأسود جداره حتى الحافة اليمنى ويسدّ تمامًا طريق أحجار الأبيض في أسفل اليمين نحو الأعلى. الوسط متشابك، لكن منطقة الأسود على اليمين تترسّخ بثبات.","101":"الأبيض 100 (S17) يدخل زاوية الأسود في أعلى اليمين، قرب الحافة بجانب R16. يقلّص الأبيض المساحة التي تصنع فيها زاوية الأسود عيونها، ويأمل كسرها إن أمكن. والأسود 101 (S16) يضغط عليه من الأسفل تاركًا لـS17 ثلاث حريات. ومن دون ارتباك يحمي الأسود شكل زاويته بإحكام.","106":"الأبيض 102 (N3)، الأسود 103 (N2)، الأبيض 104 (M2)، الأسود 105 (N4)، الأبيض 106 (M3). في الأسفل يلتصق الأبيض مباشرة يسار O3، ويضع الأسود أحجارًا تحته وفوقه فيضع N3 في أتاري. يتصل الأبيض بـM3 ويجعل L3 وM3 وN3 وM2 مجموعة واحدة قوية. وصار لـO3 أيضًا رفيقان في N4 وN2، وهو آمن قرب الجدار على اليمين. تبادل هادئ رسّخ فيه الطرفان الحدود في الأسفل.","112":"الأسود 107 (B8)، الأبيض 108 (A9)، الأسود 109 (A10)، الأبيض 110 (C10)، الأسود 111 (B12)، الأبيض 112 (C8). على الحافة اليسرى يدخل الأسود تحت B9، ويضيّق الأبيض على الأحجار السوداء بـA9 وC10. كانت النقلة 110 حادة إذ أنقصت حريات B10–A10 وC11 ورفاقه معًا إلى اثنتين، لكن الأسود يتصل بـB12 فيجمع أحجاره الرئيسة على اليسار ويزيل الخطر الكبير. والأبيض 112 ينقص حريات B8 إلى اثنتين ويُبقي أحجار الأسود على الحافة صغيرة.","116":"الأسود 113 (T5)، الأبيض 114 (T4)، الأسود 115 (T7)، الأبيض 116 (T2). يضع الأسود أحجارًا على حافة اللوح القصوى بجانب أحجار الأبيض في أسفل اليمين، ليقلّص مساحة عيون الأبيض. يحمي الأبيض الحافة بـT4 وT2 ويضمن شكلًا حيًّا في الزاوية. وحتى إن لم يستطع الأسر، فالأسود بهذا يصغّر منطقة الخصم ويستعد للـيوسيه (نهاية اللعب التي تُحدَّد فيها الحدود).","121":"الأسود 117 (H9) يصطدم بالحجر الأبيض J9 في الوسط ويجعل أحجار الأبيض الوسطى أثقل. والأبيض 118 (Q14) يُلعب تحت Q15 في أعلى اليمين محاولًا قطع الأحجار السوداء. ينقص الأسود 119 (R17) حريات حجر الزاوية S17 إلى اثنتين، وحين يتصل الأبيض 120 (S18) يربط الأسود 121 (R15) بين Q15 وR16 بإحكام. ضاعت فكرة الأبيض، وصار Q14 حجرًا متروكًا داخل منطقة الأسود. وصارت أحجار الأسود في أعلى اليمين مجموعة واحدة قوية.","122":"الأبيض 122 (G6) يُلعب فوق G5 مباشرة. يذهب ليقطع الصلة بين أحجار الأسود في الأسفل G3–G5 وحجري الأسود H7 وJ7 في الوسط. كانت G3–G5 قد تسللت بين أحجار بيضاء، وهي محاطة بالأبيض. فإن قُطعت صلتها بالخارج هنا، صعب جدًا على هذه الأحجار السوداء أن تعيش. ومن هنا تبدأ أعنف معركة في المباراة، من أسفل اليسار على امتداد الجانب السفلي.","128":"الأسود 123 (H5)، الأبيض 124 (J5)، الأسود 125 (K5)، الأبيض 126 (H6)، الأسود 127 (J6)، الأبيض 128 (J4). يبحث الأسود عن مخرج نحو اليمين بـH5 وK5، لكن الأبيض يسدّ الطريق بـJ5 وH6. وضع الأسود 127 الحجر J5 في أتاري، لكن الأبيض يتصل بـJ4 ويجعل أحجاره في الأسفل مجموعة كبيرة واحدة. فقدت أحجار الأسود الأربعة G3 وG4 وG5 وH5 طريقها إلى الخارج تقريبًا.","131":"الأسود 129 (G8) يُلعب فوق أحجار الأبيض G7 وG6 وH6 فيتركها بحريتين. والأبيض 130 (F7) يصلها بالجدار الأبيض على اليسار ويزيل القلق. ثم الأسود 131 (M5): لا يعتني الأسود فورًا بأحجاره الأربعة في الأسفل، بل يصفّ K5 وM5 في الجزء الأيمن من الجانب السفلي ويبني شكله فوق L3. الفكرة: أخذ مكان كبير أولًا بدل التشبث بأحجار ضعيفة.","134":"الأبيض 132 (E2)، الأسود 133 (D4)، الأبيض 134 (F3). يلتفّ الأبيض تحت زاوية الأسود في أسفل اليسار، ويقوّي الأسود زاويته بـD4 مع إنقاص حريات E4 وE3 وE2 البيضاء إلى ثلاث. والنقلة 134 قاسية: تقوّي أحجار الأبيض على اليسار، وتضع F2 في أتاري، وتنقص حريات الأحجار السوداء الأربعة G3–H5 إلى اثنتين. في أسفل اليسار تتشابك زاوية الأسود وأحجار الأبيض والأحجار السوداء الأربعة في صراع على أيّ مجموعة لها كم حرية.","137":"الأسود 135 (L8) يُلعب تحت الحجر الأبيض L9 في الوسط فيجعل أحجار الأبيض الوسطى أثقل. والأبيض 136 (D6) يتسلل بين حجري زاوية الأسود C6 وE6. لو لم يردّ الأسود لانشطرت أحجار زاويته نصفين وصارت الزاوية نفسها في خطر. يتصل الأسود 137 (D5) فورًا: ثمانية أحجار سوداء في الزاوية مجموعة واحدة بثماني حريات. اختار الأسود حماية مجموعة الزاوية الكبيرة بدل الأحجار الأربعة في الأسفل.","138":"الأبيض 138 (F5) يضع أحجار الأسود الأربعة G3 وG4 وG5 وH5 في أتاري. حريتها الأخيرة F4، لكن الأسود لا يستطيع اللعب هناك: كل ما حولها أبيض، فلن تبقى للحجر حرية خاصة. يستطيع الأبيض متى شاء أن يلعب F4 ويأسر الأربعة. أي أن هذه الأحجار السوداء لم يعد يمكن إنقاذها. مقابل حماية زاويته في أسفل اليسار، تخلى الأسود عن الأحجار الأربعة في الأسفل. لكن شوساكو لا يتحسر، بل يتجه في النقلة التالية إلى مكان كبير في الوسط.","139":"الأسود 139 (M9) يصطدم بيمين الحجر الأبيض L9 في الوسط. تنخفض حريات L9 إلى اثنتين (K9 وL10)، وعلى الأبيض أن ينفق نقلة لمساعدة أحجاره الوسطى. خسر الأسود أربعة أحجار في الأسفل، لكنه في الأثناء رسّخ زاويته وكسب الدور لمهاجمة الأبيض في الوسط. في هذه المقايضة — التخلي عن أحجار لأخذ مكان كبير في موضع آخر — يُعتقد أن الأسود لم يخسر كثيرًا. وكانت مثل هذه الصفقات الهادئة من مواطن قوة شوساكو.","145":"الأبيض 140 (B4)، الأسود 141 (B3)، الأبيض 142 (B2)، الأسود 143 (C3). يضع الأبيض أحجارًا على حافة زاوية الأسود في أسفل اليسار ليقلّص مساحة عيونه. ويردّ الأسود بهدوء بـB3 وC3، فيجمع عشرة أحجار في الزاوية مجموعة واحدة بسبع حريات. ثم يلعب الأبيض 144 (B16) هانيه فوق B15 على حافة أعلى اليسار، مضيّقًا من الأعلى مساحة عيون أحجار الأسود على اليسار، فيوقفه الأسود 145 (A15) على الحافة. لكلتا المجموعتين السوداوين متسع كافٍ للحياة.","151":"الأبيض 146 (B6)، الأسود 147 (B5)، الأبيض 148 (A5)، الأسود 149 (B7)، الأبيض 150 (A7)، الأسود 151 (A6). على الحافة اليسرى يضع الأبيض أحجارًا بين زاوية الأسود وB7، فتبدأ معركة أسر دقيقة. يلعب الأسود 151 في A6 فيأسر الحجر الأبيض B6، ويضع في الوقت نفسه A5 وA7 في أتاري. هذا شكل «كو». في الكو يمكن الأسر ذهابًا وإيابًا مرات كثيرة، لكن لا يجوز الاسترداد فورًا؛ يجب اللعب في مكان آخر أولًا.","154":"الأبيض 152 (B11) تهديد كو: نقلة مهدِّدة في مكان آخر يجب على الخصم الرد عليها، تُلعب ليتمكن من استرداد الكو. وضعت B10 وA10 السوداوين في أتاري، فيردّ الأسود 153 (A11) بأسر ذلك الحجر الأبيض. والآن يستطيع الأبيض الاسترداد بـ154 (B6) آسرًا الحجر الأسود في A6. هدِّد، واجعل الخصم يردّ، ثم استردّ: هكذا تُخاض معركة الكو. صار B7 وB8 السوداوان في أتاري من جديد.","157":"الأسود 155 (A3) لا يواصل الكو بل يرسّخ الزاوية. يأسر الأبيض 156 (A8) حجري الأسود B7 وB8، لكن الأسود 157 (A4) يضع B4 وA5 البيضاوين كليهما في أتاري. حصيلة هذا الكو: أخذ الأبيض حجرين أسودين على الحافة اليسرى، وأمّن الأسود زاويته الكبيرة في أسفل اليسار. وبقي B4 وA5 الأبيضان داخل زاوية الأسود، وسيصيران لاحقًا بذرة كو صغير آخر.","162":"الأبيض 158 (L10) يمدّ الحجر الأبيض الأوسط L9 القليل الحريات وينقذه. والأسود 159 (H11) يقوّي أحجاره يسار الوسط، والأبيض 160 (N13) يضع N12 في أتاري. لا ينقذ الأسود N12، بل يضع بـ161 (N14) الحجر الأبيض N13 في أتاري، فيأسر الأبيض 162 (O12) الحجر N12. مقابل التخلي عن حجر واحد، يصل الأسود بـN14 أحجاره في أعلى اليمين بإحكام، ويكسب شكلًا يضغط على O15 وP15 البيضاوين في الأعلى. وتتوالى قرارات شوساكو التي لا تتشبث بالأحجار الصغيرة.","167":"الأسود 163 (O14) يصطف تحت O15 وP15 البيضاوين في الأعلى فينقص حرياتهما إلى ثلاث. والأبيض 164 (N17) يدافع كأنه يصل الأحجار البيضاء في الأعلى. ويدخل الأسود 165 (R2) في أسفل اليمين مساحة عيون زاوية الأبيض، فيردّ الأبيض 166 (S1)، ثم يصل الأسود 167 (O2) بين O3 وO2 وN2 في الأسفل. هدأت المعارك الكبيرة، وتنتقل المباراة إلى مرحلة رسم الحدود في أنحاء اللوح.","171":"الأبيض 168 (O8) ينزل من الأحجار البيضاء الوسطى ويطلّ على منطقة الأسود في أسفل اليمين. والأسود 169 (O7) يسدّ الطريق تحته، ثم الأبيض 170 (N8) والأسود 171 (N7): كلما امتد الأبيض جانبيًا اصطف الأسود تحته. وسّع الأبيض شكل أحجاره الوسطى، لكن الأسود لم يتنازل عن خطوة واحدة من منطقته الممتدة من أسفل اليمين إلى الجانب السفلي. ولأحجار الأسود M8 وL8 وM9 خمس حريات، فلا خطر عليها بعد.","179":"من هنا تبدأ اليوسيه. الأبيض 172 (K18) والأسود 173 (J18) والأبيض 174 (L19) يحددون الحدود في الأعلى؛ والأسود 175 (D18) في أعلى اليسار؛ والأبيض 176 (D1) والأسود 177 (C1) والأبيض 178 (E1) والأسود 179 (C2) على حافة أسفل اليسار. في اليوسيه يُقارَن كم نقطة تكسب كل نقلة، وتُلعب الأماكن الأكبر أولًا. وضع الأسود 177 الحجر D1 في أتاري، فاتصل الأبيض بـE1، وبالنقلة 179 أُغلقت زاوية الأسود بإحكام. وتستمر يوسيه متينة دون خطأ كبير من أيّ طرف.","185":"الأبيض 180 (C18) والأسود 181 (J19) يوسيه في الأعلى أيضًا. والأبيض 182 (K4) ينقص حريات K5 الأسود إلى اثنتين في الأسفل، والأسود 183 (L4) يتسلل بين أحجار الأبيض في الأسفل لينقص حريات L3 وM3 وN3 وM2. وضع الأبيض 184 (M14) الحجر M13 في أتاري، لكن الأسود لا ينقذه، ويختار بـ185 (N15) إنقاص حريات O15 وP15 البيضاوين في الأعلى إلى اثنتين. رأى الأسود مهاجمة أحجار الخصم الضعيفة أهم من حجر صغير.","189":"الأبيض 186 (T16) والأسود 187 (T15) والأبيض 188 (T17) يحددون الحدود على حافة أعلى اليمين. وضع الأسود 187 الحجر T16 في أتاري، فاتصل الأبيض بـT17، وبقيت أحجار الأبيض في زاوية أعلى اليمين في شكل حيّ صغير. ثم الأسود 189 (R14): يضع الحجر الأبيض Q14 الباقي في الداخل في أتاري، فيمحو كل أثر له داخل منطقة الأسود على اليمين. وصارت منطقة الأسود الكبيرة من أعلى اليمين نزولًا على الجانب الأيمن شبه محسومة.","192":"الأبيض 190 (H10) يتسلل يسار الوسط بين H9 وH11 السوداوين. تنخفض حريات H9 إلى اثنتين، ويظهر خطر أن تُقطع أحجار الأسود الوسطى. يضع الأسود 191 (G10) الحجر H10 في أتاري، فيتصل الأبيض 192 (J10) وينجو. يسار الوسط ما تزال الأحجار السوداء والبيضاء يقطع بعضها بعضًا، ولا أحد آمن تمامًا بعد.","199":"الأسود 193 (O17) يوضع بهدوء بين P17 وN17 البيضاوين في الأعلى. وحين يضعه الأبيض 194 (O18) في أتاري، يمتد الأسود 195 (O16) ويضع بدوره O15 وP15 في أتاري. يتصل الأبيض 196 (P16) لينقذهما ويضع في الوقت نفسه O16 وO17 السوداوين في أتاري، لكن الأسود 197 (N16) يتصل وينجو تاركًا لـN17 حريتين. وحين يدافع الأبيض 198 (M17)، يضع الأسود 199 (M15) الحجر M14 في أتاري. في الأعلى يضع الأسود الأحجار البيضاء في أتاري واحدًا تلو الآخر وهو يصل أحجاره، ويتوغل في منطقة الأبيض.","204":"الأبيض 200 (L14) يتصل وينقذ M14. والأسود 201 (M1) يلعب على أقصى الحافة السفلية فينقص حريات L3 وM3 وN3 وM2 إلى ثلاث. وحين يضع الأبيض 202 (L1) الحجر M1 في أتاري، يتصل الأسود 203 (N1) فتلتحق أحجاره بأحجار الأسود على اليمين. والأبيض 204 (K2) يرتّب شكل أحجاره في الأسفل كي لا يدخل الأسود. تتحدد الحدود في الأسفل بطريقة يكسب فيها الأسود قليلًا كل مرة.","208":"الأسود 205 (Q18) يُلعب فوق أحجار الأبيض في الزاوية R18 وS18 وS17 وT17 وT16 في أعلى اليمين فينقص حرياتها إلى ثلاث. وحين يصل الأبيض 206 (P18) أحجاره في الأعلى ويترك لـQ18 حريتين، يتصل الأسود 207 (Q17) ويجمع أحجاره في أعلى اليمين. والأبيض 208 (Q19) يلعب على أقصى الحافة العليا ويحفظ الشكل الحي لأحجار زاويته. حُسمت زاوية أعلى اليمين: يعيش الأبيض صغيرًا، ويحيط به الأسود بإحكام.","211":"الأسود 209 (J12) يضع حجرًا في الوسط ليقوّي الصلات بين أحجاره الوسطى. والأبيض 210 (G14) يقترب من اليسار من H14 وH15 وH16 السوداء فيترك لها أربع حريات. والأسود 211 (G15) يتصل بأحجار الأسود في الأعلى وينقص حريات G14 إلى اثنتين. صارت الأحجار السوداء الممتدة من الأعلى إلى الوسط مجموعة واحدة كبيرة.","219":"من الأبيض 212 (F9) إلى الأسود 219 (G11) يطارد الأسود والأبيض أحدهما الآخر يسار الوسط. بالأسود 213 (G9) والأبيض 214 (K8) والأسود 215 (K7) والأبيض 216 (J8) والأسود 217 (H8)، ينقص كل طرف حريات الآخر. وضع الأبيض 218 (F10) الحجر F11 في أتاري، لكن الأسود 219 (G11) يتصل، فتصير أحجار الأسود الوسطى مجموعة كبيرة من اثني عشر حجرًا. إنه تبادل متقارب، على الأحجار الوسطى للطرفين فيه أن تراقب حرياتها لتنجو.","226":"الأبيض 220 (D19) والأسود 221 (E19) والأبيض 222 (C19) يوسيه على حافة أعلى اليسار. ثم الأسود 223 (P10): يضع الحجر الأبيض Q10 على اليمين في أتاري وينقص حريات P11 إلى اثنتين. ويضع الأبيض 224 (O10) بدوره P10 في أتاري، فيمتد الأسود 225 (P9) وينجو، ثم ينقص الأبيض 226 (P8) حريات P9 وP10 السوداوين إلى اثنتين. صار الجانب الأيمن حسابًا دقيقًا: هل يأسر الأسود Q10، أم عليه أن يحمي P9 وP10؟","233":"الأسود 227 (M10) يُلعب في الوسط بين N10 وO10 وN11 وL9 وL10 البيضاء، فينقص حريات المجموعتين. ومن الأبيض 228 (J11) إلى الأسود 231 (J13)، يسار الوسط، يضع الأسود H13 في أتاري ويجمع أحجاره الوسطى في مجموعة كبيرة من خمسة عشر حجرًا. وضع الأبيض 232 (O9) الحجرين P9 وP10 في أتاري، لكن هنا يأتي الأسود 233 (Q9): يأسر الحجر الأبيض Q10، فترتفع حريات P9 وP10 دفعة واحدة إلى تسع. سقط أخيرًا Q10 الضعيف منذ النقلة 81، وصارت منطقة الأسود على اليمين محمية في كل زواياها.","238":"الأبيض 234 (G13) يتصل وينقذ H13. والأسود 235 (O13) يضع N13 في أتاري، وحين يتصل الأبيض 236 (N12) تصير أحجار الأبيض الوسطى مجموعة كبيرة من ثلاثة عشر حجرًا. والأسود 237 (K13) يزيد ربط أحجاره الوسطى، والأبيض 238 (L13) يأسر الحجر الأسود M13. في الوسط صار للمجموعة البيضاء الكبيرة وللمجموعة السوداء الكبيرة شكلان حيّان واضحان. ولم يبقَ إلا يوسيه صغيرة وكو.","242":"الأسود 239 (A6) يأسر الحجر الأبيض A5، فيعود الكو على الحافة اليسرى. إنه الحجر الذي وضعه الأسود في أتاري بـA4 في النقلة 157. والأبيض 240 (D16) تهديد كو: ينقص حريات D17 وE17 وD18 السوداء في أعلى اليسار إلى ثلاث ويهدد بقطعها. يردّ الأسود 241 (E16) بالاتصال فيجمع أحجاره في الأعلى. والأبيض 242 (A5) يستردّ الكو الآن.","245":"الأسود 243 (P12) تهديد كو يضع الحجر الأبيض P11 على اليمين في أتاري. لكن الأبيض 244 (A6) لا يردّ، بل يتصل في A6 ويُنهي الكو على الحافة اليسرى. لا يأسر الأسود P11 فورًا، بل يضع بـ245 (A16) حجرًا على حافة أعلى اليسار فينقص حريات أحجار الأبيض هناك إلى خمس. لعله رأى ذلك أكبر من أسر حجر واحد. وسيصل الأبيض P11 لاحقًا بـ266 (O11).","248":"الأبيض 246 (A17) ينقص حريات أحجار الأسود على حافة أعلى اليسار إلى أربع. ثم الأسود 247 (F8): نقلة حادة تنقص حريات F9 وF10 وE10 وD10 وE11 وC10 البيضاء على اليسار إلى ثلاث. والأبيض 248 (E8) يصلها بالجدار الأبيض في أسفل اليسار ويحميها. صُدّ هجوم الأسود، لكنه بإجبار الأبيض على الدفاع يصل أولًا إلى اليوسيه التالية.","253":"الأسود 249 (M4) ينقص حريات L3 وM3 وN3 وM2 البيضاء في الأسفل إلى اثنتين. والأبيض 250 (R1) ينقص حريات R2 وR3 وQ3 السوداء على حافة أسفل اليمين، فيدخل الأسود 251 (Q1) تحت ذلك الحجر الأبيض. والأبيض 252 (Q4) ينقص حريات Q3 وR3 وR2 إلى اثنتين، فيردّ الأسود 253 (P4) بإنقاص الحريات من جهة R4. صارت زاوية أسفل اليمين سباقًا متقاربًا ينتزع فيه كل طرف حريات الآخر واحدة واحدة.","259":"الأبيض 254 (P7) يدخل إلى داخل جدار الأسود في أسفل اليمين، فيوقفه الأسود 255 (P6). والأبيض 256 (M11) ينقص حريات M10 وM9 وM8 وL8 السوداء في الوسط إلى ثلاث. ثم الأسود 257 (S7): ينقص حريات R4–R7 وQ4 البيضاء في أسفل اليمين إلى ثلاث. وضع الأبيض 258 (S5) الحجر T5 في أتاري، لكن بالأسود 259 (S6) صارت ستة أحجار بيضاء في أتاري (لم يبقَ لها إلا الحرية S4). وفي أواخر المباراة تجد أحجار الأبيض في أسفل اليمين نفسها فجأة في خطر غير متوقع.","263":"الأبيض 260 (T6) يأسر T5 فيزيد حريات أحجاره. ويظهر الآن كو على حافة أسفل اليمين. والأسود 261 (K19) تهديد كو يضع الحجر الأبيض K18 في الأعلى في أتاري، فيردّ الأبيض 262 (L18) بالاتصال. وحين يستردّ الأسود 263 (T5) الكو، تعود الأحجار البيضاء الستة إلى أتاري. فإن خسر الأبيض هذا الكو خسر أحجارًا كثيرة في أسفل اليمين، لذا عليه أن يدافع في نقلته التالية.","267":"باتصال الأبيض 264 (S4) تعيش أحجار الأبيض في أسفل اليمين بعينين في T3 وT1. ويلعب الأسود 265 (J16) والأبيض 266 (O11) نقاطًا صغيرة، ويملأ الأسود 267 (T6) موضع الكو، وتنتهي المباراة بعد 267 نقلة. يفوز الأسود بفارق 11 نقطة. استند شوساكو إلى الجدار السميك الذي بناه في أسفل اليمين بجعل الأبيض يزحف على الخط الثالث (حتى النقلة 43)، وأقام منطقة كبيرة على الجانب الأيمن. ومنذ النقلة 76 دخل الأبيض الجانب الأيمن وهرب إلى الوسط؛ عاشت أحجاره، لكن الأسود وهو يطاردها رسّخ منطقته في الأعلى وعلى اليمين، وأسر أخيرًا في النقلة 233 الحجر Q10 الذي كان يستهدفه منذ النقلة 81. وفي أسفل اليسار تخلّى عن أربعة أحجار، لكنه حمى زاويته مقابل ذلك ووصل أولًا إلى الأماكن الكبيرة في الوسط. لا مغامرات كبيرة، بل مهاجمة أحجار الخصم وزيادة المنطقة بشكل طبيعي: فوز على طريقة شوساكو حقًّا. ومن هذه المباراة سيبني شوساكو ابن العشرين رقمًا ما يزال يُروى حتى اليوم، 19 فوزًا في 19 مباراة قلعة، حتى وفاته المبكرة عام 1862 وهو في الثلاثينيات من عمره."}},"shilin":{"t":"مباراة «شيلين غوانغجي»","w":"الأحمر (لم يُحفظ اسمه)","b":"الأسود (لم يُحفظ اسمه)","ev":"موسوعة الحياة اليومية «شيلين غوانغجي»: «مباراة فاز فيها من أعطى النقلة الأولى، بمدفعين من الجهة نفسها»","d":"القرن الثالث عشر","pl":"الصين (سونغ–يوان)","lead":"هذا السجل مأخوذ من «شيلين غوانغجي»، وهي موسوعة للحياة اليومية جمعها تشن يوانجينغ في أواخر عهد سلالة سونغ وبدايات يوان. ويُقال إنه من أقدم سجلات الشيانغتشي الكاملة الباقية. إنها مباراة نموذجية يترك فيها اللاعب الأقوى النقلة الأولى لخصمه، وفي تسع نقلات فقط يحاصر الحصانُ الأسود العربةَ الحمراء.","c":{"0":"يزيد عمر هذا السجل على 700 عام، وهو من الزمن الواقع بين سلالتي سونغ ويوان. يرد في باب الألعاب من موسوعة «شيلين غوانغجي»، ويُقال إنه من أقدم مباريات الشيانغتشي الكاملة التي بقيت لنا. لم تُحفظ أسماء اللاعبين. يقول العنوان إن اللاعب الأقوى «أعطى النقلة الأولى» للأضعف، فهي درس يبيّن كيف يخسر الأحمر الذي يبدأ. الأحمر في الأسفل ويبدأ اللعب. يُعتقد أن شيانغتشي اتخذت شكلها الحالي تقريبًا، بالنهر والمدافع، في عهد سلالة سونغ، ولا سيما سونغ الجنوبية. وكان تشن يوانجينغ، جامع كتاب \"شيلين غوانغجي\"، من أواخر عهد سونغ الجنوبية. وبعد ذلك، في أواخر القرن الثالث عشر، أسقطت سلالة يوان المغولية سلالة سونغ. وبينما كانت السلالات تتبدّل، كان كتاب للحياة اليومية يضم بالفعل مباراة نموذجية في شيانغتشي.","1":"ينقل الأحمر المدفع الأيمن إلى العمود الأوسط. هذا هو «المدفع المركزي» الذي يصوّب مباشرة على الجنرال الأسود، وما زال من أقوى الافتتاحيات حتى اليوم. ونرى أنه كان يُلعب قبل 700 عام.","2":"يردّ الأسود بمدفع إلى الوسط أيضًا، فيتواجه المدفعان. عندما يحرّك الطرفان المدفع من الجهة نفسها يُسمّى ذلك «مدفعين في اتجاه واحد». ومعركة المدفع ضد المدفع محبوبة منذ قرون. إخراج المدفع من الجهة المعاكسة لجهة الخصم يُسمّى «مدفعين في اتجاهين متعاكسين»، والسجلات القديمة مليئة بمباريات المدفعين في اتجاه واحد وفي اتجاهين متعاكسين. كان زمنًا يحب المعارك السريعة التي تتصادم فيها المدافع فورًا. أما اليوم، فعند المحترفين يرد الأسود على المدفع الأوسط غالبًا بـ«خيلَي الستار»، ويُقال إن المدفعين في اتجاه واحد صارا أقل شيوعًا من قبل.","3":"يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. هذا الجندي مهدَّد من المدفع الأسود ويحتاج إلى حارس. والحصان يستعد أيضًا للتقدّم.","4":"يفعل الأسود الشيء نفسه ويحمي جنديه الأوسط بحصان. يبني الطرفان أولًا قاعدة متينة.","5":"ينقل الأحمر العربة اليمنى خطوة إلى الجانب نحو عمود مفتوح. العربة أقوى قطعة على الرقعة، لذلك من الجيد تشغيلها مبكرًا.","6":"يُخرج الأسود الحصان الآخر ويترك العربتين في البيت الآن. الخطة هي تقديم القطع أولًا. لكن العربة التي تخرج متأخرة قد يصعب استخدامها في الهجوم لاحقًا. كثيرًا ما تعرض المباريات النموذجية في الكتب القديمة خطأً ينبغي تجنّبه. وهذه المباراة تعلّم أن الأسود، حتى لو تأخر في إخراج العربات، يستطيع الفوز إذا أحسن استعمال القطع الأخرى.","7":"تعبر العربة الحمراء النهر دفعة واحدة وتدخل معسكر الأسود. تريد تهديد القطع السوداء، لكن بقية القطع الحمراء ما زالت في البيت، فالهجوم متسرّع قليلًا. كان يمكن أيضًا إخراج الحصان أو العربة اليسرى أولًا.","8":"يقدّم الأسود جندي العمود 3 خطوة واحدة. بهذا يفتح طريقًا للحصان ليقفز إلى الأمام لاحقًا. يكاد الأسود يدعو العربة الحمراء إلى القدوم.","9":"تأخذ العربة الحمراء جنديًا وتصوّب الآن على الحصان الأسود خلفه. كسب قطعة وتهديد أخرى يبدو رائعًا. لكن العربة تقدّمت بعيدًا جدًا ولا صديق حولها. والعربة الوحيدة في معسكر العدو يسهل مطاردتها.","10":"يقفز الحصان الأسود إلى الأمام. يهرب من العربة ويقترب من معسكر الأحمر في الوقت نفسه: مهمتان بنقلة واحدة. سيكون هذا الحصان بطل المباراة.","11":"يعيد الأحمر العربة خطوة إلى الوراء ليهاجم الحصان من الجانب. العربة تأخذ من بعيد، فلا يستطيع الحصان أن يرتاح. ومع ذلك لا تساعد هذه النقلة على إخراج قطع حمراء أخرى.","12":"يتقدّم الحصان الأسود أكثر ويعبر النهر إلى معسكر الأحمر. وفي كل مرة يهرب فيها من العربة يقترب أكثر من الجنرال الأحمر.","13":"يقدّم الأحمر جنديًا ليفتح الطريق لحصانه. الفكرة إخراجه ومبادلته بالحصان الأسود. لكن هذا يمنح الأسود وقتًا ليتقدّم أكثر.","14":"يرفع الأسود فيلًا ويهاجم العربة الحمراء. طرد عربة الخصم بقطعة دفاعية أمر فعّال جدًا. على الأحمر أن يحرّك العربة مرة أخرى، ويكسب الأسود نقلة إضافية.","15":"تنزلق العربة الحمراء جانبًا وتأخذ جنديًا آخر. صار الأحمر متقدّمًا بجنديين، لكن هذه هي النقلة الخاسرة. فالعربة الآن بعيدة عن جنرالها ولا تستطيع العودة للدفاع. كان على الأحمر أن يحتاط من الحصان، كأن يعيد العربة إلى البيت.","16":"يتوغّل الحصان الأسود أعمق ويهاجم العربة الحمراء. وهناك المزيد: إذا قفز مرة أخرى فسيكشّ الجنرال الأحمر ويهاجم في الوقت نفسه العربة في زاوية الأحمر. حصان واحد صنع تهديدين معًا.","17":"يطارد الأحمر الحصان بالعربة. لكن لم يعد من الممكن إيقافه. لم يبقَ حول الجنرال الأحمر أحد يساعد.","18":"يقفز الحصان مع كِش! وهو يهاجم أيضًا العربة في زاوية الأحمر، فإذا تنحّى الجنرال ضاعت العربة. تسع نقلات فقط، لكن المباراة تعلّمنا ماذا يحدث لعربة تندفع وحدها، ولماذا يجب أن تقاتل القطع معًا. قبل 700 عام كان اللاعبون يفكّرون في الأشياء نفسها على الرقعة نفسها."}},"qima13":{"t":"التضحية بالحصان في ثلاث عشرة نقلة («جوتشونغمي»)","w":"الأحمر (لم يُحفظ اسمه)","b":"الأسود (لم يُحفظ اسمه)","ev":"«جوتشونغمي»، الجزء الأول، المباراة الأولى","d":"1632 (سنة النشر)","pl":"الصين (مينغ)","lead":"هذه أول مباراة في كتاب «جوتشونغمي» («السرّ في داخل اليوسفية»)، وهو كتاب شيانغتشي نشره تشو جينتشن من عهد سلالة مينغ سنة 1632. يترك الأحمر للأسود أن يأخذ حصانًا مجانًا، ويندفع في الهجوم أثناء ذلك، ويُميت في ثلاث عشرة نقلة. وما زالت محبوبة بعد نحو 400 عام باسم «التضحية بالحصان في ثلاث عشرة نقلة».","c":{"0":"هذه المباراة الأولى في كتاب «جوتشونغمي» الذي طُبع سنة 1632 قرب نهاية سلالة مينغ. ويُعدّ مع «كتيّب زهر البرقوق» اللاحق أحد الكتابين الكلاسيكيين الكبيرين في الشيانغتشي. ليست مباراة حقيقية بل نموذج كُتب لتعليم خطة، لذلك لا توجد أسماء لاعبين. الأحمر في الأسفل ويبدأ، وينتهي كل شيء في ثلاث عشرة نقلة فقط. كان عام 1632 هو العام الخامس من عهد تشونغتشن في سلالة مينغ. كانت الثورات تندلع في أنحاء البلاد، قبل سقوط مينغ (1644) باثني عشر عامًا فقط. وفي اليابان كانت بداية عصر إيدو، بعد 25 عامًا من أقدم سجل شوغي، مباراة سوكي وسانسا. ويُروى أن اسم \"جو تشونغ مي\" (أسرار داخل اليوسفية) مأخوذ من حكاية من عهد تانغ: حين شُقّت يوسفية ضخمة، وُجد بداخلها شيوخ يلعبون لعبة لوحية مستمتعين.","1":"ينقل الأحمر المدفع الأيمن إلى الوسط. هذا هو «المدفع المركزي» الذي يحدّق مباشرة في الجنرال الأسود. واشتهر كتاب «جوتشونغمي» بدراسة طرق الهجوم بهذه الافتتاحية. في هذا الكتاب دوّن المؤلف تشو جينتشن، نقلةً بعد نقلة، كيف يُهاجَم بالمدفع الأوسط. أما \"كتاب زهر البرقوق\" (ميهوا بو) الذي جمعه وانغ زاييويه لاحقًا في عهد تشينغ، فيُعرف بالعكس: الرد على المدفع الأوسط بـ«خيلَي الستار». \"جو تشونغ مي\" للهجوم و\"ميهوا بو\" للدفاع: هذان الكتابان أصل افتتاحيات المدفع الأوسط اليوم.","2":"ينقل الأسود أيضًا المدفع من الجهة نفسها إلى الوسط. هذان «مدفعان في اتجاه واحد» يتصادمان وجهًا لوجه. كل طرف يصوّب على الجندي الأوسط للآخر.","3":"يُخرج الأحمر حصانًا ليحمي الجندي الأوسط. يحمي الجندي الذي يصوّب عليه المدفع الأسود، ويبدأ الحصان العمل.","4":"يحمي الأسود أيضًا الجندي الأوسط بحصان. حتى الآن الشكلان متماثلان.","5":"يقدّم الأحمر العربة اليمنى خطوة واحدة فقط. الآن تستطيع في النقلة التالية أن تجري جانبًا. العربة التي تتحرك جانبيًا هكذا تُسمّى «العربة الأفقية»، وتستطيع الانتقال بسرعة إلى أي جناح.","6":"يحرّك الأسود العربة خطوة إلى الجانب لتتمكن من الصعود مستقيمة. هذه «عربة مستقيمة». العربة الأفقية ضد العربة المستقيمة: طريقتان مختلفتان لاستخدام العربة وجهًا لوجه. «مدفعان في اتجاه واحد، عربة أفقية ضد عربة مستقيمة» شكل كلاسيكي لهذه الافتتاحية يتكرر مرارًا في الكتب القديمة. وما زال حتى اليوم من أول التفرعات التي يلقاها من يدرسها.","7":"تنتقل العربة الأفقية الحمراء إلى عمود على اليسار. هذا العمود يمرّ بجوار المستشار الأسود مباشرة، حيث الدفاع ضعيف. يستعد الأحمر للاقتحام من هنا.","8":"تعبر العربة المستقيمة السوداء النهر وتتوغّل في معسكر الأحمر. يريد الأسود أن يردّ بهجوم من عنده. لكنها نقلة تستعجل الهجوم قبل الدفاع.","9":"تندفع العربة الحمراء إلى عمق معسكر الأسود. تقف على «عين» الفيل، وهي النقطة التي يجب أن يمرّ بها الفيل، فلا يستطيع الفيل الأسود التحرك. وبجوار المستشار صارت قريبة جدًا من الجنرال.","10":"يُخرج الأسود الحصان الآخر نحو الحافة. ومن أهدافه منع العربة الحمراء من التسلّل من الجانب.","11":"ها هي التضحية بالحصان! يرفع الأحمر العربة الأخرى خطوة واحدة. يترك هذا الحصانَ في الزاوية اليسرى بلا حارس، فيستطيع المدفع الأسود أخذه مجانًا. لكن الأحمر يكسب مقابل حصان واحد الوقتَ لإدخال العربتين في الهجوم بسرعة.","12":"يأخذ المدفع الأسود الحصان الأحمر. يبدو أن الأسود كسب قطعة. لكن هذا المدفع صار بعيدًا عن بيته ولا يستطيع المساعدة في الدفاع. ويُقال إن الأفضل هنا كان رفع مستشار لتقوية الدفاع بدل الأخذ.","13":"يتقدّم المدفع الأحمر. مستخدمًا المدفع الأسود في الوسط «حاجزًا» يقفز فوقه، يصوّب الآن على الحصان الأسود خلفه. المدفع قطعة عجيبة تأخذ بالقفز فوق قطعة واحدة بالضبط.","14":"يتراجع الأسود بالحصان ليهرب. لكن هذا الحصان كان القطعة المهمة التي تحمي الجندي الأوسط. وبهروبه انفتحت ثغرة في الوسط. كان لدى الأسود دفاعات أخرى، لكن هذا كان أسوأ اختيار.","15":"يأخذ المدفع الأحمر الجندي الأوسط — كِش! بعد ذهاب الحصان الأسود صار الوسط مفتوحًا تمامًا. ومن هنا ينطلق هجوم الأحمر بسرعة.","16":"يرفع الأسود مستشارًا ليسدّ ما أمام الجنرال. هذه هي الطريقة الجيدة الوحيدة لصدّ الكِش.","17":"تصل العربة الحمراء الثانية إلى العمود نفسه. عربتان مصطفّتان في عمود واحد قوة هائلة. الخطة هي اقتحام عمق معسكر الأسود.","18":"يتنحّى الجنرال الأسود جانبًا. وإلا لحدّقت فيه العربتان الحمراوان من العمود نفسه.","19":"تأخذ العربة الحمراء الأمامية المستشار الأسود — كِش! سيأخذها المستشار الآخر فورًا، لكن هذا جزء من الخطة. يضحّي الأحمر بعربة ليحطّم حرس الجنرال الأسود. يا لها من نقلة جريئة!","20":"يأخذ الأسود العربة بالمستشار. في عدد القطع صار الأسود متقدّمًا كثيرًا. لكن بيت الجنرال صار أكثر فراغًا.","21":"تنتقل آخر عربة حمراء إلى عمود الجنرال — كِش مرة أخرى. لم يبقَ للجنرال الأسود تقريبًا أي قطعة تحميه.","22":"يضع الأسود مدفعًا أمام الجنرال ليسدّ الكِش. وضع قطعة في الوسط هكذا يُسمّى الاعتراض.","23":"تأخذ العربة الحمراء ذلك المدفع — كِش مجددًا. تواصل العربة أخذ القطع السوداء وهي تحاصر الجنرال.","24":"لا يستطيع الجنرال الأسود إلا العودة إلى الوسط. كل النقاط الأخرى تحت سيطرة القطع الحمراء.","25":"أخيرًا يقف المدفع الأحمر في الوسط: مدفعان في عمود واحد — كِش. المدفع الأمامي هو الحاجز والخلفي يضرب الجنرال: إنه مات «المدفع المزدوج». لا مكان يذهب إليه الجنرال الأسود، ويفوز الأحمر. بالتخلّي عن حصان واحد فقط فاز الأحمر في ثلاث عشرة نقلة. منذ 400 عام وهذه المباراة تعلّمنا أن الوقت ونشاط القطع قد يكونان أهم من عددها."}},"sokei1607":{"t":"أقدم مباراة شوغي محفوظة","w":"أوهاشي سوكي (الأول)","b":"هون-إنبو سانسا","ev":"أقدم مباراة مسجّلة","d":"يونيو 1607","pl":"اليابان (مكان اللعب غير مسجّل)","lead":"من بين كل مباريات الشوغي التي كُتبت نقلةً نقلة، هذه أقدم مباراة ما زالت بين أيدينا. السِّنتي هو سوكي، الذي أسّس لاحقًا بيت أوهاشي لأساتذة الشوغي. والغوتي هو سانسا، مؤسس بيت هون-إنبو للعبة غو، وكان قويًّا في الشوغي أيضًا. يفوز سوكي في 133 نقلة.","c":{"0":"أهلًا بكم، أنا Musowl. لُعبت هذه المباراة عام 1607، حين كان عصر إيدو قد بدأ للتوّ. السِّنتي أوهاشي سوكي سيُسمّى لاحقًا أول «ميجين»، أي أكبر أساتذة الشوغي في البلاد. والغوتي هون-إنبو سانسا أسّس بيت هون-إنبو للعبة غو وكان يجيد الشوغي كثيرًا؛ وكان الاثنان يلعبان كثيرًا أمام كبار القوم. بقيت ثماني مباريات بينهما بلا أفضلية، ويُقال إن سوكي فاز بسبع منها. وبعد أكثر من 400 سنة ما زلنا نستطيع إعادة كل نقلة. كان عام 1607 هو العام الرابع بعد أن أقام توكوغاوا إيياسو حكومته في إيدو. وبعد أن سلّم لقب الشوغون لابنه هيديتادا، بدأ إيياسو في ذلك العام نفسه ببناء قلعة في سونبو (مدينة شيزوؤكا اليوم). هذه المباراة من الزمن الذي كانت فيه اليابان تنتقل من عصر الحروب إلى عصر إيدو.","1":"P-7f. تفتح هذه النقلة قطر الفيل، وما زالت حتى اليوم أكثر نقلة أولى شيوعًا. إذن كان الشوغي يبدأ هكذا قبل 400 سنة.","2":"P-3d. الغوتي أيضًا يفتح قطر فيله. الآن ينظر الفيلان أحدهما إلى الآخر عبر وسط الرقعة. وُلد سانسا في كيوتو عام 1559، وصار راهبًا بوذيًا في الثامنة من عمره. كان \"هونينبو\" اسم القاعة الصغيرة التي سكنها في معبد جاكّوجي، فصار اسمًا لبيته في لعبة غو. ويُروى أن أودا نوبوناغا أثنى عليه ووصفه بأنه أستاذ حقيقي.","3":"S-4h. يرفع السِّنتي الفضة اليمنى. إنه يستعدّ لدفعها إلى الأمام. وُلد سوكي نحو عام 1555، ويُروى أنه من عائلة من أهل مدينة كيوتو. وفي عام 1603 أهدى الإمبراطور كتابًا من مسائل تسومي-شوغي من تأليفه. ويُقال إنه أقدم مجموعة تسومي-شوغي معروفة.","5":"P-4f. يدفع السِّنتي بيدق العمود 4 ليُفسح مكانًا للفضة. وهي مرتبطة بالنقلة التالية S-4g.","6":"S-4b. الغوتي أيضًا يرفع فضة. المدافعون يتجمعون في العمود 4 لدى الغوتي. بعد هذه المباراة بخمس سنوات، في عام 1612، بدأ إيياسو يدفع لأمهر لاعبي غو والشوغي راتبًا من الأرز. كانت تلك بداية بيوت \"إييموتو\" التي جعلت الشوغي مهنتها، واستمر بيت أوهاشي الذي أسسه سوكي طوال عصر إيدو.","10":"R-4b. ينقل الغوتي الرخ إلى العمود 4. يُسمّى هذا اليوم «رخ العمود الرابع»، وهو من خطط الرخ المنقول حيث يتحرك الرخ إلى اليسار. وكان يُلعب قبل 400 سنة. إذن هذه المباراة هي ما نسميه اليوم مباراة \"متقابلة\": سينتي بالرخ الثابت ضد غوتي بالرخ المنقول. وبعد أربعمئة عام، ما زال رخ العمود الرابع محبوبًا عند المحترفين والهواة. من الجميل أن نرى خطة مشهورة في أقدم سجل.","11":"R-4h. رخ السِّنتي أيضًا يذهب إلى العمود 4، فيتقابل الرخّان. وسيحرّك السِّنتي هذا الرخ مرات كثيرة بحثًا عن مكان جيد للهجوم. بلغة اليوم، يقف رخ سينتي في مربع \"رخ العمود الرابع الأيمن\". إنه يقف مقابل رخ غوتي مباشرة ويهاجم مستقيمًا عبر العمود 4، وما زال يُلعب اليوم طريقةً لكسر هذا النظام.","12":"B-3c. يتقدم الفيل خطوة ليقوّي العمود 4. جعل الغوتي هذا العمود متينًا جدًا.","16":"K-6b. ينقل الغوتي ملكه إلى اليسار. مع الرخ المنقول يختبئ الملك عادةً في الجهة المعاكسة للرخ. وكلما ابتعد عن القتال كان أكثر أمانًا.","17":"K-6h. السِّنتي أيضًا ينقل ملكه إلى اليسار. سيذهب بعدها إلى 7h ثم إلى 8g. في ذلك الزمن، لم تكن الحصون ذات الأسماء، مثل حصن مينو اليوم، قد اتخذت على الأرجح شكلًا واضحًا. ونرى اللاعبين يتلمّسان طريقهما لحماية الملك.","19":"K-7h. وصل الملك إلى العمود 7. الهدف التالي جمع الذهب والفضة حوله لبناء قلعة.","21":"G-5h. يقترب الذهب الأيمن من الملك. الذهب مدافع ممتاز، ووجوده قرب الملك يجعله في أمان.","24":"S-5c. يأتي الغوتي بفضة إلى العمود 5. ومع الفضتين في 5c و4c صار الوسط متينًا أيضًا.","29":"S-6g. تصل فضة السِّنتي قرب الملك. ومع الفضة في 6g والذهب في 7h يتكوّن جدار حول الملك.","30":"G-6c. يرفع الغوتي ذهبًا ليقوّي ما أمام ملكه. كلا اللاعبين يبني معسكره ببطء وعناية.","33":"P-8f. يدفع السِّنتي بيدق العمود 8 ليُفسح مكانًا للملك. إنه يستعدّ لـ K-8g.","35":"K-8g. يذهب الملك إلى 8g. ليست هذه قلعة مما نستعمله اليوم: الملك يقف عاليًا قرب الحافة. ونرى كيف كان لاعبو ذلك الزمان يفكرون في الدفاع.","36":"K-8b. يستقرّ ملك الغوتي في 8b. الآن كل ملك مختبئ جيدًا في زاويته.","39":"N-7g. يقفز الحصان إلى الأعلى ليستطيع القفز إلى 6e في أي وقت. يريد السِّنتي أن تساعد قطع القلعة في الهجوم أيضًا.","41":"R-3h. ينقل السِّنتي الرخ إلى العمود 3. العمود 4 لدى الغوتي قوي جدًا، فيغيّر السِّنتي مكان الهجوم. في ذلك الوقت لم تكن هناك كتب تدوّن الطرق الثابتة للعب الافتتاح (جوسيكي). كان الأساتذة يبحثون عن الأشكال الجيدة مباراةً بعد مباراة. ولاحقًا درس لاعبو بيتَي أوهاشي وإيتو سجلات مثل هذا، فنمّوا الجوسيكي.","42":"R-3b. ينقل الغوتي رخه فورًا إلى العمود 3 أيضًا. أينما ذهب رخ السِّنتي تبعه رخ الغوتي.","43":"P-2e. الآن يدفع السِّنتي بيدق العمود 2. الخطة أن ينقل الرخ إلى العمود 2 ويهاجم هناك.","44":"B-5a. يسحب الغوتي فيله إلى الخلف. يعيد ترتيب قطعه حتى تستطيع قطع أخرى صدّ هجوم على العمود 2.","45":"R-2h. عاد الرخ إلى عموده الأول، العمود 2. العمود 4 ثم 3 ثم 2: قام رخ السِّنتي برحلة طويلة.","46":"R-2b. يتبعه رخ الغوتي مرة أخرى إلى العمود 2. أينما أرسل السِّنتي رخه، استقبله الغوتي في العمود نفسه. «مطاردة الرخّين» هذه هي أجمل ما في الافتتاح.","47":"P-6e. الآن يبدأ السِّنتي القتال في العمود 6 حيث لا يوجد رخ. فبدل الهجوم حيث يراقب الرخّان أحدهما الآخر، يضرب حيث الغوتي أضعف. يبدأ وسط المباراة. بدء القتال في عمود لا يوجد فيه رخ الخصم فكرة ما زالت تُستعمل كثيرًا في المباريات المتقابلة اليوم. وقد انتبه إليها الأستاذ قبل 400 عام.","49":"Px6d. يدفع السِّنتي البيدق ويأسر. الفكرة جذب ذهب الغوتي إلى الأمام وإرخاء الدفاع حول الملك.","50":"Gx6d. يستردّ الغوتي بالذهب. ابتعد الذهب قليلًا عن ملكه، فتنفتح ثغرة صغيرة في الدفاع.","51":"P-4e. ثم يدفع السِّنتي بيدق العمود 4. إنه يهزّ دفاع الغوتي في هذا العمود أيضًا.","53":"N-3g. يقفز الحصان الآخر لينضمّ إلى الهجوم. قطع السِّنتي المهاجمة تتقدم واحدة بعد أخرى.","54":"P*6e. يُسقط الغوتي بيدقًا في 6e، المربع الذي يريد حصان السِّنتي القفز إليه. البيدق رخيص، لكنه مفيد جدًا لسدّ طريق قطعة الخصم.","56":"P-7e. يردّ الغوتي بهجوم مضاد. يضغط على العمود الذي فوق ملك السِّنتي مباشرة. إذا تحطمت البيادق فوق الملك صعب الدفاع عنه.","57":"Px7e. يأسر السِّنتي بالبيدق. وإلا لتقدم بيدق الغوتي حتى 7f.","58":"Gx7e. يستردّ الغوتي بالذهب الذي صار في 7e. يقدّم الغوتي ذهبه ليضغط على ملك السِّنتي.","59":"P*7f. يُسقط السِّنتي بيدقًا ليوقف الذهب. هذا البيدق يحمي رأس الملك.","61":"R-6i. يذهب رخ السِّنتي حتى أسفل العمود 6. يريد أن يضيف قوته إلى القتال في هذا العمود. لاحقًا ستأسره فضة الغوتي.","63":"Nx6e. يقفز الحصان من 7g ويأسر البيدق في 6e. الحصان الذي أعدّه السِّنتي منذ زمن يبدأ العمل أخيرًا.","64":"Nx6e. يستردّ الغوتي بحصانه. تبادل الطرفان الحصانين.","66":"P-8e. يضغط الغوتي من العمود 8 أيضًا. يحاول نزع البيادق أمام ملك السِّنتي واحدًا بعد آخر.","68":"P*7g. يُسقط الغوتي بيدقًا في 7g بجوار الملك مباشرة. إن أسره السِّنتي تُسحب القطعة الآسرة من مكانها، وإن لم يأسره يترقّى البيدق. إنها حيلة معروفة لكسر الدفاع ببيدق صغير.","69":"G-7i. يسحب السِّنتي الذهب إلى الخلف ليبتعد. يفضّل أن يحافظ على شكل دفاعه بدل أسر البيدق الآن.","70":"N*7e، كِش. يُسقط الغوتي حصانًا. يصل الحصان إلى الملك في 8g قافزًا فوق القطع الأخرى. يشتدّ هجوم الغوتي.","72":"Sx7e. بعد أن أسر بيدق السِّنتي الحصان، يستردّ الغوتي بالفضة ويتقدم. قطع الغوتي المهاجمة الآن بجوار ملك السِّنتي مباشرة.","74":"P*8f، كِش. يُسقط الغوتي بيدقًا آخر أمام الملك في 8g مباشرة. لم يعد الملك يستطيع البقاء هناك.","75":"K-9h. يهرب ملك السِّنتي إلى 9h على الحافة. يبتعد عن الخطر ويعيد بناء دفاعه.","77":"Px7e. الآن يأسر بيدق السِّنتي في 7f الفضة في 7e. يزيل السِّنتي قلب هجوم الغوتي ويحصل على فرصة للرد.","79":"S*7f. يُسقط السِّنتي فضة تصطدم بالذهب في 7e. تحمي رأس الملك وتحاول طرد الذهب.","81":"Sx7f. تبادل الطرفان الفضة والذهب. يقلّل السِّنتي مهاجمي الغوتي واحدًا بعد آخر.","83":"Px6e. يأسر بيدق 6f الحصان في 6e. يخسر الغوتي مهاجمًا آخر، وتزداد القطع في يد السِّنتي.","84":"S*7h. يُسقط الغوتي فضة تستهدف الرخ في 6i. سيخسر السِّنتي رخه، لكنه في الأثناء يسرّع هجومه.","85":"P*9b. من هنا يبدأ هجوم السِّنتي المضاد. بيدق يُسقط في 9b قرب ملك الغوتي يجذب الرمح إلى الأمام. تحريك القطع حول الملك يصنع ثغرات.","86":"Lx9b. يأسر الغوتي البيدق بالرمح. لكن الرمح صار في 9b وأصبح هدفًا للحصان التالي.","87":"N*8d. يُسقط السِّنتي حصانًا يهاجم معًا الرمح في 9b والذهب في 7b. مهاجمة هدفين في وقت واحد هي أبرع ما يفعله الحصان.","88":"B-5a. يسحب الغوتي فيله ليصوّب على الحصان في 8d عبر القطر. يريد أسره وإيقاف الهجوم.","89":"N*7d، كِش. يُسقط السِّنتي حصانه الآخر ويضع ملك الغوتي في كِش. الحصان يعطي كِشًا بالقفز فوق القطع، لذلك يصعب صدّه.","90":"K-8c. يصعد ملك الغوتي. وبتقدمه يقترب أيضًا من حصاني السِّنتي.","91":"Nx9b+. يأسر حصان 8d الرمح ويترقّى، فصار يتحرك مثل الذهب. دخل السِّنتي منطقة ملك الغوتي.","92":"Kx9b. يأسر الغوتي الحصان المترقّي بالملك. صار ملك الغوتي على الحافة في 9b.","93":"Bx7g. يأسر فيل السِّنتي البيدق في 7g. لم يتحرك هذا الفيل طوال المباراة، لكنه الآن يبدأ العمل. وسيكون له دور كبير لاحقًا.","94":"Sx6i+. تأسر فضة الغوتي رخ السِّنتي وتترقّى. خسارة الرخ كبيرة، لكن السِّنتي يرى أن هجومه على الملك أسرع.","95":"Gx6i. يستردّ السِّنتي الفضة المترقّية بالذهب. ذهب السِّنتي المدافع ما زال ثابتًا.","97":"P*9c، كِش. البيدق رخيص، لكنه إذا أُسقط أمام الملك مباشرة صار قويًا جدًا.","98":"K-8a. يتراجع ملك الغوتي إلى 8a. طرق هروبه تقلّ شيئًا فشيئًا.","99":"Bx8f. يأسر الفيل البيدق في 8f. وعبر قطره يرى الآن عمق معسكر الغوتي. إنه يستعدّ للنقلة الكبيرة التالية.","101":"G*9b، كِش. يعمل الذهب في 9b والبيدق في 9c معًا لطرد ملك الغوتي من الحافة.","103":"B-5c+. يطير فيل 8f حتى 5c ويترقّى إلى «حصان التنين». يتحرك مثل الفيل ومعها خطوة واحدة في أي اتجاه: قطعة قوية جدًا. دخلت قطعة السِّنتي الكبيرة قرب ملك الغوتي.","104":"K-6a. يواصل ملك الغوتي الهروب نحو العمود 6. إنه يُدفع من الحافة نحو وسط الرقعة.","105":"L*6d. يُسقط السِّنتي رمحًا. يتحرك الرمح إلى الأمام مستقيمًا مهما شاء، فيراقب العمود 6 كله.","106":"P*6b. يُسقط الغوتي بيدقًا ليسدّ طريق الرمح.","107":"+Bx4c. يأسر حصان التنين الفضة في 4c. يخسر الغوتي مدافعًا آخر.","108":"N*5b. يُسقط الغوتي حصانًا ليقوّي دفاعه. الوضع صعب، لكن الغوتي يواصل القتال.","109":"K-8g. هنا يرفع السِّنتي ملكه مرة إلى 8g. يبدو أنه يعطي الملك مساحة أكبر قبل أن يردّ الغوتي.","110":"R*8i، كِش. يردّ الغوتي بإسقاط رخ مع كِش. الغوتي أيضًا يحاول الإمساك بملك السِّنتي.","112":"P-7g+، كِش. يترقّى البيدق إلى «توكين» ويعطي كِشًا. التوكين يتحرك مثل الذهب، لكن إن أُسر لا يحصل الخصم إلا على بيدق.","114":"Rx6i+. يأسر الرخ الذهب ويصير تنينًا. فقد ملك السِّنتي مدافعيه، وصارت المباراة سباقًا: من يمسك ملك الآخر أولًا؟","115":"S*5c. يُسقط السِّنتي فضة ليضيّق الشبكة حول ملك الغوتي. الضغط على ملك الخصم حتى وملكك في خطر هو جوهر مثل هذا السباق.","116":"S*6f، كِش. يُسقط الغوتي فضة ويعطي كِشًا. على ملك السِّنتي أن يهرب.","117":"K-8f. يهرب الملك إلى 8f. لملك السِّنتي مساحة واسعة إلى الأعلى.","119":"K-9e. يواصل الملك حتى 9e على الحافة. هنا تكاد قطع الغوتي لا تصل إليه. صار ملك السِّنتي آمنًا مؤقتًا، فيستطيع التركيز على الهجوم.","120":"P-6c. يدفع الغوتي بيدقًا للدفاع. لكن دفاع الغوتي لم يعد كافيًا.","121":"S*6b. هنا يبدأ السِّنتي الإنهاء. يُسقط فضة داخل معسكر الغوتي ليأسر القطع التي تحرس الملك.","122":"Bx6b. يأسر الغوتي الفضة بالفيل.","123":"Sx6b+. تأسر فضة 5c الفيل وتترقّى. يخسر الغوتي قطعة كبيرة.","125":"Nx6b+. ويأسر حصان 7d الذهب ويترقّى أيضًا. قطعةً بقطعة، يُعرّي السِّنتي دفاع الغوتي.","126":"Kx6b. يأسر الغوتي بالملك. لكن لم يبقَ تقريبًا أي مدافع حول ملك الغوتي.","127":"B*5c، كِش. يُسقط السِّنتي الفيل الذي أسره للتو. استعمال القطع المأسورة فورًا هو ما يجعل الشوغي مثيرًا جدًا.","129":"G*8d، كِش. يغلق الذهب طريق هروب الملك من الأعلى.","131":"P*7c، كِش. لا خيار لملك الغوتي إلا أن يعود إلى الخلف.","133":"Lx6c+. يأسر الرمح البيدق في 6c ويترقّى. رأى سانسا أنه إذا دخلت قطعة إلى 6b في النقلة التالية فلن يبقى للملك مهرب، فاستسلم هنا. يفوز سوكي في 133 نقلة. أبرز ما فيها: «مطاردة الرخّين» في الافتتاح، وشدّ الحبل بالبيادق والأحصنة في الوسط، والنهاية التي ضحّى فيها السِّنتي برخه ليسابق نحو الملك. تُظهر هذه المباراة كيف ترتبط أفكار أستاذ عاش قبل 400 سنة بشوغي اليوم."}},"hu1960":{"t":"هو رونغهوا ابن الخامسة عشرة يهزم يانغ غوانلين","w":"يانغ غوانلين","b":"هو رونغهوا","ev":"البطولة الوطنية الفردية الخامسة للشيانغتشي، الجولة 3","d":"28 أكتوبر 1960","pl":"بكين","lead":"كان يانغ غوانلين قد فاز بالبطولة الوطنية ثلاث مرات. وأمامه بالقطع السوداء جلس هو رونغهوا، ابن الخامسة عشرة، في أول بطولة وطنية له. تخلّى هو عن مدفع مبكرًا ليمسك بزمام المبادرة، ثم فاز في نهاية طويلة. وفاز هو بالبطولة ثم بعشرة ألقاب وطنية متتالية، لذلك تُذكر هذه المباراة على أنها لحظة انتقال التاج من البطل القديم إلى الجديد.","c":{"0":"هذه الجولة 3 من البطولة الوطنية الفردية الخامسة للشيانغتشي في بكين سنة 1960. يلعب بالأحمر يانغ غوانلين، الفائز بالبطولة الأولى سنة 1956 وبثلاث من البطولات الأربع التي أُقيمت حتى ذلك الحين — أقوى لاعب في زمنه. ويلعب بالأسود هو رونغهوا من شنغهاي، عمره 15 عامًا فقط، وهذه أول بطولة وطنية له. توقّع الجميع فوز الأحمر، لكن هذه المباراة ستغيّر تاريخ الشيانغتشي. في عام 1960 كانت الصين تمرّ بأوقات صعبة جدًا: فبعد السياسة المعروفة بـ\"القفزة الكبرى إلى الأمام\" لم يكن الطعام كافيًا. ويُروى أن البطولة الوطنية الفردية لم تُقم بسبب ذلك في العام التالي (1961). وكانت البطولة الوطنية الفردية للشيانغتشي نفسها جديدة، إذ بدأت قبل أربع سنوات فقط، عام 1956.","1":"ينقل يانغ المدفع الأيمن إلى الوسط. المدفع المركزي يصوّب مباشرة على الجنرال الأسود، وكانت هذه الافتتاحية التي درسها يانغ أعمق دراسة. كان المدفع الأوسط بطل كتاب \"جو تشونغ مي\" قبل أكثر من 300 عام؛ إنه أقدم بداية هجومية في شيانغتشي. وكان يانغ غوانلين لاعبًا زاده حدّةً بالدراسة الحديثة.","2":"يُخرج هو حصانًا ليحمي الجندي الأوسط. إخراج الحصان مبكرًا يهيّئ للدفاع والهجوم معًا. وُلد هو رونغهوا في شنغهاي عام 1945. تعلّم الشيانغتشي من أبيه، وصقل لعبه أمام الكبار عند أكشاك الشيانغتشي في الشوارع. ويُروى أن عائلته كانت فقيرة إلى حدّ أنها لم تستطع شراء قطع خشبية، فكان يلعب بقطع من الورق. انضم إلى فريق شنغهاي عام 1959، ويُقال إنه خسر في البداية أكثر من مئة مباراة متتالية.","3":"يُخرج الأحمر أيضًا حصانًا، فيحمي الجندي الأوسط وهو يقدّم قطعه. يؤمّن الطرفان الوسط أولًا.","4":"يقدّم الأسود مبكرًا جندي العمود 7. يكبح الحصان الأحمر ويفتح طريقًا لحصانه. في هذا الوضع يُخرج معظم اللاعبين عربة أولًا.","5":"ينقل الأحمر العربة اليمنى خطوة إلى الجانب نحو عمود مفتوح.","6":"يُخرج الأسود أيضًا عربة إلى الجانب. يريد الطرفان تشغيل أقوى قطعة، العربة، مبكرًا.","7":"هنا يقدّم الأحمر جنديًا. كثيرون كانوا سيرسلون العربة إلى ما وراء النهر، لكن يانغ يقود اللعب نحو ترتيب المدافع الذي يحبه.","8":"يتقدّم المدفع الأسود حتى النهر ويقف أمام العربة اليمنى الحمراء مباشرة. هذه الخطة، «المدفع الأيسر يحبس العربة»، تُبقي العربة محبوسة في البيت. كانت فكرة جريئة لمنع يانغ من الوصول إلى ترتيبه المفضّل. حبس العربة في جهة المدفع الأوسط بمدفع يقف عند النهر من أفكار الأسود لمواجهة المدفع الأوسط. ومنذ زمن الكتب القديمة دُرست هجمات الأحمر ودفاعات الأسود هكذا، شيئًا فشيئًا.","9":"يُخرج الأحمر الحصان الآخر، فيطوّر الجناح الأيسر ويستعد للرد.","10":"يرفع الأسود فيلًا ليقوّي الدفاع. الأفيال لا تعبر النهر؛ مهمتها حراسة بيت الجنرال.","11":"يندفع المدفع الأحمر إلى عمق معسكر الأسود، يأخذ حصانًا ويكشّ! إنها مبادلة مدفع بحصان. فعل ذلك مبكرًا هكذا يكلّف وقتًا غالبًا، لكن يُقال إنها هنا نقلة مقبولة.","12":"يستعيد الأسود المدفع بالعربة. صارت القطع متعادلة من جديد، وخرجت العربة السوداء بشكل طبيعي.","13":"يُخرج الأحمر العربة اليسرى أيضًا. يريد طرد المدافع السوداء وتحريك عرباته.","14":"يقدّم الأسود المدفع الآخر أيضًا حتى النهر، فيحبس العربة اليسرى الحمراء. الآن أمام كل عربة حمراء مدفع. بدأ الأحمر يضيق.","15":"يأخذ الأحمر الحصان نحو النهر. في ذهنه تهديدان: أخذ الجندي الأوسط بالحصان، أو تقديم جندي لمهاجمة المدفع الأسود.","16":"يرفع الأسود مستشارًا ليحرس الوسط. وبهذا يمنع الحصان من أخذ الجندي الأوسط مع كِش.","17":"يقدّم الأحمر الجندي. فينفتح الطريق الذي كان الجندي يسدّه، والآن يستطيع الحصان الأحمر أخذ المدفع الأسود. المدفع مهدَّد.","18":"هذه أشهر لحظة في المباراة. لا ينقذ الأسود المدفع، بل يقدّم العربة ليهاجم الحصان الأحمر. يتخلّى هو عن مدفع ليحافظ على شكل هجومه. كان خصمه بطلًا ثلاث مرات وهو في الخامسة عشرة، ومع ذلك اختار الاندفاع على حساب القطع — فدُهش المتفرجون.","19":"يأخذ الحصان الأحمر المدفع الأسود. صار الأسود ناقصًا قطعة. وفي المقابل تضغط العربة السوداء من الجانب على العربة والحصان الأحمرين.","20":"يأخذ المدفع الأسود الآخر الجندي الأوسط — كِش! يبدأ الهجوم المضاد للأسود. على الأحمر أن يرفع مستشارًا ليحمي الجنرال.","21":"يرفع الأحمر مستشارًا ليسدّ الكِش. لكن المدفع الأسود ما زال مغروسًا في عمق معسكر الأحمر.","22":"تأخذ العربة السوداء العربة الحمراء. عندما ابتعد المدفع قبل قليل انفتح طريق العربة.","23":"يستعيد الأحمر بالحصان — عربة مقابل عربة. ما زال الأسود ناقصًا قطعة، لكن قطعه تعمل بشكل أفضل.","24":"يتقدّم الحصان الأسود حتى النهر. ومن الأفكار مطاردة الحصان الأحمر بعد ذلك.","26":"ينزلق المدفع الأسود ويقف ملاصقًا للحصان الأحمر. حصان الشيانغتشي لا يستطيع التحرّك في اتجاه إذا كانت قطعة ملاصقة له من تلك الجهة («ساق» الحصان). ومع ساق مسدودة بالمدفع يكاد الحصان الأحمر لا يتحرك.","28":"يقدّم الأسود الجندي الأوسط. لاحقًا سيصبح هذا الجندي مهاجمًا مهمًا في معسكر الأحمر.","30":"يأخذ الحصان الأسود جنديًا ويتسلّل إلى معسكر الأحمر. شيئًا فشيئًا يستعيد الأسود ما خسره.","32":"يعود الحصان الأسود إلى الوسط. يتجنّب المبادلة مع الحصان الأحمر ويحتل نقطة وسطى جيدة.","34":"يتراجع المدفع الأسود نقطة واحدة. يستعد للانزلاق ومهاجمة الحصان الأحمر.","36":"ينزلق المدفع الأسود، ومستخدمًا عربته حاجزًا، يهاجم الحصان الأحمر. المدفع يأخذ بالقفز فوق قطعة واحدة بالضبط.","38":"يقفز الحصان الأسود ويهاجم العربة الحمراء. وبابتعاده يزيل أيضًا الحاجز الذي كان المدفع الأحمر يحتاجه لمهاجمة العربة السوداء.","40":"كشّ المدفع الأحمر، فأنزل الأسود المستشار ليسدّ. الأحمر يقاوم بقوة.","42":"يأخذ المدفع الأسود الحصان الأحمر! يستعيد الأسود المدفع الذي تخلّى عنه في الافتتاح. القطع متعادلة، وللأسود جندي زائد، وكل قطع هجومه الثلاث عبرت النهر. الأسود أفضل بوضوح.","44":"يقدّم الأسود جنديًا ويعرضه مجانًا. إذا أخذه الأحمر صارت خطة خفية ممكنة — نقلة تنظر بعيدًا.","45":"يأخذ الأحمر الجندي بفيل. الآن على الأحمر أن يحذر خطة الأسود.","46":"يعرض الأسود الحصان أيضًا. إذا أخذه الحصان الأحمر، يستطيع المدفع الأسود أن يكشّ ويكشف في الوقت نفسه هجومًا على العربة الحمراء.","47":"لا يأخذ الأحمر الحصان، بل يعيد حصانه إلى الوراء. البطل القديم يانغ لا يقع في الفخاخ بسهولة.","48":"تنزلق العربة السوداء جانبًا وتتحرّر من التثبيت. الآن تستطيع العربة التحرك بحرية من جديد، للهجوم أو للدفاع.","50":"يدخل المدفع الأسود إلى الوسط ويحدّق مباشرة في الجنرال الأحمر — موقع قوي جدًا.","52":"يقفز الحصان الأسود إلى الأمام مجددًا. المدفع والحصان يعملان معًا في الوسط.","56":"يذهب الحصان الأسود حتى الحافة ويصوّب على جانب الجنرال الأحمر. للحصان على الحافة نقلات أقل، لكن مهمته هنا مهمة: تهديد ملجأ الجنرال.","58":"يتقدّم الجندي الأوسط الأسود أكثر ويضغط على معسكر الأحمر. بعد عبور النهر يستطيع الجندي التحرك جانبًا أيضًا، فيصبح أقوى بكثير.","60":"تتبادل المدافع. أخذ المدفع الأحمر المدفع الأسود، ثم استعاد الجندي الأسود المدفع الأحمر. صار الجندي الأسود قريبًا من معسكر الأحمر.","62":"تأخذ العربة السوداء أحد الفيلين الأحمرين. يفقد دفاع الأحمر قطعة أخرى.","64":"يكشّ الحصان الأسود! يسدّ الأحمر ساق الحصان بالعربة. في الشيانغتشي يمكن إيقاف كِش الحصان بوضع قطعة ملاصقة له.","66":"يتراجع الحصان الأسود مؤقتًا. يواصل الكِش وهو يبحث عن أفضل مربع له.","70":"يكشّ الحصان الأسود مرة أخرى. لا تستطيع العربة الحمراء مغادرة جانب الجنرال، فلا تشارك في الهجوم.","72":"يعود الحصان الأسود إلى الحافة. يُبقي العربة الحمراء مقيّدة بينما يخطط الأسود للخطوة التالية.","76":"تأخذ العربة السوداء الفيل الأحمر الآخر أيضًا. صار الجنرال الأحمر وحيدًا جدًا.","82":"تأخذ العربة السوداء الحصان الأحمر. يُبادَل هنا الحصان الأحمر الذي قاتل بجد.","83":"يستعيد الأحمر الحصان الأسود بالعربة. بعد تبادل الحصانين صارت الرقعة أوضح بكثير. الآن المعركة بين العربة والجنود في الجانبين.","90":"يأخذ الجندي الأسود أحد المستشارين الحمر! الجندي قطعة صغيرة، لكنه في عمق معسكر الخصم يصبح قويًا بما يكفي ليُبادل بمستشار.","91":"يستعيد الأحمر الجندي بالمستشار الآخر. جندي مقابل مستشار — صار الجنرال الأحمر أقل حماية.","92":"تأخذ العربة السوداء جنديًا أحمر. في النهاية يحدّد عدد الجنود الباقين من يفوز.","98":"تأخذ العربة السوداء جنديًا آخر. لم يبقَ للأحمر إلا قليل من الجنود. خطوة بخطوة يتجه الأسود نحو وضع أسهل للفوز.","99":"تأخذ العربة الحمراء في المقابل فيلًا أسود. العربتان تتبادلان الضربات، قطعة لكل منهما.","104":"يبدأ الأسود بدفع الجندي الذي على الحافة. إيصال هذا الجندي إلى عمق معسكر الأحمر هو طريق الأسود إلى الفوز.","112":"تقف العربة السوداء خلف الجندي لتحميه. العربة والجندي معًا فريق قوي جدًا.","115":"تأخذ العربة الحمراء أحد الجنود السود. بقي للأسود جندي واحد. والأحمر لم يستسلم بعد.","123":"يقدّم الأحمر الجندي. لكن يُقال إن سحب العربة لحماية الجنرال كان أفضل هنا. صارت هذه النقلة نقطة التحول في المباراة.","124":"يتحرك الجندي الأسود جانبًا نحو الجنرال الأحمر. يتقدّم الجندي خطوة واحدة فقط كل مرة، لكنه كلما اقترب من الجنرال صار أخطر.","126":"تتراجع العربة السوداء وتهاجم الجندي الأحمر. على الأسود مراقبة ذلك الجندي، وإلا استطاع الأحمر أن يرد به.","134":"وصل الجندي الأحمر إلى آخر الرقعة، لكن العربة السوداء طاردته طوال الطريق. الجندي الذي يبلغ النهاية لا يستطيع التقدّم بعد ذلك، بل يتحرك جانبًا فقط.","136":"تأخذ العربة السوداء آخر جندي أحمر. للأسود عربة وجندي ومستشاران، وللأحمر عربة ومستشار واحد. وبجندي زائد صار فوز الأسود واضحًا.","140":"تكشّ العربة السوداء! لا يستطيع الجنرال الأحمر إلا التراجع.","144":"يتقدّم الجندي الأسود مرة أخرى وصار الآن بجوار الجنرال الأحمر مباشرة. مع تعاون الجندي والعربة لم يعد الجنرال الأحمر في أمان.","148":"يتحرك الجنرال الأسود أيضًا جانبًا. في النهاية يكون الجنرال قطعة مقاتلة أيضًا، تتحكّم في المكان الذي تستطيع قطع الخصم الذهاب إليه.","150":"تتراجع العربة السوداء، مستعدة للدفاع والهجوم معًا. إنها تجهّز العربة لأفضل مربع للضربة الأخيرة.","152":"تدخل العربة السوداء العمود 4، ولا يعود الأحمر قادرًا على الصمود. حُسمت المباراة: فاز هو رونغهوا ابن الخامسة عشرة. تضحية جريئة بمدفع في الافتتاح، وتعاون الحصان والمدفع في وسط اللعب، ولعب دقيق في نهاية طويلة — كانت في هذه المباراة الثلاثة كلها. فاز هو بالبطولة وصار بطلًا وطنيًا عشر مرات متتالية من 1960 إلى 1979."}},"soei1790":{"t":"سوئي الشيطان يهزم الميجين بلا أفضلية","w":"أوهاشي سوئي (السادس)","b":"أوهاشي سوكي (التاسع)","ev":"أوشيرو شوغي (المباراة السنوية في قلعة إيدو)","d":"1790","pl":"اليابان (إيدو)","lead":"لعب أوهاشي سوئي، الملقّب بـ«سوئي الشيطان»، هذه المباراة بلا أفضلية ضد ميجين ذلك الزمان أوهاشي سوكي التاسع في مباريات القلعة. في تلك السنة كانا يتناوبان بين مباريات بلا أفضلية ومباريات بأفضلية الرمح، وتُذكر هذه المباراة تحفةً نادرة. فاز سوئي في 121 نقلة.","c":{"0":"أنا Musowl. كانت مباريات القلعة (أوشيرو شوغي) حدثًا سنويًا كبيرًا تلعب فيه بيوت الشوغي أمام الشوغون. السِّنتي أوهاشي سوئي كان قويًا جدًا حتى لُقّب «سوئي الشيطان»، وصار لاحقًا الميجين التاسع. والغوتي أوهاشي سوكي التاسع كان قد صار ميجين قبل سنة واحدة فقط. إنها مباراة الميجين ضد الميجين القادم. نشر سوئي فكرة بناء دفاع متين أولًا ثم الهجوم، وهي قريبة جدًا من شوغي اليوم، ولذلك يُسمّى أبا الشوغي الحديث. كان عام 1790 هو الزمن الذي كان فيه ماتسوديرا سادانوبو، كبير وزراء الشوغون توكوغاوا إييناري، ينفّذ \"إصلاحات كانسي\". طُلب من الناس ترك الإسراف، وفي ذلك العام شُدّدت أيضًا قواعد نشر الكتب. ومع ذلك استمرت مباريات القلعة. ويُقال إن الشوغون الثامن يوشيمونه هو من حدّد يوم شوغي القلعة في 17 نوفمبر، ومنه جاء \"يوم الشوغي\" في اليابان اليوم.","1":"P-7f. تفتح النقلة الأولى قطر الفيل. من هنا يبني سوئي خطة للهجوم بقطع الجانب الأيمن. وُلد سوئي عام 1756 ابنًا لسوجون، الرئيس الخامس للفرع الثاني من بيت أوهاشي. أُرسل وهو صغير ليعيش عند عائلة أخرى، لكن يُروى أنه أُعيد إلى البيت حين عُرف أنه أستاذ بالفطرة، فورث البيت.","3":"P-2f. يدفع السِّنتي البيدق الذي أمام الرخ. دفع هذا البيدق مبكرًا للضغط على الخصم من الأفكار التي كان سوئي يقدّرها.","4":"P-4d. يدفع الغوتي بيدقًا يغلق قطر فيله. يتجنب تبادل الفيلين ويستعدّ لمباراة هادئة. وُلد غوتي، سوكي التاسع، عام 1744. لعب في القلعة أول مرة في الثانية عشرة، ويُقال إنه هزم عمّه إيتو كانجو. وفي العام السابق لهذه المباراة (1789)، وفي السادسة والأربعين، تسلّم لقب ميجين الذي ظل شاغرًا 27 عامًا.","5":"S-4h. يرفع السِّنتي الفضة اليمنى ليستعملها في الهجوم والدفاع.","7":"P-5f. يدفع السِّنتي بيدق الوسط ليسهل خروج الفضة والذهب.","9":"P-3f. يدفع السِّنتي بيدق العمود 3 أيضًا ليفتح طريق قفزة الحصان. إنه يستعدّ لـ N-3g.","11":"P-2e. يدفع السِّنتي بيدق الرخ أكثر. الآن يجب على الغوتي حماية العمود 2 بالفيل أو بفضة. دفع الجندي الذي أمام الرخ ومبادلته بجندي الخصم يُسمّى \"مبادلة جندي الرخ\". ويُقال إن سوئي أظهر بوضوح أن هذه المبادلة مفيدة. وما زالت حتى اليوم أبسط فكرة في افتتاحيات الرخ الثابت.","12":"B-3c. يحمي الغوتي العمود 2 بالفيل. وإلا لاخترق رخ السِّنتي العمود 2 بعد P-2d.","15":"G-5h. يقرّب السِّنتي ذهبًا من الملك ويبدأ ببناء دفاعه.","17":"N-3g. يقفز الحصان إلى الأعلى ويكتمل شكل هجوم السِّنتي. من هنا يستطيع القفز إلى 4e أو 2e ليصل إلى معسكر الغوتي. ويُعرف سوئي أيضًا بأنه فاز في شبابه (عام 1779) بخطة جديدة اسمها \"صائد الطيور\". لم يكن يتقيد بالأشكال الثابتة، بل كان يحب ابتكار طرق جديدة للعب.","20":"R-5b. ينقل الغوتي رخه إلى عمود الوسط 5. يُسمّى هذا اليوم «الرخ الأوسط». الهدف هزّ معسكر السِّنتي من الوسط. صارت المباراة الآن \"متقابلة\": سينتي بالرخ الثابت ضد غوتي بالرخ المنقول (رخ الوسط). ويُروى أن سوكي التاسع كان يجرّب كثيرًا خططًا جديدة مثل الرخ المنقول. وما زال رخ الوسط محبوبًا اليوم، ويُلعب بأسماء مثل \"رخ الوسط المرح\".","22":"P-5e. يدفع الغوتي فورًا بيدق العمود 5 نحو بيدق السِّنتي. وكما يحب الرخ الأوسط، يبدأ القتال في الوسط. وضع الرخ في الوسط ودفع جندي العمود 5 فورًا هو الحركة الأساسية لرخ الوسط. إنها طريقة هجوم مباشرة ما زالت حيّة في رخ الوسط اليوم.","23":"Px5e. يأسر السِّنتي البيدق. وإلا لأسر بيدق الغوتي البيدق في 5f.","24":"S-6d. يقدّم الغوتي فضة ليستعيد البيدق في 5e.","25":"P-5d. يدفع السِّنتي البيدق المأسور أبعد. وضعه أمام رخ الغوتي مباشرة يجبره على أسره، فتبتعد قطع الغوتي عن أفضل مربعاتها.","26":"Rx5d. يأسر الغوتي البيدق بالرخ، الذي خرج إلى 5d وصار قويًا في الوسط.","27":"B-7i. يسحب السِّنتي فيله إلى الخلف. بعد تراجعه مرة يستطيع لاحقًا العمل على قطر آخر. سيخرج هذا الفيل لاحقًا إلى 2d.","28":"K-4a. يضع الغوتي ملكه في 4a. مع الرخ الأوسط يختبئ الملك عادةً في اليمين.","29":"P*5f. يُسقط السِّنتي بيدقًا كي لا يتقدم رخ الغوتي في العمود 5.","30":"P*5e. يُسقط الغوتي بيدقًا أيضًا ويصطدم مجددًا في العمود 5. يستمر شدّ الحبل في الوسط.","32":"Px5f. يأسر بيدق الغوتي بيدق السِّنتي ويعضّ داخل معسكره.","34":"S-5e. يُخرج الغوتي الفضة ليسيطر على العمود 5.","35":"Gx5e. يأسر السِّنتي الفضة بالذهب. سيتبادل الطرفان الذهب والفضة.","36":"Rx5e. يستردّ الغوتي الذهب بالرخ. بعد تبادل الذهب بالفضة يهدأ القتال في الوسط. صار في يد السِّنتي فضة، وفي يد الغوتي ذهب.","37":"P*5f. يُسقط السِّنتي بيدقًا ليغلق العمود 5، فلا يعود رخ الغوتي قادرًا على الدخول.","38":"R-5b. يسحب الغوتي رخه. انتهى قتال الوسط مؤقتًا.","39":"G-5h. يرفع السِّنتي ذهبه الآخر ويقوّي ما حول الملك.","41":"K-6i. يبدأ ملك السِّنتي بالتحرك إلى اليسار، بعيدًا عن الوسط حيث دار القتال.","43":"K-7h. يصل الملك إلى 7h. من هنا سيبني السِّنتي قلعة من الذهب والفضة. كان سوئي يؤمن بالدفاع أولًا ثم الهجوم.","44":"R-8b. يعيد الغوتي رخه إلى العمود 8. بما أن الوسط هدأ، يريد الآن الهجوم من العمود 8.","45":"S*7g. يُسقط السِّنتي الفضة التي في يده أمام الملك. يستعدّ مسبقًا لهجوم الغوتي من العمود 8.","47":"P-1f. يدفع السِّنتي بيدق الحافة. بيدق الحافة المتقدم يفيد لاحقًا في هجوم من الحافة أو كطريق هروب للملك.","49":"P-1e. يتقدم بيدق الحافة خطوة أخرى. السِّنتي يستعدّ بعناية.","51":"P-2d. هنا يبدأ السِّنتي هجومه، فيصادم ببيدق الرخ الذي ظل يدفعه منذ البداية. يبدأ هجوم السِّنتي.","53":"Bx2d. يطير الفيل الذي تراجع إلى 7i على القطر حتى 2d. الآن نفهم لماذا سحبه السِّنتي في النقلة 27.","54":"Bx2d. يأسر الغوتي الفيل بفيله. تبادل الطرفان الفيلين.","55":"Rx2d. يستردّ السِّنتي بالرخ، الذي يراقب من 2d معسكر الغوتي. صار لكل طرف فيل في يده.","56":"P*2c. يُسقط الغوتي بيدقًا ليسدّ طريق الرخ.","57":"R-2f. يسحب السِّنتي رخه. لا يتوغل كثيرًا ويعيد الرخ إلى مكان آمن.","59":"P-4f. يدفع السِّنتي بيدق العمود 4 استعدادًا للهجوم التالي. بعد العمود 2 تقضي الخطة بالهجوم من العمودين 3 و4.","60":"R-8d. يرفع الغوتي رخه ليستطيع استعماله جانبيًا أيضًا.","61":"P-3e. يدفع السِّنتي بيدق العمود 3 ليصطدم ببيدق الغوتي في 3d.","63":"P-4e. يصادم السِّنتي ببيدق العمود 4. إنه يهزّ الغوتي في عدة أعمدة معًا: 3 و4 و5.","65":"P-5e. يقدّم السِّنتي بيدق العمود 5 أيضًا، فيدقّ إسفينًا في وسط دفاع الغوتي.","66":"P*5c. يُسقط الغوتي بيدقًا ليحمي العمود 5.","67":"Px3d. يأسر بيدق السِّنتي البيدق في 3d. لاحقًا سيصل إلى 3c ويترقّى ليضغط على ملك الغوتي.","68":"P-8f. يردّ الغوتي ويدفع بيدق العمود 8 ليشعل النار قرب ملك السِّنتي.","69":"Sx8f. يأسر السِّنتي بالفضة. تتقدم فضة 7g وتدافع دون أن تهمل الملك.","70":"B*4d. يُسقط الغوتي الفيل الذي في يده. عبر أقطاره يراقب معسكر السِّنتي، مستعدًا للدفاع والهجوم.","71":"R-2i. يسحب السِّنتي الرخ حتى الأسفل. يبتعد عن خط الفيل ويظل يراقب العمود 2.","72":"P-6e. يدفع الغوتي بيدق العمود 6 ليهزّ ما حول ملك السِّنتي.","74":"P*3f. يُسقط الغوتي بيدقًا يهاجم الحصان في 3g.","75":"B*6f. يُسقط السِّنتي فيله. عبر القطر يهاجم الرخ في 8d. يدافع ويهاجم قطعة كبيرة في آن واحد: عصفوران بحجر واحد.","76":"R-8a. يُنقذ الغوتي رخه. بنقلة فيل واحدة أعاد السِّنتي رخ الغوتي إلى الأسفل.","77":"Nx4e. يقفز الحصان ويأسر البيدق في 4e. بعدها يريد القفز إلى 3c أو 5c.","78":"G*4f. يُسقط الغوتي ذهبًا يضغط على الحصان من الخلف.","79":"P-3c+. يتقدم بيدق 3d إلى 3c ويترقّى إلى توكين. دخلت قطعة للسِّنتي قرب ملك الغوتي.","80":"Nx3c. يأسر الغوتي التوكين بحصانه.","81":"Nx3c+. يأسر حصان السِّنتي في 4e ذلك الحصان ويترقّى. قطعةً بقطعة، يقلّل السِّنتي مدافعي ملك الغوتي.","82":"Bx3c. يستردّ الغوتي الحصان المترقّي بالفيل.","83":"S-5g. يرفع السِّنتي الفضة إلى 5g لتصطدم بذهب الغوتي في 4f وتطرد الذهب الذي اقترب.","85":"Gx5g. تبادل الطرفان الفضة والذهب. نظّف السِّنتي معسكره من قطعة الغوتي التي دخلته.","86":"P-7e. يدفع الغوتي بيدق العمود 7 مستهدفًا رأس ملك السِّنتي.","87":"N*4e. يُسقط السِّنتي حصانًا مرة أخرى. هذا الحصان يهاجم الفيل في 3c.","88":"B-2d. يُبعد الغوتي فيله إلى 2d.","89":"P*3c. يُسقط السِّنتي بيدقًا ليدقّ إسفينًا قرب ملك الغوتي.","90":"G-2b. يسحب الغوتي الذهب للدفاع.","91":"P-5d. يدفع السِّنتي بيدق العمود 5 أكثر ويستدرج فضة الغوتي إلى 5d.","92":"Sx5d. يأسر الغوتي البيدق بالفضة. لكن بذلك يفرغ المربع 4c، وهذا يرتبط بنقلات السِّنتي التالية.","93":"Rx2d. هذه نقطة التحول. يأسر السِّنتي فيل الغوتي بالرخ. حتى لو خسر الرخ، يقدّر أنه يستطيع في الأثناء الانقضاض على ملك الغوتي.","94":"Px2d. يأسر الغوتي الرخ ببيدق. أعطى السِّنتي رخه، لكنه كسب فيلًا، قطعة هجومية، في يده.","95":"B*3b، كِش. يُسقط السِّنتي الفيل. بعد Rx2d هذه هي البداية الحقيقية لهجوم السِّنتي.","96":"K-5a. يهرب ملك الغوتي إلى 5a.","97":"Bx5d+. يأسر الفيل الفضة في 5d ويترقّى إلى حصان التنين. ولأن 4c كان فارغًا، وصل الفيل مباشرة على القطر. المربع الذي أفرغته Sx5d في النقلة 92 أثمر هنا.","98":"Px5d. يأسر الغوتي حصان التنين ببيدق. أعطى السِّنتي كل قطعه الكبيرة، لكن فضة الغوتي المدافعة ذهبت أيضًا.","99":"P*5c. يُسقط السِّنتي بيدقًا أمام ملك الغوتي مباشرة كموطئ قدم. بعدها يريد الترقية في 5b.","100":"R*4h. يردّ الغوتي ويُسقط الرخ الذي كسبه في معسكر السِّنتي. تصير المباراة سباقًا: أيّ هجوم أسرع؟","101":"S-5h. يسحب السِّنتي الفضة للدفاع ويمنع الرخ من الانزلاق جانبيًا نحو الملك.","102":"B*5f، كِش. يُسقط الغوتي فيلًا. من 5f يصل قطريًا عبر 6g إلى الملك في 7h.","103":"K-8h. ينزل السِّنتي بملكه خطوة خارج خط الفيل. بهذه النقلة الدفاعية يضمن ألا يخسر السباق.","104":"Bx4e. يأسر فيل الغوتي الحصان.","105":"Px5b+. يترقّى البيدق إلى توكين ويأسر ذهب الغوتي. صارت قطعة للسِّنتي بجوار ملك الغوتي مباشرة.","106":"Kx5b. يأسر الغوتي التوكين بالملك.","107":"P*5c، كِش. يمكن إسقاط البيادق مرارًا، فيستطيع السِّنتي مواصلة الكِش هكذا (لكن لا يجوز وجود بيدقين غير مترقّيين لك في العمود نفسه).","108":"K-6b. يهرب ملك الغوتي إلى 6b.","109":"S*6d. يُسقط السِّنتي فضة ليغلق طرق هروب الملك.","110":"S*7d. يُسقط الغوتي فضة أيضًا للدفاع.","111":"P-5b+. يصنع السِّنتي توكين ويهاجم الملك من الخلف أيضًا.","112":"K-7b. يذهب ملك الغوتي إلى 7b. شيئًا فشيئًا يُدفع نحو الحافة.","113":"Sx7c+. تأسر الفضة الحصان في 7c وتترقّى. ذهب مدافع آخر للغوتي.","114":"Kx7c. يأسر الغوتي الفضة المترقّية بالملك.","115":"G*6d، كِش. من هنا يستعمل السِّنتي القطع التي في يده لاصطياد ملك الغوتي.","116":"K-8c. يذهب ملك الغوتي إلى 8c.","117":"Gx7d، كِش. يأسر الذهب الفضة في 7d مع كِش، وينزع مدافعي ملك الغوتي.","118":"Kx7d. يأسر الغوتي الذهب بالملك. سُحب الملك نحو وسط الرقعة.","119":"Sx7e، كِش. تأسر فضة 8f بيدقًا مع كِش. الفضة التي صعدت للدفاع في النقلة 69 تنضمّ إلى الهجوم في النهاية.","120":"K-6c. يهرب ملك الغوتي إلى 6c.","121":"S-6d، كِش. تنتقل فضة 7e إلى 6d مع كِش. ما زال في يد السِّنتي ذهب وفضة وحصان؛ وحين رأى سوكي أن الملك لا يستطيع الإفلات، استسلم هنا. يفوز سوئي في 121 نقلة. بعد قتال الوسط بنى السِّنتي أولًا قلعة متينة، ثم وسّع الهجوم إلى الأعمدة 2 و3 و4، وأخيرًا ضحّى برخه لينقضّ على الملك. إنها تحفة بين ميجينين تُظهر شوغي سوئي: «الدفاع أولًا ثم الهجوم»."}},"soho1856":{"t":"سوهو القدّيس وفيله البعيد النظر","w":"أمانو سوهو","b":"إيتو سوإين (الثامن)","ev":"أوشيرو شوغي (المباراة السنوية في قلعة إيدو)","d":"1856","pl":"اليابان (إيدو)","lead":"لعب أمانو سوهو، الملقّب بـ«قدّيس الشوغي»، مباراة القلعة هذه ضد إيتو سوإين الثامن الذي صار لاحقًا ميجين، وكانت آخر مباراة قلعة لسوهو. في النقلة 33 أسقط فيلًا في زاوية معسكره هو، B*1h، وهي نقلة يذكرها تاريخ الشوغي ضربةَ معلّم. يفوز سوهو في 111 نقلة.","c":{"0":"أنا Musowl. لعب أمانو سوهو في أواخر عصر إيدو، وكان قويًا جدًا حتى سُمّي «دان ثالث عشر حقيقي» و«قدّيس الشوغي». لكنه لم يولد في أحد بيوت الشوغي، فلم يستطع أن يصير ميجين أبدًا. أما الغوتي إيتو سوإين الثامن فكان أصغر من سوهو في المدرسة نفسها، وصار لاحقًا ميجين. كانت مباراة القلعة هذه عام 1856 آخر مباراة قلعة لعبها سوهو. يُقال إن سوهو كان أستاذًا في استعمال الفيل، فانتبه إلى الأفيال في هذه المباراة. كان عام 1856 بعد ثلاث سنوات من وصول \"السفن السوداء\" للعميد البحري بيري إلى اليابان. وفي ذلك العام وصل الأمريكي تاونسند هاريس إلى شيمودا، وافتُتحت في معبد اسمه غيوكوسينجي أول قنصلية أمريكية في اليابان. هذه مباراة القلعة من زمن اقتربت فيه نهاية عصر إيدو وبدأت البلاد تتغير بسرعة.","1":"P-7f. تفتح النقلة الأولى قطر الفيل. سيكون فيل سوهو نجم هذه المباراة. وُلد سوهو عام 1816، وكان يُنادى في حياته اليومية \"توميجيرو\". تعلّم الشوغي تلميذًا في البيت الرئيسي لأوهاشي، لكن رتبته لم تتجاوز الدان السابع. ويُروى أن الميجين الثالث عشر سيكيني كينجيرو كرّمه لاحقًا بلقب \"قدّيس الشوغي\". وتوفي سوهو عام 1859، بعد هذه المباراة بثلاث سنوات، في الرابعة والأربعين.","3":"P-2f. يدفع السِّنتي البيدق الذي أمام الرخ. كان سوهو يحب الافتتاحات السريعة، فيدفع بيدق الرخ مبكرًا ويحرّك قطعه.","4":"P-5d. يدفع الغوتي بيدق الوسط. تظهر خطة: سيذهب الرخ إلى العمود 5 رخًا أوسط. الرخ الثابت لسينتي ورخ الوسط لغوتي: إنها المباراة المتقابلة نفسها \"الرخ الثابت ضد رخ الوسط\" التي لعبها سوئي وسوكي التاسع قبل نحو 60 عامًا. وفي مباريات القلعة في عصر إيدو كان الرخ المنقول يُلعب كثيرًا أيضًا.","7":"S-4h. يرفع السِّنتي الفضة اليمنى استعدادًا للهجوم والدفاع.","11":"P-2e. يدفع السِّنتي بيدق الرخ أكثر. ينوي بعدها الاصطدام في 2d.","12":"S-6d. يقدّم الغوتي فضة. الفكرة دفعها نحو 5e والهجوم في الوسط.","13":"P-2d. يصدم السِّنتي ببيدقه بيدق الغوتي ليتبادل بيدق الرخ. إنها طريقة طبيعية لبدء القتال، وما زالت شائعة اليوم. مبادلة جندي الرخ هي الفكرة التي يُقال إن أوهاشي سوئي أثبت فائدتها قبل نحو 60 عامًا. وفي زمن سوهو صارت جزءًا عاديًا من لعب الرخ الثابت.","15":"Rx2d. يأسر الرخ البيدق. يكسب السِّنتي بيدقًا في يده ويتقدم الرخ. تبادل بيدق الرخ يعطيك بيدقًا إضافيًا في اليد ويجعل الرخ أسهل استعمالًا.","16":"R-5b. ينقل الغوتي رخه إلى العمود 5. بالرخ الأوسط ينوي الرد من الوسط.","17":"K-6i. ينقل السِّنتي ملكه إلى اليسار، بعيدًا عن الوسط حيث سيهاجم الرخ الأوسط.","19":"R-2h. يعود الرخ إلى بيته. بعد كسب بيدق، يسحبه السِّنتي بهدوء.","20":"P*2c. يُسقط الغوتي بيدقًا ليسدّ الثغرة في العمود 2.","21":"Bx2b+. هنا يتبادل السِّنتي الفيلين. بعد التبادل يكون لكل طرف فيل في يده يستطيع إسقاطه في أي مكان. ومن الآن يُظهر سوهو براعته في اختيار مكان إسقاط فيله. كان تبادل الفيلين مبكرًا والاحتفاظ بواحد في اليد ثم التنافس على مكان إسقاطه أحبّ طرق اللعب إلى سوهو. فالفيل الذي في اليد يمكن إسقاطه في أي مربع، فيصير قويًا جدًا إذا أُحسن استعماله.","22":"Sx2b. يستردّ الغوتي بالفضة. صار لكل طرف فيل في يده.","24":"P-5e. يصدم الغوتي ببيدق الوسط بيدق السِّنتي. إنه هجوم نموذجي للرخ الأوسط.","26":"Sx5e. تصل فضة الغوتي حتى 5e. قطع الغوتي تزداد قوة في الوسط.","27":"P*5d. يُسقط السِّنتي بيدقًا داخل معسكر الغوتي. البيدق في 5d يسدّ ما أمام رخ الغوتي ويعرقل قطعه.","29":"B*5c. يُسقط السِّنتي فيله داخل معسكر الغوتي. الفكرة أن يعيث فسادًا داخل موقع الغوتي.","30":"B*4d. يُسقط الغوتي فيله أيضًا ويصدم به فيل السِّنتي. إنها نقلة دفاعية للتخلص من فيل السِّنتي.","31":"Bx4d+. يأسر فيل السِّنتي فيل الغوتي ويترقّى.","32":"Sx4d. يستردّ الغوتي حصان التنين بالفضة. تبادل الطرفان الفيلين مرة أخرى، وعاد في يد السِّنتي فيل.","33":"B*1h. هذه هي اللحظة الشهيرة. يُسقط سوهو فيله في زاوية معسكره، في 1h. عبر قطره ينظر عبر الرقعة كلها حتى معسكر الغوتي. الآن يسند البيدق في 5d من الخلف، ولاحقًا حين ينفتح القطر سيقوم بعمل كبير: إنه «الفيل البعيد النظر». يُعدّ من ضربات المعلّمين في تاريخ الشوغي، وإن كان بعض الميجين اللاحقين يرون أنه ربما كان مخرجًا ذكيًا من موقف صعب.","34":"G-4b. يقرّب الغوتي ذهبًا ليثبّت ما حول الملك.","35":"S-5g. يرفع السِّنتي فضة استعدادًا لقتال الوسط.","37":"S-5f. تتقدم الفضة أكثر وتستهدف مربعي الوسط 5e و4e.","39":"R-5h. ينقل السِّنتي رخه إلى الوسط. السِّنتي أيضًا يجمع قوته في العمود 5 بشكل الرخ الأوسط.","41":"P-6f. يدفع السِّنتي بيدق العمود 6 ليفتح الطريق لفضته وفيله.","43":"K-7i. يدخل الملك أعمق إلى اليسار. حتى سوهو يرتّب دفاع الملك قبل الهجوم.","45":"G-5i. يقرّب السِّنتي ذهبًا من الملك ليقوّي الدفاع.","46":"P-8e. يدفع الغوتي بيدق العمود 8 ويستعدّ للهجوم من قرب ملك السِّنتي.","47":"B-2g. يصعد فيل 1h مربعًا واحدًا. بتحريك خطه قليلًا صار يستهدف 4e و3f.","49":"S-4e. تتقدم الفضة إلى 4e وتضغط على معسكر الغوتي. الفيل في 2g يسندها من الخلف.","50":"P*5e. يُسقط الغوتي بيدقًا ليغلق الوسط.","52":"P-8f. يبدأ الغوتي قتالًا في العمود 8 ويصدم البيدق القريب من ملك السِّنتي.","54":"P-7e. يصدم الغوتي أيضًا ببيدق العمود 7. يحاول كسر عدة بيادق أمام ملك السِّنتي.","56":"Sx4e. تأسر فضة الغوتي فضة السِّنتي في 4e.","57":"Bx4e. يستردّ فيل 2g الفضة في 4e. قطر الفيل كان مفيدًا هنا.","58":"S-4d. يرفع الغوتي فضة ليطارد الفيل في 4e.","59":"B-1h. يعود الفيل مرة أخرى إلى الزاوية في 1h. حين طاردته الفضة رجع إلى مكانه الذي يرى منه بعيدًا. انظر كيف سيعمل هذا الفيل في النهاية.","60":"S*5f. يُسقط الغوتي فضة ويهاجم في الوسط.","61":"Sx5f. يأسر السِّنتي بفضته.","62":"Px5f. يستردّ الغوتي ببيدق يصل إلى 5f.","63":"Rx5f. يأسر السِّنتي البيدق بالرخ. الرخ يعمل في الوسط.","64":"S*5e. يُسقط الغوتي فضة أخرى ليطارد رخ السِّنتي.","65":"R-5h. يعود الرخ إلى مكانه.","66":"Sx6f. تأسر فضة الغوتي البيدق في 6f وتقترب من ملك السِّنتي. يستمر هجوم الغوتي.","67":"P*6g. يُسقط السِّنتي بيدقًا حتى لا تدخل الفضة أكثر.","68":"P*7g. يُسقط الغوتي بيدقًا في 7g قرب ملك السِّنتي. يريد تحريك قطع السِّنتي وصنع ثغرة.","69":"Nx7g. يأسر السِّنتي البيدق بالحصان. لاحقًا سيقفز هذا الحصان إلى 6e ليهاجم.","70":"Sx7e. تأسر فضة الغوتي البيدق في 7e وتقترب من رأس ملك السِّنتي.","71":"G-6h. يقرّب السِّنتي ذهبًا ليحمي الملك.","72":"P*7f. يُسقط الغوتي بيدقًا آخر يستهدف الحصان. يصير هجوم الغوتي حادًا.","73":"N-6e. هنا يردّ السِّنتي. يقفز الحصان إلى 6e ويستهدف 5c في معسكر الغوتي.","74":"S-6d. يسحب الغوتي الفضة ليستهدف الحصان في 6e.","75":"S*5c. يُسقط السِّنتي فضة في عمق معسكر الغوتي. يسندها البيدق في 5d والحصان في 6e. البيدق الذي أسقطه السِّنتي في 5d منذ زمن طويل صار مفيدًا هنا.","76":"Gx5c. يأسر الغوتي الفضة بالذهب.","77":"Px5c+. يأسر بيدق 5d الذهب ويترقّى إلى توكين.","78":"Sx5c. يأسر الغوتي التوكين بالفضة.","79":"Nx5c+. يأسر حصان 6e تلك الفضة ويترقّى. يستمر الأسر، ويفرغ معسكر الغوتي أكثر فأكثر.","80":"Sx5c. يأسر الغوتي الحصان المترقّي بالفضة. لكن بيدق السِّنتي في 5d لم يعد موجودًا، فصار قطر فيل 1h مفتوحًا حتى 6c.","81":"Bx6c+. أخيرًا يتحرك فيل 1h. يندفع على القطر دفعة واحدة، يأسر البيدق في 6c ويصير حصان تنين. «الفيل البعيد النظر» الذي أُسقط في النقلة 33 يؤدي هنا عمله الكبير بعد 48 نقلة. إنها نقلة فيل حقيقية تجري من طرف الرقعة إلى طرفها الآخر.","82":"S*7g. يُسقط الغوتي فضة ليضغط على ملك السِّنتي. الغوتي أيضًا يواصل الهجوم.","83":"P*2d. يُسقط السِّنتي بيدقًا في العمود 2 ليهزّ ما حول ملك الغوتي.","84":"Px2d. يأسره الغوتي ببيدق.","85":"P*2e. يُسقط السِّنتي بيدقًا آخر. يستهدف بيدق الغوتي في 2d ويحاول فتح العمود 2.","86":"B*3c. يُسقط الغوتي فيلًا ليقوّي دفاعه.","87":"P*5e. يُسقط السِّنتي بيدقًا ليكبح حركة فضة الغوتي وفيله.","88":"Sx7h+. تأسر فضة الغوتي ذهب السِّنتي وتترقّى.","89":"Gx7h. يستردّ السِّنتي بالذهب.","90":"G*7g. يُسقط الغوتي ذهبًا يضغط على ملك السِّنتي. القتال قرب ملك السِّنتي شرس أيضًا.","91":"S*4e. يُسقط السِّنتي فضة. هذه الفضة تستهدف 3d قرب ملك الغوتي.","92":"R-6a. ينقل الغوتي رخه إلى العمود 6 ليهاجم حصان التنين لدى السِّنتي.","93":"+B-7d. يبتعد حصان التنين إلى 7d. إنها قطعة قوية: تنفع في معسكرها وفي معسكر الخصم.","94":"Px2e. يأسر بيدق الغوتي البيدق في 2e.","95":"Sx3d. تأسر الفضة البيدق في 3d. فضة السِّنتي الآن أمام ملك الغوتي مباشرة.","96":"B-2d. ينقل الغوتي فيله إلى 2d استعدادًا لهجوم السِّنتي.","97":"S*4f. يُسقط السِّنتي فضة أخرى. تقطع قطر الفيل في 2d وتحدّ مما يستطيع فعله.","98":"G*3c. يُسقط الغوتي ذهبًا للدفاع.","99":"Sx3c+. تأسر فضة 3d الذهب وتترقّى.","100":"Kx3c. يأسر الغوتي الفضة المترقّية بالملك. خرج ملك الغوتي إلى 3c حيث المدافعون قليلون.","101":"S*3e. يُسقط السِّنتي فضة أخرى. تهاجم الفيل في 2d وتغلق أيضًا أحد طرق هروب الملك.","102":"N*8g، كِش. يُسقط الغوتي حصانًا مع كِش. إنها المقاومة الأخيرة.","103":"Gx8g. يأسر السِّنتي الحصان بالذهب.","104":"Gx8g. يستردّ الغوتي بالذهب. لكن ملك السِّنتي لم يُمسك بعد.","105":"Sx2d، كِش. تأسر الفضة الفيل مع كِش. من هنا يطارد السِّنتي ملك الغوتي دفعة واحدة.","106":"Kx2d. يأسر الغوتي الفضة بالملك.","107":"S-3e، كِش. تنتقل فضة 4f إلى 3e مع كِش وتسحب ملك الغوتي خارج معسكره.","108":"Kx3e. يأسر ملك الغوتي الفضة ويخرج إلى 3e. الملك الذي يخرج إلى الوسط بلا مدافعين في خطر كبير.","109":"B*4f، كِش. الفيل مرة أخرى حتى النهاية. يُسقط السِّنتي الفيل من يده مع كِش. في مباراة سوهو كانت الأفيال نجومًا من البداية إلى النهاية.","110":"K-4d. يهرب ملك الغوتي إلى 4d.","111":"G*3d، كِش. حين رأى سوإين أن الملك لم يعد يستطيع الإفلات، استسلم هنا. يفوز سوهو في 111 نقلة. أدّت B*1h في النقلة 33 عملًا كبيرًا بعد 48 نقلة عبر Bx6c+، وحُسمت المباراة أيضًا بكِش من فيل. إنها تحفة تُظهر كيف كان سوهو يضع القطعة وهو ينظر بعيدًا إلى المستقبل."}},"sakata1913":{"t":"ساكاتا سانكيتشي يهزم سيكيني بالرخ الجانبي","w":"ساكاتا سانكيتشي","b":"سيكيني كينجيرو","ev":"مباراة نظّمتها صحيفة أوساكا أساهي","d":"14 يوليو 1913","pl":"اليابان (أوساكا)","lead":"كان ساكاتا سانكيتشي من أوساكا وسيكيني كينجيرو، الذي صار لاحقًا الميجين الثالث عشر، خصمين طوال حياتهما. هذه مباراة بلا أفضلية لعباها في أوساكا صيف عام 1913. هاجم ساكاتا بـ«الرخ الجانبي» بوضع رخه في العمود 3، وفاز في معركة طويلة من 143 نقلة.","c":{"0":"أنا Musowl. وُلد ساكاتا سانكيتشي في ساكاي قرب أوساكا، وتعلّم الشوغي وحده تقريبًا، وصار أقوى لاعب في غرب اليابان. وكان سيكيني كينجيرو أفضل لاعب في طوكيو، وصار لاحقًا الميجين الثالث عشر. تقابلا مرات كثيرة منذ شبابهما، أكثر من 30 مباراة في المجموع: خصومة مشهورة. في أبريل من تلك السنة ذهب ساكاتا أول مرة إلى طوكيو ولعب ضد سيكيني. ويُقال إن عبارة «فضّتي تبكي» خرجت من تلك المباراة التي كانت بأفضلية الرمح. أما مباراة يوليو هذه فبلا أفضلية، ضد سيكيني الذي جاء إلى أوساكا. كان عام 1913 العام الثاني من عصر تايشو: فقد توفي الإمبراطور ميجي، وكان هذا أول صيف في العصر الجديد. وفي الشهر نفسه (يوليو)، قرب أوساكا، تأسست \"فرقة تاكارازوكا للغناء\" التي صارت لاحقًا فرقة تاكارازوكا المسرحية المعروفة اليوم. وكانت المباراة التي ترعاها جريدة أمرًا جديدًا أيضًا: لم يكن ذلك موجودًا في عصر إيدو حين كانت بيوت الشوغي تدير اللعبة.","1":"P-7f. تفتح النقلة الأولى قطر الفيل. من هنا يبني ساكاتا خطة مليئة بأفكاره الخاصة. وُلد ساكاتا عام 1870 في ساكاي لعائلة فقيرة تصنع الجزء العلوي من صنادل القش. ويُروى أنه ترك المدرسة الابتدائية بعد نحو نصف عام، وظل ضعيفًا في القراءة والكتابة. ويُقال إنه تعلّم الشوغي في نحو الثانية عشرة وهو يشاهد الكبار يلعبون على المقاعد في الشارع.","3":"P-5f. يدفع السِّنتي بيدق الوسط ويستعدّ لرفع فضة إلى 5g. وُلد غوتي، سيكيني كينجيرو، عام 1868. سافر في شبابه في أنحاء البلاد ليصقل مهارته، وبعد هذه المباراة بثماني سنوات، عام 1921، صار الميجين الثالث عشر في الثالثة والخمسين.","5":"P-6f. يدفع السِّنتي بيدق العمود 6 أيضًا فيغلق قطر الفيل. يتجنب تبادل الفيلين ويبني موقعه ببطء.","9":"S-6g. تصعد فضة أمام الملك وتبدأ جدار الدفاع.","11":"B-7g. يصعد الفيل مربعًا خلف البيدق في 6f. استعمال الفيل في الدفاع يعطي شكلًا قريبًا من قلعة ياغورا. وضع الفيل في 7g وفضة في 6g وذهب في 7h يقود إلى حصن ياغورا، الحصن الكلاسيكي في مباريات الرخ الثابت ضد الرخ الثابت. وفي عصرَي شووا وهيسي اللاحقين صار ياغورا من أكثر الخطط لعبًا عند المحترفين.","13":"S-4h. يرفع السِّنتي الفضة الأخرى أيضًا استعدادًا للهجوم.","16":"K-4b. ينقل الغوتي، سيكيني، ملكه نحو اليمين.","17":"G-7h. يقترب ذهب من الملك ليقوّي الدفاع.","19":"P-3f. يدفع السِّنتي بيدق العمود 3. هنا تبدأ خطة ساكاتا.","21":"R-3h. ينقل السِّنتي الرخ إلى العمود 3. هذا هو «الرخ الجانبي». بدل العمود 2 يقف الرخ في العمود المجاور، العمود 3، ليهاجم من هناك. كان ساكاتا يستعمل كثيرًا خططًا فريدة كهذه. ما زال الرخ الجانبي يُلعب أحيانًا في مباريات الرخ الثابت، خطةً لمهاجمة العمود 3 القريب من ملك الخصم مبكرًا. ويبقى اسم ساكاتا حيًّا أيضًا في اسم افتتاحية: \"رخ ساكاتا المواجه\".","23":"K-6i. يذهب ملك السِّنتي إلى اليسار، بعيدًا عن العمود 3 حيث سيكون الهجوم.","26":"K-3b. يذهب ملك الغوتي إلى 3b. لكن هذا بجوار العمود 3 مباشرة، وهو ما يستهدفه رخ السِّنتي.","27":"P-3e. يبدأ هجوم الرخ الجانبي. يصدم السِّنتي ببيدق العمود 3 ويريد اختراق هذا العمود بالرخ.","28":"Px3e. يأسر الغوتي بالبيدق.","29":"Rx3e. يأسر الرخ البيدق. يخرج رخ السِّنتي إلى 3e ويراقب منطقة ملك الغوتي. وكسب السِّنتي بيدقًا أيضًا.","30":"B-3a. يسحب الغوتي فيله استعدادًا للدفاع عن العمود 3.","31":"R-3h. يسحب السِّنتي رخه. بعد كسب بيدق يعيده إلى البيت بهدوء.","32":"P-8f. يردّ الغوتي في العمود 8.","34":"Bx8f. يقطع الفيل الذي تراجع إلى 3a القطر كله حتى 8f ويأسر البيدق. استعمال ذكي لخط الفيل الطويل.","35":"Bx8f. يأسر السِّنتي الفيل بفيله.","36":"Rx8f. يستردّ الغوتي بالرخ. تبادل الطرفان الفيلين.","37":"P*8g. يُسقط السِّنتي بيدقًا ليطارد رخ الغوتي.","38":"R-8b. يعود رخ الغوتي إلى بيته. صار لكل طرف فيل في يده.","39":"S-4f. يقدّم السِّنتي فضة استعدادًا لقتال الوسط والعمود 4.","43":"K-7i. يُدخل السِّنتي ملكه أعمق ويرتّب دفاعه.","47":"K-8h. يستقرّ الملك في 8h محاطًا بالذهب والفضة.","51":"P-5e. يصدم السِّنتي ببيدق الوسط. من هنا يبدأ القتال الحقيقي.","52":"Px5e. يأسر الغوتي بالبيدق.","53":"B*6c. يُسقط السِّنتي فيله داخل معسكر الغوتي. الفكرة أن يعيث فسادًا داخل موقع الغوتي.","55":"R-5h. ينقل السِّنتي الرخ إلى العمود 5 ليضيفه إلى قتال الوسط.","56":"B*9b. يُسقط الغوتي فيله أيضًا. عبر قطره يراقب معسكر السِّنتي.","57":"B-3f+. يعود فيل 6c على القطر ويترقّى وهو يغادر معسكر الخصم، فيصير حصان تنين في 3f. وبعودته إلى معسكره يستطيع الدفاع والهجوم. حصان التنين في معسكرك مدافع موثوق جدًا.","58":"P-4e. يدفع الغوتي بيدقًا ليطارد الفضة في 4f.","59":"S-5g. تتراجع الفضة إلى 5g.","60":"Px7f. يأسر بيدق الغوتي في العمود 7 البيدق الذي أمام ملك السِّنتي.","61":"Sx7f. يستردّ السِّنتي بالفضة.","62":"S-5d. يأتي الغوتي بفضة إلى الوسط ليقوّي دفاعه.","63":"+B-3g. يتراجع حصان التنين ليحرس معسكر السِّنتي.","64":"R-7b. ينقل الغوتي رخه إلى العمود 7 ويستهدف رأس ملك السِّنتي.","65":"P*7e. يُسقط السِّنتي بيدقًا ليسدّ طريق الرخ.","66":"G-4d. يرفع الغوتي ذهبًا.","68":"K-4c. يصعد ملك الغوتي إلى 4c. إنه شكل نادر، والملك قريب من وسط الرقعة. سيكون لموقع هذا الملك أهمية كبيرة في السباق الأخير.","69":"G-6g. يرفع السِّنتي ذهبًا بجوار الفضة في 5g ويبني جدار دفاع.","71":"N-7g. يقفز الحصان، جاهزًا للهجوم.","73":"P-6e. يصدم السِّنتي ببيدق العمود 6 ليهزّ معسكر الغوتي.","75":"P*5f. يُسقط السِّنتي بيدقًا ليثبّت الوسط.","76":"P-3f. يدفع الغوتي بيدق العمود 3 ويناوش حصان التنين لدى السِّنتي.","77":"+Bx3f. يأسر حصان التنين البيدق.","78":"Px5f. يأسر بيدق الغوتي بيدق السِّنتي ويضغط على الوسط.","79":"Sx5f. يستردّ السِّنتي بالفضة.","80":"P*5e. يُسقط الغوتي بيدقًا ليسدّ طريق الفضة.","81":"Sx6e. تأسر الفضة البيدق في 6e وتقترب من معسكر الغوتي من الجانب.","82":"P*6d. يُسقط الغوتي بيدقًا ليطارد الفضة.","83":"Sx5d. تأسر الفضة الفضة في 5d وتُزيل مدافعًا من مدافعي الغوتي.","84":"Gx5d. يستردّ الغوتي بالذهب.","85":"P*6e. يُسقط السِّنتي بيدقًا آخر ويواصل الهجوم في العمود 6.","86":"P*3e. يُسقط الغوتي بيدقًا ليطارد حصان التنين لدى السِّنتي.","87":"+B-3g. يعود حصان التنين إلى 3g. إنه مدافع مهم عن معسكر السِّنتي، فلا يدفعه إلى الأمام بالقوة.","88":"S-4d. يرفع الغوتي فضة ليحمي الملك.","89":"P*5f. يُسقط السِّنتي بيدقًا مقابل بيدق الغوتي في 5e محاولًا فتح الوسط.","91":"Px6d. يأسر بيدق 6e البيدق في 6d. دخل بيدق للسِّنتي معسكر الغوتي.","92":"P-4f. يدفع الغوتي بيدق العمود 4 ويردّ.","95":"P-6c+. يترقّى البيدق إلى توكين. التوكين يتحرك مثل الذهب، لكن إن أُسر لا يحصل الخصم إلا على بيدق.","96":"Gx6c. يأسر الغوتي التوكين بالذهب.","97":"P*6f. يُسقط السِّنتي بيدقًا ليسدّ ثغرة في معسكره.","98":"N-3c. يقفز الغوتي بحصانه ليساعد في الدفاع.","99":"S*6e. يُسقط السِّنتي فضة من يده. هذه الفضة تستهدف الذهب في 5d.","100":"P*6d. يُسقط الغوتي بيدقًا ليحاول إيقاف الفضة.","101":"Sx5d. تأسر الفضة الذهب في 5d. ذهب مدافع آخر عن ملك الغوتي.","102":"Gx5d. يستردّ الغوتي بالذهب.","103":"P*3d. يُسقط السِّنتي بيدقًا ويناوش منطقة ملك الغوتي.","104":"Kx3d. يأسر ملك الغوتي البيدق ويخرج إلى 3d. الملك يتقدم أكثر فأكثر.","105":"P*3f. يُسقط السِّنتي بيدقًا ليكبح ما أمام ملك الغوتي.","106":"S*4d. يُسقط الغوتي فضة ليحمي الملك.","107":"R-3i. يعيد السِّنتي الرخ إلى العمود 3. ملك الغوتي في العمود 3، فيعود الرخ الجانبي إلى العمل.","108":"K-4c. يعود ملك الغوتي إلى 4c.","109":"Px3e. يأسر بيدق 3f البيدق في 3e. يتقدم بيدق للسِّنتي حتى يقترب جدًا من ملك الغوتي.","110":"P*3h. يُسقط الغوتي بيدقًا يهاجم الرخ في 3i.","111":"G*3d، كِش. يُسقط السِّنتي ذهبًا من يده ويدفع ملك الغوتي أكثر.","112":"K-5c. يهرب ملك الغوتي إلى 5c.","113":"R-5i. بعد أن هاجمه بيدق العمود 3، يبتعد الرخ إلى 5i.","115":"+B-2f. يتنحّى حصان التنين إلى 2f. لو جاءت فضة الغوتي إلى 4f لهاجمت حصان التنين في 3g، فيبدو أنه يتفادى ذلك مسبقًا.","116":"Sx4f. تأسر فضة الغوتي البيدق في 4f وتقترب من معسكر السِّنتي.","117":"Gx3c. يأسر الذهب الحصان. يقشر السِّنتي قطع الغوتي واحدة بعد أخرى.","119":"G-3d. يعود الذهب إلى 3d، وهو مربع يغلق طريق هروب الملك.","121":"N*7d. يُسقط السِّنتي حصانًا. يستهدف 8b حيث رخ الغوتي، و6b.","122":"R-4b. يُنقذ الغوتي رخه إلى العمود 4.","123":"P*4d. يُسقط السِّنتي بيدقًا ليجذب ذهب الغوتي المدافع من مكانه.","124":"Gx4d. يأسر الغوتي البيدق بالذهب.","125":"Gx4d. يأسر السِّنتي الذهب بذهبه.","126":"Rx4d. يستردّ الغوتي بالرخ.","127":"Gx5f. يأسر الذهب البيدق في 5f.","128":"Sx5f. يأسر الغوتي الذهب بالفضة.","129":"Rx5f. يستردّ السِّنتي الفضة بالرخ. تستمر المبادلات وتدخل المباراة مرحلتها الأخيرة.","130":"S*5e. يُسقط الغوتي فضة ليطارد رخ السِّنتي.","131":"R-5i. يتراجع الرخ.","132":"P*5h. يُسقط الغوتي بيدقًا ويطارد الرخ مرة أخرى.","133":"R-6i. يذهب الرخ إلى 6i. يطارد الغوتي رخ السِّنتي بالبيادق بلا توقف.","134":"K-5d. يخرج ملك الغوتي حتى 5d. الملك في وسط الرقعة قليل المدافعين وسهل الاستهداف.","135":"+B-3f، كِش. يذهب حصان التنين إلى 3f ويعطي كِشًا للملك في 5d عبر القطر المارّ بـ4e. حصان التنين الذي حرس معسكر السِّنتي طوال هذا الوقت ينضمّ هنا إلى الهجوم.","136":"G*4e. يُسقط الغوتي ذهبًا ليقطع خط حصان التنين.","137":"G*6e، كِش. يُسقط السِّنتي ذهبًا ويقترب من جانب الملك مباشرة.","138":"Px6e. يأسر الغوتي الذهب ببيدق.","139":"Sx6e، كِش. تأسر فضة 7f ذلك البيدق مع كِش. الفضة التي وقفت أمام الملك منذ وسط المباراة تنضمّ إلى الهجوم.","140":"K-4c. يعود ملك الغوتي إلى 4c.","141":"+Bx4e. يأسر حصان التنين الذهب في 4e. يواصل السِّنتي أسر القطع حول ملك الغوتي.","142":"Rx4e. يأسر الغوتي حصان التنين بالرخ.","143":"S*5d، كِش. حين رأى سيكيني أن الملك لم يعد يستطيع الإفلات، استسلم هنا. يفوز ساكاتا في 143 نقلة. هاجم بالرخ الجانبي في العمود 3، ودافع عن معسكره بحصان التنين خلال وسط مباراة طويل وهو يقشر قطع الغوتي شيئًا فشيئًا، ثم أمسك في النهاية بملك الغوتي الذي خرج إلى الأمام. إنها مباراة عنيدة صبورة تشبه ساكاتا الذي علّم نفسه بنفسه. وبعد وفاته مُنح ساكاتا لقبي ميجين وأوشو."}},"nanzenji1937":{"t":"مبارزة نانزن-جي: بيدق الحافة عند ساكاتا","w":"كيمورا يوشيو","b":"ساكاتا سانكيتشي","ev":"مباراة خاصة نظمتها صحيفة يوميوري","d":"فبراير 1937","pl":"اليابان (معبد نانزن-جي، كيوتو)","lead":"كان ساكاتا سانكيتشي مقطوعًا لسنوات عن عالم الشوغي في طوكيو لأنه أعلن نفسه «ميجين». في هذه المباراة عاد إلى المسرح الكبير وهو في السادسة والستين. خصمه كان كيمورا يوشيو، ابن الحادية والثلاثين، الذي صار بعد قليل أول ميجين يُختار بالقوة. لعبا 7 أيام في معبد نانزن-جي في كيوتو، ولكل منهما 30 ساعة للتفكير. ومنذ نقلته الأولى دفع ساكاتا البيدق الواقع على حافة الرقعة تمامًا، فأدهش البلاد كلها.","c":{"0":"أنا Musowl. وُلد ساكاتا سانكيتشي في ساكاي قرب أوساكا، وصار الأستاذ الكبير لغرب اليابان بعد أن تعلّم كل شيء تقريبًا بنفسه. في أواخر عصر تايشو أعلن نفسه «ميجين» من تلقاء نفسه، فقطع عالم الشوغي في طوكيو صلته به، ولم يستطع لوقت طويل أن يلعب رسميًا مع محترفي طوكيو. ثم ترك سيكيني كينجيرو لقب الميجين، وبدأ نظام جديد يُحدَّد فيه الميجين بالقوة (بطولة ميجين-سين). وفي هذا السياق نظمت صحيفة يوميوري مباراة بين ساكاتا وكيمورا يوشيو، أقوى المرشحين للقب الجديد. لُعبت المباراة من 5 إلى 11 فبراير 1937، طوال 7 أيام، في معبد نانزن-جي في كيوتو. وكان لكل لاعب 30 ساعة كاملة للتفكير، وهذا أمر لا يُتصوَّر اليوم.","1":"P-7f. أكثر نقلة أولى شيوعًا: تفتح قطر الفيل. وُلد كيمورا يوشيو في هونجو بطوكيو ونشأ تلميذًا لسيكيني كينجيرو. كان يقدّر الأسلوب «المستقيم» الذي يكدّس النقلات الصحيحة واحدة بعد أخرى، وفي هذه المباراة أيضًا يبني موقعه بهدوء وثبات.","2":"P-9d. هذا هو «بيدق الحافة عند ساكاتا» الشهير. غوته متأخر بنقلة أصلًا، وبحسب المنطق السائد آنذاك كان دفع البيدق الذي على الحافة تمامًا في النقلة الثانية يشبه رمي نقلة أخرى. ويُروى أن ساكاتا أراد بهذه النقلة أن يُظهر كبرياءه بعد سنوات بلا مسرح. وكتب الأديب أودا ساكونوسوكي لاحقًا في أحد أعماله كم تأثر حين قرأ عن هذه النقلة في الصحيفة.","3":"P-5f. يدفع كيمورا البيدق الأوسط. ما دام الخصم قد خسر نقلة، فهو يريد أن يأخذ مساحة واسعة في الوسط ويمسك بزمام المبادرة. وكتب كيمورا لاحقًا بكلماته أن بيدق الحافة فاجأه كثيرًا، لكنه بدأ فورًا يفكر في نية خصمه.","4":"P-3d. ويفتح ساكاتا أيضًا قطر فيله. حتى الآن دفع غوته بيدقي العمودين 9 و3. وهل سيفيد بيدق الحافة يومًا؟ هذا من أهم ما يُتابَع في هذه المباراة. وعام 1937، عام هذه المباراة، هو أيضًا العام الذي بدأت فيه الحرب بين اليابان والصين في يوليو. وكانت الصحف تفرد مساحات كبيرة لمبارزات الشوغي الكبرى، وسُمّيت هذه المباراة «مباراة القرن».","5":"P-5e. يتقدم كيمورا ببيدق العمود 5 خطوة أخرى ويأخذ «موقع العمود 5». أخذ الموقع يعني إيصال بيدق إلى الصف الخامس وجعل المنطقة حوله لك. ومن يسيطر على الوسط يترك لقطع الخصم أماكن أقل للحركة.","6":"P-4d. نقلة تسد فيل اللاعب نفسه عن قصد. يرد ساكاتا على البيدق الأوسط في 5e ببيدق في 4d ويستعد لبناء معسكره بهدوء. وسدّ الفيل بهذه الطريقة فكرة تظهر كثيرًا لاحقًا في افتتاحيات «الرخ المنقول».","7":"S-4h. تصعد الفضة اليمنى لتسند موقع العمود 5. الموقع المأخوذ ينهار بسهولة، لذلك من المهم أن يُسند من الخلف بفضة.","8":"S-3b. ويرفع ساكاتا فضة أيضًا. تنوي هذه الفضة الذهاب إلى 4c ثم 3d لتعمل في العمود 3. وفي الشهر التالي لعب ساكاتا أيضًا ضد هانادا تشوتارو في معبد تنريو-جي في كيوتو، وفي تلك المرة دفع في النقلة الثانية بيدق الحافة المقابلة، P-1d. وفاز هانادا بتلك المباراة في 169 نقلة.","9":"S-5g. تقف الفضة الآن خلف البيدق في 5e مباشرة. صار موقع العمود 5 مسنودًا بقوة، واكتمل تشكيل «الموقع الأوسط». بدأت بطولة ميجين-سين، التي تحدد الميجين بالقوة، حين قرر سيكيني كينجيرو عام 1935 أن يترك اللقب. وفي وقت هذه المباراة كان الدوري الذي يختار أول ميجين جاريًا، وكان كيمورا في الصدارة.","10":"S-4c. تصل الفضة إلى 4c. تراقب المربع 5d وتمنع بيدق سينته في العمود 5 من التقدم أكثر. وصارت حياة ساكاتا لاحقًا مسرحية «أوشو» لهوجو هيديجي، واشتهرت كثيرًا أيضًا عبر الأغاني والأفلام.","11":"P-2f. الآن يدفع كيمورا البيدق الذي أمام رخه. فإلى جانب الموقع الأوسط يجهّز هجومًا على العمود 2 أيضًا: خطة طموحة وقوية. وفي مباريات ذلك الزمن بلا أفضلية كانت المعارك التي لا يحرك فيها أي طرف رخه («رخ ثابت» ضد «رخ ثابت») شائعة، وكيمورا يلعب في هذا التيار الرئيسي.","12":"P-3e. يمد ساكاتا بيدق العمود 3. وردًّا على هجوم كيمورا في العمود 2 يأخذ موقعًا في العمود 3 ليقاوم.","13":"P-2e. يتقدم بيدق الرخ مرة أخرى. قريبًا سيصطدم بالبيدق في 2d، لذلك على غوته أن يقرر كيف يستخدم فيله.","14":"B-3c. يصعد الفيل خطوة وينضم إلى الدفاع عن العمود 2. سيستخدم ساكاتا الفيل للدفاع عن العمود 2، ويستعد لتحريك رخه في النقلة التالية.","15":"K-6h. يبدأ كيمورا بنقل ملكه إلى اليسار. يبدو أن المعركة ستكون في الجهة اليمنى، فالفكرة الأساسية إبعاد الملك إلى الجهة الأخرى.","16":"R-2b. يدير ساكاتا رخه إلى العمود 2. ولأنه يواجه رخ الخصم مباشرة، تُسمّى هذه الافتتاحية «الرخ المقابل». بيدق الحافة مع الرخ المقابل خطة جريئة لاستقبال رخ الخصم وجهًا لوجه، وهي من صميم أسلوب ساكاتا. وفي مباريات كبار اللاعبين بلا أفضلية في ذلك الزمن كانت افتتاحيات الرخ المنقول قليلة، وهذا أيضًا يُظهر تميّز ساكاتا.","17":"P-4f. دفع بيدق العمود 4 يفتح للفضة والذهب طريقًا إلى الأمام. يسعى كيمورا إلى تشكيل سميك من الوسط إلى اليمين.","18":"G-3b. يقرّب ساكاتا ذهبه الأيسر من الرخ ويستعد للقتال في العمود 2. وفي الرخ المقابل تُعد حماية جانب الرخ بذهب شكلًا مألوفًا.","20":"S-3d. تتقدم الفضة إلى 3d وتسند البيدق في 3e. قطع غوته تتقدم شيئًا فشيئًا في العمودين 3 و2.","21":"K-7h. يتحرك الملك مربعًا آخر إلى اليسار. ملك كيمورا يبتعد أكثر عن الجهة اليمنى حيث ستقع المعركة.","22":"G-6b. يرفع ساكاتا الذهب من 6a إلى 6b. هذا استعداد لتحصين ملكه في الجهة اليسرى.","24":"K-6a. يذهب ملك ساكاتا إلى 6a. في افتتاحيات الرخ المنقول يُحصَّن الملك عادة في الجهة المقابلة للرخ، نحو العمودين 7 و8، ويبدأ ساكاتا بنقل ملكه في ذلك الاتجاه.","25":"G-4g. يرفع كيمورا ذهبه الأيمن إلى 4g. يسند البيدق في 4f والمربع 3f، والفكرة أن يشارك الذهب في معركة الجهة اليمنى. هذا التشكيل يقدّم الهجوم وسماكة الوسط على دفاع الملك.","26":"P-2d. أخيرًا يبدأ ساكاتا القتال. في الرخ المقابل الخطة الأساسية أن يتصادم البيدقان هكذا في العمود 2 ويتواجه الرخّان.","27":"Px2d. يأخذ كيمورا البيدق. لو لم يأخذه، للعب غوته P-2e وأخذه، ولانفتح عمود رخ غوته أولًا.","28":"Bx2d. يستعيد الفيل. يخرج إلى 2d ويراقب الجهة اليمنى من معسكر سينته.","29":"P-5d. يدفع كيمورا البيدق الأوسط أبعد. الفكرة استخدام موقع العمود 5 للهجوم المضاد من الوسط؛ فإن أخذ غوته بالبيدق بدأت فضة سينته وفيله يعملان في الوسط. ولأن فيل غوته ذهب إلى 2d صار الوسط أضعف قليلًا.","30":"N-3c. لا يأخذ ساكاتا البيدق في 5d. بل يقفز بحصانه إلى 3c ويضيف قطعة هجومية أخرى. فكرته أن يترك الوسط الآن ويسرّع هجومه في اليمين.","31":"P-3f. يدفع كيمورا بيدق العمود 3 ليصطدم ببيدق غوته في 3e. الفكرة إزالة موقع غوته في العمود 3 وفتح طريق لذهبه وفضته.","32":"P*2f. يُسقط ساكاتا بيدقًا من يده في 2f. إن لعب غوته بعدها P-2g+ انكسر العمود 2 حيث يقف رخ سينته. إنها نقلة حادة تطعن معسكر الخصم ببيدق خفيف واحد.","33":"Px3e. يترك كيمورا البيدق في 2f مؤقتًا ويأخذ البيدق في 3e. ربما رأى أن دفع بيدق إلى العمود 3 هنا سيقيّد فيل غوته وفضته.","34":"Bx3e. يستعيد الفيل البيدق في 3e. ولأن الفضة في 3d تحميه، لا يمكن أخذه مجانًا في الحال.","35":"G-3f. يرفع كيمورا ذهبه ويواجه الفيل. إنه يعرض تبادل الذهب بالفيل؛ وإن حدث التبادل صار في يد سينته فيل، وكسب أيضًا وقتًا لأخذ بيدق غوته في 2f.","36":"K-7b. يترك ساكاتا الفيل مؤقتًا وينقل ملكه إلى 7b. يقرر أن ينقل الملك إلى مكان أكثر أمانًا قليلًا قبل أن يشتد القتال.","37":"Px5c+. يأخذ بيدق كيمورا في 5d ويترقّى فيصير «توكين». إنها نقلة قاسية تُرقّي بيدقًا بجوار ملك غوته مباشرة.","38":"Gx5c. يأخذ غوته بالذهب. هكذا يُجذب ذهب غوته إلى 5c، ويبتعد الذهب الذي كان يحرس الملك عن مكانه.","39":"P*2e. يُسقط كيمورا بيدقًا في 2e. يقطع الصلة بين بيدق غوته في 2f والرخ في 2b، ويترك البيدق في 2f وحيدًا. وإن أخذه لاحقًا صار رخ سينته حرًّا.","41":"G-5i. يسحب كيمورا ذهبه الأيسر ليقوّي الدفاع حول ملكه. نقلة هادئة تضيف نقلة دفاعية قبل سباق الهجمات.","43":"Gx3e. هنا يحدث تبادل الذهب بالفيل. يحصل كيمورا على فيل، ويحصل غوته على ذهب في يده. الفيل قطعة كبيرة تعمل من بعيد، فسيكون ورقة رابحة لاحقًا عند استهداف الملك.","44":"Sx3e. تستعيد الفضة الذهب. تخرج فضة غوته إلى 3e وتضغط على معسكر سينته.","45":"P*3d. يُسقط كيمورا بيدقًا يهاجم الحصان في 3c. وإن استطاع بعدها أن يلعب P-3c+ انفتحت ثغرة في دفاع غوته.","46":"Nx2e. يقفز ساكاتا بحصانه آخذًا البيدق في 2e. يفلت الحصان من هجوم البيدق ويقترب في الوقت نفسه من معسكر سينته.","47":"P-4e. يدفع كيمورا بيدق العمود 4، ومع البيدق في 3d يكبح قطع غوته. يتكوّن جدار من بيادق سينته من الوسط إلى اليمين.","48":"R-2d. يصعد رخ غوته إلى 2d. يعمل جانبيًا ويستهدف البيدق في 3d وينضم إلى الهجوم.","49":"Px4d. يأخذ كيمورا البيدق في 4d ويتقدم مرة أخرى. وإن نجح بعدها في P-4c+ انهار معسكر غوته انهيارًا شديدًا.","50":"P*5e. يُسقط غوته بيدقًا في 5e، في طريق فيل سينته تمامًا. إنه طُعم: بإجبار سينته على الأخذ بالفيل يغيّر غوته مكان الفيل.","51":"Bx5e. يأخذ كيمورا بالفيل. يخرج الفيل إلى 5e في الوسط ويراقب مسافات بعيدة.","52":"Gx4d. يأخذ ذهب ساكاتا من 5c البيدق في 4d ويوقف هجوم بيادق سينته. وفي الوقت نفسه صار هذا الذهب يهاجم الفيل في 5e.","53":"S-4f. يرفع كيمورا الفضة إلى 4f ويربطها بالفيل في 5e. يحمي الفيل ويضيف فضة إلى خط المواجهة.","54":"Gx5e. يأخذ ساكاتا الفيل بالذهب. كان بإمكان سينته أن يستعيد بالفضة من 4f، لكن كيمورا يختار نقلة أخرى. ربما رأى أن أخذ القطعة التي في قلب هجوم غوته أهم من الاستعادة في 5e.","55":"Sx3e. لا يستعيد كيمورا الذهب في 5e؛ بل يأخذ فضة غوته في 3e. بعد تبادل الفيل بالفضة صار غوته متقدمًا قليلًا في القطع. ومع ذلك فإن خروج فضة سينته قرب رخ غوته وحصانه له معنى كبير.","56":"R-2a. يتراجع الرخ الذي هاجمته الفضة إلى 2a. يبقى آمنًا ويواصل مراقبة العمود 2.","57":"B*7g. يُسقط كيمورا الفيل الذي كسبه في 7g. المربع 7g يحمي ملك سينته، ومن هناك ينظر الفيل أيضًا عبر قطر طويل يمر بالوسط إلى عمق معسكر غوته. إنه مربع يفيد الدفاع والهجوم معًا.","58":"G*4e. يُسقط غوته ذهبه من يده في 4e. وبصفّ ذهبين في 5e و4e يسيطر على 5f و4f في الوسط: نقلة قوية.","59":"P*5c. يُسقط كيمورا بيدقًا في 5c. وإن لعب بعدها P-5b+ وُلد توكين بجوار ملك غوته مباشرة.","60":"P*5a. يُسقط ساكاتا بيدقًا في الصف الأخير ليحمي 5b. يُسمّى مثل هذا البيدق الدفاعي «بيدق القاع». إنها نقلة متواضعة لكنها مهمة توقف هجوم توكين الخصم.","61":"S-4f. يعيد كيمورا الفضة إلى 4f ويهاجم ذهبي غوته في 4e و5e. وإن خرج ذهب ليأخذها، استطاع سينته أن يستغل الوقت لدفع هجومه في الجهة اليمنى.","62":"Gx4f. يأخذ الذهب الذي في 5e الفضة. يواصل غوته كسب القطع، لكن ذهبه في المقابل يتوغل بعيدًا قرب معسكر سينته.","63":"P-3c+. يترقّى البيدق في 3d ويصير توكين. أخيرًا تدخل قطع سينته الجهة اليمنى من معسكر غوته.","64":"R-2d. يرفع غوته رخه إلى 2d ليراقب التوكين من الجانب.","65":"+Px3b. يأخذ التوكين الذهب في 3b. التوكين رخيص كالبيدق لكنه يتحرك كالذهب، وإن أُخذ لم يحصل الخصم إلا على بيدق. أخذ ذهب بتوكين مكسب مُفرح جدًا للمهاجم.","66":"R-3d. يخرج الرخ إلى 3d ويضغط على الجهة اليمنى من معسكر سينته. ويدخل ساكاتا أيضًا سباق الهجمات.","67":"+P-4b. يقترب التوكين من الملك أكثر. التوكين لا يتقدم إلا خطوة واحدة كل مرة، لكنه يقترب بثبات من ملك غوته، كما يقول المثل: «التوكين بطيء لكنه أكيد».","68":"P-7d. هذا يصنع طريق هروب لملك غوته. قبل أن يصل التوكين يفتح ساكاتا العمود 7 ليستطيع الملك الهرب إلى الأعلى.","69":"Rx2f. أخيرًا يأخذ كيمورا البيدق في 2f برخه. يخرج الرخ إلى الصف السادس ويعمل جانبيًا على نطاق واسع، وينظر أيضًا إلى الذهب في 4f. الرخ الذي عجز عن الحركة طويلًا يعود إلى الحياة هنا.","70":"R-3i+. يُدخل ساكاتا رخه إلى عمق معسكر سينته ويرقّيه إلى تنين. يتحرك التنين كالرخ ويستطيع أيضًا أن يخطو مربعًا قطريًا: قطعة قوية تهدد الصف الأخير لسينته.","71":"S*6a. يعطي كيمورا فضة مجانًا مع كِش. بإجبار غوته على الأخذ بالملك، يعيد الملك إلى الصف الأخير ويستعد لإسقاط ذهب هناك. إفساد شكل الملك ولو بثمن قطعة من الأساليب المعروفة لاصطياد الملك.","72":"Kx6a. يأخذ الملك الفضة. ينزل إلى 6a، ويقلّ المدافعون من حوله.","73":"G*8b. يُسقط كيمورا ذهبًا في 8b. يغلق طريق الهروب على يسار الملك، ويستهدف أيضًا الحصان في 8a والمربع 7a.","74":"S-7a. تتراجع الفضة لتوقف هجوم الذهب.","75":"Rx4f. هنا يأخذ الرخ الذهب في 4f. وبين نقلات الهجوم يستعيد كيمورا القطع واحدة بعد أخرى، ويسترد ما كان غوته قد أخذه من قبل.","76":"Sx8b. وتأخذ فضة غوته أيضًا الذهب في 8b. الطرفان يتبادلان أخذ القطع في سباق محتدم.","77":"Rx4e. يأخذ الرخ الذهب الآخر في 4e أيضًا. الآن يتقدم سينته بوضوح في القطع. يعمل الرخ جانبيًا على امتداد الصف الخامس ويراقب المنطقة أمام ملك غوته.","78":"K-7b. يصعد الملك إلى 7b ويبتعد قليلًا عن التوكين والفضة.","79":"+P-5b. يتقدم التوكين مرة أخرى ويقترب خطوة خطوة من ملك غوته.","80":"S*7a. يُسقط غوته فضة من يده في 7a ليقوّي المنطقة تحت الملك.","81":"G*6b، كِش. لا يستطيع الملك أن يهرب إلا إلى الأعلى، ويُدفع نحو المكان المكشوف.","82":"K-7c. يهرب الملك إلى 7c. طريق الهروب الذي فُتح بـ P-7d في النقلة 68 ينفع الآن.","83":"Rx2e. يأخذ الرخ الحصان في 2e. وبين الكِشّات يجمع كيمورا القطع واحدة بعد أخرى ويدّخرها للهجوم الأخير.","84":"G*5f. يُسقط ساكاتا ذهبًا في 5f. يسد الطريق الجانبي لرخ سينته ويضغط أيضًا على معسكر سينته: نقلة عنيدة.","85":"G*6f. ويُسقط كيمورا أيضًا ذهبًا ويهاجم الذهب في 5f. يطارد ذهب غوته ويحمي في الوقت نفسه ما فوق ملكه: عصفوران بحجر واحد.","86":"P-8d. يدفع غوته بيدق العمود 8 ويفتح مساحة أكبر لهروب الملك.","87":"Gx5f. يأخذ الذهب الذهب في 5f. قطع سينته تزداد، وقطع غوته المهاجمة تقلّ.","88":"B*4g. يُسقط ساكاتا فيله في 4g مستهدفًا الذهب في 5f. لا يستسلم أبدًا ويواصل البحث عن هجوم مضاد.","89":"R-6e. يدور الرخ إلى 6e. يراقب العمود 6 ويريد مهاجمة ملك غوته من الأعلى.","90":"Sx6b. تأخذ الفضة الذهب في 6b وتزيل مهاجمًا قرب الملك.","91":"+Px6b. يستعيد التوكين الفضة. حتى لو أُخذ التوكين لا يحصل الخصم إلا على بيدق، لذلك هو قطعة موثوقة يمكن دفعها إلى الأمام مرة بعد مرة.","92":"S*5d. يُسقط غوته فضة ويهاجم الرخ في 6e. يحاول طرد الرخ وتقوية المنطقة فوق الملك.","93":"G*7b، كِش. لم يعد أمام ملك غوته إلا الهرب إلى 8c.","94":"K-8c. يذهب الملك إلى 8c. لقد طُورد حتى صار بجوار البيدق في 9d، بيدق الحافة الذي دُفع في النقلة الثانية.","95":"B-5e. يخرج الفيل من 7g إلى 5e. قطره يراقب 6d و7c قرب ملك غوته، ومع الرخ والذهب والتوكين لم يبق أي دفاع. استسلم ساكاتا هنا، وفاز كيمورا في 95 نقلة. لم يُستفد من بيدق الحافة في النقلة الثانية في هذه المباراة، وكتب نايتو كونيو لاحقًا أنها من أعظم المباريات في تاريخ الشوغي. وفي ديسمبر من العام نفسه صار كيمورا أول ميجين يُختار بالقوة، وما زال بيدق الحافة عند ساكاتا يُروى أسطورةً تُعلن تحوّل عصر."}},"sokan1725":{"t":"حصان سوكان العبقري: N*3e","w":"إيتو سوكان الثالث","b":"أوهاشي سومين (لاحقًا أوهاشي سويو الرابع)","ev":"شوغي القلعة (المباراة السنوية في قلعة إيدو)","d":"اليوم 17 من الشهر 11، سنة 1725 (كيوهو 10)","pl":"اليابان (قلعة إيدو)","lead":"مباراة في القلعة بين إيتو سوكان الثالث (20 سنة)، الذي صار لاحقًا الميجين السابع، وأوهاشي سومين (17 سنة)، وريث الفرع الثاني لأسرة أوهاشي والذي صار لاحقًا أوهاشي سويو الرابع. تصطدم قلعة ياغورا عند السِّنتي بجدار الفضّيتين عند الغوتي. الحصان الذي أسقطه سوكان في 3e في النقلة 81 نقلة مشهورة، ويُروى أن الميجين الخامس عشر أوياما ياسوهارو وصفها لاحقًا بأنها «نقلة عبقرية». فاز سوكان في 101 نقلة.","c":{"0":"أنا Musowl. نشاهد اليوم مباراة في القلعة من منتصف عصر إيدو، سنة 1725 (كيوهو 10). كان شوغي القلعة مباراة سنوية في قلعة إيدو يلعبها أمام الشوغون أساتذةُ بيوت الشوغي الثلاثة: البيت الرئيسي لأوهاشي، والفرع الثاني لأوهاشي، وبيت إيتو. يقال إن الشوغون الثامن توكوغاوا يوشيموني ثبّتها في اليوم السابع عشر من الشهر الحادي عشر، ومن هنا جاء «يوم الشوغي» الحالي (17 نوفمبر). كان السِّنتي، إيتو سوكان الثالث، في العشرين من عمره، وقد ورث بيت إيتو قبل سنتين فقط عند وفاة أبيه سوئين الثاني. وكان الغوتي، أوهاشي سومين، في السابعة عشرة، وسيحمل لاحقًا اسم أوهاشي سويو الرابع. تابِعوا هذه المبارزة بين وريثين شابين من بيوت الشوغي.","1":"P-7f. تفتح هذه النقلة قطر الفيل، وهي أكثر نقلة أولى شيوعًا. في هذه السنة توفي آراي هاكوسيكي في اليابان وبطرس الأكبر في روسيا. كانت «إصلاحات كيوهو» التي قام بها يوشيموني جارية، وكان الساموراي وأهل المدينة في إيدو يستمتعون بالشوغي على حد سواء.","2":"P-3d. يفتح الغوتي قطر فيله أيضًا. يُروى أن سوكان كان في صغره يحب المبارزة بالسيف وفنون القتال أكثر من الشوغي. ويقال إنه انصرف إلى الشوغي بعد أن توفي أخوه الأكبر إينداتسو في الخامسة عشرة سنة 1712.","3":"P-2f. يدفع السِّنتي البيدق الذي أمام الرخ ليستعد للهجوم على العمود 2. هذه البداية، P-7f وP-3d وP-2f، ما زالت اليوم من أكثر الافتتاحات شيوعًا.","4":"P-4d. يدفع الغوتي البيدق الذي أمام فيله ويغلق القطر من جديد. إنه يتجنب تبادل الفيلين ويبني معسكره بهدوء. في مباريات القلعة في ذلك العصر تظهر هذه النقلة P-4d، التي يختار بها الغوتي الدفاع، كثيرًا جدًا.","5":"P-2e. يدفع السِّنتي بيدق الرخ خانة أخرى. بعدها ستبادل النقلة P-2d البيادق على العمود 2، لذا يحتاج الغوتي إلى نقلة تمنع ذلك.","6":"B-3c. يصعد الفيل ليحرس الخانة 2d. كان منع تبادل بيدق الرخ بهذه الطريقة هو الدفاع المعتاد للغوتي في تلك الأيام. ولأن الفيل يُستعمل للدفاع، تصبح لعبة الغوتي بطيئة.","7":"S-4h. يرفع السِّنتي الفضّي الأيمن. الفضّي نافع في الهجوم والدفاع، ويتجه أولًا نحو الوسط.","8":"S-3b. يرفع الغوتي فضّيًا أيضًا ويبدأ ببناء دفاع ملكه.","9":"P-5f. يدفع السِّنتي بيدق الوسط ليفتح طريق الفضّي إلى 5g.","10":"S-4c. يذهب فضّي الغوتي إلى 4c، وقريبًا سيقف بجانبه فضّي ثانٍ في 5c. قبل سنتين، في مباراة القلعة سنة 1723 بين اللاعبين نفسيهما، ردّ سومين على البداية نفسها بنقل رخه إلى 4b: رخ العمود الرابع. أما هذه المرة فيترك الرخ على العمود 8 ويقاتل بالرخ الثابت.","11":"P-4f. يدفع السِّنتي بيدق العمود 4 لتتحرك قطع اليمين بسهولة. يُروى أن سوكان لعب أول مباراة له في القلعة وهو في الحادية عشرة، وفاز بها.","12":"G-3b. يرفع الغوتي قائدًا ذهبيًا ليقوّي الفيل في 3c ودفاع الملك.","13":"S-5g. يصل الفضّي إلى الوسط. سيبدّل هذا الفضّي خانته مرات عدة ويصبح بطل الهجوم.","14":"P-5d. يدفع الغوتي بيدق الوسط أيضًا استعدادًا لجلب فضّي إلى 5c.","16":"S-6b. يتحرك الفضّي الأيسر أيضًا. يسعى الغوتي إلى شكل فيه فضّيتان متجاورتان في 4c و5c. هذا الجدار من الفضّيات ينتمي إلى عائلة التشكيلات التي سُمّيت لاحقًا «غانغي» (تشكيلة الإوز البري).","17":"G-5h. يرفع السِّنتي ذهبيًا ويبدأ ببناء قلعة ملكه.","18":"S-5c. صارت الفضّيتان متجاورتين. تحرس فضّيتا 4c و5c الوسط، وأصبح معسكر الغوتي متينًا جدًا.","19":"K-6h. ينقل السِّنتي ملكه إلى اليسار. إبعاد الملك عن الجهة اليمنى التي ستهاجم منها هو القاعدة الأساسية للرخ الثابت.","21":"P-6f. يدفع السِّنتي بيدق العمود 6. هكذا ينفتح الطريق أمام الفضّي ليأتي إلى 7g ويبني «قلعة ياغورا».","22":"P-8d. يدفع الغوتي بيدق رخه ويستعد للهجوم نحو ملك السِّنتي.","25":"S-7g. يذهب الفضّي الأيسر إلى 7g. بالفضّي في 7g وذهبيٍّ سيأتي إلى 6g وذهبيٍّ في 7h سيُلَفّ الملك في قلعة ياغورا. تُلعب الياغورا منذ عصر إيدو، وما زالت اليوم من أشهر القلاع.","28":"K-4a. ينقل الغوتي ملكه إلى اليمين. كل جانب يحمي ملكه في الجناح المقابل، فسيدور القتال بعيدًا عن الملكين.","29":"G-6g. يصعد الذهبي ويكاد شكل الياغورا يكتمل.","31":"B-7i. يسحب السِّنتي الفيل إلى الخلف. هذا يُخلي 8h للملك، وسيذهب الفيل لاحقًا إلى 6h ليهاجم على قطر.","33":"K-8h. يدخل الملك إلى الياغورا. من الآن فصاعدًا ستحسم متانةُ كل ملك المباراة.","35":"G-7h. ينضم الذهبي الآخر وتكتمل قلعة ياغورا: الفضّي في 7g والذهبيان في 6g و7h والملك في 8h. شكل متين.","36":"N-7c. يقفز الغوتي بحصانه الأيسر ليصوّب على 6e. الحصان هو القطعة المناسبة تمامًا لمهاجمة فضّي ياغورا الخصم.","37":"S-4h. يسحب السِّنتي الفضّي من 5g إلى 4h. الخطة أن يدير هذا الفضّي إلى اليمين عبر 3g حتى 2f ويهاجم على العمودين 2 و3. يبدو التفافًا، لكنه طريقة مهمة لجمع القطع المهاجمة.","38":"R-8d. يرفع الغوتي رخه خانة واحدة ليستطيع التحرك جانبيًا أيضًا: «رخ عائم».","41":"S-3g. يصل الفضّي إلى 3g. السِّنتي الآن جاهز لصدم البيادق على العمود 3 وبدء الهجوم.","43":"P-3e. يبدأ الهجوم. يدفع السِّنتي بيدق العمود 3 نحو بيدق الغوتي ليكسر الدفاع أمام الفضّي في 4c والفيل في 3c.","44":"Px3e. يأسر الغوتي البيدق.","45":"S-2f. يذهب الفضّي إلى 2f. بعد ذلك يريد أن يأسر في 3e بالفضّي ويدفعه إلى الأمام.","46":"S-3d. يرفع الغوتي فضّيًا ليحمي البيدق في 3e. تتحدّق فضّيات الجانبين ببعضها على العمود 3.","47":"R-3h. ينتقل الرخ إلى العمود 3. يجمع السِّنتي الفضّي والرخ على العمود 3 ليخترق من هناك.","50":"P-6e. يبدأ الغوتي هجومًا معاكسًا في الجهة الأخرى. يدفع بيدق العمود 6 نحو بيدق السِّنتي مصوّبًا على فضّي الياغورا وذهبيها. الآن يهاجم كل جانب من الجهة التي يحبها أكثر: معركة مفعمة بالحيوية.","51":"Px6e. يأسر السِّنتي البيدق.","52":"Nx6e. يأسر الغوتي بالحصان من 7c، فيحط الحصان في 6e. يصوّب هذا الحصان على الفضّي في 7g والخانة 5g، وهو قطعة مزعجة جدًا للسِّنتي.","53":"Sx3e. لا يتراجع السِّنتي أيضًا: يأسر الفضّي البيدق في 3e ويتقدم. ترك حصان الغوتي وشأنه وتقديم هجومه الخاص نقلة جريئة.","54":"Sx3e. يأسر فضّي الغوتي الفضّي.","55":"Rx3e. يأسر الرخ ردًّا. تبادل الجانبان الفضّيين وخرج رخ السِّنتي حتى 3e.","56":"P*3d. يُسقط الغوتي بيدقًا ليسد طريق الرخ.","57":"R-3h. يعود الرخ إلى مكانه. أين سيستعمل السِّنتي الفضّي الذي كسبه؟ هذا ما سنراه.","58":"P-7e. يدفع الغوتي بيدق العمود 7 ليضرب رأس ياغورا السِّنتي. ومع الحصان في 6e يتجمع هجوم الغوتي قرب ملك السِّنتي.","59":"S-6f. يرفع السِّنتي الفضّي من 7g إلى 6f ويهاجم الحصان في 6e. إنها نقلة تدافع وتحاول في الوقت نفسه إزالة قطعة مهاجمة.","60":"S-6d. يرفع الغوتي فضّيًا ليحمي الحصان في 6e.","61":"P*3e. يُسقط السِّنتي بيدقًا على العمود 3 من جديد مصوّبًا على البيدق في 3d.","62":"Px7f. يتقدم بيدق الغوتي ويأسر بيدق السِّنتي في 7f. اختفى البيدق الذي أمام ياغورا السِّنتي، وصار حول الملك شيء من التيار الهوائي.","63":"Px3d. يأسر السِّنتي البيدق في 3d. هذا البيدق يقف الآن قرب ملك الغوتي، وسيؤدي لاحقًا عملًا كبيرًا.","64":"S-7e. يذهب فضّي الغوتي إلى 7e. يهاجم الفضّي في 6f ويضغط أكثر على معسكر السِّنتي.","65":"P-4e. يدفع السِّنتي بيدق العمود 4 نحو بيدق الغوتي في 4d. إنه يُضعف شيئًا فشيئًا البيادق التي تحمي معسكر الغوتي.","66":"Sx6f. يأسر فضّي الغوتي الفضّي في 6f. بحسب ذكاء الشوغي الاصطناعي في هذا الموقع، اللعب هنا أسهل للغوتي، أي لسومين. يضغط الحصان في 6e والفضّي في 7e على ملك السِّنتي، ويصعب على السِّنتي الموازنة بين الدفاع والهجوم.","67":"Gx6f. يأسر السِّنتي ردًّا بالذهبي. يصل الذهبي إلى الوسط ويحدّق في الحصان في 6e.","68":"S*7e. يُسقط الغوتي فضّيًا من يده ليصوّب على الذهبي في 6f.","69":"Gx6e. يأسر ذهبيُّ السِّنتي الحصانَ في 6e. يزيل السِّنتي حصان الغوتي المهاجم ويكسب قطعة.","70":"P-8f. يدفع الغوتي بيدق العمود 8 ليضرب رأس ملك السِّنتي.","71":"Gx7e. يأسر الذهبي الفضّي في 7e. ذهبيُّ السِّنتي يؤدي عملًا رائعًا.","72":"Bx7e. يستعيد الغوتي الذهبي بالفيل من 4b. يصوّب هذا الفيل على معسكر السِّنتي عبر قطر طويل.","73":"Bx8f. يأسر فيل السِّنتي من 6h البيدق في 8f. يواجه فيل الغوتي ويعرض تبادل الفيلين.","74":"Bx8f. يبادل الغوتي الفيلين.","75":"Px8f. يأسر السِّنتي ردًّا بالبيدق. بهذه التبادلات كسب السِّنتي فضّيات وفيلًا، ويرى ذكاء الشوغي الاصطناعي في هذا الموقع المباراة متعادلة تقريبًا من جديد. لكن مع الغوتي أيضًا فيل في يده، وهو يتقدم نحو ملك السِّنتي.","76":"B*6f. يُسقط الغوتي الفيل ليصوّب على محيط ملك السِّنتي. يشير هذا الفيل نحو الملك في 8h وهو قاعدة الهجوم التالي.","77":"P*7g. يُسقط السِّنتي بيدقًا ليقطع خط الفيل.","78":"P*8g. يُسقط الغوتي بيدقًا في 8g ويضغط على رأس ملك السِّنتي.","79":"Gx8g. يأسر السِّنتي البيدق بالذهبي. لكن لأن الذهبي ذهب إلى 8g صارت الخانة 7h فارغة.","80":"S*6g. يُسقط الغوتي فضّيًا بجانب ملك السِّنتي مباشرة. إذا تابع الغوتي بنقلة مثل S-7h+ فسيكون ملك السِّنتي في خطر حقيقي. عادةً هذه هي اللحظة التي يُفكَّر فيها بالدفاع.","81":"N*3e. هذه ذروة المباراة، نقلة سوكان الشهيرة. بدلًا من الدفاع أسقط حصانًا في 3e قرب ملك الغوتي. بعد ذلك يهدد الحصان بالقفز إلى معسكر الغوتي بـ N-4c+ أو N-2c، ولا يمكن أسره لأن الرخ في 3h يحميه من الخلف. وفوق ذلك، بيدق السِّنتي في 3d يمنع الغوتي من طرده ببيدق. ومع أن ملكه هو كان في خطر، وجد سوكان هجومًا أسرع بخطوة من هجوم خصمه، ويُروى أن الميجين الخامس عشر أوياما ياسوهارو وصفها لاحقًا بأنها «نقلة عبقرية».","82":"G-4b. يسحب الغوتي الذهبي من 4c إلى 4b استعدادًا لقفزة الحصان.","83":"S*4c. يُسقط السِّنتي فضّيًا من يده في 4c مصوّبًا على الذهبي في 3b. يصل الحصان في 3e إلى 4c، فهذا الفضّي مسنود من الخلف.","84":"Px7g+. يهاجم الغوتي أيضًا. يأسر البيدق في 7g ويصنع توكين ويضغط على ملك السِّنتي.","85":"Nx7g. يأسر السِّنتي التوكين بالحصان.","86":"P*7f. يُسقط الغوتي بيدقًا ليهاجم الحصان في 7g. يحاول الغوتي نزع القطع المحيطة بملك السِّنتي واحدة تلو الأخرى.","87":"Sx3b+. يأسر فضّيُّ السِّنتي الذهبيَّ في 3b ويترقّى. ذهب أحد الذهبيين اللذين يحرسان ملك الغوتي.","88":"Gx3b. يستعيد الغوتي الفضّي المترقّي بالذهبي من 4b.","89":"B*5c. يُسقط السِّنتي فيلًا من يده في 5c. لأن الذهبي ذهب من 4b إلى 3b، صار القطر من 5c عبر 4b إلى 3a مفتوحًا، فهذه كِشّة. يجب على الغوتي أن يسدّها بقطعة.","90":"S*4b. يُسقط الغوتي فضّيًا ليقطع خط الفيل.","91":"S*4c. يُسقط السِّنتي فضّيًا آخر في 4c مصوّبًا مرة أخرى على الذهبي في 3b.","92":"G*5b. يُسقط الغوتي ذهبيًا يهاجم الفيل في 5c ويقوّي الدفاع.","93":"N-2c. الحصان الذي أُسقط في 3e في النقلة 81 يقفز أخيرًا إلى الداخل. عدم الترقية هو المفتاح: الحصان غير المترقّي ما زال يصل إلى 3a، فهذه كِشّة. أما الحصان المترقّي فيتحرك كالذهبي ولا يصل إلى 3a، فلن تكون كِشّة.","94":"K-2b. يهرب ملك الغوتي إلى 2b.","95":"Sx3b+. يأسر الفضّي في 4c الذهبي في 3b ويترقّى.","96":"Kx3b. يأسر الغوتي الفضّي المترقّي بالملك. خرج الملك إلى 3b ولم يبقَ له تقريبًا أي مدافع.","97":"G*3c. إسقاط ذهبي مع كِشّة يطرد ملك الغوتي إلى الخارج.","98":"Nx3c. يأسر الغوتي الذهبي بالحصان.","99":"Px3c+. يأسر البيدق في 3d الحصان ويصبح توكين. البيدق الذي أسره السِّنتي في النقلة 63 يؤدي هنا عملًا كبيرًا.","100":"Sx3c. يأسر الغوتي التوكين بالفضّي.","101":"B-3a+. يقفز الفيل من 5c إلى 3a ويترقّى إلى حصان تنين ويعطي كِشّة. هنا استسلم سومين. حتى حين كان ملكه هو في خطر لم يتحول سوكان إلى الدفاع؛ بدءًا من N*3e طارد ملك الغوتي دفعة واحدة. بعد ثلاث سنوات، سنة 1728، صار سوكان الميجين السابع في الثالثة والعشرين، وفي سنة 1734 قدّم إلى حكومة الشوغون مجموعته من مسائل الكِش مات «شوغي موسو». أما الخاسر سومين فحمل لاحقًا اسم أوهاشي سويو الرابع وواجه الميجين سوكان مرات كثيرة. وما زالت النقلة N*3e التي وُلدت من مبارزة هذين الشابين تُروى بوصفها نقلة يُعجب بها المحترفون اليوم."}},"alekhine1930":{"t":"مدفع أليخين","w":"ألكسندر أليخين","b":"آرون نيمزوفيتش","ev":"بطولة سان ريمو الدولية، الجولة الثالثة","d":"يناير 1930","pl":"إيطاليا (سان ريمو)","lead":"بطل العالم أليخين يضيّق على معسكر خصمه شيئًا فشيئًا حتى يفوز. في النهاية يصفّ الأبيض رخّين والوزير واحدًا خلف الآخر على العمود c، وهو تشكيل سُمّي لاحقًا «مدفع أليخين». يستسلم الأسود قبل أن يخسر أي قطعة، لأنه لم يبقَ لأي من قطعه نقلة جيدة. بعض السجلات تُكمل المباراة بضع نقلات أخرى قبل أن تنتهي.","c":{"0":"يناير 1930، سان ريمو، مدينة ساحلية في إيطاليا. هذه الجولة الثالثة من بطولة دوري كامل تضم 16 لاعبًا. الأبيض: ألكسندر أليخين، بطل العالم منذ أن هزم كابابلانكا عام 1927. الأسود: آرون نيمزوفيتش، المفكّر الذي نشر أفكارًا جديدة في كتابه «نظامي» عام 1925. فاز أليخين بهذه البطولة بنتيجة مذهلة: 14 نقطة من 15 مباراة (13 فوزًا وتعادلان). في نهاية هذه المباراة سترى «مدفع» الأبيض مصفوفًا على العمود c.","1":"يلعب الأبيض e4. تأخذ النقلة مربعًا في الوسط وتفتح الطريق للوزير والفيل: إنها أكثر نقلة أولى لُعبت منذ زمن بعيد. وُلد أليخين في عائلة ثرية في موسكو، وغادر روسيا بعد الثورة، ثم صار مواطنًا فرنسيًا.","2":"يلعب الأسود e6: هذا هو الدفاع الفرنسي. يُقال إن الاسم جاء من مباراة بالمراسلة بين لندن وباريس نحو عام 1834، فاز بها فريق باريس بهذه النقلة. كان نيمزوفيتش أستاذًا في هذا الدفاع.","3":"يلعب الأبيض d4. يبني بيدقا e4 وd4 جدارًا كبيرًا في الوسط. في الدفاع الفرنسي، مهمة الأبيض هي إبقاء هذين البيدقين مدعومين.","4":"يلعب الأسود d5. يضرب بيدق e4 فورًا ويجبر الأبيض على الاختيار: الأخذ أو الحماية أو التقدّم. هذا هو الوضع الأساسي للدفاع الفرنسي.","5":"الحصان إلى c3. إنها الطريقة الأكثر طبيعية لحماية بيدق e4. الآن يختار الأسود نقلة تقيّد هذا الحصان.","6":"يلعب الأسود ♗b4: متغيّر فيناور، المسمّى باسم الأستاذ البولندي من القرن التاسع عشر شيمون فيناور. يثبّت الفيل حصان c3 أمام الملك ويُضعف حمايته لـ e4. كان تقييد قطع الخصم الخطة المفضّلة لدى نيمزوفيتش.","7":"يلعب الأبيض e5. يتقدّم البيدق حتى لا يستطيع الحصان الأسود المجيء إلى f6. يشكّل بيدقا الأبيض في d4 وe5 الآن «سلسلة بيادق» مائلة. في «نظامي» علّم نيمزوفيتش أن مثل هذه السلسلة تُهاجَم من قاعدتها.","8":"يلعب الأسود c5. كما يقول كتابه تمامًا، يهاجم d4، قاعدة السلسلة. هذا أكثر هجوم مضاد شيوعًا للأسود في الدفاع الفرنسي.","9":"يلعب الأبيض ♗d2. اليوم النقلة 5.a3 أكثر شيوعًا، وهي تجبر الفيل على الأخذ أو التراجع، لكن الأبيض يعرض بهدوء تبادل الفيلين. لاحقًا عُرف هذا الخط أيضًا باسم بوغولوبوف. يريد الأبيض القتال دون إفساد بنية بيادقه.","10":"يلعب الأسود ♘e7. سيذهب الحصان لاحقًا إلى c6 أو f5، وهو ترتيب نموذجي في الدفاع الفرنسي. مربع f6 يسيطر عليه بيدق e5، لذا يسلك الحصان هذا الطريق.","11":"يلعب الأبيض ♘b5! نقلة نادرة: يهاجم الحصان الفيل ويتّجه نحو d6. مربع d6 يحميه بيدق e5 ولا يستطيع أي بيدق أسود طرد قطعة منه: إنه «ثقب». كان أليخين يحب أن يُشغل خصومه بالتفكير بنقلات مفاجئة خارج النظرية المعتادة.","12":"يلعب الأسود ♗xd2+. قبل أن يُؤخذ فيله، يبادله بالفيل الأبيض. بهذا يتخلّى الأسود عن القطعة التي كانت تثبّت على القطر.","13":"يلعب الأبيض ♕xd2. يأخذ الوزير ويقف في مربع يعمل فيه جيدًا. يواصل الأبيض خطته في استهداف d6.","14":"يبيّت الأسود. ينتقل الملك إلى الأمان في g8. لأن الوسط مغلق، يقوّي الأسود دفاعه أولًا.","15":"يلعب الأبيض c3. تدعم النقلة بيدق d4 وتُعدّ لـ b4 لاحقًا. لم يبيّت الأبيض بعد، لكن مع الوسط المغلق لا عجلة لدى ملكه.","16":"يلعب الأسود b6 استعدادًا لإخراج فيل c8 إلى a6. في الدفاع الفرنسي يُسدّ هذا الفيل ببيادقه نفسها ويُسمّى «الفيل السيئ». يريد الأسود مبادلته بقطعة بيضاء جيدة.","17":"يلعب الأبيض f4. يحصل بيدق e5 على مدافع ثانٍ، وتضعف دفعة الأسود المضادة f6. ثبّت الأبيض الوسط بقوة كبيرة.","18":"يلعب الأسود ♗a6. الفكرة هي مبادلة الفيل السيئ بحصان b5 أو بفيل f1. نقلة منطقية، على طريقة نيمزوفيتش تمامًا.","19":"يلعب الأبيض ♘f3. يخرج الحصان الأخير لدعم d4 وe5. لا يزال الأبيض يرفض تبادل الفيلين.","20":"يلعب الأسود ♕d7. الوزير أيضًا يستهدف حصان b5. إن أخذ الأسود بعدها بـ ♗xb5، فسيضطر الأبيض إلى الاسترداد ببيدق أو بالفيل.","21":"يلعب الأبيض a4. إن جاء ♗xb5 فإن axb5 يفتح العمود a ويكسب مساحة كبيرة في جناح الوزير. بدأت البطولة في 16 يناير من ذلك العام واستمرت حتى 4 فبراير. كانت مسرحًا كبيرًا لأليخين بصفته بطل العالم الجديد.","22":"يلعب الأسود ♘bc6. يخرج الحصان الآخر ويراقب b4 وd4. لا يستعجل الأسود تبادل الفيلين ويدافع عن الوسط بعدد القطع.","23":"يلعب الأبيض b4! يدفع بيادق جناح الوزير ويوسّع المعركة هناك. فتح الخطوط في الجهة التي لديك فيها قطع أكثر يكبّر أفضليتك.","24":"يلعب الأسود cxb4. إن لم يأخذ، يضغط الأبيض أكثر بـ b5 أو c5؛ لذا يأخذ، فتنفتح الخطوط.","25":"يلعب الأبيض cxb4. الآن العمود c مفتوح من أعلاه إلى أسفله. سيكون هذا العمود مسرح المعركة كلها. بيدق b4 يسيطر أيضًا على c5 وa5.","26":"يلعب الأسود ♗b7 ويسحب الفيل. ربما ظنّ أن التبادل في b5 سيمنح الأبيض لعبًا قويًا على العمودين a وc. لكن الحصان الأبيض يتجه مباشرة إلى هدفه التالي.","27":"يلعب الأبيض ♘d6! يدخل الحصان ثقب d6 الذي كان يقصده. لا يستطيع أي بيدق أسود طرده. ينظر إلى فيل b7 ويجثم كالعملاق في وسط معسكر الأسود.","28":"يلعب الأسود f5. يوقف بيادق جناح الملك ويمنع هجوم الأبيض f4-f5. لكن بيدق e6 لن يستطيع التحرك أبدًا بعد الآن، ويتجمّد معسكر الأسود أكثر.","29":"يلعب الأبيض a5. يدفع مرة أخرى ويهزّ بيدق b6. يواصل الأبيض التضييق على الأسود في جناح الوزير.","30":"يلعب الأسود ♘c8. ينطلق الحصان ليتبادل مع حصان d6. هذا الحصان الأبيض القوي هو أكثر قطعة تزعج الأسود.","31":"يلعب الأبيض ♘xb7. قبل أن يُبادَل، يأخذ الأبيض بنفسه فيل الأسود الجيد. الآن فقد الأسود القطعة التي كانت تحرس المربعات الفاتحة.","32":"يلعب الأسود ♕xb7 ويسترد بالوزير. المادة متساوية، لكن الفيل الأبيض يستطيع الآن مهاجمة مربعات الأسود الفاتحة الضعيفة.","33":"يلعب الأبيض a6! يضرب البيدق الوزير ويجمّد بيدق a7. مربعات مثل b7 وc6 تصير للأبيض شيئًا فشيئًا.","34":"يلعب الأسود ♕f7. يتراجع الوزير إلى جناح الملك. لم يبقَ له تقريبًا مكان في جناح الوزير.","35":"يلعب الأبيض ♗b5. يسافر الفيل عبر المربعات الفاتحة وينظر إلى حصان c6. سيضطر الأسود إلى استخدام قطع كثيرة لحراسة c6.","36":"يلعب الأسود ♘8e7. الحصان الآخر يحمي c6. تتجمّع قطع الأسود واحدة تلو الأخرى في مربعات سلبية.","37":"يبيّت الأبيض أخيرًا. مع الوسط المغلق لم تكن هناك عجلة. ومع ملك آمن يستطيع الرخ دخول المعركة.","38":"يلعب الأسود h6. يصنع مربع هروب قرب الملك تحسبًا لهجوم الأبيض على جناح الملك. لكنها ليست خطة حقيقية.","39":"يلعب الأبيض ♖fc1. يدخل الرخ العمود c المفتوح. من الآن تتجمّع قطع الأبيض على العمود c واحدة تلو الأخرى.","40":"يلعب الأسود ♖fc8. يضع الأسود أيضًا رخًّا على العمود c لحراسة c6 وc7. يبدأ شدّ الحبل على العمود c.","41":"يلعب الأبيض ♖c2. يصعد الرخ مربعًا واحدًا ليترك مكانًا لقطعة أخرى خلفه. تتضح خطة رصّ القطع على العمود.","42":"يلعب الأسود ♕e8. الوزير أيضًا يأتي لحراسة c6. يدافع الأسود الآن عن c6 بحصانين والوزير ورخ.","43":"يلعب الأبيض ♖ac1. الرخ الثاني يصل أيضًا إلى العمود c. صار هناك رخّان أبيضان مرصوصان عليه.","44":"يلعب الأسود ♖ab8. يذهب رخّه إلى العمود b وينظر إلى بيدق b4. يبحث الأسود عن طريقة للهجوم المضاد في جناح الوزير.","45":"يلعب الأبيض ♕e3. يتنحّى الوزير لحظة ليشقّ طريقه إلى ما خلف الرخّين. من هنا يعيد الأبيض ترتيب قطعه ببطء.","46":"يلعب الأسود ♖c7. الرخ في c7 يحرس c6 مرة أخرى. إنه يستعدّ لرصّ الأبيض قطعه على العمود c.","47":"يلعب الأبيض ♖c3. يخرج الرخ الأمامي إلى c3. الآن صار c2 وc1 فارغين، فيستطيع الوزير الوقوف خلفهما.","48":"يلعب الأسود ♕d7. يبقى الوزير قرب c6 وc7 ليحافظ على عدد المدافعين. تقريبًا كل قطع الأسود تعمل الآن على حراسة c6.","49":"يلعب الأبيض ♖1c2. يصعد الرخ الخلفي إلى c2. في الأمام c3، وخلفه c2، والمربع الفارغ c1 للوزير.","50":"يلعب الأسود ♔f8. يمشي الملك نحو جناح الوزير لينضمّ إلى الدفاع. الأسود مضغوط إلى حد أن ملكه نفسه يجب أن يدافع.","51":"يلعب الأبيض ♕c1. رخ c3 ورخ c2 والوزير في c1 يقفون الآن في صف واحد على العمود c. هذا هو التشكيل الذي سُمّي لاحقًا «مدفع أليخين». وجد المؤرخون أن الاسم لا يظهر في الكتب إلا منذ تسعينيات القرن العشرين، ويُقال إن كتبًا روسية أقدم سمّته «ترتيب أليخين». عندما تُرصّ الرخاخ والوزير على عمود واحد، تستطيع القطع الخلفية الاسترداد إذا أُخذت الأمامية، فتضغط على مربع بقوة كبيرة.","52":"يلعب الأسود ♖bc8. يضع هو أيضًا رخّه الأخير على العمود c لحراسة c6 وc7. بالعدّ، كل شيء محمي، لكن قطع الأسود بالكاد تستطيع الحركة.","53":"يلعب الأبيض ♗a4. الفكرة هي b5 في النقلة التالية، مهاجمًا حصان c6. يقف الحصان أمام رخ c7؛ فإن هرب أخذ رخ c3 في c7.","54":"يلعب الأسود b5. يعطي بيدقًا ليوقف b5 الأبيض. بأي نقلة أخرى كان الأبيض سيكسب الحصان بـ b5.","55":"يلعب الأبيض ♗xb5. يأخذ البيدق، ويعود الفيل للنظر إلى c6 وe8. للأبيض بيدق زائد والكمّاشة مستمرة.","56":"يلعب الأسود ♔e8. يتجه الملك إلى d8 ليحمي رخ c7. ليس لدى الأسود أفضل من أخذ ملكه نحو الوسط الخطير.","57":"يلعب الأبيض ♗a4. يعود الفيل ويهدّد مجددًا بدفع بيدق إلى b5. هذه المرة طريق بيدق b4 إلى b5 مفتوح.","58":"يلعب الأسود ♔d8. الآن يحمي الملك c7. فإن جاء b5، يستطيع الحصان مغادرة c6.","59":"يلعب الأبيض h4: مجرد خطوة بيدق، نقلة انتظار. لكن الأسود لم تبقَ له تقريبًا أي نقلة. إن تحرّك الوزير أو حصان لم يصمد c6؛ وإن تحرّك رخ انهار العمود c؛ وإن تحرّك الملك ضعف c7. يُقال إن نقلات بيادقه القليلة كانت ستنفد قريبًا أيضًا، فاستسلم نيمزوفيتش هنا. الوضع الذي يصبح فيه الاضطرار إلى النقل خسارة بحد ذاته يُسمّى «تسوغتسفانغ». بعد البطولة، ضمّ أليخين إلى مجموعة أفضل مبارياته سبع مباريات كاملة من هذه البطولة."}},"ck1992g8":{"t":"شينوك يهزم تينسلي","w":"شينوك (حاسوب)","b":"ماريون تينسلي","ev":"المباراة الثامنة من بطولة العالم للداما «الإنسان ضد الآلة» (لقاء من 39 مباراة)","d":"19 أغسطس 1992","pl":"المملكة المتحدة (لندن)","lead":"لقاء من 39 مباراة بين ماريون تينسلي، البطل البشري الذي لم يكد يخسر طوال أكثر من 40 عامًا، وبرنامج «شينوك» الذي صُنع في جامعة ألبرتا بكندا. في المباراة الثامنة هزم شينوك تينسلي لأول مرة. ويقال إنها أول مرة يهزم فيها حاسوب بطل عالم بشريًا في لقاء على لقب عالمي في رياضة ذهنية. ومع ذلك فاز تينسلي باللقاء: 4 انتصارات وهزيمتان و33 تعادلًا.","c":{"0":"19 أغسطس 1992، فندق بارك لين في لندن: المباراة الثامنة من بطولة «الإنسان ضد الآلة» ذات الـ39 مباراة. في هذه الداما يبدأ الأسود؛ قطعه في الأعلى على المربعات 1–12، وقطع الأبيض في الأسفل على 21–32. هنا يلعب شينوك بالأسود، والبطل ماريون تينسلي، وهو عالم رياضيات، بالأبيض. المربعات الداكنة مرقمة من 1 إلى 32، وتُكتب النقلة بمربع البداية ومربع النهاية مثل 11-15. ويُكتب الأكل بحرف x، وفي الأكل المتتابع يُكتب كل مربع تهبط فيه القطعة.","1":"ينقل شينوك من 11 إلى 15. إنها أشهر نقلة افتتاحية نحو الوسط، وتُلقب منذ زمن بعيد «أولد فيثفول» (الوفي القديم). بدأ فريق بقيادة جوناثان شيفر صنع شينوك عام 1989 في جامعة ألبرتا بكندا. وفي الافتتاح كان يلعب من كتاب نقلات جُمعت من مباريات البشر.","2":"ينقل الأبيض من 23 إلى 18، ملاصقًا للقطعة على 15 وجهًا لوجه. يسمى الافتتاح 11-15 23-18 «الصليب» (Cross). وُلد تينسلي عام 1927 في ولاية أوهايو الأمريكية، وكان أستاذًا للرياضيات يبحث في التوافقيات.","3":"يلعب الأسود 10-14، فتصبح النقلات الثلاث الأولى 11-15 23-18 10-14. وحتى لا تكثر التعادلات، كثيرًا ما تُسحب النقلات الثلاث الأولى بالقرعة في البطولات («قيد النقلات الثلاث»)، وهذه النقلات الثلاث إحدى تلك القرعات (ballots). وتستخدم بطولة الولايات المتحدة هذا القيد منذ 1934.","4":"يأكل الأبيض 18x11 قافزًا فوق القطعة على 15. في الداما يجب الأكل متى أمكن. هذه هي النقلة الوحيدة: حتى الآن يسير الطرفان في طريق إجباري.","5":"يرد الأسود الأكل 8x15 فيتساوى العدد من جديد. كان 7x16 ممكنًا أيضًا، لكن محرك هذا الموقع يراه أسوأ بوضوح. تصعد القطعة من 8 وتمسك المربع الأوسط 15 مرة أخرى.","6":"يلعب الأبيض 22-17. يذكر أحد كتب الافتتاحات هنا 26-23 خطًا رئيسيًا، يصل إلى الوضع نفسه في افتتاح آخر (10-14 22-18 11-15). اختار تينسلي 22-17 وخرج عن الخط الرئيسي. ويقال إن طاولة هذا اللقاء هي نفسها التي استُخدمت في بطولة العالم للشطرنج بين كاسباروف وكاربوف عام 1986.","7":"يلعب الأسود 14-18، خطوة داخل معسكر الأبيض، مستهدفًا الفجوة قرب 22 و23. القطعة على 18 شوكة للأبيض، وعليه أن يفكر في طريقة لطردها.","8":"يلعب الأبيض 24-19 ويترك نفسه للأكل كي تتبادل القطع. يزيل التبادل قطعة الأسود على 15 من الوسط وينظم صف الأبيض.","9":"يأكل الأسود 15x24. الأكل إجباري، فلا نقلة غيرها.","10":"يرد الأبيض الأكل 28x19. كان 27x20 ممكنًا أيضًا، لكن المحرك يراه أسوأ. تقف القطعة القادمة من 28 على 19 وتمسك الوسط من جديد.","11":"يلعب الأسود 7-11 ويقدم قطعة خلفية لدعم 18 و15. في الداما من المهم إبقاء القطع متجمعة كي تحمي بعضها.","12":"يلعب الأبيض 17-14، نقلة جريئة تتوغل في الفجوة التي تركتها قطعة الأسود على 10. تنغرس القطعة على 14 في معسكر الأسود وتقيد قطع جناحه الأيسر.","13":"يلعب الأسود 11-16 فيتمدد إلى اليمين ويراقب قطعة الأبيض على 19. بعد هذه النقلة يميل تقدير المحرك قليلًا نحو الأسود.","14":"يلعب الأبيض 19-15 ويدق إسفينًا ثانيًا في وسط معسكر الأسود. قطعتا الأبيض على 14 و15 تسدان طرق الأسود.","15":"يلعب الأسود 4-8 فيرفع قطعة من الصف الأخير ليمنع قطعة الأبيض على 15 من الوصول إلى 11. قطع الصف الخلفي، مثل التي على 4، تمنع الخصم من التتويج، لذا فإن اختيار وقت تحريكها قرار صعب.","16":"يلعب الأبيض 21-17 ويقدم قطعة من الجناح الأيسر ليدعم القطعة على 14 من الخلف.","17":"يلعب الأسود 16-19 متقدمًا نحو معسكر الأبيض وضاغطًا على جناحه الأيمن. تقف القطعة على 19 بين قطعتي الأبيض على 23 و24 وتقلل نقلاتهما.","18":"يلعب الأبيض 17-13 نحو الحافة اليسرى. القطعة على الحافة أصعب أكلًا، لكن اتجاهات حركتها أقل.","19":"يلعب الأسود 12-16 ويضع قطعة خلف 19 ليدعمها بقوة. الآن يمسك الأسود الجناح الأيمن للأبيض بقطعتيه على 16 و19.","20":"يلعب الأبيض 25-21، وهي النقلة التي يقال إنها قادت إلى الخسارة. وضع تقرير المجلة البريطانية الأسبوعية «ذا سبكتيتور» عليها علامة «؟» وذكر أن تينسلي ندم عليها فورًا تقريبًا ورأى أن 26-22 كانت أفضل. ومحرك هذا الموقع أيضًا يرى 26-22 أفضل نقلة هنا. يتفق الرأيان: هنا كانت نقطة التحول.","21":"يلعب الأسود 18-22 ويقدم القطعة لقطعة الأبيض على 26 ليستعيدها بعد ذلك. إنها نقلة لتفكيك صف الدفاع الأبيض.","22":"يأكل الأبيض 26x17. الأكل إجباري، فهذه النقلة الوحيدة.","23":"يرد الأسود الأكل 9x18 فتقف قطعة على 18 من جديد. بعد التبادل صار هذا الإسفين أقوى، وبقيت ثغرات قرب مربعي الأبيض 22 و26.","24":"يلعب الأبيض 29-25 ويرفع قطعة خلفية ليسد الفجوة.","25":"يلعب الأسود 16-20 نحو الحافة اليمنى استعدادًا للتقدم إلى 24. إنه تمهيد للخطة القادمة.","26":"يلعب الأبيض 17-14 ويضع قطعة على 14 من جديد مستهدفًا قطعتي الأسود على 10 و9.","27":"يلعب الأسود 2-7 ويقدم قطعة خلفية لتشارك في الخطة التالية.","28":"يلعب الأبيض 21-17. بحسب المحرك يصبح تفوق الأسود واضحًا بعد هذه النقلة. تقل باستمرار قطع الأبيض القادرة على الحركة بحرية.","29":"يلعب الأسود 19-24. وضع تقرير «ذا سبكتيتور» عليها علامة «!» وسماها مناورة الفوز، وذكر أن الجمهور لم يتوقعها. التقدم إلى 24 يجعل الضربة 7-10 ممكنة بعدها، فينهار الجناح الأيمن للأبيض. وبحسب محرك هذا الموقع أيضًا صار الأسود قريبًا من الفوز.","30":"يلعب الأبيض 30-26. حتى مع المحرك لا تبقى للأبيض نقلة جيدة. لا يستطيع الأبيض إيقاف ما يرمي إليه الأسود.","31":"يلعب الأسود 7-10 ويترك قطعة الأبيض على 14 تأكلها. التضحية بقطعة لاستعادة أكثر منها تسمى في الداما «ضربة» (shot).","32":"يأكل الأبيض 14x7. الأكل إجباري، لا خيار للأبيض.","33":"يقفز الأسود مرتين، 3x10x19: من 3 إلى 10 ثم إلى 19، آكلًا قطعتي الأبيض على 7 و15. صار الأسود متقدمًا بقطعة.","34":"يلعب الأبيض 27-23 ويرد الهجوم: يترك نفسه للأكل كي يقفز هو مرتين بعد ذلك.","35":"يأكل الأسود 18x27. هذا الأكل إجباري أيضًا.","36":"يقفز الأبيض مرتين، 32x23x16، فيتساوى العدد من جديد. لكن قطع الأسود قريبة من صف تتويج الأبيض (29–32)، ويبدو أن الأسود سيتوّج أولًا.","37":"يلعب الأسود 24-27 ويترك قطعة الأبيض على 31 تأكل، ليرد بالأكل بقطعة 20 ويوصل قطعة إلى 27.","38":"يأكل الأبيض 31x24. إنها النقلة الوحيدة.","39":"يرد الأسود الأكل 20x27. قطعة الأسود على 27 على بعد خطوة من صف التتويج، ولم تبق للأبيض قطع خلفية لحراسته.","40":"يلعب الأبيض 26-22. لا يستطيع منع تتويج الأسود، فيدفع قطعته إلى الأمام.","41":"يلعب الأسود 8-12 وينظم قطعه قبل التتويج. يستحسن المحرك أيضًا التتويج فورًا بـ27-31، لكن الأسود يبقى متفوقًا في الحالتين.","42":"يلعب الأبيض 16-11 متوغلًا في معسكر الأسود محاولًا أن يتوّج هو أيضًا.","43":"يلعب الأسود 27-31 ويتوّج أول ملك في المباراة. الملك يتحرك إلى الأمام والخلف، فهو أقوى بكثير من القطعة العادية.","44":"يلعب الأبيض 11-7. من هنا تستطيع القطعة أن تتوّج في النقلة التالية بالذهاب إلى 3 أو 2.","45":"يلعب ملك الأسود 31-26 ويعود فورًا إلى خط المواجهة ليطارد قطع الأبيض.","46":"يلعب الأبيض 25-21. قطع الأبيض متكدسة في اليسار، وقليل منها يستطيع الحركة بحرية.","47":"يلعب الأسود 26-30 ويسحب الملك لحظة ليراقب الأبيض. لا يستعجل، بل ينتظر حتى تنفد نقلات الأبيض المفيدة.","48":"يلعب الأبيض 22-18.","49":"يلعب ملك الأسود 30-26 ويتقدم من جديد ليهاجم من الخلف قطعتي الأبيض على 18 و21.","50":"يلعب الأبيض 18-14. بحسب تقرير «ذا سبكتيتور» استسلم تينسلي بعد هذه النقلة دون أن ينتظر رد الأسود. ويضيف التقرير أن شينوك كان يستطيع فرض الفوز من هنا.","51":"في سجل فريق شينوك نفسه آخر نقلة هي 26-22، والمباراة فوز لشينوك. ويقال إن تينسلي لم يخسر سوى سبع مباريات في 45 عامًا منذ 1950، اثنتان منها أمام شينوك في هذا اللقاء. ومع ذلك فاز تينسلي بعدها بأربع مباريات وكسب اللقاء 4–2 مع 33 تعادلًا. واصل فريق شينوك أبحاثه، وأعلن عام 2007 أنه أثبت أن الداما تنتهي بالتعادل إذا لعب الطرفان بلا خطأ."}},"logistello1997":{"t":"لوجيستيلو يكتسح بطل العالم","w":"لوجيستيلو (حاسوب)","b":"تاكيشي موراكامي","ev":"المباراة السادسة من مواجهة من ست مباريات بين تاكيشي موراكامي ولوجيستيلو","d":"7 أغسطس 1997","pl":"الولايات المتحدة (برينستون، معهد NEC للأبحاث)","lead":"في أغسطس 1997 خاض بطل العالم في الريفيرسي تاكيشي موراكامي مواجهة من ست مباريات أمام لوجيستيلو، وهو برنامج كتبه ميخائيل بورو. فاز لوجيستيلو بالمباريات الخمس الأولى، ثم بالسادسة 37–27، لتنتهي المواجهة 6–0. كانت هذه أقرب مباريات المواجهة. تابِعها نقلةً نقلة، من الافتتاحيات المسمّاة النمر وروز-بيل والسمكة الذهبية حتى آخر مربع.","c":{"0":"7 أغسطس 1997، معهد NEC للأبحاث في برينستون بولاية نيوجيرسي: اليوم الأخير من مواجهة من ست مباريات. يلعب بالأسود البرنامج لوجيستيلو، وبالأبيض تاكيشي موراكامي، بطل العالم منذ العام السابق. فاز لوجيستيلو بالمباريات الخمس كلها، ويقاتل موراكامي من أجل فوز واحد. في الريفيرسي تقلب أحجار خصمك بحصرها بين حجرين من أحجارك. يستمر اللعب حتى تمتلئ المربعات الأربعة والستون، ويفوز من يملك أحجارًا أكثر في النهاية.","1":"يبدأ الأسود بـ f5. النقلات الأولى الأربع الممكنة تعطي الشكل نفسه إذا أُدير اللوح أو عُكس، فلا فرق أيّها تُلعب. جرت العادة أن تُكتب المباريات بدءًا من f5، وتُدار المباريات التي تبدأ من مكان آخر عادةً إلى هذا الشكل للمقارنة. كتب لوجيستيلو ميخائيل بورو، وقد وُلد البرنامج من بحثه للدكتوراه في جامعة بادربورن في ألمانيا.","2":"يلعب الأبيض d6. يقف الحجر الأبيض الجديد على خط مستقيم مع الحجر الأسود الذي يأخذه، ولذلك تُسمّى الافتتاحية العمودية، وهي النقلة الثانية الأكثر شيوعًا. والأخريان هما القطرية (f6) والموازية (f4). كان موراكامي آنذاك في الثانية والثلاثين، يدرّس الإنجليزية في طوكيو. ويقال إنه بدأ اللعب عام 1981 في نحو السادسة عشرة.","3":"يلعب الأسود c4. يلعب معظم اللاعبين c3 أولًا، لكن الترتيب هنا مقلوب. حين تأتي c3 بعد نقلتين تصل المباراة إلى وضع معروف جدًا من طريق آخر. الوصول إلى الوضع نفسه بترتيب مختلف يسمّى تبديل الترتيب. استخدم لوجيستيلو «تعلّم الكتاب»: كان يتعلّم باستمرار نقلات الافتتاح من المباريات التي يلعبها.","4":"يلعب الأبيض d3 في وسط صف الأحجار السوداء ويأخذ حجرًا في المركز. لكل طرف أربعة أحجار. في الافتتاح، الأهم بكثير من كثرة الأحجار أن تُبقي لنفسك نقلات كثيرة وتترك لخصمك قليلًا. حلّ موراكامي ثانيًا في بطولة اليابان عام 1987 وصار من أفضل لاعبي البلاد.","5":"بـ c3 تصل المباراة إلى «النمر» الشهير. النمر هو شكل f5 وd6 وc3 وd3 وc4، وهو من أكثر الافتتاحيات لعبًا عند الخبراء والمبتدئين معًا. تتفرّع منه استمرارات كثيرة لكل منها اسمه. وفي مايو من العام نفسه هزم حاسوب ديب بلو من IBM بطلَ العالم في الشطرنج غاري كاسباروف، وكانت مواجهة الآلة والإنسان حديث الجميع.","6":"يلعب الأبيض f4، وهي إحدى الاستمرارات الرئيسية للنمر. يأخذ الأبيض e5 ويكسب موطئ قدم على اليمين. وهناك خط آخر مدروس جيدًا يستمر هنا بـ f6. فاز موراكامي ببطولة اليابان عام 1996، فتأهّل لبطولة العالم في العام نفسه في طوكيو، وفاز بها أيضًا.","7":"يلعب الأسود c5 ويقلب d5 وe5. يصفّ الأسود أحجاره على اليسار ويبدأ في تضييق الأماكن التي يلعب فيها الأبيض. كل ما سبق نظرية افتتاح درسها الطرفان آلاف المرات. أُعلن أن الجائزة 3000 دولار للفائز و1000 للخاسر.","8":"يلعب الأبيض b3، نقلة هادئة لا تقلب إلا حجرًا أسود واحدًا في أعلى اليسار. النقلات التي تقلب أحجارًا قليلة نادرًا ما تمنح الخصم مربعات جديدة، ولذلك تكون غالبًا الأفضل في الافتتاح. كان مدير البطولة ديفيد بارسونز من نيويورك، وهو لاعب ريفيرسي قوي وأستاذ في الشطرنج.","9":"بـ c2 تصل المباراة إلى الخط المسمّى «روز-بيل»: من النمر، f4 ثم c5 ثم b3 ثم c2. يقلب الأسود حجرين في أعلى اليسار ويحبس الأحجار البيضاء في الداخل. نُقلت المباريات أيضًا مباشرة على خادم ألعاب في الإنترنت، ويقال إن لاعبين وبرامج أقوياء من أنحاء العالم كانوا يتابعونها ويعلّقون عليها نقلة بنقلة.","10":"يلعب الأبيض e6، فيقلب d5 وc4 ويعود إلى المركز. النظرية مستمرة: في قوائم الافتتاحيات اليابانية يسمّى الخط القادم «السمكة الذهبية». كان لوجيستيلو يعمل على حاسوب واحد من نوع PentiumPro بسرعة 233 ميغاهرتز، لا يختلف كثيرًا عن حاسوب منزلي عادي في ذلك الوقت.","11":"يلعب الأسود c6 ولا يقلب إلا d5. يتكوّن جدار أسود على اليسار، ويُدفع الأبيض إلى اللعب قرب الحافة اليسرى. إجبار الخصم على اللعب حيث لا يريد فكرة أساسية في الريفيرسي. وفي السنوات الأربع قبل هذه المواجهة شارك لوجيستيلو في 23 بطولة دولية وفاز بـ 17 منها.","12":"يلعب الأبيض b4 ويقلب c5. يلعب بجوار الحافة اليسرى لكن ليس عليها بعد. مربعات العمودين b وg والصفين 2 و7 تقع داخل الحافة مباشرة، والحجر هناك كثيرًا ما يسلّم تلك الحافة للخصم. أول مرة خسر فيها بطل عالم مباراة أمام حاسوب كانت عام 1980، أمام برنامج يسمّى «ذا مور».","13":"يلعب الأسود b5، فيقلب c5 وc4 ويقوّي الجدار الأسود على اليسار. وبوقوعها بين b4 وb3 تنتزع النقلة مزيدًا من خيارات الأبيض. لُعبت المواجهة بوقت تفكير طويل لكل مباراة، حتى لا يكون الإنسان في وضع أضعف من حيث وقت التفكير.","14":"يلعب الأبيض d2 ويقلب أربعة أحجار دفعة واحدة: d3 وd4 وd5 وc3. قلب أحجار كثيرة مبكرًا يمنح الخصم عادةً نقلات أكثر، لكن هذا ما زال من النظرية، ويستعيد الأبيض العمود الأوسط. النتيجة الآن الأبيض 10 والأسود 8، لكن عدد الأحجار في الافتتاح لا يكاد يقول شيئًا عن الفائز.","15":"يلعب الأسود e3 ولا يقلب إلا d4. يواصل الأسود إدخال أحجار منفردة إلى المركز بنقلات هادئة. داخل النظرية لا يحصل أيّ طرف عادةً على أفضلية كبيرة. كان لوجيستيلو يقيّم الأوضاع بإعطاء درجات لأنماط الأحجار على اللوح بأكثر من مليون رقم.","16":"يلعب الأبيض a6: يدخل الحافة اليسرى ويقلب b5 وc4. أحجار الحافة يصعب قلبها من الداخل وقد تصبح قوية. لكن الخروج إلى الحافة مبكرًا جدًا قد يسمح للخصم أيضًا باستغلالها. وكل هذا ما زال خط السمكة الذهبية الذي درسه الأبيض حتمًا مرات كثيرة.","17":"يلعب الأسود c1، يدخل الحافة العليا ويقلب d2. أخذ الأبيض مكانًا على الحافة اليسرى، فيأخذ الأسود مكانًا على العليا: لكل طرف حافة. وفي عام 2023، بعد 26 عامًا من هذه المباراة، أظهر حساب أن الريفيرسي 8×8 تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا.","18":"يلعب الأبيض b6، يقلب c6 ويجمع أحجارًا بيضاء على اليسار. هذه النقلات الثماني عشرة الأولى تطابق الخط المسمّى «السمكة الذهبية» في القوائم اليابانية. سار اللاعبان على طريق مدروس جيدًا. ومن النقلة التالية تخرج المعركة من الكتاب.","19":"يلعب الأسود f3 ويغادر النظرية المعروفة. إنها نقلة هادئة لا تقلب إلا f4 وتمنح الأسود موطئ قدم في أعلى اليمين. على الأبيض الآن أن يبحث بنفسه عن مربع جيد. كان اختيار نقلات تقلب قليلًا وتترك للخصم خيارات أقل من سمات لعب لوجيستيلو.","20":"يلعب الأبيض f6، يقلب e5 وd4 ويتمدّد نحو أسفل اليمين. يحاول الأبيض قلب الأحجار الداخلية حتى لا يعطي نقلات جديدة. لكن كثرة الأحجار البيضاء في الخارج، بجوار المربعات الفارغة، تعطي الأسود أيضًا أماكن للعب.","21":"يلعب الأسود f7 ويقلب f6. ينزل الأسود في اللوح ويغلق الجهة الخارجية للأحجار البيضاء. كلما قلّت أحجارك الملاصقة للمربعات الفارغة وكانت أكثر في الداخل، صعب على الخصم إيجاد نقلات. هذه فكرة جوهرية في الريفيرسي.","22":"يلعب الأبيض e1، يدخل الحافة العليا بجوار c1 الأسود ويقلب d2. يبدأ الصراع على الحواف. ومزيد من الأحجار على الحواف يقود إلى الصراع على الزوايا. الزوايا الأربع أقوى المربعات: الحجر فيها لا يمكن قلبه أبدًا.","23":"يلعب الأسود e2 ويعيد قلب d2. بوقوعه داخل e1 الأبيض مباشرة يصعّب على الأبيض التمدّد على الحافة العليا. الصف الثاني يقود إلى مربعات قرب الزوايا، فيحتاج إلى حذر. ومرة أخرى لا يقلب الأسود إلا حجرًا واحدًا.","24":"يلعب الأبيض f1، يقلب e2 ويضع حجرين أبيضين متجاورين على الحافة العليا. هناك c1 أسود، وe1 وf1 أبيضان. شكل الحافة قد يحسم لاحقًا الصراع على زواياها. يطيل الأبيض الحافة حتى يصعب على الأسود اللعب فيها.","25":"يلعب الأسود e7 ويقلب e6 وe5 وd6. يأخذ الأسود العمود الأوسط ويقلّص المجموعة البيضاء بحصرها. في الأسفل يقف f7 وe7 الأسودان متجاورين، وسيصعب على الأبيض بلوغ الحافة السفلى. النتيجة الأسود 15 والأبيض 14: تكاد تكون متعادلة.","26":"يلعب الأبيض g3، يقلب f3 وe3 ويتمدّد إلى اليمين. العمود g داخل الحافة مباشرة، لكن g3 ليست بجوار زاوية، فلا خطر بعد. يحافظ الأبيض على نقلاته ويهدم موطئ قدم الأسود على اليمين.","27":"يلعب الأسود c7 ويقلب c6. يصل الأسود إلى أسفل اليسار. c7 داخل الحافة لكنها بعيدة عن الزاوية a8، فهي آمنة نسبيًا. وبحسب سجلّ (لوغ) لوجيستيلو، خرج الوضع بعد نقلة الأبيض التالية من كتاب افتتاحياته. وحتى هنا كان على الأرجح يلعب نقلات متعلَّمة.","28":"يلعب الأبيض g4 ويقلب f4 وe4. هنا يخرج الوضع من كتاب لوجيستيلو. من الآن يحسب لوجيستيلو إلى الأمام ويختار كل نقلة بنفسه. تمدّد الأبيض كثيرًا على اليمين، لكن الأحجار البيضاء المواجهة للمربعات الفارغة ازدادت أيضًا.","29":"يلعب الأسود g5 ويقلب f4 وe3. يُظهر سجلّ لوجيستيلو أنه قدّر فرصته في الفوز هنا بـ 57%. يتسلّل الأسود إلى خارج الجدار الأبيض على اليمين ويصعّب على الأبيض بلوغ الحافة اليمنى. أفضلية صغيرة للأسود في حكم الآلة.","30":"يلعب الأبيض d1، يقلب d2 وc2 ويصفّ d1 وe1 وf1 على الحافة العليا. يسعى الأبيض إلى تلك الحافة. لكن كلما طال صف أبيض على حافة، زاد خطر أن يحصره الأسود من الطرفين.","31":"يلعب الأسود g1! يقلب f1 وe1 وd1 ويجعل الحافة العليا كلها سوداء من c1 إلى g1، حاصرًا الصف الأبيض من طرفه بنقلة واحدة. بعد ذلك قدّر لوجيستيلو فرصته في الفوز بـ 68%. لكن g1 بجوار الزاوية h1، فقد يأخذ الأبيض h1 لاحقًا.","32":"يلعب الأبيض f2 ويقلب e3. يدخل الأبيض الصف الثاني داخل الحافة العليا السوداء. هذا يصعّب على الأسود توسيع الحافة ويعطي الأبيض موطئ قدم لأخذ الزاوية h1 لاحقًا. نقلات الأبيض تقلّ شيئًا فشيئًا.","33":"يلعب الأسود h3، يدخل الحافة اليمنى ويقلب g4. الحافة اليمنى تصل الزاويتين h1 وh8 وهي مهمة جدًا. h3 تبعد مربعين عن h1، فلا خطر فوري بخسارة الزاوية. وكان لوجيستيلو ما زال يقدّر فرصته بـ 68%.","34":"يلعب الأبيض h4، يقلب g4 وf4 ويدخل هو أيضًا الحافة اليمنى. يقف h3 الأسود وh4 الأبيض متجاورين، والحافة اليمنى محلّ نزاع. يصمد الأبيض كي لا يتنازل عن الحافة كلها.","35":"يلعب الأسود h5! يقلب h4 وg4 وf3 وe2. في هذه اللحظة حسب لوجيستيلو المربعات الستة والعشرين الباقية حتى النهاية، فوجد أن الأسود يفوز بفارق 6 أحجار مع أفضل لعب. حساب كامل كهذا حتى النهاية فوق طاقة أي إنسان. ومن هنا لم يرتكب لوجيستيلو خطأً واحدًا. لم يعد السؤال هل يستطيع الأبيض الفوز، بل بكم سيفوز الأسود.","36":"يلعب الأبيض c8، يدخل الحافة السفلى ويقلب c7 وc6 وc5. كان لوجيستيلو يتوقّع d8، ويُظهر سجلّه أن c8 وسّعت الفارق مع أفضل لعب بحجرين. اختار الأبيض نقلة تقلب كثيرًا، وربما أعطى الأسود نقلات أكثر من اللازم. ومع ذلك بقي 24 مربعًا، ويقاتل موراكامي حتى النهاية.","37":"يلعب الأسود b1 ويقلب c2 وd3 وe4 قطريًا. تنضمّ b1 إلى الصف الأسود من c1 إلى g1 وتطيل الحافة العليا. b1 بجوار الزاوية a1، لكن الأبيض لا يستطيع لعب a1 إلا إذا أمكن لحجر أبيض حصر الأحجار السوداء على الحافة. وهو لا يستطيع ذلك الآن.","38":"يلعب الأبيض d7 ويقلب d6. في الأسفل يقلب الأبيض الأحجار السوداء واحدًا واحدًا محاولًا صنع نقلات. في نهاية المباراة يقع في الضيق الطرفُ الذي تنفد نقلاته أولًا.","39":"يلعب الأسود h2، يقلب g3 وf4 ويصل الحافة اليمنى من h2 إلى h5. h2 بجوار الزاوية h1 وعادةً ما تكون خطرة. لكن لوجيستيلو حسب حتى النهاية وتأكّد أنه لا يخسر شيئًا حتى لو أخذ الأبيض h1.","40":"يلعب الأبيض e8 ويقلب e7 وe6 وe5 وe4 على العمود. صار للأبيض c8 وe8 على الحافة السفلى، ويترك d8 فارغًا على أمل أن يُضطرّ الأسود إلى اللعب هناك.","41":"يلعب الأسود d8 ويقلب d7 وd6 وd5 وd4 على العمود وكذلك e7: خمسة في المجموع. يدخل بين c8 وe8 ويقلب خطة الأبيض عليه. ويأخذ الأسود أيضًا العمود الأوسط كله ويتقدّم 27 مقابل 18.","42":"يلعب الأبيض g6 ويقلب f6 وf7 وf5. يدخل الأبيض الفراغ في أسفل اليمين ليقلّل نقلات الأسود. الآن تُحسم المباراة حول الزاوية h8.","43":"يلعب الأسود f8 ويقلب e8 وf7 وf6 وf5. يدخل الأسود الحافة السفلى ويأخذ مجموعة من الأحجار البيضاء. ومع c8 وd8 وe8 وf8 تكون اليد العليا للأسود في الأسفل.","44":"يلعب الأبيض g8، يقلب f8 وe8 وd8 وf7 ويستعيد الحافة السفلى: من c8 إلى g8 أبيض. لكن g8 بجوار الزاوية h8. فما إن يستطيع الأسود لعب h8 حتى تصبح هذه الحافة البيضاء كلها سوداء.","45":"يلعب الأسود h6 ويقلب g6. الحافة اليمنى سوداء من h2 إلى h6. يبقى في أسفل اليمين مربعان، h7 وh8. كون عدد المربعات الفارغة في منطقة زوجيًا أو فرديًا يحدّد من يلعب فيها أخيرًا. ويسمّى هذا الزوجية، وهي فكرة أساسية في نهاية المباراة.","46":"يلعب الأبيض g7 ويقلب f6. g7 هو المربع القطري المجاور للزاوية h8، ويسمّى مربع X، واللعب فيه عادةً خطير جدًا. لم يكن لدى الأبيض تقريبًا ما هو أفضل، وربما اضطُرّ إلى اللعب هنا. الآن صار الأسود جاهزًا لأخذ الزاوية h8.","47":"يلعب الأسود a2، يقلب b3 وc4 ويدخل الحافة اليسرى. لا يتعجّل الأسود أخذ h8، بل يستخدم أولًا نقلاته على اليسار. يمكن أخذ الزاوية لاحقًا، وعدم التعجّل هو أسلوب اللعب القوي.","48":"يلعب الأبيض a3، يقلب b3 ويصطفّ هو أيضًا على الحافة اليسرى. a2 أسود، وa3 وa6 أبيضان: يبدأ الصراع على هذه الحافة.","49":"يلعب الأسود a4 ويقلب b4 وa3 وb5 وc6 وb3: خمسة في المجموع. يحصر a3 الأبيض على الحافة ويأخذ معه أحجارًا داخلية. النتيجة الأسود 34 والأبيض 19: تقدّم كبير للأسود.","50":"يلعب الأبيض b7 ويقلب c6 وd5. b7 هو مربع X المجاور للزاوية a8، فتسمح هذه النقلة للأسود بأخذ a8. لم يبقَ للأبيض تقريبًا أي مربع آمن.","51":"يلعب الأسود a8 فيأخذ الزاوية ويقلب b7 وc6 وd5 وe4 قطريًا. حجر الزاوية لا يمكن قلبه أبدًا بعد الآن. ويكسب الأسود أيضًا القطر الطويل من الزاوية ويتقدّم 37 مقابل 18.","52":"يلعب الأبيض b8 ويقلب b7. على الحافة السفلى صار الصف الأبيض بجوار a8 الأسود. يستهلك الأبيض نقلاته القليلة الباقية واحدة تلو الأخرى.","53":"يلعب الأسود b2 ويقلب c3. b2 هو مربع X المجاور للزاوية a1، فتسمح النقلة للأبيض بأخذ a1. حسب لوجيستيلو حتى النهاية ويعلم أن التنازل عن a1 لا يغيّر النتيجة. وعلى الأرجح يرتّب المربعات الباقية ليلعب هو النقلات الأخيرة.","54":"يلعب الأبيض a1 فيأخذ الزاوية ويقلب b2 وc3 وd4. لكن بحسب سجلّ لوجيستيلو كانت a5 أفضل للأبيض بحجرين. الزوايا ثمينة دائمًا، لكن أخذ زاوية في نهاية المباراة ليس صحيحًا دائمًا، وهذا ما يجعل الريفيرسي صعبة. وبهذه النقلة زاد الفارق مع أفضل لعب من 6 إلى 10.","55":"يلعب الأسود h8 فيأخذ الزاوية ويقلب دفعة واحدة ستة أحجار على الحافة السفلى: g8 وf8 وe8 وd8 وc8 وb8. نقلتا الأبيض في g7 وg8 تتحوّلان هنا إلى مكسب للأسود. النتيجة الأسود 42 والأبيض 17.","56":"يلعب الأبيض h1 فيأخذ الزاوية ويعيد قلب ستة أحجار على الحافة العليا: g1 وf1 وe1 وd1 وc1 وb1. الحافة العليا كلها بيضاء. لكل طرف الآن زاويتان: للأسود a8 وh8، وللأبيض a1 وh1.","57":"يلعب الأسود h7، يقلب g7 وf7 ويجعل الحافة اليمنى سوداء من h2 إلى h8 (وh1 بيضاء). في نهاية المباراة تُحسم الحواف والزوايا واحدة بعد الأخرى.","58":"يلعب الأبيض g2 ويقلب f3 وe4 وd5 وc6 قطريًا. لم يبقَ فارغًا سوى مربعين على الحافة اليسرى: a5 وa7.","59":"يلعب الأسود a5 ويقلب b6 وc7. يبقى مربع واحد، a7، ويلعب الأبيض النقلة الأخيرة.","60":"يلعب الأبيض a7 ويقلب b6، فتمتلئ المربعات الأربعة والستون. الأسود 37 والأبيض 27: يفوز لوجيستيلو. انتهت المواجهة 6–0، فوزًا كاملًا للحاسوب على بطل العالم في الريفيرسي. ويقال إن بورو سحب لوجيستيلو من البطولات بعد خمسة أشهر، في يناير 1998. كانت هذه أقرب المباريات الست، وظلّ موراكامي حتى النهاية يقاتل الآلة في صراع شبه متكافئ. وبعد 26 عامًا، في 2023، أظهر الحساب أن الريفيرسي 8×8 تنتهي بالتعادل إذا لعب الطرفان لعبًا مثاليًا."}},"koyasan1948":{"t":"مبارزة جبل كويا: «الوهم سيئ، النظر جيدًا جيد»","w":"ماسودا كوزو","b":"أوياما ياسوهارو","ev":"بطولة ميجين-سين السابعة، نهائي المتحدّين (من ثلاث مباريات)، المباراة 3","d":"مارس 1948","pl":"اليابان (جبل كويا، واكاياما)","lead":"نشأ ماسودا كوزو وأوياما ياسوهارو عند المعلّم نفسه، كأخ أكبر وأخ أصغر. كانت مواجهتهما من ثلاث مباريات على حق تحدّي الميجين تسوكادا ماساو متعادلة، ولُعبت المباراة الأخيرة على جبل كويا حيث كان الثلج ما زال باقيًا. وصل ماسودا إلى موقف رابح، لكنه عند الكِش الأخير اختار مربع هروب خاطئًا لملكه فخسر بعد انقلاب كبير. وما زالت الكلمات التي قالها حينها تُروى في عالم الشوغي حتى اليوم.","c":{"0":"أنا Musowl. وُلد ماسودا كوزو عام 1918 في محافظة هيروشيما، ووُلد أوياما ياسوهارو عام 1923 في محافظة أوكاياما. كلاهما كان تلميذًا لكيمي كينجيرو في أوساكا، وكان ماسودا التلميذ الأقدم، يكبره بخمس سنوات. وكان يُعتقد آنذاك أن ماسودا هو الأقوى. كانت هذه المباراة الثالثة من مواجهة من ثلاث مباريات لتحديد من يتحدّى الميجين تسوكادا ماساو؛ فاز أوياما بالأولى وماسودا بالثانية. بعد ثلاث سنوات من نهاية الحرب كان الطعام ما زال شحيحًا، ويُروى أن الصحيفة المنظِّمة، ماينيتشي، وفّرت مكونات السوكيياكي، ووفّر جبل كويا الأرز الأبيض، وقدّم أحد الداعمين الساكي لتقوم المباراة.","1":"P-2f. يدفع ماسودا البيدق الذي أمام رخه. هذه بداية مباراة «الرخ الثابت» الذي يُستخدم إلى الأمام مباشرة. ويُروى أن ماسودا كتب وهو صبي على ظهر مسطرة أمه عزمه على «هزيمة الميجين ولو أعطاه أفضلية رمح»، ثم غادر البيت.","2":"P-8d. ويدفع أوياما أيضًا بيدق رخه، فيمدّ الطرفان عمودي رخّيهما. وإن استمر الأمر هكذا صارت المباراة معركة «الجناح المزدوج» أو «أخذ البيدق الجانبي».","3":"P-2e. يتقدم بيدق الرخ أكثر. إن لعب سينته بعدها P-2d استطاع تبادل البيادق وإخراج رخه إلى الأمام.","4":"P-8e. يمدّ أوياما بيدقه بالطريقة نفسها. في تلك السنوات التي تلت الحرب مباشرة كانت مباريات الرخ الثابت التي يدفع فيها الطرفان بيادق الرخ هكذا شائعة حتى بين أقوى اللاعبين.","5":"P-7f. يفتح قطر الفيل. الآن يبدأ فيل سينته العمل أيضًا، ويبدأ بناء الافتتاحية فعلًا.","6":"G-3b. يحمي الذهب رأس الفيل. ويستعد أيضًا للدفاع عن المربع 2c حين يبادل سينته بيدق رخه. في صيف هذا العام، 1948، أقيمت الألعاب الأولمبية في لندن، لكن اليابان لم يُسمح لها بالمشاركة بسبب الحرب.","7":"B-7g. يصعد الفيل لمواجهة هجوم غوته على العمود 8. صدّ عمود رخ الخصم بالفيل شكل شائع في افتتاحيات الجناح المزدوج.","8":"P-3d. ويفتح غوته قطر فيله أيضًا. الآن صار البيدق في 3d مكشوفًا بجانب رخ سينته، وصار السؤال هل يستطيع سينته أخذه بالرخ مفترق طرق كبيرًا.","10":"S-6b. ويرفع أوياما فضة أيضًا. يستعد لاستخدامها في العمود 5 في الوسط.","12":"P-5d. يدفع أوياما بيدق العمود 5. يبدو أنه ينوي إدخال فضة إلى الوسط ليقيّد رخ سينته.","13":"P-2d. أخيرًا يصدم ماسودا بيدق رخه. معارك أخذ البيدق الجانبي والجناح المزدوج تبدأ بهذا التبادل.","15":"Rx2d. يستعيد الرخ ويخرج إلى 2d. بتبادل بيدق الرخ يكسب سينته بيدقًا في يده.","16":"P*2c. يُسقط غوته بيدقًا ليدفع الرخ إلى الخلف. عادةً يتراجع الرخ إلى 2f أو 2h، لكن أمام سينته هنا خيار مهم.","17":"Rx3d. يحرّك ماسودا رخه جانبيًا ويأخذ البيدق في 3d. هذا هو «أخذ البيدق الجانبي». يُكسب بيدق مجانًا، لكن الرخ يصبح بسهولة معزولًا قرب معسكر الخصم؛ وهناك مثل قديم يقول: «من أخذ البيدق الجانبي مرض ثلاث سنين». إنها استراتيجية فيها خطر وفيها مكسب. كان ماسودا يبتكر النقلات الجديدة واحدة بعد أخرى ويعيش بشعار «عمر كامل من النقلات الجديدة»، فهو يقفز بنفسه إلى مثل هذه التفرعات الخطرة.","18":"S-5c. بدل مطاردة الرخ يرفع أوياما فضته إلى الوسط. في أخذ البيدق الجانبي المعتاد يضايق غوته الرخ غالبًا بنقلات مثل B-3c، أما هنا فتظهر طريقة أوياما الخاصة في تسميك الوسط.","19":"R-3f. يتراجع الرخ مربعًا إلى مكان آمن. ومع الاحتفاظ بالبيدق الزائد يهدّئ سينته رخه.","20":"P-5e. يدفع أوياما بيدق العمود 5 أبعد ويحاول السيطرة على الوسط. وبما أنه خسر بيدقًا، يريد التعويض بقطع نشيطة.","22":"S-4d. تخرج الفضة إلى 4d، فتقترب من رخ سينته في 3f وتراقب الوسط أيضًا.","23":"Px5e. يأخذ ماسودا البيدق في 5e. صار سينته متقدمًا ببيدقين.","24":"R-5b. يدير أوياما رخه إلى العمود 5. وضع الرخ في الوسط يكوّن شكل «الرخ الأوسط» بهدف استعادة البيدق في 5e. إنه استخدام مرن للرخ يميّز أوياما، الذي اشتهر لاحقًا أستاذًا لافتتاحيات الرخ المنقول.","25":"K-6i. ينقل ماسودا ملكه إلى اليسار استعدادًا لهجوم من الوسط.","26":"Sx5e. تستعيد الفضة البيدق في 5e. تصطف فضة غوته ورخه على العمود 5 ويضغطان على معسكر سينته من الوسط.","28":"P*5f. يُسقط غوته بيدقًا ينهش معسكر سينته. إن لعب غوته بعدها P-5g+ انهار معسكر سينته.","29":"P*5g. ويُسقط سينته أيضًا بيدقًا للدفاع. بيدق مقابل بيدق: معركة صغيرة تدور في الوسط.","30":"Px5g+. يأخذ غوته البيدق ويصنع توكين. يستطيع سينته الاستعادة فورًا، فهذا مجرد تبادل بيادق.","32":"K-4a. ينقل أوياما ملكه إلى 4a على اليمين. ولأن الرخ يُستخدم في العمود 5، يحصّن الملك على اليمين بعيدًا عن الرخ.","33":"P*5f. يُسقط سينته بيدقًا ليطرد الفضة من 5e. نقلة تليق بسينته الذي في يده بيادق كثيرة.","34":"S-4d. تتراجع الفضة إلى 4d. تعود قرب معسكرها وتنتظر الفرصة التالية.","35":"R-2f. يعود الرخ إلى العمود 2 ويرتّب تشكيل سينته.","37":"P-6f. دفع بيدق العمود 6 يفتح طريقًا لخروج الفضة.","38":"S-5c. يرفع غوته فضة أخرى إلى الوسط فيزداد العمود 5 سماكة.","39":"S-6g. تصعد الفضة إلى 6g فتقوّي منطقة الملك وتسند الوسط.","41":"R-2h. يعود الرخ إلى مربعه الأصلي. ومع البيادق المكسوبة في الوسط يتخذ سينته وضعًا دفاعيًا متينًا.","43":"G-5h. يصعد الذهب وينضم إلى الدفاع عن الوسط.","45":"P-4f. بدفع بيدق العمود 4 يبدأ ماسودا التحضير لهجوم من الجهة اليمنى.","46":"R-8b. يعيد أوياما رخه إلى 8b. فقد هدأت معركة الوسط، والآن يستهدف الهجوم عبر العمود 8.","49":"B-5i. يتراجع الفيل إلى 5i ليُستخدم على قطر آخر. إنه استعداد لنقل الفيل من 7g نحو العمودين 4 و3.","51":"N-7g. يقفز الحصان الأيسر استعدادًا للمشاركة في الهجوم.","52":"P-8f. يصدم أوياما البيادق في العمود 8 ليبادل بيدق رخه.","54":"Rx8f. يأخذ الرخ، ويخرج رخ غوته إلى 8f. وبتبادل بيدق الرخ يضيف غوته أيضًا بيدقًا إلى يده.","55":"P*8g. يُسقط سينته بيدقًا ليدفع الرخ إلى الخلف.","57":"B-2f. يخرج الفيل إلى 2f وينظر إلى الجهة اليمنى من معسكر الخصم.","58":"B-4d. ويُخرج أوياما فيله أيضًا في مواجهة فيل سينته.","59":"B-3g. يتراجع الفيل مربعًا ويتجنب تبادل الفيلين.","61":"R-4h. يدور الرخ إلى العمود 4. يستعد لدفع بيدق العمود 4 والهجوم من اليمين.","62":"P-6e. يدفع أوياما بيدق العمود 6 ويجهّز هجومًا مضادًا من اليسار.","63":"P-4e. ويهاجم ماسودا أيضًا عبر العمود 4. الهجومان على وشك الاصطدام: موقف متوتر.","64":"P-6f. اصطدام بيادق ينخز ما أمام فضة سينته.","66":"P*6e. يُسقط غوته بيدقًا آخر ليطارد الفضة. وباستخدام البيادق بمهارة يفكك تشكيل سينته شيئًا فشيئًا.","68":"P*5e. ويُسقط غوته بيدقًا في الوسط أيضًا، ليصطدم ببيدق سينته في 5f.","69":"S-4f. تخرج الفضة إلى 4f وتنضم إلى الهجوم على العمود 4.","70":"P-7e. ويصدم غوته أيضًا بيدق العمود 7 ويضغط على الجهة اليسرى لسينته.","72":"S-6d. تتقدم الفضة لتسند البيدق في 6e.","73":"P-4d. يدسّ ماسودا بيدق العمود 4 ويقترب من المنطقة أمام ملك غوته.","75":"S-3e. تتقدم الفضة إلى 3e وتضيف قطعة هجومية أخرى.","76":"N-3c. يقفز الحصان ليسد طريق الفضة.","77":"Px5e. يأخذ سينته البيدق الأوسط. يختفي بيدق غوته الأوسط، ويشتد الصراع على العمود 5.","78":"Bx5e. يستعيد الفيل، ويخرج فيل غوته إلى الوسط.","79":"P*5c. بيدق يجبر فضة غوته على تغيير مكانها.","81":"Bx5e. يذهب ماسودا إلى تبادل الفيلين. يأخذ فيل غوته في الوسط ويضيف فيلًا إلى يده.","83":"Nx6e. يقفز الحصان ويأخذ البيدق في 6e ويقترب من معسكر غوته.","85":"P*5c. بيدق يهدد ذهب غوته.","87":"P*2d. ويُسقط سينته بيدقًا في العمود 2 أيضًا ويجهّز هجومًا من اليمين.","88":"P*5g. ويُسقط أوياما أيضًا بيدقًا في معسكر سينته ويصنع موطئ قدم للهجوم المضاد.","92":"B*4e. يُسقط غوته فيله من يده ويراقب وسط معسكر سينته.","93":"B*9f. ويُسقط ماسودا أيضًا فيلًا. من 9f ينظر هذا الفيل البعيد المدى قطريًا نحو رخ غوته وملكه. وسيلعب هذا الفيل دورًا مهمًا في المشهد الأخير أيضًا.","94":"P*8e. يُسقط غوته بيدقًا ليعرقل فضة سينته.","98":"K-3a. ينقل أوياما ملكه مربعًا أعمق، بعيدًا عن هجوم سينته.","99":"N-3g. ينضم الحصان الأيمن أيضًا إلى الهجوم.","100":"B-5f. يتقدم الفيل إلى 5f مستهدفًا عمق معسكر سينته.","102":"P*7g. بيدق يستدرج الذهب ويفتح طريق الفيل.","104":"B-8i+. يترقّى الفيل في أعمق نقطة من معسكر سينته ويصير حصان التنين. يتحرك كالفيل ويستطيع أيضًا أن يخطو مربعًا إلى الأمام أو الخلف أو الجانبين: قطعة قوية.","105":"Px2c+. ويرقّي ماسودا أيضًا بيدقًا قرب ملك غوته ويدخل سباق الهجمات.","106":"+Bx2c. يأخذ أوياما حصان التنين من 8i حتى 2c عبر القطر الطويل ويأخذ التوكين. تُظهر هذه النقلة كيف تصل هذه القطعة من طرف الرقعة إلى طرفها الآخر.","107":"R-2h. يدور الرخ إلى العمود 2 ليواصل الهجوم هناك.","110":"+B-8i. يعود حصان التنين إلى عمق معسكر سينته. نقلة مرنة تميّز أوياما، تستخدم قطعة واحدة للدفاع والهجوم.","112":"Sx6e. يأخذ أوياما بفضته الحصان في 6e. يزيل الحصان الذي كان قلب هجوم سينته ويزيد ما في يده.","115":"S-7d. تتقدم الفضة إلى 7d مستهدفة حصان غوته.","116":"N*6e. يُسقط غوته حصانًا ويهاجم المنطقة حول ملك سينته.","118":"S-5f. تتقدم الفضة وتقترب من ملك سينته.","119":"Sx7c+. يأخذ ماسودا الحصان ويصنع فضة مرقّاة. وهذه الفضة تنظر أيضًا نحو ملك غوته.","120":"+Bx7h. هنا يتخلى أوياما عن حصان التنين ليأخذ ذهبًا. نقلة كل شيء أو لا شيء: يرمي قطعة كبيرة لينتزع حماة ملك سينته.","121":"Kx7h. يأخذ الملك القطعة. فقد ملك سينته ذهبًا مدافعًا، وبدأت منطقته تضعف.","122":"G*6g، كِش. يُسقط أوياما ذهبًا من يده، ويستمر هجومه.","124":"Gx5h. يأخذ الذهب ذهبًا ويقترب أكثر من ملك سينته.","126":"N-5g+. يترقّى الحصان ويطارد ملك سينته.","128":"S-4g+. وتترقّى الفضة أيضًا وتحاول تطويق ملك سينته.","130":"+N-4h، كِش. يعطي الحصان المرقّى كِشًّا. يرمي غوته في الهجوم كل قطعة يملكها.","133":"Kx4h. يستعيد الملك. هنا كادت قطع غوته الهجومية تنفد. في يد سينته فيل وذهب وفضتان وحصانان وبيادق كثيرة: موقف يتقدم فيه سينته بفارق كبير. يكفي أن يوصل ملكه إلى الأمان ليفوز ماسودا.","134":"R*8h، كِش. يُسقط أوياما آخر رخ عنده ويعطي كِشًّا. يعمل من بعيد جانبيًا: مقاومته الأخيرة.","135":"K-4g. يرفع ماسودا ملكه. كان يستطيع أيضًا أن يضع قطعة حاجزة، لكن ماسودا اختار الهرب نحو وسط الرقعة.","136":"Rx8g+. يأخذ الرخ بيدقًا ويصير تنينًا ويعطي كِشًّا مرة أخرى.","137":"Bx8g. يأخذ الفيل الذي في 9f التنين. الفيل الذي أُسقط في النقلة 93 يفيد هنا.","138":"Rx8g+. يستعيد أوياما الفيل برخ 8b، ويصنع تنينًا جديدًا ويعطي كِشًّا.","139":"K-4f. كانت هذه النقلة المصيرية. رفع ماسودا ملكه إلى 4f، لكن هذا المربع يقع على قطر يستطيع غوته أن يُسقط فيه فيلًا. ويقال إنه لو وضع قطعة حاجزة من يده أو هرب في اتجاه آخر لفاز ماسودا. كانت نقلة لُعبت بحكم العادة والنصر أمام عينيه.","140":"B*6d، كِش. يُسقط أوياما فيله في 6d. يصل قطره إلى الملك في 4f.","141":"N*5e. يُسقط ماسودا حصانًا ليقطع خط الفيل. يسدّ الفيل بالحصان الذي في يده.","142":"G*4g، كِش. الذهب يحميه التنين فلا يمكن أخذه، واستسلم ماسودا هنا. لم يعد إنقاذ ملكه ممكنًا، وأعلن ماسودا، الذي كان ينبغي أن يفوز، استسلامه بنبرة مازحة: «الوهم سيئ، النظر جيدًا جيد». وبهذا الفوز صار أوياما في منتصف عشرينياته متحدّيًا على لقب الميجين، وبدأ طريقه ليصبح أستاذًا كبيرًا يحمل لقب الميجين 18 مرة في المجموع. وصار إينوي ياسوشي من صحيفة ماينيتشي، الذي شهد المباراة، روائيًا فيما بعد وكتب عنها قصة قصيرة بعنوان «شوبو» (المنازلة). وقد بدأ التنافس الطويل بين الأخوين في المدرسة يتحرك حقًا هنا، على جبل كويا."}},"fischer1972":{"t":"المباراة التي صفّق لها سباسكي","w":"بوبي فيشر","b":"بوريس سباسكي","ev":"بطولة العالم، المباراة السادسة","d":"23 يوليو 1972","pl":"آيسلندا (ريكيافيك)","lead":"المباراة السادسة من بطولة العالم التي تحدّى فيها الأمريكي فيشر بطلَ العالم السوفيتي سباسكي في خضمّ الحرب الباردة. فيشر، الذي كان يفتتح دائمًا تقريبًا بـ e4، بدأ بـ c4، وفي غامبيت الوزير الذي لم يلعبه من قبل قطّ، حطّم من الأمام الدفاع المفضّل لخصمه. اشتهرت المباراة لأن الخاسر سباسكي صفّق مع الجمهور. وبهذا الفوز تقدّم فيشر في المواجهة لأول مرة.","c":{"0":"23 يوليو 1972، ريكيافيك عاصمة آيسلندا. هذه المباراة السادسة من بطولة العالم، وتُلعب في قاعة رياضية. الأبيض: الأمريكي بوبي فيشر، 29 عامًا. الأسود: بوريس سباسكي من الاتحاد السوفيتي، بطل العالم منذ 1969. في زمن الحرب الباردة جذبت هذه المواجهة انتباه العالم كله بوصفها «معركة عقول» بين أمريكا والاتحاد السوفيتي. بعد خمس مباريات كانت النتيجة متعادلة 2½–2½. خسر فيشر المباراة الأولى، وخسر الثانية لعدم حضوره، لكنه عادل النتيجة بعد ذلك.","1":"يلعب الأبيض c4! كان فيشر يبدأ دائمًا تقريبًا بـ e4، بل كتب أن e4 «الأفضل بالتجربة». يُقال إنها كانت المرة الثالثة فقط التي افتتح فيها بـ c4 في مباراة جادة. استقبل الجمهور وسباسكي هذه النقلة بدهشة كبيرة. البدء بـ c4 يُسمّى «الافتتاح الإنجليزي».","2":"يلعب الأسود e6. يحتفظ بترتيب مرن ليتمكن من لعب d5 مهما حدث. يُقال إن فريق سباسكي استعدّ لـ e4 أو d4 من فيشر ولم يدرس c4 كثيرًا.","3":"الحصان إلى f3. نقلة طبيعية تسيطر على e5 وd4 وتساعد في حماية الملك. لا يكشف الأبيض بعد أي ترتيب سيختار.","4":"يلعب الأسود d5. يأخذ مربعًا في الوسط ويواجه بيدق c4. إن استمر الأمر هكذا اقتربت المباراة من غامبيت الوزير.","5":"يلعب الأبيض d4. هنا تنضمّ المباراة إلى الترتيب المسمّى غامبيت الوزير. الوصول إلى الوضع نفسه بترتيب نقلات مختلف يُسمّى «تبديل الترتيب». يُقال إن فيشر لم يلعب غامبيت الوزير في مباراة جادة قبل هذه قط.","6":"يلعب الأسود ♘f6. يخرج الحصان الذي يحمي الملك ويدعم d5. لا يأخذ الأسود بيدق c4، بل يختار «غامبيت الوزير المرفوض» بوسط متين.","7":"الحصان إلى c3. يزيد الضغط على بيدق d5. لُعب هذا الترتيب في آلاف المباريات منذ القرن التاسع عشر: إنه من أعرق طرق القتال.","8":"يلعب الأسود ♗e7. نقلة هادئة تُعدّ للتبييت. كان سباسكي يستخدم هذا الترتيب الكلاسيكي سلاحًا له كثيرًا.","9":"يلعب الأبيض ♗g5. يواجه الفيل حصان f6 ويقيّد قطعة تحمي d5. هذا أكثر ترتيب شيوعًا في غامبيت الوزير.","10":"يبيّت الأسود. ينتقل الملك إلى الأمان في g8. حتى هنا كل شيء معروف منذ عقود.","11":"يلعب الأبيض e3. تفتح النقلة طريق فيل f1 وتدعم d4. ترتيب الأبيض أيضًا متين ودون عجلة.","12":"يلعب الأسود h6 ويسأل الفيل: تبادل أم تراجع؟ من هنا يدخل الأسود «متغيّر تارتاكوفر»، مع b6 وفيل c8 متجهًا إلى b7 أو e6. يأتي الاسم من تارتاكوفر، الخاسر في «كش مات ريتي» في هذه القاعة.","13":"يلعب الأبيض ♗h4. يتراجع الفيل ويُبقي تثبيت حصان f6. التبادل الآن سيمنح قطع الأسود مساحة أكبر للتنفّس.","14":"يلعب الأسود b6. هذه النقلة المميّزة لمتغيّر تارتاكوفر. سيخرج فيل c8 إلى b7 أو مربع آخر. يُقال إن سباسكي لم يخسر قط مباراة بهذا الترتيب.","15":"يلعب الأبيض cxd5. تتبادل البيادق في الوسط ويجب على الأسود أن يحسم بنيته. من هنا تغادر عدة قطع الرقعة واحدة تلو الأخرى بسرعة.","16":"يلعب الأسود ♘xd5. يسترد الحصان ويعرض التبادل على فيل الأبيض وحصانه. بتبادل القطع يحاول الأسود التخلص من ضيق وضعه.","17":"يلعب الأبيض ♗xe7. يتبادل الفيلان. الآن يخرج الوزير الأسود إلى e7.","18":"يلعب الأسود ♕xe7 ويسترد بالوزير. مع قلة القطع الخفيفة يتضح الوضع.","19":"يلعب الأبيض ♘xd5. يتبادل الحصانان أيضًا، فيتحدد شكل بيدق الأسود في d5.","20":"يلعب الأسود exd5. يسترد ببيدق e، فيبقى بيدق أسود في d5. يمسك هذا البيدق الوسط، لكن حوله بيادق صديقة قليلة، فقد يصبح هدفًا لاحقًا.","21":"يلعب الأبيض ♖c1. يذهب الرخ إلى العمود c ليُعدّ الضغط حين يلعب الأسود c5. يستهدف الأبيض جناح الوزير الأسود من العمود c.","22":"يلعب الأسود ♗e6. يحمي الفيل d5 ويُعدّ لـ c5. هذا ترتيب شائع في متغيّر تارتاكوفر.","23":"يلعب الأبيض ♕a4. من a4 يستهدف الوزير جناح الوزير الأسود. مكان غير مألوف قليلًا يضغط على مربعات مثل a7 وc6.","24":"يلعب الأسود c5. كما هو مخطط، يدعم بيدقا c5 وd5 الوسط. البيدقان المتجاوران هكذا يُسمّيان «البيدقين المعلّقين»: قد يكونان قويين أو ضعيفين.","25":"يلعب الأبيض ♕a3! من a3 يستهدف الوزير بيدق c5. خلف ذلك البيدق، على القطر حتى f8، يقف الوزير الأسود، فيصعب على البيدق التحرك.","26":"يلعب الأسود ♖c8. يحمي الرخ c5. حتى الآن اتّبع الأسود النمط المعروف.","27":"يلعب الأبيض ♗b5! أثارت هذه النقلة حديثًا كثيرًا. يُقال إنها تستعير فكرة من مباراة لعبها الأستاذ السوفيتي فورمان عام 1970. يمنع الفيل حصان الأسود من الذهاب إلى d7 أو c6 ويحاول إرباك ترتيب الأسود. ويُقال إن الأستاذ الكبير السوفيتي غيلر علّق لاحقًا بأن على الأسود أن يلعب هنا ♕b7.","28":"يلعب الأسود a6 ويطلب من الفيل التراجع أو التبادل. لا يستطيع الفيل الأبيض البقاء طويلًا في b5.","29":"يلعب الأبيض dxc5. تتبادل البيادق ويجب على الأسود أن يسترد ببيدق b. الآن تقف بيادق الأسود متجاورة في c5 وd5 بوصفها «بيدقين معلّقين».","30":"يلعب الأسود bxc5. للأسود بيدقان في c5 وd5، لكن لا بيادق حولهما لتدعمهما. سيواصل الأبيض توجيه قطعه نحو هذين البيدقين.","31":"يبيّت الأبيض. الملك آمن والرخ يستطيع التحرك الآن. لا يستعجل الأبيض؛ يستعدّ لمهاجمة نقاط ضعف خصمه بصبر.","32":"يلعب الأسود ♖a7. يخرج الرخ إلى الصف السابع حيث يستطيع التحرك جانبيًا أيضًا. مربع غير مألوف، لكن الفكرة هي الدفاع مع حراسة مربعات مثل a6 وc7.","33":"يلعب الأبيض ♗e2. يتراجع الفيل بحثًا عن مربع أفضل. كانت نقلات هذه المواجهة تُنشر تقريبًا كل يوم في صحف العالم وتلفزيوناته، وكان كثير من الناس يتابعونها واحدة واحدة.","34":"يلعب الأسود ♘d7. يخرج الحصان مستعدًا للذهاب إلى b6 أو f6. لا يزال الأسود يمسك المساحة ببيادقه الوسطى.","35":"يلعب الأبيض ♘d4! يقفز الحصان إلى الوسط ويعرض نفسه للتبادل مع فيل الأسود في e6. هذا الفيل قطعة مهمة تحمي بيادق الأسود.","36":"يلعب الأسود ♕f8. يذهب الوزير إلى العمود f مفكرًا في هجوم مضاد من هناك. إن أخذ الأبيض في e6، ينوي الأسود الاسترداد ببيدق f وفتح العمود f.","37":"يلعب الأبيض ♘xe6. يُبادَل الحصان بالفيل. الآن صار للأسود قطعة أقل لحماية بيادقه.","38":"يلعب الأسود fxe6. يسترد ببيدق f فينفتح العمود f. لكن بيدق e6 يصبح أيضًا هدفًا ضعيفًا لقطع الأبيض.","39":"يلعب الأبيض e4! يضرب في الوسط ويتحدّى بيدق الأسود في d5. إن بادل الأسود صار بيدق d5 أكثر عزلة وانهارت بنية الأسود.","40":"يلعب الأسود d4. يتقدّم البيدق متجنّبًا الاصطدام. الآن للأسود «بيدق حرّ» في d4 داخل معسكر الأبيض، لكن الأبيض يستطيع إبقاءه محاصرًا وهو يقاتل.","41":"يلعب الأبيض f4. يتقدّم على جناح الملك استعدادًا للمتابعة إلى e5 أو f5. لأن للأسود قطعًا كثيرة على جناح الوزير، يقرّر الأبيض الهجوم من الجهة الأخرى.","42":"يلعب الأسود ♕e7. يراقب الوزير في e7 المربع e5. إنه يستعدّ لتقدّم بيادق الأبيض.","43":"يلعب الأبيض e5. يصل البيدق إلى e5 ويضيّق حركة قطع الأسود. لم يعد حصان الأسود قادرًا على المجيء إلى f6، وقلّ المدافعون عن الملك الأسود.","44":"يلعب الأسود ♖b8. يذهب الرخ إلى العمود b ويستهدف بيدق b2. يحاول الأسود الهجوم المضاد من جناح وزيره.","45":"يلعب الأبيض ♗c4. ينظر الفيل إلى بيدق e6 ويسيطر على d5 أيضًا. سيصبح هذا الفيل لاحقًا مهاجمًا مهمًا ضد الملك الأسود.","46":"يلعب الأسود ♔h8. يدخل الملك الزاوية، خارج قطر الفيل. لا خطر بعد، لكن قطع الأسود صارت سلبية.","47":"يلعب الأبيض ♕h3. يتحوّل الوزير إلى جناح الملك ويستهدف بيدق e6. الوزير الذي كان على جناح الوزير ينتقل أخيرًا إلى موقع الهجوم.","49":"يلعب الأبيض b3. يدعم البيدق الفيل ويزيل أي تهديد لـ b2. يتخلّص الأبيض أولًا من نقاط ضعفه ثم يهاجم.","51":"يلعب الأبيض f5! يضرب ببيدق ليفتح الخطوط حول الملك الأسود. من هنا يبدأ هجوم الأبيض فعلًا.","53":"يلعب الأبيض ♖xf5. يتقدّم الرخ ويستولي على العمود f المفتوح. تتجمّع قطع الأبيض قرب الملك الأسود.","55":"يلعب الأبيض ♖cf1. ينضمّ الرخ الآخر إليه على العمود f فيضاعف الضغط. ليس مدفع أليخين تمامًا، لكنها الفكرة نفسها: رصّ القطع على عمود واحد.","57":"يلعب الأبيض ♕g3. يدخل الوزير جناح الملك ويقترب من الملك الأسود. كل قطع الأبيض تأخذ مواقع الهجوم.","59":"يلعب الأبيض h4. خطوة بيدق واحدة تمنع حصان الأسود من المجيء إلى g5. نقلة صغيرة لكنها دقيقة، تنزع من الأسود دفاعًا واحدًا.","61":"يلعب الأبيض e6! يتقدّم البيدق ويشطر معسكر الأسود نصفين. بيدق e6 محميّ بالفيل الأبيض، ورخّا الأسود وحصانه بالكاد يتحركون.","63":"يلعب الأبيض ♕e5. يأتي الوزير إلى الوسط ويستهدف بيادق الأسود وقطعه. الأسود منشغل تمامًا بالدفاع وحده.","65":"يلعب الأبيض a4. يوقف بيادق جناح الوزير الأسود ويزيل أي لعب مضاد عبر a5. إزالة كل همّ دفاعي قبل الهجوم أمر من طباع فيشر تمامًا.","67":"يلعب الأبيض ♖1f2. يعيد ترتيب رخّيه ليُعدّ الفكرة التالية. لا يستطيع الأسود إلا الذهاب والإياب بين ♕d8 و♕e8؛ لا يستطيع فعل شيء من تلقاء نفسه.","71":"يلعب الأبيض ♗d3. ينتقل الفيل إلى القطر الذي يستهدف h7. إن جاء الوزير بعده إلى القطر نفسه، سيقع ضغط هائل على h7، أمام الملك الأسود مباشرة.","73":"يلعب الأبيض ♕e4. يصطفّ الوزير والفيل على القطر نفسه ويستهدفان h7. يهدّد الأبيض بإدخال رخ إلى f8 ثم إعطاء كش مات في h7.","74":"يلعب الأسود ♘f6. يهاجم الحصان الوزير ويسدّ القطر. لكن هذه النقلة تسمح بضربة الأبيض التالية.","75":"يلعب الأبيض ♖xf6! يعطي رخًّا مقابل الحصان: «تضحية بالفارق». يختفي حصان f6، وتنفتح المربعات حول الملك الأسود.","76":"يلعب الأسود gxf6. لا بد أن يأخذ. وإلا اقتحم الأبيض f8 أو h7.","77":"يلعب الأبيض ♖xf6. يدخل الرخ الآخر إلى f6 ويستعيد البيدق. صار الملك الأسود محاطًا بقطع الأبيض.","79":"يلعب الأبيض ♗c4. يدعم الفيل بيدق e6 ويستهدف أيضًا مربعات قرب الملك الأسود. لم يعد لدى الأسود تقريبًا دفاع جيد.","81":"يلعب الأبيض ♕f4. يستهدف الوزير بيدق h6 والمربع f8، ولم يعد ممكنًا إيقاف هجوم الأبيض. استسلم سباسكي هنا. ويُقال إن سباسكي، متأثرًا بجودة المباراة، صفّق مع الجمهور. تقدّم فيشر الآن في المواجهة لأول مرة 3½–2½، وفي النهاية صار بطل العالم بنتيجة 12½–8½. اللقب الذي احتفظ به لاعبون سوفييت 24 عامًا منذ 1948 انتقل أخيرًا إلى يد أخرى."}},"kanju1754":{"t":"كانجو يهزم أخاه ويبلغ الدان الثامن","w":"إيتو كانجو","b":"أوهاشي سوكي الثامن","ev":"شوغي القلعة (المباراة السنوية في قلعة إيدو)","d":"اليوم 17 من الشهر 11، سنة 1754 (هوريكي 4)","pl":"اليابان (قلعة إيدو)","lead":"مباراة في القلعة بلا أفضلية بين إيتو كانجو، المشهور بتحفة مسائل الكِش مات «شوغي زوكو»، وأخيه الأكبر نفسه أوهاشي سوكي الثامن. كان الاثنان خصمين كبيرين تواجها مرات كثيرة في القلعة. كان كانجو قد هزم أخاه في السنة السابقة، وفاز بهذه المباراة أيضًا، فبلغ قبل أخيه الدان الثامن، وهو رتبة «الميجين القادم». أمام رخ العمود الرابع عند الغوتي يهاجم كانجو بسرعة، ويكسب قطعًا بفيله، وفي النهاية يجرّ ملك الخصم إلى وسط الرقعة ويُميته. فاز كانجو في 137 نقلة.","c":{"0":"أنا Musowl. مباراة اليوم هي مباراة القلعة لسنة 1754 (هوريكي 4). السِّنتي إيتو كانجو والغوتي أوهاشي سوكي الثامن كانا في الحقيقة أخوين. أبوهما هو الميجين الخامس إيتو سوئين الثاني؛ وكان سوكي الابن الثالث وكانجو الابن الخامس. تبنّى البيتُ الرئيسي لأوهاشي سوكي وهو في الحادية عشرة، فتقابل الاثنان مرات كثيرة، أحدهما بوصفه رأس بيت أوهاشي والآخر بوصفه وريث بيت إيتو، وكلٌّ يحمل اسم أسرته. في السنة السابقة هزم كانجو أخاه بلا أفضلية، وإن فاز بهذه المباراة أيضًا فسيبلغ الدان الثامن، أي «الميجين القادم». لنشاهد هذه المباراة المهمة بين الأخوين.","1":"P-7f. النقلة الأولى تفتح قطر الفيل. في هذه السنة، في كيوتو، شاهد الطبيب ياماواكي تويو تشريح جسد إنسان، وكان أول تشريح في اليابان بإذن رسمي. كانت خطوة كبيرة للطب الياباني قادت لاحقًا إلى كتاب التشريح الشهير «كايتاي شينشو».","2":"P-3d. يفتح الغوتي قطر فيله أيضًا. وفي الوقت نفسه تقريبًا بدأت في أمريكا الشمالية «الحرب الفرنسية والهندية» بين بريطانيا وفرنسا. وكان يحكم اليابان الشوغون التاسع توكوغاوا إييشيغي، وما زال شوغي القلعة يُقام كل سنة في اليوم السابع عشر من الشهر الحادي عشر.","3":"P-2f. يدفع السِّنتي بيدق الرخ. وُلد كانجو سنة 1719، وكان عمره 36 سنة بالحساب القديم للعمر. فقد أباه في الخامسة، ويقال إنه تعلّم الشوغي وهو يتربّى على أيدي إخوته الكبار.","4":"P-4d. يغلق الغوتي قطر الفيل. في مباريات القلعة في عصر إيدو كان الغوتي كثيرًا جدًا ما يغلق القطر هنا، ثم يتشكل شكل المباراة بحسب ما إذا أبقى الغوتي رخه ثابتًا أو نقله.","5":"P-2e. يدفع السِّنتي بيدق الرخ أكثر. يُروى أن كانجو قرأ وهو في السابعة تقريبًا كتابًا في مسائل الكِش مات، وأبدى ملاحظة حادة أدهشت أخاه سوكان.","6":"B-3c. يصعد الفيل ليحرس 2d. كان سوكي أكبر من كانجو بأربع سنوات، وفي القلعة كان الأخ الأكبر دائمًا في موقع اللاعب الأقوى.","7":"S-4h. يرفع السِّنتي الفضّي الأيمن، وهو قطعة مهمة للهجوم السريع. يُروى أن كانجو ألّف وهو في الثالثة عشرة مسألة كِش مات طويلة جدًا يحتاج حلها إلى 611 نقلة.","9":"P-5f. يدفع السِّنتي بيدق الوسط. لاحقًا سيتقدم هذا البيدق إلى 5e ثم 5d ويساعد على كسر معسكر الغوتي.","11":"P-3f. يدفع السِّنتي بيدق العمود 3 لكي يقفز الحصان إلى 3g. في الهجوم السريع يؤدي هذا الحصان دورًا مهمًا.","12":"R-4b. ينقل الغوتي رخه إلى العمود 4. هذا هو «رخ العمود الرابع»، الافتتاح الكلاسيكي للرخ المنقول، يُلعب منذ عصر إيدو وما زال اليوم محبوبًا عند الهواة والمحترفين. يخطط سوكي لنقل رخه إلى اليسار وحماية ملكه في اليمين.","13":"G-5h. يرفع السِّنتي ذهبيًا ليبني دفاع الملك. وجود الذهبيات حول الملك يجعل صدّ هجوم الخصم أسهل.","14":"K-6b. يذهب ملك الغوتي إلى الجهة المقابلة للرخ. في الرخ المنقول القاعدة الأساسية هي حماية الملك بعيدًا عن الرخ.","15":"K-6h. يذهب ملك السِّنتي أيضًا إلى اليسار. لأن السِّنتي يريد بدء القتال مبكرًا، يبني قلعة بسيطة. وفي المقابل سيقاتل بدفاع رقيق قليلًا.","17":"K-7h. وصل الملك إلى 7h. القلعة رقيقة، لكن السِّنتي يستطيع الهجوم أبكر بكثير. هذه هي فكرة «الهجوم السريع».","19":"P-9f. يدفع السِّنتي بيدق الطرف. سيفيد هذا البيدق لاحقًا في الهجوم على ملك الغوتي. ويرد الغوتي بعدها بـ P-9d.","23":"N-3g. يقفز الحصان استعدادًا للهجوم. حين يبدأ القتال على العمودين 3 و4 سيقفز هذا الحصان إلى 4e وينضم.","24":"P-4e. يدفع الغوتي أولًا بيدقه على العمود 4. لو قفز السِّنتي N-4e وأسر البيدق لاستطاع الرخ في 4b أن يأسر ردًّا. دفع البيدق الذي أمام الرخ هكذا استعداد للهجوم السريع من السِّنتي.","26":"K-8b. يدخل ملك الغوتي عميقًا إلى 8b. بعد ذلك سيأتي ذهبي إلى 7b، ومع الفضّي في 6b سيحرسان الملك.","27":"R-2f. يصعد الرخ خانة ويصبح رخًا عائمًا يستطيع التحرك جانبيًا أيضًا. الفكرة نقله إلى العمود 3 أو 4 للهجوم.","29":"P-3e. يبدأ الهجوم. يصدم السِّنتي البيادق على العمود 3 مصوّبًا على رأس الفيل في 3c. أمام رخ العمود الرابع، بدء القتال بصدم البيادق على العمود 3 أو 4 نمط شائع في الهجوم السريع.","31":"P-2d. يصدم السِّنتي بيادق العمود 2 أيضًا. الفكرة إضعاف دفاع الفيل في 3c من العمودين 2 و3 معًا.","33":"Bx3c+. يأسر السِّنتي الفيل بفيله: تبادل الفيلين. الآن مع كل جانب فيل في يده يستطيع إسقاطه في أي مكان.","35":"P-5e. يدفع السِّنتي بيدق الوسط نحو بيدق الغوتي في 5d. بعد تبادل الفيلين يكون هزّ معسكر الخصم من الوسط فعّالًا.","36":"P-3f. يدفع الغوتي بيدقه من 3e إلى 3f ويهاجم الحصان في 3g. إنه هجوم معاكس يتحرّش بقطع السِّنتي المهاجمة.","38":"P*3d. يُسقط الغوتي بيدقًا ليسدّ العمود 3. الآن يوجد جدار من بيدق الغوتي أمام رخ السِّنتي في 3f.","39":"Px5d. يأسر السِّنتي البيدق على العمود 5. يصوّب هذا البيدق على 5c في معسكر الغوتي. حين يقترب البيدق من معسكر الخصم يصير موطئ قدم لإسقاط فيل أو فضّي.","40":"B*2h. يُسقط الغوتي فيله في عمق معسكر السِّنتي، في 2h. الفكرة أن يأسر الرمح بعدها بـ B-1i+.","41":"P-9e. يصدم السِّنتي بيدق الطرف. دون أن يهتم بالفيل في 2h يهاجم من الطرف الأيسر حيث يسكن ملك الغوتي. الهجوم من الطرف القريب من الملك من أهم طرق القتال ضد الرخ المنقول.","42":"Bx1i+. يأسر فيل الغوتي الرمح ويترقّى إلى حصان تنين. إنه قطعة قوية، لكنه عالق في الزاوية فلا يستطيع العمل فورًا.","43":"Px9d. يأسر السِّنتي بيدق الطرف ويقترب من ملك الغوتي عبر العمود 9. ومع أن حصان التنين عند الغوتي أخذ الرمح، يواصل السِّنتي الهجوم بهدوء.","44":"P*9b. يُسقط الغوتي بيدقًا ليحرس الطرف. توقّف العمود 9 الآن، لكن هذا البيدق سيضيّق لاحقًا طريق هروب ملك الغوتي.","45":"B*5c. يُسقط السِّنتي فيله في 5c. عبر قطريه يهاجم هذا الفيل في آن واحد الفضّي في 6b والرخ في 4b: «شوكة». ستضيع إحداهما حتمًا، فالغوتي في ورطة كبيرة.","46":"P-4f. يدفع الغوتي بيدق العمود 4 ليهاجم معسكر السِّنتي ردًّا. يتقدم قرب رخ السِّنتي ليبطئ هجومه ولو قليلًا.","47":"Bx6b+. يأسر الفيل الفضّي في 6b ويترقّى إلى حصان تنين. الآن مع السِّنتي فضّي في يده للهجوم التالي.","48":"Gx6b. يستعيد الغوتي حصان التنين بالذهبي. تبادلا الفيل والفضّي، لكن هجوم السِّنتي مستمر.","49":"S*5c. يُسقط السِّنتي الفضّي في 5c. يسنده البيدق في 5d، ويصوّب هذا الفضّي على الرخ في 4b والذهبي في 6b معًا.","51":"Sx4b+. يأسر الفضّي الرخ في 4b ويترقّى. كسب كانجو الرخ، أقوى قطعة عند خصمه.","53":"P-5c+. يترقّى البيدق في 5d إلى توكين. هذا التوكين عامل مجتهد يصوّب على الفضّيات والذهبيات داخل معسكر الغوتي.","54":"Sx5c. يأسر الغوتي التوكين. حتى الآن كسب السِّنتي رخًا وهو متقدم بوضوح في القطع. ويرى ذكاء الشوغي الاصطناعي في هذا الموقع أيضًا أن موقف السِّنتي أفضل.","56":"L*4b. يُسقط الغوتي رمحًا ليواجه الرخ على العمود 4. الرمح يتقدم مستقيمًا قدر ما يشاء، فيوضع أمام الرخ ليصطدم به.","59":"N-4e. يقفز الحصان من 3g إلى 4e وينضم إلى الهجوم. الحصان يقفز فوق القطع الأخرى، فيستطيع الهجوم حتى حيث يكثر المدافعون.","60":"+B-6d. يعود حصان التنين من 1i عبر قطر طويل إلى 6d. يحمي ملكه ويراقب في الوقت نفسه رخ السِّنتي. يقال إن حصان التنين «قوي حين يُسحب إلى معسكرك».","61":"P*2b. يُسقط السِّنتي بيدقًا في 2b ليرقّيه بعدها إلى توكين. داخل معسكر الخصم يعمل التوكين تمامًا كالذهبي.","62":"B*4d. يُسقط الغوتي فيله في 4d. يصوّب هذا الفيل على البيدق في 2b، وعلى القطر الآخر ينظر عبر 5e و6f نحو ملك السِّنتي.","63":"S-6f. يرفع السِّنتي الفضّي من 5g إلى 6f ليقطع قطر الفيل في 4d. نقلة هادئة تحمي محيط ملكه.","64":"Bx2b. يأسر فيل الغوتي البيدق في 2b. الغوتي أيضًا لا يتراجع: يزيل البيدق الذي أسقطه السِّنتي ويرتّب دفاعه.","65":"P*3c. يُسقط السِّنتي بيدقًا آخر ليصنع موطئ قدم في معسكر الغوتي. يصوّب هذا البيدق على منطقة 3b ويعرقل أيضًا فيل الغوتي.","66":"Lx4e. يأسر رمح الغوتي الحصان في 4e. خسر السِّنتي حصانًا مهاجمًا، لكن ما زال معه رخ في يده.","67":"R*4c. يُسقط السِّنتي رخه الآخر في 4c. بالرخين يصوّب على معسكر الغوتي. يستطيع السِّنتي استعمال الرخين لأنه كسب أحدهما بشوكة الفيل ابتداءً من النقلة 45.","68":"P*4b. يُسقط الغوتي بيدقًا ليسدّ الرخ. لكن بيدقًا واحدًا لا يستطيع أن يحبس قوة الرخ الكبيرة طويلًا.","69":"Rx4e+. يأسر الرخ في 4c الرمح في 4e ويترقّى إلى تنين. التنين يتحرك كالرخ ويستطيع أيضًا أن يخطو خطوة قطرية: قطعة قوية جدًا.","71":"P*5d. يُسقط السِّنتي بيدقًا على العمود 5 ليكبح معسكر الغوتي. يمنع هذا البيدق فضّي الغوتي من الخروج نحو 5e، وسيصير لاحقًا توكين.","72":"N*4d. يُسقط الغوتي حصانًا ليهاجم الرخ في 5f. يقفز الحصان خانتين إلى الأمام وخانة إلى الجانب، فيصل من 4d إلى الرخ في 5f.","73":"R-4f. يتنحّى الرخ من 5f إلى 4f ويسند التنين في 4e من الخلف. الرخ والتنين الآن على خط واحد يحمي أحدهما الآخر.","74":"S*3e. يُسقط الغوتي فضّيًا ليهاجم الرخ في 4f قطريًا. الفضّي يتحرك قطريًا إلى الأمام أيضًا، فيصل من 3e إلى 4f.","75":"+Rx3e. بدلًا من إبعاد الرخ يأسر السِّنتي الفضّي في 3e بالتنين من 4e. سيأسر بيدقٌ التنينَ ردًّا، لكن يبدو أن كانجو فضّل ألّا يترك لخصمه وقتًا لإعادة الترتيب بدلًا من عدّ القطع. ويرى ذكاء الشوغي الاصطناعي في هذا الموقع أن موقف السِّنتي ما زال أفضل.","77":"P*3d. يُسقط السِّنتي بيدقًا ليهاجم الفيل في 3c. الفيل يتحرك قطريًا فقط، لذا هو ضعيف أمام بيدق يأتي من الأمام.","79":"L*2c. يُسقط السِّنتي رمحًا ليهاجم الفيل في 2b. إن هرب الفيل استطاع السِّنتي أن يأسر الحصان بعدها بـ L-2a+. ويرى ذكاء الشوغي الاصطناعي في هذا الموقع أن تقدم السِّنتي يكبر في هذه المرحلة.","80":"P*5g. يُسقط الغوتي بيدقًا في معسكر السِّنتي ليبدأ هجومًا معاكسًا. أسره يعيد فضّي السِّنتي إلى الخلف، فيتغير دفاعه قليلًا.","83":"Lx2a+. يأسر الرمح الحصان ويترقّى. انهارت الزاوية اليمنى من معسكر الغوتي، وصار مع السِّنتي حصان في يده.","85":"+Lx1a. يأسر الرمح المترقّي الرمحَ أيضًا. صار مع السِّنتي قطع أكثر في يده، وهو يتجه الآن نحو ملك الغوتي. سيكون الرمح والحصان اللذان في يده قطعتين أساسيتين للهجوم على ملك الغوتي.","87":"L*8f. يُسقط السِّنتي الرمح الذي في يده في 8f. إذا صعدنا العمود 8 مستقيمًا نجد البيدق في 8c، ووراءه ملك الغوتي في 8b، فهذا الرمح يحدّق في رأس الملك. من هنا يبدأ هجوم كانجو على الملك.","88":"P-3g+. يصنع الغوتي أيضًا توكين في معسكر السِّنتي. التوكين يتحرك كالذهبي وهو قوي جدًا في معسكر الخصم.","89":"N*9e. يُسقط السِّنتي حصانًا ليصوّب على 8c. مع الرمح في 8f يهاجم رأس ملك الغوتي. الخانة 8c أمام ملك الغوتي مباشرة؛ إن انكسرت صار الملك عاريًا.","90":"R*2h. يُسقط الغوتي رخًا ليصوّب على ملك السِّنتي. يستعمل الغوتي رخيه في محاولة أخيرة ضد ملك السِّنتي.","91":"S-6f. يرفع السِّنتي الفضّي، في نقلة تفكر في الدفاع عن ملكه وفي الهجوم معًا. يغطي هذا الفضّي أيضًا 5e و7e ويُبعد قطع الغوتي.","93":"G-6h. يقرّب السِّنتي الذهبي ليحمي ملكه. حين يقترب هجوم الخصم، من المهم أن تدافع بنقلة واحدة فقط ثم تهاجم دفعة واحدة.","95":"Rx4d. يأسر الرخ في 4f الحصان في 4d. من هنا يضغط الرخ على معسكر الغوتي من الجانب أيضًا، نحو 4b و4a.","97":"P-5c+. يرقّي السِّنتي البيدق في 5d إلى توكين. إذا أُسر التوكين فالخسارة بيدق واحد فقط، لكن قطعة الخصم تُجبر على الحركة لتأسره.","99":"Nx8c+. يأسر الحصان في 9e البيدق في 8c ويترقّى. هذا أمام ملك الغوتي مباشرة. لقد اختفى البيدق الذي كان يحرس ملك الغوتي.","101":"N*7e. يُسقط السِّنتي حصانه الآخر مصوّبًا على الذهبي في 8c وعلى 6c. الحصان يتحرك بطريقة يصعب على القطع العادية سدّها، لذلك هو قوي جدًا قرب الملك.","103":"Lx8c+. يأسر الرمح في 8f الذهبي في 8c ويترقّى. الرمح الذي أُسقط في النقلة 87 يؤدي هنا مهمته.","104":"K-6a. يهرب ملك الغوتي أكثر نحو اليمين. إنه يبتعد عن مدافعيه.","105":"S*7b. إسقاط فضّي مع كِشّة يدفع الملك نحو الوسط. الفضّي يتحرك قطريًا إلى الأمام أيضًا، فيصل من 7b إلى الملك في 6a.","106":"K-5b. يخرج ملك الغوتي إلى الوسط. حين يخرج الملك إلى الوسط يقلّ المدافعون حوله، وهذا خطير جدًا.","107":"Nx6c+. يأسر الحصان في 7e البيدق في 6c ويترقّى. الحصان المترقّي يتحرك كالذهبي، فهذه كِشّة على الملك في 5b.","109":"Sx6c+. يأسر السِّنتي بالفضّي من 7b ويترقّى. تستمر الأسرات، ويتناقص مدافعو الغوتي شيئًا فشيئًا.","111":"S*7b. يُسقط السِّنتي فضّيًا آخر مصوّبًا على حصان التنين في 6c. الفضّي يتحرك قطريًا إلى الخلف أيضًا، فيصل من 7b إلى 6c.","112":"+B-5c. يتنحّى حصان التنين عند الغوتي إلى 5c وينضم إلى دفاع الملك. بجانب ملكه يكون حصان التنين مدافعًا قويًا جدًا.","113":"G*6c. يُسقط السِّنتي ذهبيًا في وجه حصان التنين في 5c مباشرة. يسند الفضّي في 7b هذا الذهبي، فإن أسره حصان التنين أسر الفضّي ردًّا.","115":"Sx6c+. يأسر الفضّي في 7b حصان التنين ويترقّى. أزال السِّنتي حصان التنين، قلب دفاع الغوتي.","116":"Kx6c. يأسر الغوتي الفضّي المترقّي بالملك. اضطر ملك الغوتي إلى الخروج حتى 6c في الوسط.","117":"B*7b. فيل يُسقط من اليد ويعطي كِشّة. الفيل يصل بعيدًا على الأقطار، ومن 7b يصوّب على الملك في 6c.","119":"P*5c. إسقاط بيدق مع كِشّة. يترك السِّنتي الملك يأسره ليجرّه إلى أعلى أكثر. الفكرة التضحية ببيدق عمدًا لاستدعاء ملك الخصم إلى خانة خطرة.","121":"B-5d+. يخرج الفيل من 7b إلى 5d ويترقّى إلى حصان تنين ويعطي كِشّة. حين يصل حصان التنين إلى جانب الملك مباشرة يكون مهاجمًا قويًا جدًا.","123":"P*5c. إسقاط بيدق آخر مع كِشّة يدفع ملك الغوتي إلى 5a. مطاردة الملك بإسقاط بيدق بعد بيدق هكذا من سمات كانجو، أستاذ مسائل الكِش مات.","124":"K-5a. عاد ملك الغوتي إلى الصف الأخير. الملك في الصف الأخير لا يستطيع الهرب حين تضغط عليه قطع كثيرة من الأعلى.","125":"P-3c+. يترقّى البيدق من 3d في 3c إلى توكين. بعدها سيدخل هذا التوكين إلى 4b ويقترب من ملك الغوتي.","126":"+Px6h. يأسر الغوتي ذهبيّ السِّنتي بالتوكين ويبدأ هجومًا معاكسًا أخيرًا. حتى حين يكون ملكك في خطر، لعب نقلات تقترب من ملك الخصم هو فن نهاية المباراة.","128":"P-5h+. يصنع الغوتي توكين آخر ويضغط، لكن السِّنتي متقدم بخطوة. هذا التوكين قريب من ملك السِّنتي، لكنه يتأخر.","129":"+Px4b. يأسر التوكين في 3c البيدق في 4b. إذا أُسر التوكين فالخسارة بيدق واحد فقط، لذا هو مثالي لاقتلاع مدافعي الخصم.","131":"Rx4b+. يأسر الرخ في 4d الذهبي في 4b ويترقّى إلى تنين ويعطي كِشّة. الرخ الذي كان ينتظر هناك منذ النقلة 95 يؤدي هنا مهمته.","135":"P-5b+. يترقّى البيدق من 5c في 5b مع كِشّة. التوكين والذهبي وحصان التنين يطوّقون ملك الغوتي. التوكين يتحرك كالذهبي، فيصل من 5b إلى الملك في 4a.","137":"G-3b. ينتقل الذهبي من 4c إلى 3b: كِش مات. حصان التنين في 5d يصل إلى 3b على القطر، فلا يستطيع الملك أسر الذهبي. وخانات الهروب 2a و2b و4a و4b كلها مغطاة أيضًا. كسب كانجو رخًا بشوكة الفيل، وضحّى بتنين ليبقى هجومه سريعًا، وانطلاقًا من الرمح والحصان على الطرف جرّ ملك الغوتي إلى وسط الرقعة وأماته. بهذا الفوز بلغ كانجو الدان الثامن، وفي السنة التالية، 1755، قدّم إلى حكومة الشوغون مجموعته من مسائل الكِش مات «شوغي زوكو». لكن كانجو توفي سنة 1760 في الثانية والأربعين (بالحساب القديم) قبل أن يصبح ميجين، ومُنح لقب الميجين بعد وفاته."}},"masuda1957":{"t":"ماسودا، أول تاج ثلاثي: مباراة الفوز بلقب الميجين","w":"ماسودا كوزو","b":"أوياما ياسوهارو","ev":"بطولة ميجين-سين السادسة عشرة، مواجهة اللقب من سبع مباريات، المباراة 6","d":"10–11 يوليو 1957","pl":"اليابان (يويوغي، طوكيو)","lead":"بعد تسع سنوات من مبارزة جبل كويا، تواجه الأخوان في المدرسة ماسودا كوزو وأوياما ياسوهارو مرة أخرى، وهذه المرة في مواجهة لقب الميجين من سبع مباريات. كان ماسودا متقدمًا 3-2 قبل المباراة السادسة، فأظهر هجومًا حادًا في معركة «الياغورا المزدوجة» وفاز في 95 نقلة. وبهذا الفوز صار ماسودا ميجين، ومع لقبي أوشو وكودان اللذين كان يحملهما صار أول حامل لـ«التاج الثلاثي» في تاريخ الشوغي.","c":{"0":"أنا Musowl. بعد خسارته أمام أوياما في مبارزة جبل كويا عام 1948، مرّ ماسودا بفترة طويلة كان بالكاد يستطيع فيها الفوز عليه. صار أوياما ميجين عام 1952 ودافع عن اللقب خمس سنوات متتالية. وفي تلك الأثناء هزم ماسودا أوياما في بطولة أوشو-سين لموسم 1955، وبحسب قواعد ذلك الوقت أنزله إلى مباراة بـ«أفضلية الرمح»؛ ويُقال إنه حقق بذلك حلم طفولته: «أن يهزم الميجين ولو أعطاه أفضلية رمح». ثم في بطولة ميجين-سين لعام 1957 كان ماسودا متقدمًا 3-2، وجاء إلى هذه المباراة السادسة في نُزُل «هاتسوهانا» في يويوغي بطوكيو. كان أوياما في الرابعة والثلاثين وماسودا في التاسعة والثلاثين.","1":"P-7f. يفتح ماسودا قطر فيله. صارت المباريات الست كلها في هذه المواجهة معارك «ياغورا مزدوجة»، وهذه المباراة تسير في الطريق نفسه. وعام 1957 هو أيضًا العام الذي افتتحت فيه البعثة اليابانية إلى القطب الجنوبي «محطة شووا» في أنتاركتيكا.","2":"P-8d. يدفع أوياما بيدق رخه. يرد بالرخ الثابت الذي يُستخدم إلى الأمام مباشرة.","3":"S-6h. تصعد الفضة اليسرى. هذه أول خطوة لبناء الحصن المسمّى «ياغورا». الياغورا شكل يشبه القلعة يحمي أعلى الملك وجانبيه بثلاث قطع من الذهب والفضة، وهو أسلوب لعب له تاريخ طويل يعود إلى عصر إيدو.","5":"S-7g. تذهب الفضة إلى 7g وتغلق قطر الفيل. يُظهر هذا نية تجنّب تبادل الفيلين وبناء الياغورا بهدوء. وفي مواجهات لقب الميجين في ذلك العصر كانت «الياغورا المزدوجة»، التي يبني فيها الطرفان ياغورا هكذا، ساحة المعركة الرئيسية.","6":"S-4b. ويرفع أوياما فضة أيضًا ويقصد الياغورا هو الآخر.","7":"P-2f. بدفع بيدق الرخ يبدأ ماسودا أيضًا التحضير لهجومه. في الياغورا من المهم بناء شكل الهجوم في الوقت نفسه مع بناء الحصن.","8":"S-6b. يرفع أوياما فضته الأخرى ويقوّي الدفاع من الوسط إلى اليمين.","9":"S-4h. وتصعد الفضة اليمنى أيضًا. هذه فضة الهجوم، وطريقة إرسالها إلى الأمام هي أبرز ما في هذه المباراة.","10":"G-3b. يصعد الذهب لبناء حصن الملك.","11":"G-7h. يقترب الذهب ويعطي الياغورا شكلها.","12":"K-4a. ينقل أوياما ملكه إلى 4a. هذا استعداد لإدخال الملك إلى الحصن.","13":"K-6i. وينقل ماسودا ملكه أيضًا إلى اليسار. سيتجه هذا الملك نحو 7i و8h ويدخل الياغورا.","14":"P-7d. يدفع أوياما بيدق العمود 7 استعدادًا للقتال في الجهة اليسرى (من جهة سينته).","15":"P-3f. دفع بيدق العمود 3 يفتح طريقًا للفضة اليمنى لتصعد إلى 3g.","16":"P-5d. يدفع غوته البيدق الأوسط ويفتح طريقًا لنقل الفيل إلى 5c.","17":"P-4f. ويدفع سينته أيضًا بيدق العمود 4 ويضع أساس هجوم من اليمين.","18":"P-6d. يدفع غوته بيدق العمود 6. الفكرة إيصاله بعدها إلى 6e وأخذ موقع فوق ياغورا سينته.","19":"P-2e. يتقدم بيدق الرخ خطوة أخرى. يقترب الهجوم على العمود 2.","20":"S-3c. تصعد الفضة إلى 3c وتقوّي الدفاع عن العمود 2. حتى لو وصل البيدق من 2e إلى 2d يستطيع غوته الدفاع.","21":"S-3g. تصعد الفضة اليمنى إلى 3g. الخطة إرسالها عبر 2f و3e إلى الأمام لتصطدم بدفاع الخصم.","22":"B-3a. يسحب أوياما فيله إلى 3a. بعدها يذهب هذا الفيل إلى مربعات مثل 5c ليكبح هجوم سينته من قطر. إنها طريقة شائعة لاستخدام الفيل في الياغورا.","23":"S-2f. تخرج الفضة إلى 2f. ومع الفضة في المقدمة يستعد سينته للهجوم عبر العمود 3 أو 2.","24":"P-6e. يمد أوياما بيدق العمود 6 ويأخذ موقعًا. يدفع بيدقًا فوق ياغورا سينته ليضيّق مساحة فيله.","25":"P-3e. أخيرًا يصدم ماسودا بيدق العمود 3. إنها إشارة للهجوم على العمود 3 مع الفضة.","27":"Sx3e. تستعيد الفضة، وتخرج فضة سينته إلى 3e. تقف في الخط الأمامي وتستهدف 4d و2d.","28":"B-5c. يخرج الفيل إلى 5c ويراقب الفضة في 3e ومعسكر سينته. الفيل الذي تراجع في النقلة 22 يبدأ العمل هنا.","29":"R-3h. يدير ماسودا رخه إلى العمود 3. وضع الرخ خلف الفضة يقوّي الهجوم على العمود 3.","30":"S-4d. يُخرج أوياما فضته إلى 4d ويهاجم الفضة في 3e. يصدم فضة بفضة ليوقف هجوم سينته.","31":"S-6h. تتراجع الفضة اليسرى وتفتح طريق الفيل. بعد تراجع الفضة من 7g يستطيع الفيل في 8h أن يعمل على قطره.","32":"P*3c. يُسقط غوته بيدقًا للدفاع عن العمود 3.","33":"Sx4d. يذهب ماسودا إلى تبادل الفضتين.","34":"Bx4d. يستعيد الفيل.","35":"Bx4d. يأخذ ماسودا الفيل في 4d بفيله من 8h. إنه تبادل فيل بفيل.","36":"Px4d. يستعيد البيدق. بعد أن بادل كل طرف فضة وفيلًا، صار لدى الطرفين الآن فضة وفيل في اليد. ومع كثرة القطع في اليد يصير القتال شرسًا، وأماكن الإسقاط كثيرة.","37":"R-4h. يدور الرخ إلى العمود 4. الفكرة دفع بيدق العمود 4 والهجوم من هناك هذه المرة.","38":"G-5b. يقرّب أوياما ذهبه ويقوّي منطقة ملكه.","39":"K-7i. ويُدخل ماسودا ملكه مربعًا أعمق أيضًا، آمنًا داخل الياغورا.","40":"P-8e. يمد أوياما بيدق العمود 8 ويجهّز هجومًا مضادًا نحو ملك سينته.","41":"P-4e. يصدم ماسودا بيدق العمود 4.","43":"Rx4e. يستعيد الرخ. يخرج رخ سينته إلى 4e، وهو مربع قوي يعمل منه جانبيًا وصعودًا ونزولًا.","44":"P*4c. يُسقط غوته بيدقًا أمام الرخ للدفاع عن العمود 4.","45":"G-5i. يتراجع الذهب لإعادة بناء الدفاع. نقلة هادئة من ماسودا تضيف نقلة دفاعية قبل الهجوم.","46":"P-8f. يصدم أوياما بيدق العمود 8 ويبدأ هجومه المضاد.","48":"N-7c. يقفز الحصان ويسند البيدق في 6e ويستعد للهجوم.","49":"P-2d. ويصدم ماسودا أيضًا بيدق العمود 2.","51":"P*2b. هنا يبدأ هجوم ماسودا الحاد. يُسقط بيدقًا في 2b ليسحب الذهب إلى الخارج.","52":"Gx2b. يأخذ الذهب. حين يذهب الذهب إلى 2b يبتعد قليلًا عن دفاع الملك.","53":"P*2c. بيدق آخر. إسقاط البيادق واحدًا بعد آخر لإبعاد الذهب المدافع عن الملك أكثر فأكثر أسلوب يُسمّى «البيدق الطارق».","54":"Gx2c. سُحب الذهب حتى 2c. صار دفاع ملك غوته رقيقًا.","55":"B*6a. يُسقط ماسودا فيله في 6a، في أعمق نقطة من معسكر غوته. يهاجم الذهب في 5b وينظر عبر قطره إلى عمق معسكر غوته: اختراق حاد.","56":"S-5a. يسحب أوياما فضته إلى 5a ليسند الذهب في 5b.","57":"S*6d. يُسقط ماسودا فضة في 6d. تستهدف الحصان في 7c، ومع الفيل يضغط على الجهة اليسرى لغوته.","58":"B*3d. ويُسقط أوياما أيضًا فيلًا في 3d. يستهدف الرخ في 4e ويكبح هجوم سينته.","59":"Sx7c. تأخذ الفضة الحصان في 7c. وهي تأخذ في طريقها تدخل معسكر غوته وتهدد رخ غوته أيضًا.","61":"Rx6e. يأخذ الرخ البيدق في 6e. يعمل جانبيًا على نطاق واسع قرب معسكر غوته.","62":"P*6d. يُسقط أوياما بيدقًا ليطارد الرخ.","64":"P*6c. يُسقط غوته بيدقًا آخر ليطارد الرخ. يستخدم بيدقًا بعد بيدق ليوقف حركته.","65":"Rx5d. يذهب الرخ إلى 5d ويأخذ البيدق الذي هناك.","66":"P*5c. يُسقط غوته بيدقًا آخر ليطارد الرخ.","67":"Rx3d. هنا يأخذ ماسودا الفيل في 3d برخه. سيأخذ غوته الرخ بالبيدق، لكن ماسودا يقرر أخذ الفيل وتأمين قطع الهجوم. استخدام قطعة كبيرة بجرأة هكذا من سمات هجمات ماسودا.","68":"Px3d. يأخذ البيدق الرخ. إنه تبادل رخ بفيل، لكن في يد سينته فيلًا وحصانًا وبيادق، والفيل في 6a والفضة في 7c مغروسان في معسكر غوته.","69":"S-7b+. تترقّى الفضة وتقترب من عمق معسكر غوته.","70":"Rx8f. يأخذ رخ أوياما البيدق في 8f ويهاجم معسكر سينته مضادًا.","71":"N*1e. يُسقط ماسودا حصانًا على الحافة. الفكرة بعدها N-2c+ لأخذ الذهب، فهو يهدد دفاع غوته من بعيد.","72":"G-3c. يهرب الذهب إلى 3c.","73":"P*8g. بيدق يدفع الرخ إلى الخلف ويحمي المنطقة فوق ملك سينته نفسه.","75":"P*2b. بيدق آخر. الفكرة بعدها P-2a+ لأخذ الحصان.","76":"S*3b. يُسقط غوته فضة للدفاع.","77":"Px2a+. يترقّى البيدق ويأخذ الحصان في 2a.","78":"Sx2a. تستعيد الفضة.","79":"P-7e. بدفع بيدق العمود 7 يقطع الحركة الجانبية للرخ في 8e. صار صعبًا على رخ غوته أن يدخل معسكر سينته.","80":"G-4b. يقترب الذهب ويقوّي منطقة الملك.","81":"P*4d. يُسقط ماسودا بيدقًا يصطدم بالبيدق في 4c. يقترب ببيدق من ملك غوته من الأعلى.","82":"S-3b. تصعد الفضة للدفاع.","83":"Px4c+. يترقّى البيدق إلى توكين ويدخل بجوار الملك تمامًا.","85":"N*4e. يُسقط ماسودا حصانًا. الفكرة أن يقفز بعدها إلى 3c أو 5c ويقترب من ملك غوته.","86":"P*8h. يُسقط أوياما بيدقًا قرب ملك سينته ويحاول هجومًا مضادًا أخيرًا.","87":"Nx3c (دون ترقية). يأخذ ماسودا الذهب في 3c بالحصان ويختار ألا يرقّيه. الحصان غير المرقّى يهاجم 2a و4a، فيعطي كِشًّا للملك في 4a. لو ترقّى لتحرك كالذهب ولزال هذا الكِش، لذلك عدم الترقية هو الصواب هنا.","89":"B*7f. يُسقط ماسودا فيله في 7f. يجري هذا الفيل قطريًا عبر 6e و5d حتى 4c ويستهدف الفضة في 4c. ومع الفيل في 6a يتركّز فيلان على المربع 4c.","90":"P-8i+. يرقّي أوياما البيدق ويعطي كِشًّا لملك سينته.","92":"Rx7e. يأخذ الرخ البيدق في 7e ويهاجم الفيل في 7f.","93":"Bx4c+. يأخذ فيل ماسودا من 6a الفضة في 4c ويصير حصان التنين.","95":"Bx4c+. يأخذ الفيل من 7f الذهب في 4c، فيولد حصان تنين ثانٍ. أحدهما بجوار ملك غوته تمامًا، وفي يد سينته ذهبان وفضة: لم يبق أي دفاع. استسلم أوياما هنا، وفاز ماسودا في 95 نقلة. صار ماسودا ميجين بأربعة انتصارات مقابل هزيمتين، ومع لقبي أوشو وكودان نال أول تاج ثلاثي في التاريخ. ويُقال إن ماسودا ترك حينها هذه الكلمات: «صعدت حتى هنا، وما زلت عند سفح الجبل»، أي إنك حتى حين تظن أنك بلغت القمة فما زلت عند السفح. وفي أكتوبر من ذلك العام أطلق الاتحاد السوفيتي أول قمر صناعي في العالم. بعد تسع سنوات من جبل كويا، هذه هي المباراة التي نال فيها ماسودا المجد."}},"ck1992g18":{"t":"شينوك يتجمّد ويستسلم في وضع تعادل","w":"ماريون تينسلي","b":"شينوك (حاسوب)","ev":"المباراة الثامنة عشرة من بطولة العالم للداما «الإنسان ضد الآلة»","d":"22 أغسطس 1992","pl":"المملكة المتحدة (لندن)","lead":"بطولة العالم بين البطل ماريون تينسلي وبرنامج شينوك. في المباراة الثامنة عشرة، وفي وضع تعادل هادئ مأخوذ من الكتب، توقف شينوك فجأة عن اللعب. ومع أنه لم يبقَ في ساعته وقت تقريبًا، اختار الفريق الاستسلام «بروح رياضية». كانت هزيمة دون خسارة على الرقعة، وشينوك الذي كان متقدمًا 2–1 لُحق به إلى 2–2.","c":{"0":"السبت 22 أغسطس 1992، فندق بارك لين في لندن: المباراة الثامنة عشرة من بطولة العالم «الإنسان ضد الآلة». الأسود (يبدأ أولًا، المربعات 1–12 في الأعلى) مع تينسلي، والأبيض (21–32 في الأسفل) مع شينوك. نظام الوقت: 20 نقلة في الساعة. كان شينوك يعمل على جهاز SGI 4D/480 قدّمته الشركة الراعية «سيليكون غرافيكس»، وهو آلة كبيرة في داخلها ثمانية حواسيب. هذه المباراة لن تُحسم على الرقعة، بل داخل تلك الآلة.","1":"يلعب تينسلي من 9 إلى 13 نحو الحافة اليسرى. لهذه النقلة الأولى اسم: «إدنبرة». في البطولات تُسحب النقلات الثلاث الأولى بالقرعة (الاقتراع) وتُلعب كما خرجت. تستخدم بطولة الولايات المتحدة قاعدة النقلات الثلاث هذه منذ 1934.","2":"يلعب الأبيض، شينوك، من 23 إلى 19 نحو الوسط. بدأ جوناثان شيفر وفريقه بناء شينوك عام 1989 في جامعة ألبرتا بكندا. وفي بطولة الولايات المتحدة المفتوحة عام 1990 في توبيلو بولاية مسيسيبي حلّ ثانيًا بعد تينسلي، فنال حق تحدي اللقب العالمي.","3":"يلعب الأسود من 6 إلى 9، فتكتمل القرعة 9-13 23-19 6-9. في البداية رفضت الاتحادات أن يلعب حاسوب على اللقب. فتخلّى تينسلي عن لقبه العالمي وكأنه يحتج، ثم وقّع مع ذلك عقدًا لمواجهة شينوك.","4":"من هنا تصبح النقلات حرّة. يرفع الأبيض 27 إلى 23 ليسند القطعة في 19 من الخلف. ويوصي بهذا الهجوم أيضًا كتاب الافتتاحيات «Key Openings» لريتشارد باسك، الذي جُمع نحو عام 1999. وكانت طاولة اللعب قد استُخدمت في بطولة العالم للشطرنج بين كاسباروف وكاربوف عام 1986.","5":"يلعب الأسود من 9 إلى 14، أقرب إلى الوسط، مراقبًا طريق الأبيض إلى 18. وهذا أيضًا الدفاع الذي يوصي به باسك. وقد راجع خبير الداما في الفريق، نورمان تريلور، معرفة شينوك بالافتتاحيات سنوات طويلة.","6":"يلعب الأبيض من 22 إلى 18، أمام القطعة في 14 مباشرة، ويجبر الأسود على أن يقرر. كتب شيفر أن آلة شينوك بدت مثل «ثلاجة بأضواء تومض». وعلى الشاشة الكبيرة في القاعة كانت أيادٍ حاسوبية واقعية جدًا تحرّك القطع وتدهش الجمهور.","7":"يلعب الأسود من 11 إلى 15. الآن يجب على الأبيض أن يأكل من 18، إمّا 14 أو 15. يعدّ باسك هذا الوضع من «نقاط الالتقاء المفتاحية»، وهي مفترقات تلتقي فيها افتتاحيات كثيرة. كانت الجائزة 10,000 دولار، تُقسم 60–40 بين الفائز والخاسر.","8":"يأكل الأبيض 18x9: يقفز فوق 14 ويهبط في 9. كان 18x11 بأكل 15 ممكنًا أيضًا، لكن محرّك هذا الموقع يفضّل 18x9 كذلك. ستُستعاد القطعة في 9 فورًا.","9":"يستعيد الأسود 5x14، قافزًا فوق 9 وهابطًا في 14. الأكل إجباري، فهذه نقلته الوحيدة. عادت القطع متساوية.","10":"يلعب الأبيض من 25 إلى 22، مقدّمًا قطعة خلفية لتنظيم الوسط. في الداما من المهم جدًا تحريك القطع جماعةً كي لا تبقى ثغرات بعد التبادلات. ما زلنا في خط الكتب.","11":"يلعب الأسود من 7 إلى 11، فيملأ ما خلف 15 ويقوّي تشكيلته. وإن هاجم الأبيض 15 يومًا ما فستسندها القطعة في 11. ما زلنا في النظرية.","12":"يلعب الأبيض من 30 إلى 25، رافعًا قطعة من الصف الأخير ليحرس ما خلف 22. وبمعدل 20 نقلة في الساعة كان شينوك يلعب نقلات الكتب بسلاسة.","13":"يلعب الأسود من 1 إلى 5. إنها قطعة من الصف الخلفي، لكن ملء 5 خلف 14 يهيّئ للتبادل القادم. ويُروى أن تينسلي قال مرارًا في حفل الافتتاح: «لا يمكن أن أخسر».","14":"يلعب الأبيض من 22 إلى 17، أمام 13، ليعرض أكلة. على الأسود أن يأكل 13x22. ويخطط الأبيض لاستعادة قطعتين دفعة واحدة.","15":"يأكل الأسود 13x22، قافزًا فوق 17 وهابطًا في 22. إن استطعت الأكل وجب عليك. استعادة الأبيض جاهزة.","16":"يأكل الأبيض 25x18x9 فيأخذ 22 و14 في قفزة مزدوجة. قدّر شينوك ذلك «تفوقًا ملموسًا»، نحو ثلث قطعة. لكن القطعة في 9 ستؤخذ حالًا.","17":"يستعيد الأسود 5x14، ولم يربح أحد ولم يخسر. في كتاب باسك يستمر الخط نفسه نقلات كثيرة. ويُقال إن تينسلي كان يتذكر بلا تردد نقلات مبارياته هو في الأربعينيات.","18":"يلعب الأبيض من 26 إلى 22، فيملأ الوسط الفارغ ويهيّئ طرقًا إلى 17 و18. وعلى الورق كان تقييم شينوك بالأبيض يرتفع شيئًا فشيئًا.","19":"يلعب الأسود من 11 إلى 16، داعيًا الأبيض إلى 24-20. يرى الأسود أن التبادلات لن تكسر تشكيلته. وهذا أيضًا خط باسك الرئيسي.","20":"يلعب الأبيض من 24 إلى 20 بجانب 16، ويجبر الأسود على الأكل 15x24. ارتفع تقييم شينوك إلى أكثر من نصف قطعة، وكتب شيفر: «ماريون يمازحنا مرة أخرى». لكن هذا الرقم جاء من النظر بعيدًا جدًا، ومع أفضل لعب كان الأسود لا يزال قادرًا على التعادل.","21":"يأكل الأسود 15x24، فيأخذ 19 ويهبط في 24. الأكل إجباري ولا نقلة غيرها. صارت قطعة سوداء في عمق معسكر الأبيض.","22":"يأكل الأبيض 20x11، قافزًا فوق 16 وهابطًا في 11. كان 28x19 ممكنًا أيضًا، لكن المحرّك يختار 20x11. ستؤكل القطعة البيضاء في 11 قريبًا.","23":"يأكل الأسود 8x15 ويستعيد القطعة في 11. ولأنه استخدم القطعة الخلفية في 8، صار حرس الصف العلوي 2 و3 و4 فقط.","24":"يأكل الأبيض 28x19 ويأخذ القطعة السوداء في 24. اختفت القطعة السوداء المتسللة مؤقتًا.","25":"يأكل الأسود 15x24، قافزًا فوق 19 مجددًا وهابطًا في 24. انتهت التبادلات والقطع متساوية. ستكون القطعة السوداء في 24 مصدر إزعاج يضيّق على جناح الأبيض الأيمن.","26":"يلعب الأبيض من 22 إلى 18، عائدًا إلى الوسط ومصوّبًا نحو القطعة السوداء في 14. ما زال هذا تسلسل باسك.","27":"يلعب الأسود من 12 إلى 16 ويترك 14 تُؤكل عمدًا. يرى المحرّك أنها تكاد تكون النقلة الوحيدة؛ فغيرها مثل 4-8 أسوأ بكثير. وفي المقابل ينال الأسود طريقًا على الجناح الأيمن.","28":"يأكل الأبيض 18x9 فيأخذ 14 كما تقضي القاعدة. وصلت القطعة البيضاء إلى 9، قريبة من الصف الذي تصبح فيه ملكًا.","29":"يلعب الأسود من 16 إلى 20 ويضعها بجانب 24 لتسند كل منهما الأخرى. صار جناح الأبيض الأيمن مسدودًا بهاتين القطعتين السوداوين.","30":"يلعب الأبيض من 23 إلى 19. هنا ينتهي خط باسك الرئيسي. كتب شيفر أن كل هذا لعب منشور وأن الأسود يستطيع التعادل.","31":"يلعب الأسود من 10 إلى 14: يقدّم قطعة وسطى ويفتح الطريق إلى 18 مع مراقبة القطعة البيضاء في 9. من هنا خرجنا من الكتاب.","32":"يلعب الأبيض من 31 إلى 26. في هذه اللحظة كان شينوك يرى تفوقًا بنحو 0.7 قطعة. لكن مع حساب أعمق سينخفض هذا الرقم قريبًا.","33":"يلعب الأسود من 14 إلى 18 ويتوغل في وسط الأبيض. يستطيع الأبيض الرد بـ 26-22، فيترك 18 تأكل ثم يستعيد.","34":"النقلة الأخيرة في السجل، 26-22، هي النقلة السابعة عشرة لشينوك. كان شينوك قد لعب 16 نقلة في 27 دقيقة وبقيت له 33 دقيقة لأربع نقلات أخرى، لكنه ظل هنا يفكر ولم يلعب. ظهرت رسالة تقول «النقلة خلال 95 ثانية»، ومع ذلك مرّت الدقائق بلا شيء. وحين بقيت دقيقتان، أجبر الفريق البرنامج على نقلة ليتأكد أنه ما زال حيًّا، ثم أوقف الساعة وطلب اجتماعًا مع المنظمين وتينسلي. سُمح لهم بالمتابعة على آلة احتياطية، لكن الفريق اختار الاستسلام «بروح رياضية». كان الوضع تعادلًا منشورًا، وكتب شيفر لاحقًا أن ألم الاستسلام في مباراة متعادلة ببطولة العالم لم يزل قط. جعلت هذه الهزيمة النتيجة 2–2؛ ثم فاز تينسلي بالمباراة الخامسة والعشرين وبالمباراة الأخيرة، واحتفظ بتاجه 4–2."}},"polgar2002":{"t":"أول فوز لبولغار على كاسباروف","w":"يوديت بولغار","b":"غاري كاسباروف","ev":"روسيا ضد بقية العالم (شطرنج سريع)، الجولة الخامسة","d":"9 سبتمبر 2002","pl":"روسيا (موسكو)","lead":"المباراة التي هزمت فيها يوديت بولغار، التي توصف بأنها أقوى لاعبة في التاريخ، المصنَّف الأول عالميًا كاسباروف لأول مرة. يستخدم كاسباروف دفاع برلين، وهو الافتتاح نفسه الذي ساهم قبل عامين في خسارته لقب بطل العالم، لكن بولغار توسّع أفضليتها شيئًا فشيئًا في نهاية دور بلا وزيرين، وفي النهاية تطارد الملك الأسود برخّين. لُعبت في حدث حافل تواجه فيه فريق روسيا وفريق بقية العالم بعشرة لاعبين لكل منهما.","c":{"0":"9 سبتمبر 2002، موسكو، روسيا. هذه الجولة الخامسة من مواجهة الفرق «روسيا ضد بقية العالم»، حيث واجه عشرة لاعبين روس عشرة من كبار لاعبي البلدان الأخرى. كانت مباراة سريعة: 25 دقيقة لكل لاعب، مع إضافة 10 ثوانٍ لكل نقلة. الأبيض: يوديت بولغار من فريق العالم، 26 عامًا. الأسود: غاري كاسباروف من روسيا، المصنَّف الأول عالميًا. لعبت بولغار ضد كاسباروف مرات كثيرة، لكنها لم تهزمه قط.","1":"يلعب الأبيض e4: أكثر نقلة أولى شيوعًا، تأخذ الوسط. بولغار هي الصغرى بين ثلاث أخوات؛ كان أبوهن لاسلو يؤمن بأن «العباقرة يمكن تربيتهم»، فعلّم بناته الشطرنج منذ الطفولة المبكرة.","2":"يلعب الأسود e5، ردّ قديم يواجه e4 وجهًا لوجه. صار كاسباروف بطلًا للعالم عام 1985 في الثانية والعشرين، واحتفظ باللقب سنوات طويلة.","3":"الحصان إلى f3 يستهدف بيدق e5. هذا من أقدم تسلسلات النقلات في الشطرنج.","4":"يلعب الأسود ♘c6. يحمي الحصان e5. يُلعب هذا الوضع منذ مئات السنين.","5":"يلعب الأبيض ♗b5. يهاجم الفيل حصان c6، حامي e5. هذا هو «روي لوبيز» (الافتتاح الإسباني)، المسمّى باسم روي لوبيز، القسّ الإسباني من القرن السادس عشر.","6":"يلعب الأسود ♘f6: «دفاع برلين». يُقال إن الاسم جاء من لاعبي برلين في القرن التاسع عشر الذين درسوه. ظلّ نادر الاستعمال زمنًا طويلًا، لكن كرامنيك استخدمه في بطولة العالم 2000، فخسر كاسباروف لقبه دون أن يفوز بمباراة واحدة.","7":"يبيّت الأبيض. بدلًا من حماية بيدق e4، يؤمّن الملك أولًا. حتى لو أُخذ e4، فالأبيض مستعد لاستعادته.","8":"يلعب الأسود ♘xe4 ويأخذ البيدق. الترتيب الملقّب «جدار برلين» عذّب كاسباروف قبل عامين؛ والآن يدخله بنفسه بالأسود.","9":"يلعب الأبيض d4. يفتح الوسط للهجوم ما دام الملك الأسود في e8. في هذا الخط من الافتتاح الإسباني، هذا أكثر خيارات الأبيض شعبية.","10":"يلعب الأسود ♘d6. يتراجع الحصان ويهاجم فيل b5. من d6 يراقب c6 وe5 معًا.","11":"يلعب الأبيض ♗xc6 ويبادل الفيل بالحصان. يختار الأبيض إفساد بنية بيادق الأسود.","12":"يلعب الأسود dxc6. الاسترداد ببيدق d يفتح الخطوط لوزير الأسود وفيله. في المقابل، صار للأسود بيدقان أحدهما أمام الآخر على العمود c: «بيدقان مضاعفان».","13":"يلعب الأبيض dxe5، يأخذ بيدقًا ويهاجم الحصان. بعد ذلك يتبادل الوزيران: هذا هو الخط الرئيسي لدفاع برلين.","14":"يلعب الأسود ♘f5. ينتقل الحصان إلى مربع جيد. لا عجلة لاستعادة بيدق e5.","15":"يلعب الأبيض ♕xd8+ ويبادل الوزيرين مع كش. من دون الوزيرين تتحول المباراة مبكرًا جدًا إلى ما يشبه نهاية الدور. يمرّ الخط الرئيسي لدفاع برلين عادةً بهذا الوضع.","16":"يلعب الأسود ♔xd8 ويسترد بالملك. لم يعد الأسود قادرًا على التبييت، لكن من دون الوزيرين نادرًا ما يكون ملكه في خطر، ولديه زوج الفيلة.","17":"يلعب الأبيض ♘c3. من هنا يُسمّى الوضع «نهاية برلين»: يلعب الأبيض ببيادقه الزائدة على جناح الملك، والأسود بفيليه.","18":"يلعب الأسود h6، نقلة معتادة تمنع حصان الأبيض وفيله من الذهاب إلى g5. سيبحث الملك الأسود عن مكان آمن في c8 أو e8.","19":"يلعب الأبيض ♖d1+. يعطي الرخ كشًّا ويأخذ العمود d المفتوح. على الملك الأسود أن يقرّر إلى أين يذهب.","20":"يلعب الأسود ♔e8. يعود الملك إلى e8. الذهاب إلى c8 ممكن أيضًا، لكن الأسود يختار هنا حراسة جناح الملك.","21":"يلعب الأبيض h3 ويمنع فيل الأسود من الذهاب إلى g4 ليتبادل مع حصان f3. أُقيم هذا الحدث عام 2002؛ وفي يونيو من ذلك العام استضافت اليابان وكوريا الجنوبية كأس العالم لكرة القدم.","22":"يلعب الأسود ♗e7. يخرج الفيل ويقوّي منطقة الملك. يفكّر الأسود في كيفية الاستفادة من فيليه.","23":"يلعب الأبيض ♘e2. يدور الحصان إلى e2 ليستهدف معسكر الأسود من d4 أو f4. إنه في طريقه إلى مربع جيد في الوسط.","24":"يلعب الأسود ♘h4 ويعرض تبادل الحصانين. من دون حصان الأبيض القوي سيكون عمل فيلي الأسود أسهل.","25":"يلعب الأبيض ♘xh4 ويبادل الحصانين. يواصل الأبيض القتال بحصانه الآخر.","26":"يلعب الأسود ♗xh4 ويسترد بالفيل. يحتفظ الأسود بزوج الفيلة.","27":"يلعب الأبيض ♗e3. يخرج الفيل وينظر إلى مربعات مثل a7 وc5. تدخل قطع الأبيض اللعب واحدة تلو الأخرى.","28":"يلعب الأسود ♗f5. يخرج الفيل الآخر أيضًا ويستهدف بيدق c2. يعمل فيلا الأسود على جانبي الرقعة.","29":"يلعب الأبيض ♘d4. يدخل الحصان الوسط ويهاجم فيل f5. من هناك يبحث عن ثغرات بين بيادق الأسود.","30":"يلعب الأسود ♗h7. يتراجع الفيل ليتجنب التبادل. ويواصل استهداف c2 على القطر الطويل.","31":"يلعب الأبيض g4! يضيّق تقدّم البيدق طريق هروب فيل h4. إن تبعته ♔g2 وf4، فقد لا يبقى لهذا الفيل ما يفعله.","32":"يلعب الأسود ♗e7 ويعيد الفيل قبل أن يُحبس. كسب الأبيض مساحة على جناح الملك.","33":"يلعب الأبيض ♔g2. يقترب الملك من الوسط. في نهاية دور بلا وزيرين يصبح الملك قطعة مقاتلة مهمة.","34":"يلعب الأسود h5. يضرب ببيدق ليهزّ جناح ملك الأبيض. يريد الأسود فتح العمود h لرخّه.","35":"يلعب الأبيض ♘f5! يستقر الحصان في المربع الممتاز f5. يستهدف بيدق g7 ويعرقل فيلي الأسود.","36":"يلعب الأسود ♗f8. يتراجع الفيل ليحمي g7. تُدفع قطع الأسود إلى الخلف شيئًا فشيئًا.","37":"يلعب الأبيض ♔f3. يتقدّم الملك أكثر ويدعم بيدق g4. لا يستطيع الملك التقدّم هكذا إلا لأن الوزيرين غائبان.","38":"يلعب الأسود ♗g6. يخرج فيل h7 ويُظهر فكرة التبادل مع حصان f5.","39":"يلعب الأبيض ♖d2. يذهب الرخ إلى الصف الثاني تمهيدًا لوصل الرخّين. لا يستعجل الأبيض، بل ينظّم قطعه.","40":"يلعب الأسود hxg4+. يبادل البيادق مع كش. ينفتح العمود h ويصير للرخ الأسود طريق.","41":"يلعب الأبيض hxg4 ويسترد ببيدق. صار العمود h خطًّا يستطيع الرخ الأسود استخدامه.","42":"يلعب الأسود ♖h3+. يدخل الرخ عبر العمود h مع كش. ينشّط الأسود قطعه ويبحث عن لعب مضاد.","44":"يلعب الأسود ♖h7. يعود الرخ ويحتفظ بالعمود h. يرى الأسود أن مجرد إعطاء الكشّات لن يجلب شيئًا.","45":"يلعب الأبيض ♔g3. يقف الملك أمام الرخ ويسدّ العمود h. يعمل الملك الأبيض مدافعًا أيضًا.","46":"يلعب الأسود f6. يهاجم البيدق e5 ليأخذ بيدق الأبيض الأوسط. يغيّر الأسود البنية بنفسه ليفتح الوضع.","47":"يلعب الأبيض ♗f4. يحمي الفيل بيدق e5. صارت كل قطع الأبيض تدعم بعضها بعضًا.","48":"يلعب الأسود ♗xf5. يأخذ الفيل الحصان. يختار الأسود التخلص من حصان الأبيض القوي.","49":"يلعب الأبيض gxf5 ويسترد ببيدق. بيدق f5 يسدّ أيضًا طريق فيل الأسود.","50":"يلعب الأسود fxe5 ويكسب البيدق. بالعدّ تعادل الأسود، لكن لدى الأبيض نقلة قوية جاهزة.","51":"يلعب الأبيض ♖e1! يذهب الرخ إلى العمود e ويستهدف بيدق e5 والملك في e8 خلفه. بسبب ملكه، صار بيدق الأسود عالقًا.","53":"يلعب الأبيض ♗xe5. يستعيد الفيل البيدق. ينظر الرخ الأبيض على العمود e إلى الملك الأسود في e8.","54":"يلعب الأسود ♔d7. يغادر الملك العمود e ويحاول وصل الرخّين.","55":"يلعب الأبيض c4! يتقدّم البيدق، فيوقف بيدق الأسود في c5 ويسيطر على d5 أيضًا. من هنا يبدأ الأبيض خطة لكسب البيادق.","57":"يلعب الأبيض ♗xd6 ويبادل الفيلين. على الأسود أن يسترد ببيدق c، وسيصبح هذا البيدق في d6 هدفًا لرخّي الأبيض.","59":"يلعب الأبيض ♖e6. يهاجم الرخ بيدق d6 مرة ثانية. لا يستطيع الأسود الاحتفاظ بهذا البيدق.","61":"يلعب الأبيض ♖exd6+ ويأخذ البيدق مع كش. صار للأبيض بيدق زائد، ورخّاه يعملان قرب الملك الأسود.","63":"يلعب الأبيض ♖2d5. يرصّ الرخّين على العمود d ويبحث عن طريق إلى معسكر الأسود. يردّ الأسود بإعطاء الكشّات للملك الأبيض.","67":"يلعب الأبيض ♔f3. متفاديًا الكشّات، يتقدّم الملك شيئًا فشيئًا. حين يتقدّم الملك تنفد كشّات الرخ الأسود.","69":"يلعب الأبيض ♔e4! يفلت الملك من كشّات الرخ ويتجه إلى الوسط. مع تقدّم الملك تنتهي كشّات الأسود قريبًا.","71":"يلعب الأبيض ♖c6+. يعطي الرخ كشًّا من العمود c ويدفع الملك الأسود نحو الزاوية.","73":"يلعب الأبيض ♖d7. يصل رخّ إلى الصف السابع. الرخ في الصف السابع قطعة قوية تستطيع أخذ البيادق من الجانب وحبس الملك.","75":"يلعب الأبيض ♔e3. يتراجع الملك ليتفادى كشّات الرخ الأسود. يضع الأبيض ملكه في مكان آمن ويهاجم بالرخّين.","77":"يلعب الأبيض ♖cc7. صار الرخّان كلاهما في الصف السابع. بالإنجليزية يُلقَّب هذا التشكيل مازحًا «الخنازير على الصف السابع»، ويُعرف بأنه قوي جدًا.","78":"يلعب الأسود ♖xf5. يستعيد بيدقًا، فتتساوى البيادق. لكن رخّي الأبيض يضيّقان الخناق حول الملك الأسود.","79":"يلعب الأبيض ♖b7+. يعطي الرخ كشًّا ويجبر الملك الأسود على التحرك. برخّين يحبس الأبيض الملك الأسود في الصف الأخير.","81":"يلعب الأبيض ♖dc7+. يعطي الرخ الآخر كشًّا أيضًا ويدفع الملك الأسود إلى d8.","83":"يلعب الأبيض ♖xg7. يأخذ بيدقًا ويصل الرخ إلى g7. إن لعب الأبيض بعدها ♖g8+، فالأسود يكاد يكون في كش مات.","84":"يلعب الأسود ♔c8، وهنا استسلم كاسباروف. يهدّد الأبيض بكش مات يبدأ بـ ♖g8+، وبأخذ بيدق a7 وغير ذلك، ولا يستطيع الأسود إيقاف كل شيء. كانت بولغار، المجرية، قد صارت في سن 15 عامًا و4 أشهر أصغر من نال لقب الأستاذ الكبير حتى ذلك الحين، محطّمةً رقم فيشر. وهنا هزمت للمرة الأولى أفضل لاعب في العالم. وفاز فريق بقية العالم بالمواجهة كلها 52 مقابل 48."}}};
